--
-- Name: accept_employee_invitation("text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."accept_employee_invitation"("invitation_token_hash" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  current_user_id uuid := (select auth.uid());
  current_user_email text := lower(coalesce((select auth.jwt() ->> 'email'), ''));
  invitation public.employee_invitations%rowtype;
  new_employee_id uuid;
begin
  if current_user_id is null or current_user_email = '' then
    raise exception 'Authentication with a verified email is required.' using errcode = '42501';
  end if;

  if invitation_token_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'Invitation token is invalid.' using errcode = '22023';
  end if;

  select *
  into invitation
  from public.employee_invitations employee_invitation
  where employee_invitation.token_hash = invitation_token_hash
    and employee_invitation.email = current_user_email
    and employee_invitation.accepted_at is null
    and employee_invitation.revoked_at is null
    and employee_invitation.expires_at > now()
  for update;

  if not found then
    raise exception 'Invitation is invalid, expired, or belongs to another email.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.employees employee
    where employee.profile_id = current_user_id
  ) then
    raise exception 'This account already belongs to an organization.' using errcode = '23505';
  end if;

  insert into public.employees (
    organization_id,
    profile_id,
    employee_number,
    job_title,
    status
  )
  values (
    invitation.organization_id,
    current_user_id,
    invitation.employee_number,
    invitation.job_title,
    'active'
  )
  returning id into new_employee_id;

  insert into public.employee_roles (organization_id, employee_id, role_id)
  values (invitation.organization_id, new_employee_id, invitation.role_id);

  insert into public.employee_stores (organization_id, employee_id, store_id)
  values (invitation.organization_id, new_employee_id, invitation.store_id);

  update public.employee_invitations
  set
    accepted_by = current_user_id,
    accepted_at = now()
  where id = invitation.id;

  return new_employee_id;
end;
$_$;


ALTER FUNCTION "private"."accept_employee_invitation"("invitation_token_hash" "text") OWNER TO "postgres";

--
-- Name: activate_manager_approval("uuid", "uuid", "text", "jsonb", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."activate_manager_approval"("target_organization_id" "uuid", "target_approval_request_id" "uuid", "target_operation_code" "text", "target_expected_payload" "jsonb", "target_execution_idempotency_key" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  request public.approval_requests%rowtype;
  required_permission text;
begin
  actor_employee_id := private.current_employee_id(target_organization_id);
  if actor_employee_id is null then
    raise exception 'An active employee is required.' using errcode = '42501';
  end if;

  select * into request
  from public.approval_requests approval_request
  where approval_request.id = target_approval_request_id
    and approval_request.organization_id = target_organization_id
  for update;

  if request.id is null
    or request.requested_by_employee_id is distinct from actor_employee_id
    or request.operation_code is distinct from target_operation_code
    or request.request_payload is distinct from target_expected_payload then
    raise exception 'The manager approval does not match this operation.' using errcode = '42501';
  end if;

  required_permission := private.approval_operation_permission(target_operation_code);
  if required_permission is null then
    raise exception 'This approval operation is not supported.' using errcode = '23514';
  end if;

  if request.status = 'CONSUMED' then
    if target_execution_idempotency_key is null
      or request.execution_idempotency_key is distinct from target_execution_idempotency_key then
      raise exception 'This manager approval was already used.' using errcode = '23514';
    end if;
  elsif request.status = 'APPROVED' and request.expires_at > now() then
    update public.approval_requests
    set
      status = 'CONSUMED',
      consumed_at = now(),
      execution_idempotency_key = target_execution_idempotency_key,
      updated_at = now()
    where id = request.id and organization_id = request.organization_id;

    perform private.write_audit_log(
      target_organization_id,
      'APPROVAL_CONSUMED',
      target_operation_code,
      actor_employee_id,
      request.approved_by_employee_id,
      request.store_id,
      request.register_id,
      request.id,
      request.requested_amount_minor,
      request.reason,
      '{}'::jsonb
    );
  else
    raise exception 'The manager approval is no longer valid.' using errcode = '42501';
  end if;

  perform set_config('tindio.approval_profile_id', (select auth.uid())::text, true);
  perform set_config('tindio.approval_organization_id', target_organization_id::text, true);
  perform set_config('tindio.approval_permission', required_permission, true);
end;
$$;


ALTER FUNCTION "private"."activate_manager_approval"("target_organization_id" "uuid", "target_approval_request_id" "uuid", "target_operation_code" "text", "target_expected_payload" "jsonb", "target_execution_idempotency_key" "uuid") OWNER TO "postgres";

--
-- Name: adjust_inventory("uuid", "uuid", "uuid", "uuid", numeric, "text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."adjust_inventory"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_movement_type" "text", "target_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  product_kind text;
  tracks_stock boolean;
  current_quantity numeric(14, 3);
  next_quantity numeric(14, 3);
  new_movement_id uuid;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'inventory.manage')) then
    raise exception 'Inventory management permission is required.' using errcode = '42501';
  end if;

  if target_quantity_delta is null
    or target_quantity_delta = 0
    or target_quantity_delta <> round(target_quantity_delta, 3) then
    raise exception 'Quantity must be non-zero with at most three decimal places.'
      using errcode = '23514';
  end if;

  if target_movement_type not in ('OPENING_STOCK', 'ADJUSTMENT') then
    raise exception 'Unsupported inventory movement type.' using errcode = '23514';
  end if;

  if char_length(trim(coalesce(target_reason, ''))) not between 2 and 500 then
    raise exception 'Inventory reason must contain between 2 and 500 characters.'
      using errcode = '23514';
  end if;

  select employee.id
  into actor_id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
  limit 1;

  if actor_id is null then
    raise exception 'An active employee record is required.' using errcode = '42501';
  end if;

  select product.product_type, product.track_inventory
  into product_kind, tracks_stock
  from public.products product
  join public.product_store_settings setting
    on setting.organization_id = product.organization_id
   and setting.product_id = product.id
   and setting.store_id = target_store_id
   and setting.is_available
  join public.stores store
    on store.id = setting.store_id
   and store.organization_id = setting.organization_id
   and store.is_active
  where product.id = target_product_id
    and product.organization_id = target_organization_id
    and product.status = 'active';

  if product_kind is null or not tracks_stock then
    raise exception 'Select an active, inventory-tracked product available at this store.'
      using errcode = '23514';
  end if;

  if product_kind = 'simple' and target_variant_id is not null then
    raise exception 'Simple products do not accept a variant.' using errcode = '23514';
  end if;

  if product_kind = 'variable' and (
    target_variant_id is null
    or not exists (
      select 1
      from public.product_variants variant
      where variant.id = target_variant_id
        and variant.product_id = target_product_id
        and variant.organization_id = target_organization_id
        and variant.is_active
    )
  ) then
    raise exception 'Select an active variant belonging to this product.'
      using errcode = '23514';
  end if;

  select inventory_level.quantity
  into current_quantity
  from public.inventory_levels inventory_level
  where inventory_level.organization_id = target_organization_id
    and inventory_level.store_id = target_store_id
    and inventory_level.product_id = target_product_id
    and inventory_level.variant_id is not distinct from target_variant_id
  for update;

  if current_quantity is null then
    raise exception 'The stock projection is not initialized for this item and store.'
      using errcode = '23514';
  end if;

  if target_movement_type = 'OPENING_STOCK' and (
    current_quantity <> 0
    or exists (
      select 1
      from public.inventory_movements movement
      where movement.organization_id = target_organization_id
        and movement.store_id = target_store_id
        and movement.product_id = target_product_id
        and movement.variant_id is not distinct from target_variant_id
    )
  ) then
    raise exception 'Opening stock can only be recorded once on an untouched item.'
      using errcode = '23514';
  end if;

  next_quantity := current_quantity + target_quantity_delta;

  update public.inventory_levels
  set
    quantity = next_quantity,
    updated_at = now()
  where organization_id = target_organization_id
    and store_id = target_store_id
    and product_id = target_product_id
    and variant_id is not distinct from target_variant_id;

  insert into public.inventory_movements (
    organization_id,
    store_id,
    product_id,
    variant_id,
    quantity_delta,
    quantity_before,
    quantity_after,
    movement_type,
    actor_employee_id,
    reason
  )
  values (
    target_organization_id,
    target_store_id,
    target_product_id,
    target_variant_id,
    target_quantity_delta,
    current_quantity,
    next_quantity,
    target_movement_type,
    actor_id,
    trim(target_reason)
  )
  returning id into new_movement_id;

  return new_movement_id;
end;
$$;


ALTER FUNCTION "private"."adjust_inventory"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_movement_type" "text", "target_reason" "text") OWNER TO "postgres";

--
-- Name: apply_inventory_change("uuid", "uuid", "uuid", "uuid", numeric, "text", "uuid", "text", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."apply_inventory_change"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_movement_type" "text", "target_actor_employee_id" "uuid", "target_reason" "text", "target_source_type" "text", "target_source_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare current_quantity numeric(14,3); next_quantity numeric(14,3);
begin
  if target_quantity_delta = 0 then raise exception 'Inventory quantity change cannot be zero.' using errcode = '23514'; end if;
  select quantity into current_quantity from public.inventory_levels where organization_id = target_organization_id and store_id = target_store_id and product_id = target_product_id and variant_id is not distinct from target_variant_id for update;
  if not found then raise exception 'The stock projection is not initialized for this item and store.' using errcode = '23514'; end if;
  next_quantity := current_quantity + target_quantity_delta;
  update public.inventory_levels set quantity = next_quantity, updated_at = now() where organization_id = target_organization_id and store_id = target_store_id and product_id = target_product_id and variant_id is not distinct from target_variant_id;
  insert into public.inventory_movements (organization_id, store_id, product_id, variant_id, quantity_delta, quantity_before, quantity_after, movement_type, actor_employee_id, reason, source_type, source_id) values (target_organization_id,target_store_id,target_product_id,target_variant_id,target_quantity_delta,current_quantity,next_quantity,target_movement_type,target_actor_employee_id,target_reason,target_source_type,target_source_id);
end; $$;


ALTER FUNCTION "private"."apply_inventory_change"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_movement_type" "text", "target_actor_employee_id" "uuid", "target_reason" "text", "target_source_type" "text", "target_source_id" "uuid") OWNER TO "postgres";

--
-- Name: apply_inventory_change_v2("uuid", "uuid", "uuid", "uuid", numeric, "text", "uuid", "text", "text", "uuid", bigint, "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."apply_inventory_change_v2"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_movement_type" "text", "target_actor_employee_id" "uuid", "target_reason" "text", "target_source_type" "text", "target_source_id" "uuid", "target_unit_cost_minor" bigint DEFAULT NULL::bigint, "target_reason_code" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_quantity numeric(14,3);
  next_quantity numeric(14,3);
  current_average_cost bigint;
  current_cost_is_known boolean;
  catalog_unit_cost bigint;
  resolved_unit_cost bigint;
  next_average_cost bigint;
  incoming_cost_is_known boolean := false;
  next_cost_is_known boolean;
  movement_cost_is_known boolean;
begin
  if target_quantity_delta = 0
    or target_reason is null
    or char_length(btrim(target_reason)) not between 2 and 500 then
    raise exception 'Inventory quantity and reason are required.' using errcode = '23514';
  end if;

  if target_source_id is not null and target_source_type is null then
    raise exception 'Inventory sources require a source type.' using errcode = '23514';
  end if;

  select level.quantity, level.average_cost_minor, level.cost_is_known
  into current_quantity, current_average_cost, current_cost_is_known
  from public.inventory_levels level
  where level.organization_id = target_organization_id
    and level.store_id = target_store_id
    and level.product_id = target_product_id
    and level.variant_id is not distinct from target_variant_id
  for update;

  if not found then
    raise exception 'The stock projection is not initialized for this item and store.' using errcode = '23514';
  end if;

  select coalesce(variant.cost_minor, product.cost_minor, 0)
  into catalog_unit_cost
  from public.products product
  left join public.product_variants variant
    on variant.id is not distinct from target_variant_id
   and variant.product_id = product.id
   and variant.organization_id = product.organization_id
  where product.id = target_product_id
    and product.organization_id = target_organization_id;

  next_quantity := current_quantity + target_quantity_delta;
  resolved_unit_cost := greatest(
    coalesce(target_unit_cost_minor, nullif(current_average_cost, 0), catalog_unit_cost, 0),
    0
  );
  next_average_cost := current_average_cost;
  next_cost_is_known := current_cost_is_known;

  if target_quantity_delta > 0 then
    if target_movement_type = 'TRANSFER_IN'
      and target_source_type = 'stock_transfer_receipt'
      and target_source_id is not null then
      select coalesce(transfer_line.unit_cost_is_known, false)
      into incoming_cost_is_known
      from public.stock_transfer_receipt_lines receipt_line
      join public.stock_transfer_lines transfer_line
        on transfer_line.id = receipt_line.stock_transfer_line_id
       and transfer_line.organization_id = receipt_line.organization_id
      where receipt_line.organization_id = target_organization_id
        and receipt_line.stock_transfer_receipt_id = target_source_id
        and transfer_line.product_id = target_product_id
        and transfer_line.variant_id is not distinct from target_variant_id
      limit 1;
    elsif target_movement_type = 'PRODUCTION'
      and target_source_type = 'production_run'
      and target_source_id is not null then
      select coalesce(production_run.cost_is_known, false)
      into incoming_cost_is_known
      from public.production_runs production_run
      where production_run.id = target_source_id
        and production_run.organization_id = target_organization_id;
    elsif target_unit_cost_minor is not null then
      -- A purchase receipt may deliberately carry a 0 minor-unit cost.
      incoming_cost_is_known := true;
    else
      incoming_cost_is_known := current_cost_is_known;
    end if;
  else
    incoming_cost_is_known := current_cost_is_known;
  end if;

  if target_quantity_delta > 0
    and target_movement_type in ('RECEIPT', 'TRANSFER_IN', 'PRODUCTION')
    and next_quantity > 0 then
    next_average_cost := round(
      ((current_quantity * current_average_cost) + (target_quantity_delta * resolved_unit_cost))
      / next_quantity
    )::bigint;
    next_cost_is_known := case
      when current_quantity <= 0 then coalesce(incoming_cost_is_known, false)
      else coalesce(current_cost_is_known, false) and coalesce(incoming_cost_is_known, false)
    end;
  elsif target_quantity_delta > 0 and current_quantity = 0 and current_average_cost = 0 then
    next_average_cost := resolved_unit_cost;
  end if;

  movement_cost_is_known := case
    when target_quantity_delta > 0 then coalesce(incoming_cost_is_known, false)
    else coalesce(current_cost_is_known, false)
  end;

  update public.inventory_levels
  set quantity = next_quantity,
      average_cost_minor = next_average_cost,
      cost_is_known = next_cost_is_known,
      updated_at = now()
  where organization_id = target_organization_id
    and store_id = target_store_id
    and product_id = target_product_id
    and variant_id is not distinct from target_variant_id;

  insert into public.inventory_movements (
    organization_id, store_id, product_id, variant_id, quantity_delta, quantity_before, quantity_after,
    movement_type, actor_employee_id, reason, source_type, source_id,
    unit_cost_minor, value_delta_minor, reason_code, cost_is_known
  ) values (
    target_organization_id, target_store_id, target_product_id, target_variant_id,
    target_quantity_delta, current_quantity, next_quantity, target_movement_type,
    target_actor_employee_id, btrim(target_reason),
    case when target_source_id is null then null else target_source_type end,
    target_source_id, resolved_unit_cost,
    round(target_quantity_delta * resolved_unit_cost)::bigint,
    target_reason_code, movement_cost_is_known
  );
end;
$$;


ALTER FUNCTION "private"."apply_inventory_change_v2"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_movement_type" "text", "target_actor_employee_id" "uuid", "target_reason" "text", "target_source_type" "text", "target_source_id" "uuid", "target_unit_cost_minor" bigint, "target_reason_code" "text") OWNER TO "postgres";

--
-- Name: approval_decision("uuid", "text", bigint); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."approval_decision"("target_organization_id" "uuid", "target_operation_code" "text", "target_amount_minor" bigint) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rule public.approval_rules%rowtype;
begin
  select * into rule
  from public.approval_rules
  where organization_id = target_organization_id
    and operation_code = target_operation_code
    and is_enabled;

  if rule.id is null then return 'ALLOWED'; end if;
  if rule.decision <> 'APPROVAL_REQUIRED' then return rule.decision; end if;
  if rule.amount_threshold_minor is not null
    and target_amount_minor is not null
    and target_amount_minor <= rule.amount_threshold_minor then
    return 'ALLOWED';
  end if;
  return 'APPROVAL_REQUIRED';
end;
$$;


ALTER FUNCTION "private"."approval_decision"("target_organization_id" "uuid", "target_operation_code" "text", "target_amount_minor" bigint) OWNER TO "postgres";

--
-- Name: approval_operation_permission("text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."approval_operation_permission"("target_operation_code" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case target_operation_code
    when 'sales.refund' then 'sales.refund'
    when 'cash.pay_out' then 'cash.pay_out'
    when 'inventory.adjust' then 'inventory.adjust.post'
    when 'discounts.apply' then 'discounts.apply'
    when 'prices.override' then 'prices.override'
    when 'cash_drawer.open' then 'cash_drawer.open'
    when 'shifts.force_close' then 'shifts.force_close'
    when 'payments.adjust' then 'payments.accept'
    when 'sales.void' then 'sales.create'
    else null
  end;
$$;


ALTER FUNCTION "private"."approval_operation_permission"("target_operation_code" "text") OWNER TO "postgres";

--
-- Name: FUNCTION "approval_operation_permission"("target_operation_code" "text"); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."approval_operation_permission"("target_operation_code" "text") IS 'Maps sensitive approval operations to their required permission. Inventory adjustments require inventory.adjust.post; approval requests additionally require adjustment create or post capability.';


--
-- Name: approve_manager_approval("uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."approve_manager_approval"("target_organization_id" "uuid", "target_approval_request_id" "uuid", "target_approver_employee_number" "text", "target_pin" "text") RETURNS TABLE("approval_request_id" "uuid", "approved_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  requester_employee_id uuid;
  request public.approval_requests%rowtype;
  approver public.employees%rowtype;
  credential private.employee_pin_credentials%rowtype;
  required_permission text;
  next_failed_attempts integer;
begin
  requester_employee_id := private.current_employee_id(target_organization_id);
  if requester_employee_id is null then
    raise exception 'An active employee is required.' using errcode = '42501';
  end if;

  select * into request
  from public.approval_requests approval_request
  where approval_request.id = target_approval_request_id
    and approval_request.organization_id = target_organization_id
  for update;

  if request.id is null then
    raise exception 'The approval request was not found.' using errcode = 'P0002';
  end if;

  if request.requested_by_employee_id is distinct from requester_employee_id then
    raise exception 'Only the requesting employee can present this approval.' using errcode = '42501';
  end if;

  if request.status <> 'PENDING' or request.expires_at <= now() then
    if request.status = 'PENDING' then
      update public.approval_requests
      set status = 'EXPIRED', updated_at = now()
      where id = request.id and organization_id = request.organization_id;
    end if;
    raise exception 'This approval request is no longer pending.' using errcode = '23514';
  end if;

  select * into approver
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.employee_number = upper(trim(coalesce(target_approver_employee_number, '')))
    and employee.status = 'active'
  for key share;

  required_permission := private.approval_operation_permission(request.operation_code);
  if approver.id is null
    or approver.id = requester_employee_id
    or not private.employee_has_permission(target_organization_id, approver.id, 'approvals.authorize')
    or not private.employee_has_permission(target_organization_id, approver.id, required_permission)
    or not exists (
      select 1
      from public.employee_stores employee_store
      where employee_store.organization_id = target_organization_id
        and employee_store.employee_id = approver.id
        and employee_store.store_id = request.store_id
    ) then
    raise exception 'A qualified manager assigned to this store must approve the request.' using errcode = '42501';
  end if;

  select * into credential
  from private.employee_pin_credentials pin_credential
  where pin_credential.employee_id = approver.id
  for update;

  if credential.employee_id is null then
    raise exception 'Manager PIN approval is unavailable. Set a secure manager PIN first.' using errcode = '42501';
  end if;

  if credential.locked_until is not null and credential.locked_until > now() then
    raise exception 'This manager PIN is temporarily locked. Try again later.' using errcode = '42501';
  end if;

  if coalesce(target_pin, '') !~ '^[0-9]{6,12}$'
    or credential.pin_hash <> extensions.crypt(target_pin, credential.pin_hash) then
    next_failed_attempts := case
      when credential.failed_window_started_at is null
        or credential.failed_window_started_at < now() - interval '15 minutes' then 1
      else credential.failed_attempts + 1
    end;

    update private.employee_pin_credentials
    set
      failed_attempts = least(next_failed_attempts, 5),
      failed_window_started_at = case
        when credential.failed_window_started_at is null
          or credential.failed_window_started_at < now() - interval '15 minutes' then now()
        else credential.failed_window_started_at
      end,
      locked_until = case when next_failed_attempts >= 5 then now() + interval '15 minutes' else null end,
      updated_at = now()
    where employee_id = approver.id;

    if next_failed_attempts >= 5 then
      perform private.write_audit_log(
        target_organization_id,
        'MANAGER_PIN_LOCKED',
        request.operation_code,
        approver.id,
        approver.id,
        request.store_id,
        request.register_id,
        request.id,
        request.requested_amount_minor,
        null,
        jsonb_build_object('lock_minutes', 15)
      );
    end if;

    raise exception 'Manager PIN verification failed.' using errcode = '42501';
  end if;

  update private.employee_pin_credentials
  set failed_attempts = 0, failed_window_started_at = null, locked_until = null, updated_at = now()
  where employee_id = approver.id;

  update public.approval_requests
  set
    status = 'APPROVED',
    approved_by_employee_id = approver.id,
    decided_at = now(),
    updated_at = now()
  where id = request.id and organization_id = request.organization_id;

  perform private.write_audit_log(
    target_organization_id,
    'APPROVAL_APPROVED',
    request.operation_code,
    approver.id,
    requester_employee_id,
    request.store_id,
    request.register_id,
    request.id,
    request.requested_amount_minor,
    request.reason,
    jsonb_build_object('expires_at', request.expires_at)
  );

  return query select request.id, now();
end;
$_$;


ALTER FUNCTION "private"."approve_manager_approval"("target_organization_id" "uuid", "target_approval_request_id" "uuid", "target_approver_employee_number" "text", "target_pin" "text") OWNER TO "postgres";

--
-- Name: approve_stock_request("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."approve_stock_request"("target_organization_id" "uuid", "target_stock_request_id" "uuid", "target_lines" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare request_row public.stock_requests%rowtype; actor_id uuid; line jsonb; request_line public.stock_request_lines%rowtype; warehouse_store_id uuid;
begin
  if (select auth.uid()) is null
     or (
       not (select private.has_permission(target_organization_id, 'inventory.manage'))
       and not (select private.has_inventory_capability(target_organization_id, 'inventory.transfer.send'))
     ) then raise exception 'Inventory permission is required.' using errcode = '42501'; end if;
  if target_lines is null or jsonb_typeof(target_lines) <> 'array' or jsonb_array_length(target_lines) not between 1 and 100 then raise exception 'Approval needs every request line.' using errcode = '23514'; end if;
  select * into request_row from public.stock_requests request where request.id = target_stock_request_id and request.organization_id = target_organization_id and request.status = 'requested' for update;
  if request_row.id is null then raise exception 'Only a submitted request can be approved.' using errcode = '23514'; end if;
  select warehouse.store_id into warehouse_store_id from public.supply_chain_warehouses warehouse where warehouse.id = request_row.source_warehouse_id and warehouse.organization_id = target_organization_id and warehouse.is_active;
  actor_id := private.inventory_actor(target_organization_id, warehouse_store_id);
  if actor_id is null then raise exception 'An assigned employee is required for the source warehouse.' using errcode = '42501'; end if;
  if (select count(*) from public.stock_request_lines where stock_request_id = request_row.id) <> jsonb_array_length(target_lines)
    or exists (select 1 from jsonb_array_elements(target_lines) approval(value) where jsonb_typeof(approval.value) <> 'object' or coalesce(approval.value->>'stock_request_line_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or coalesce(approval.value->>'approved_quantity','') !~ '^\d+(\.\d{1,3})?$')
    or (select count(*) from jsonb_array_elements(target_lines)) <> (select count(distinct value->>'stock_request_line_id') from jsonb_array_elements(target_lines)) then raise exception 'Approval lines are invalid.' using errcode = '23514'; end if;
  for line in select value from jsonb_array_elements(target_lines) loop
    select * into request_line from public.stock_request_lines item where item.id = (line->>'stock_request_line_id')::uuid and item.stock_request_id = request_row.id and item.organization_id = target_organization_id for update;
    if request_line.id is null or (line->>'approved_quantity')::numeric > request_line.requested_quantity then raise exception 'Approved quantity cannot exceed the request.' using errcode = '23514'; end if;
    update public.stock_request_lines set approved_quantity = (line->>'approved_quantity')::numeric(14,3) where id = request_line.id;
  end loop;
  if not exists (select 1 from public.stock_request_lines where stock_request_id = request_row.id and approved_quantity > 0) then raise exception 'Approve at least one requested quantity.' using errcode = '23514'; end if;
  update public.stock_requests set status = 'approved', approved_by_employee_id = actor_id, approved_at = now() where id = request_row.id;
  perform private.write_audit_log(target_organization_id, 'STOCK_REQUEST_APPROVED', 'inventory.manage', actor_id, null, request_row.requesting_store_id, null, null, null, null, jsonb_build_object('stock_request_id', request_row.id));
end;
$_$;


ALTER FUNCTION "private"."approve_stock_request"("target_organization_id" "uuid", "target_stock_request_id" "uuid", "target_lines" "jsonb") OWNER TO "postgres";

--
-- Name: assert_archive_export_delivered(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."assert_archive_export_delivered"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status = 'archived' and old.status is distinct from 'archived' then
    if old.archive_requested_at is null then
      raise exception 'Request an archive before archiving this organization.' using errcode = '22023';
    end if;

    if not exists (
      select 1
      from public.organization_export_sessions export_session
      where export_session.organization_id = new.id
        and export_session.delivered_at is not null
        and export_session.delivered_at >= old.archive_requested_at
    ) then
      raise exception 'Download and complete a fresh organization export before archiving this organization.' using errcode = '22023';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."assert_archive_export_delivered"() OWNER TO "postgres";

--
-- Name: assert_organization_operational(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."assert_organization_operational"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_organization_id uuid;
begin
  target_organization_id := case when tg_op = 'DELETE' then old.organization_id else new.organization_id end;

  if not exists (
    select 1
    from public.organizations organization
    where organization.id = target_organization_id
      and organization.status = 'active'
  ) then
    raise exception 'This organization is suspended or archived. No operational data can be changed.' using errcode = '42501';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "private"."assert_organization_operational"() OWNER TO "postgres";

--
-- Name: assign_customer_identity(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."assign_customer_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.customer_number <> 0 then
      raise exception 'Customer numbers are assigned by TINDIO.' using errcode = '42501';
    end if;

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(new.organization_id::text, 702017)
    );

    select coalesce(max(customer.customer_number), 0) + 1
    into new.customer_number
    from public.customers customer
    where customer.organization_id = new.organization_id;
  end if;

  new.loyalty_card_code := nullif(btrim(coalesce(new.loyalty_card_code, '')), '');
  if new.loyalty_card_code is null then
    new.loyalty_card_code := 'TND-' || lpad(new.customer_number::text, 8, '0');
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."assign_customer_identity"() OWNER TO "postgres";

--
-- Name: assign_open_shift_to_refund(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."assign_open_shift_to_refund"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  active_shift_id uuid;
begin
  select shift.id
  into active_shift_id
  from public.shifts shift
  where shift.organization_id = new.organization_id
    and shift.store_id = new.store_id
    and shift.register_id = new.register_id
    and shift.opened_by_employee_id = new.refunded_by_employee_id
    and shift.status = 'open'
  for update;

  if active_shift_id is null then
    raise exception 'Open the original register shift before processing this refund.'
      using errcode = '23514';
  end if;

  new.shift_id := active_shift_id;
  return new;
end;
$$;


