-- Name: FUNCTION "checkout_sale_v1"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid", "target_idempotency_key" "uuid", "target_items" "jsonb", "target_payments" "jsonb"); Type: COMMENT; Schema: private; Owner: postgres
