--
-- Name: clock_in_employee("uuid", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."clock_in_employee"("target_organization_id" "uuid", "target_store_id" "uuid", "target_clock_in_note" "text" DEFAULT NULL::"text") RETURNS TABLE("entry_id" "uuid", "store_id" "uuid", "clocked_in_at" timestamp with time zone, "clocked_out_at" timestamp with time zone, "was_replayed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  existing_entry public.time_clock_entries%rowtype;
  normalized_note text := nullif(trim(coalesce(target_clock_in_note, '')), '');
begin
  if target_organization_id is null or target_store_id is null then
    raise exception 'Choose an assigned store before clocking in.' using errcode = '23514';
  end if;

  if normalized_note is not null and char_length(normalized_note) not between 2 and 500 then
    raise exception 'A clock-in note must contain between 2 and 500 characters.' using errcode = '23514';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  join public.employee_stores employee_store
    on employee_store.employee_id = employee.id
   and employee_store.organization_id = employee.organization_id
   and employee_store.store_id = target_store_id
  join public.stores store
    on store.id = employee_store.store_id
   and store.organization_id = employee_store.organization_id
   and store.is_active
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
  for key share of employee, store;

  if actor_employee_id is null then
    raise exception 'An active employee assignment for this store is required.' using errcode = '42501';
  end if;

  select entry.*
  into existing_entry
  from public.time_clock_entries entry
  where entry.organization_id = target_organization_id
    and entry.employee_id = actor_employee_id
    and entry.clocked_out_at is null
  for update;

  if existing_entry.id is not null then
    if existing_entry.store_id = target_store_id then
      return query
      select
        existing_entry.id,
        existing_entry.store_id,
        existing_entry.clocked_in_at,
        existing_entry.clocked_out_at,
        true;
      return;
    end if;

    raise exception 'Clock out from your current store before clocking in elsewhere.'
      using errcode = '23505';
  end if;

  return query
  insert into public.time_clock_entries as entry (
    organization_id,
    employee_id,
    store_id,
    clock_in_note
  )
  values (
    target_organization_id,
    actor_employee_id,
    target_store_id,
    normalized_note
  )
  returning entry.id, entry.store_id, entry.clocked_in_at, entry.clocked_out_at, false;
end;
$$;


ALTER FUNCTION "private"."clock_in_employee"("target_organization_id" "uuid", "target_store_id" "uuid", "target_clock_in_note" "text") OWNER TO "postgres";

--
-- Name: clock_in_employee_with_pin("uuid", "uuid", "uuid", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."clock_in_employee_with_pin"("target_organization_id" "uuid", "target_store_id" "uuid", "target_employee_id" "uuid", "target_pin" "text", "target_request_id" "uuid") RETURNS TABLE("result_code" "text", "message" "text", "entry_id" "uuid", "employee_id" "uuid", "employee_name" "text", "store_id" "uuid", "store_name" "text", "clocked_in_at" timestamp with time zone, "clocked_out_at" timestamp with time zone, "was_replayed" boolean, "shift_id" "uuid", "register_id" "uuid", "register_name" "text", "shift_opened_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  verification_result text;
  selected_employee public.employees%rowtype;
  selected_name text;
  selected_store_name text;
  selected_entry public.time_clock_entries%rowtype;
begin
  if target_employee_id is null or target_request_id is null then
    raise exception 'Choose an employee and submit a valid attendance request.' using errcode = '23514';
  end if;
  actor_id := private.require_attendance_terminal(target_organization_id, target_store_id);

  select employee.* into selected_employee
  from public.employees employee
  join public.profiles profile on profile.id = employee.profile_id
  where employee.id = target_employee_id
    and employee.organization_id = target_organization_id
  for update of employee;

  select coalesce(nullif(profile.full_name, ''), profile.email, selected_employee.employee_number)
  into selected_name
  from public.profiles profile
  where profile.id = selected_employee.profile_id;

  select store.name into selected_store_name
  from public.stores store
  where store.id = target_store_id and store.organization_id = target_organization_id;

  select entry.* into selected_entry
  from public.time_clock_entries entry
  where entry.organization_id = target_organization_id
    and entry.clock_in_request_id = target_request_id;

  if selected_entry.id is not null then
    if selected_entry.employee_id is distinct from target_employee_id
      or selected_entry.store_id is distinct from target_store_id then
      raise exception 'This attendance request was already used for a different employee.' using errcode = '23505';
    end if;
    return query select 'CLOCKED_IN', 'This employee is already clocked in.', selected_entry.id,
      target_employee_id, selected_name, selected_entry.store_id, selected_store_name,
      selected_entry.clocked_in_at, selected_entry.clocked_out_at, true,
      null::uuid, null::uuid, null::text, null::timestamptz;
    return;
  end if;

  verification_result := private.verify_attendance_employee_pin(
    target_organization_id, target_store_id, target_employee_id, target_pin, actor_id
  );
  if verification_result <> 'VERIFIED' then
    return query select verification_result,
      case verification_result
        when 'INVALID_PIN' then 'Incorrect employee PIN.'
        when 'PIN_LOCKED' then 'This employee PIN is temporarily locked. Try again later.'
        when 'PIN_NOT_SET' then 'This employee needs a PIN before using attendance.'
        when 'EMPLOYEE_INACTIVE' then 'This employee is no longer active.'
        when 'STORE_NOT_ALLOWED' then 'This employee is not assigned to this store.'
        when 'ATTENDANCE_NOT_ALLOWED' then 'This employee does not have attendance access.'
        else 'This employee is unavailable for attendance.'
      end,
      null::uuid, target_employee_id, selected_name, target_store_id, selected_store_name,
      null::timestamptz, null::timestamptz, false,
      null::uuid, null::uuid, null::text, null::timestamptz;
    return;
  end if;

  select entry.* into selected_entry
  from public.time_clock_entries entry
  where entry.organization_id = target_organization_id
    and entry.employee_id = target_employee_id
    and entry.clocked_out_at is null
  for update;

  if selected_entry.id is not null then
    if selected_entry.store_id is distinct from target_store_id then
      return query select 'ALREADY_CLOCKED_IN', 'Clock out from the current store before clocking in elsewhere.',
        selected_entry.id, target_employee_id, selected_name, selected_entry.store_id,
        (select store.name from public.stores store where store.id = selected_entry.store_id),
        selected_entry.clocked_in_at, null::timestamptz, true,
        null::uuid, null::uuid, null::text, null::timestamptz;
      return;
    end if;
    return query select 'CLOCKED_IN', 'This employee is already clocked in.', selected_entry.id,
      target_employee_id, selected_name, selected_entry.store_id, selected_store_name,
      selected_entry.clocked_in_at, null::timestamptz, true,
      null::uuid, null::uuid, null::text, null::timestamptz;
    return;
  end if;

  insert into public.time_clock_entries (
    organization_id, employee_id, store_id, clock_in_verification_method,
    clock_in_request_id, clocked_in_by_employee_id
  ) values (
    target_organization_id, target_employee_id, target_store_id, 'employee_pin',
    target_request_id, actor_id
  ) returning * into selected_entry;

  perform private.write_audit_log(
    target_organization_id, 'EMPLOYEE_CLOCKED_IN', 'attendance.use', actor_id,
    target_employee_id, target_store_id, null, null, null, null,
    jsonb_build_object('attendance_id', selected_entry.id, 'verification_method', 'employee_pin')
  );

  return query select 'CLOCKED_IN', 'Employee clocked in.', selected_entry.id,
    target_employee_id, selected_name, target_store_id, selected_store_name,
    selected_entry.clocked_in_at, null::timestamptz, false,
    null::uuid, null::uuid, null::text, null::timestamptz;
end;
$$;


ALTER FUNCTION "private"."clock_in_employee_with_pin"("target_organization_id" "uuid", "target_store_id" "uuid", "target_employee_id" "uuid", "target_pin" "text", "target_request_id" "uuid") OWNER TO "postgres";

--
-- Name: clock_out_employee("uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."clock_out_employee"("target_organization_id" "uuid", "target_clock_out_note" "text" DEFAULT NULL::"text") RETURNS TABLE("entry_id" "uuid", "store_id" "uuid", "clocked_in_at" timestamp with time zone, "clocked_out_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  normalized_note text := nullif(trim(coalesce(target_clock_out_note, '')), '');
begin
  if target_organization_id is null then
    raise exception 'An organization is required to clock out.' using errcode = '23514';
  end if;

  if normalized_note is not null and char_length(normalized_note) not between 2 and 500 then
    raise exception 'A clock-out note must contain between 2 and 500 characters.' using errcode = '23514';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
  for key share;

  if actor_employee_id is null then
    raise exception 'An active employee is required to clock out.' using errcode = '42501';
  end if;

  return query
  update public.time_clock_entries entry
  set
    clocked_out_at = now(),
    clock_out_note = normalized_note
  where entry.organization_id = target_organization_id
    and entry.employee_id = actor_employee_id
    and entry.clocked_out_at is null
  returning entry.id, entry.store_id, entry.clocked_in_at, entry.clocked_out_at;

  if not found then
    raise exception 'There is no open time-clock entry to close.' using errcode = 'P0002';
  end if;
end;
$$;


ALTER FUNCTION "private"."clock_out_employee"("target_organization_id" "uuid", "target_clock_out_note" "text") OWNER TO "postgres";

--
-- Name: clock_out_employee_with_pin("uuid", "uuid", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."clock_out_employee_with_pin"("target_organization_id" "uuid", "target_employee_id" "uuid", "target_pin" "text", "target_request_id" "uuid") RETURNS TABLE("result_code" "text", "message" "text", "entry_id" "uuid", "employee_id" "uuid", "employee_name" "text", "store_id" "uuid", "store_name" "text", "clocked_in_at" timestamp with time zone, "clocked_out_at" timestamp with time zone, "was_replayed" boolean, "shift_id" "uuid", "register_id" "uuid", "register_name" "text", "shift_opened_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  verification_result text;
  selected_name text;
  selected_entry public.time_clock_entries%rowtype;
  open_shift public.shifts%rowtype;
  selected_store_name text;
  selected_register_name text;
begin
  if target_employee_id is null or target_request_id is null then
    raise exception 'Choose an employee and submit a valid attendance request.' using errcode = '23514';
  end if;

  select entry.* into selected_entry
  from public.time_clock_entries entry
  where entry.organization_id = target_organization_id
    and entry.clock_out_request_id = target_request_id;

  if selected_entry.id is not null then
    if selected_entry.employee_id is distinct from target_employee_id then
      raise exception 'This attendance request was already used for a different employee.' using errcode = '23505';
    end if;
    perform private.require_attendance_terminal(target_organization_id, selected_entry.store_id);
    select coalesce(nullif(profile.full_name, ''), profile.email, employee.employee_number), store.name
      into selected_name, selected_store_name
    from public.employees employee
    join public.profiles profile on profile.id = employee.profile_id
    join public.stores store on store.id = selected_entry.store_id
    where employee.id = target_employee_id and employee.organization_id = target_organization_id;
    return query select 'CLOCKED_OUT', 'This employee is already clocked out.', selected_entry.id,
      target_employee_id, selected_name, selected_entry.store_id, selected_store_name,
      selected_entry.clocked_in_at, selected_entry.clocked_out_at, true,
      null::uuid, null::uuid, null::text, null::timestamptz;
    return;
  end if;

  select entry.* into selected_entry
  from public.time_clock_entries entry
  where entry.organization_id = target_organization_id
    and entry.employee_id = target_employee_id
    and entry.clocked_out_at is null
  for update;

  if selected_entry.id is null then
    raise exception 'There is no open attendance entry to close.' using errcode = 'P0002';
  end if;
  actor_id := private.require_attendance_terminal(target_organization_id, selected_entry.store_id);

  select coalesce(nullif(profile.full_name, ''), profile.email, employee.employee_number), store.name
  into selected_name, selected_store_name
  from public.employees employee
  join public.profiles profile on profile.id = employee.profile_id
  join public.stores store
    on store.id = selected_entry.store_id and store.organization_id = employee.organization_id
  where employee.id = target_employee_id and employee.organization_id = target_organization_id;

  verification_result := private.verify_attendance_employee_pin(
    target_organization_id, selected_entry.store_id, target_employee_id, target_pin, actor_id
  );
  if verification_result <> 'VERIFIED' then
    return query select verification_result,
      case verification_result
        when 'INVALID_PIN' then 'Incorrect employee PIN.'
        when 'PIN_LOCKED' then 'This employee PIN is temporarily locked. Try again later.'
        when 'PIN_NOT_SET' then 'This employee needs a PIN before using attendance.'
        when 'EMPLOYEE_INACTIVE' then 'This employee is no longer active.'
        when 'ATTENDANCE_NOT_ALLOWED' then 'This employee does not have attendance access.'
        else 'This employee is unavailable for attendance.'
      end,
      selected_entry.id, target_employee_id, selected_name, selected_entry.store_id,
      selected_store_name, selected_entry.clocked_in_at, null::timestamptz, false,
      null::uuid, null::uuid, null::text, null::timestamptz;
    return;
  end if;

  select shift.* into open_shift
  from public.shifts shift
  where shift.organization_id = target_organization_id
    and shift.opened_by_employee_id = target_employee_id
    and shift.status = 'open'
  order by shift.opened_at
  limit 1
  for update;

  if open_shift.id is not null then
    select register.name into selected_register_name
    from public.registers register
    where register.id = open_shift.register_id
      and register.organization_id = target_organization_id;
    return query select 'OPEN_REGISTER_SHIFT', 'Close the register shift before clocking out.',
      selected_entry.id, target_employee_id, selected_name, selected_entry.store_id,
      selected_store_name, selected_entry.clocked_in_at, null::timestamptz, false,
      open_shift.id, open_shift.register_id, selected_register_name, open_shift.opened_at;
    return;
  end if;

  update public.time_clock_entries entry
  set clocked_out_at = now(),
      clock_out_verification_method = 'employee_pin',
      clock_out_request_id = target_request_id,
      clocked_out_by_employee_id = actor_id
  where entry.id = selected_entry.id
  returning * into selected_entry;

  perform private.write_audit_log(
    target_organization_id, 'EMPLOYEE_CLOCKED_OUT', 'attendance.use', actor_id,
    target_employee_id, selected_entry.store_id, null, null, null, null,
    jsonb_build_object('attendance_id', selected_entry.id, 'verification_method', 'employee_pin')
  );

  return query select 'CLOCKED_OUT', 'Employee clocked out.', selected_entry.id,
    target_employee_id, selected_name, selected_entry.store_id, selected_store_name,
    selected_entry.clocked_in_at, selected_entry.clocked_out_at, false,
    null::uuid, null::uuid, null::text, null::timestamptz;
end;
$$;


ALTER FUNCTION "private"."clock_out_employee_with_pin"("target_organization_id" "uuid", "target_employee_id" "uuid", "target_pin" "text", "target_request_id" "uuid") OWNER TO "postgres";

--
-- Name: close_register_shift("uuid", "uuid", bigint, "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."close_register_shift"("target_organization_id" "uuid", "target_shift_id" "uuid", "target_counted_cash_minor" bigint, "target_closing_note" "text") RETURNS TABLE("shift_id" "uuid", "expected_cash_minor" bigint, "counted_cash_minor" bigint, "difference_minor" bigint, "closed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  target_shift public.shifts%rowtype;
  calculated_cash record;
  normalized_closing_note text;
begin
  if target_organization_id is null
    or target_shift_id is null
    or target_counted_cash_minor is null
    or target_counted_cash_minor < 0 then
    raise exception 'A shift and non-negative counted cash amount are required.'
      using errcode = '23514';
  end if;

  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'shifts.close')) then
    raise exception 'Shift closing permission is required.' using errcode = '42501';
  end if;

  normalized_closing_note := nullif(trim(coalesce(target_closing_note, '')), '');
  if normalized_closing_note is not null
    and char_length(normalized_closing_note) not between 2 and 500 then
    raise exception 'A closing note must contain between 2 and 500 characters.'
      using errcode = '23514';
  end if;

  select shift.*
  into target_shift
  from public.shifts shift
  where shift.id = target_shift_id
    and shift.organization_id = target_organization_id
    and shift.status = 'open'
  for update;

  if target_shift.id is null then
    raise exception 'The open shift was not found.' using errcode = 'P0002';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  join public.employee_stores employee_store
    on employee_store.employee_id = employee.id
   and employee_store.organization_id = employee.organization_id
   and employee_store.store_id = target_shift.store_id
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active';

  if actor_employee_id is null then
    raise exception 'An active employee assignment for this shift store is required.'
      using errcode = '42501';
  end if;

  if target_shift.opened_by_employee_id is distinct from actor_employee_id then
    raise exception 'Only the employee who opened this shift can close it.'
      using errcode = '42501';
  end if;

  select *
  into calculated_cash
  from private.calculate_shift_cash(target_shift.id);

  return query
  update public.shifts shift
  set
    status = 'closed',
    closed_by_employee_id = actor_employee_id,
    expected_cash_minor = calculated_cash.expected_cash_minor,
    counted_cash_minor = target_counted_cash_minor,
    difference_minor = target_counted_cash_minor - calculated_cash.expected_cash_minor,
    closing_note = normalized_closing_note,
    closed_at = now()
  where shift.id = target_shift.id
    and shift.organization_id = target_organization_id
  returning
    shift.id,
    shift.expected_cash_minor,
    shift.counted_cash_minor,
    shift.difference_minor,
    shift.closed_at;
end;
$$;


ALTER FUNCTION "private"."close_register_shift"("target_organization_id" "uuid", "target_shift_id" "uuid", "target_counted_cash_minor" bigint, "target_closing_note" "text") OWNER TO "postgres";

--
-- Name: complete_inventory_count("uuid", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."complete_inventory_count"("target_organization_id" "uuid", "target_store_id" "uuid", "target_note" "text", "target_lines" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor_id uuid; count_id uuid; line jsonb; expected numeric(14,3); counted numeric(14,3); target_line_product_id uuid; target_line_variant_id uuid;
begin
 if (select auth.uid()) is null or not (select private.has_permission(target_organization_id,'inventory.manage')) then raise exception 'Inventory permission is required.' using errcode='42501'; end if;
 if target_lines is null or jsonb_typeof(target_lines) <> 'array' or jsonb_array_length(target_lines) not between 1 and 500 then raise exception 'A count needs one to 500 items.' using errcode='23514'; end if;
 perform private.inventory_count_actor(target_organization_id, target_store_id, array['inventory.count.create', 'inventory.count.finalize']::text[]);
  actor_id := private.inventory_actor(target_organization_id, target_store_id); if actor_id is null then raise exception 'An assigned employee is required for this store.' using errcode='42501'; end if;
 insert into public.inventory_counts (organization_id,store_id,status,note,started_by_employee_id,completed_by_employee_id,completed_at) values (target_organization_id,target_store_id,'completed',nullif(btrim(target_note),''),actor_id,actor_id,now()) returning id into count_id;
 for line in select value from jsonb_array_elements(target_lines) loop
  if coalesce(line->>'counted_quantity','') !~ '^\d+(\.\d{1,3})?$' then raise exception 'Counted quantities must be non-negative.' using errcode='23514'; end if;
  target_line_product_id:=(line->>'product_id')::uuid; target_line_variant_id:=nullif(line->>'variant_id','')::uuid; counted:=(line->>'counted_quantity')::numeric;
  select level.quantity into expected from public.inventory_levels level where level.organization_id=target_organization_id and level.store_id=target_store_id and level.product_id=target_line_product_id and level.variant_id is not distinct from target_line_variant_id for update; if not found then raise exception 'One count item has no stock projection.' using errcode='23514'; end if;
  insert into public.inventory_count_lines (organization_id,inventory_count_id,product_id,variant_id,expected_quantity,counted_quantity) values (target_organization_id,count_id,target_line_product_id,target_line_variant_id,expected,counted);
  if counted <> expected then perform private.apply_inventory_change(target_organization_id,target_store_id,target_line_product_id,target_line_variant_id,counted-expected,'COUNT',actor_id,'Inventory count','inventory_count',count_id); end if;
 end loop; return count_id; end; $_$;


ALTER FUNCTION "private"."complete_inventory_count"("target_organization_id" "uuid", "target_store_id" "uuid", "target_note" "text", "target_lines" "jsonb") OWNER TO "postgres";

--
-- Name: complete_organization_export("uuid", integer, "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."complete_organization_export"("target_export_session_id" "uuid", "target_record_count" integer, "target_manifest" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  export_session public.organization_export_sessions%rowtype;
  actor_employee_id uuid;
  delivery_completed_at timestamptz := clock_timestamp();
begin
  if target_record_count not between 1 and 50000000
    or jsonb_typeof(target_manifest) <> 'object'
    or not (target_manifest ? 'format')
    or not (target_manifest ? 'sections') then
    raise exception 'Export delivery details are invalid.' using errcode = '22023';
  end if;

  select session.*
  into export_session
  from public.organization_export_sessions session
  where session.id = target_export_session_id
    and session.profile_id = (select auth.uid())
    and session.expires_at > now()
  for update;

  if not found then
    raise exception 'The organization export session is missing or has expired.' using errcode = '42501';
  end if;

  if not private.has_organization_export_access(export_session.organization_id) then
    raise exception 'You do not have permission to export this organization.' using errcode = '42501';
  end if;

  if export_session.delivered_at is not null then
    return jsonb_build_object(
      'export_session_id', export_session.id,
      'delivered_at', export_session.delivered_at,
      'record_count', export_session.delivered_record_count,
      'was_replayed', true
    );
  end if;

  update public.organization_export_sessions session
  set
    delivered_at = delivery_completed_at,
    delivered_record_count = target_record_count,
    delivery_manifest = target_manifest
  where session.id = export_session.id;

  actor_employee_id := private.current_organization_member_employee_id(export_session.organization_id);

  perform private.write_audit_log(
    export_session.organization_id,
    'ORGANIZATION_EXPORT_DELIVERED',
    'organization.export',
    actor_employee_id,
    null,
    null,
    null,
    null,
    null,
    null,
    jsonb_build_object(
      'export_session_id', export_session.id,
      'record_count', target_record_count,
      'format', target_manifest ->> 'format'
    )
  );

  return jsonb_build_object(
    'export_session_id', export_session.id,
    'delivered_at', delivery_completed_at,
    'record_count', target_record_count,
    'was_replayed', false
  );
end;
$$;


ALTER FUNCTION "private"."complete_organization_export"("target_export_session_id" "uuid", "target_record_count" integer, "target_manifest" "jsonb") OWNER TO "postgres";

--
-- Name: consume_organization_rate_limit("uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."consume_organization_rate_limit"("target_organization_id" "uuid", "target_action_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_action_code text := lower(btrim(coalesce(target_action_code, '')));
  configured_limit integer;
  current_window_start timestamptz := date_trunc('hour', clock_timestamp());
  current_window_ends_at timestamptz;
  observed_request_count integer;
begin
  case normalized_action_code
    when 'organization.export' then
      configured_limit := 3;
      if not private.has_organization_export_access(target_organization_id) then
        raise exception 'You do not have permission to export this organization.' using errcode = '42501';
      end if;
    when 'organization.lifecycle' then
      configured_limit := 10;
      if not private.has_organization_lifecycle_access(target_organization_id) then
        raise exception 'Only an organization owner can change this lifecycle.' using errcode = '42501';
      end if;
    when 'organization.recovery_drill' then
      configured_limit := 10;
      if not private.has_organization_recovery_manage_access(target_organization_id) then
        raise exception 'Only an owner can record a recovery drill.' using errcode = '42501';
      end if;
    else
      raise exception 'Unsupported organization rate-limit action.' using errcode = '22023';
  end case;

  current_window_ends_at := current_window_start + interval '1 hour';

  delete from public.organization_rate_limit_windows rate_window
  where rate_window.window_started_at < current_window_start - interval '2 days';

  insert into public.organization_rate_limit_windows (
    organization_id,
    profile_id,
    action_code,
    window_started_at,
    request_count
  )
  values (
    target_organization_id,
    (select auth.uid()),
    normalized_action_code,
    current_window_start,
    1
  )
  on conflict (organization_id, profile_id, action_code, window_started_at)
  do update
    set request_count = public.organization_rate_limit_windows.request_count + 1,
        updated_at = now()
  where public.organization_rate_limit_windows.request_count < configured_limit
  returning request_count into observed_request_count;

  if observed_request_count is null then
    select rate_window.request_count
    into observed_request_count
    from public.organization_rate_limit_windows rate_window
    where rate_window.organization_id = target_organization_id
      and rate_window.profile_id = (select auth.uid())
      and rate_window.action_code = normalized_action_code
      and rate_window.window_started_at = current_window_start;
  end if;

  return jsonb_build_object(
    'allowed', coalesce(observed_request_count, configured_limit) <= configured_limit,
    'limit', configured_limit,
    'remaining', greatest(configured_limit - coalesce(observed_request_count, configured_limit), 0),
    'retry_after_seconds', greatest(
      floor(extract(epoch from current_window_ends_at - clock_timestamp()))::integer,
      0
    )
  );
end;
$$;


ALTER FUNCTION "private"."consume_organization_rate_limit"("target_organization_id" "uuid", "target_action_code" "text") OWNER TO "postgres";

--
-- Name: create_catalog_product("uuid", "uuid", "text", "text", "text", "text", "text", bigint, bigint, boolean, "text", "uuid"[], "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_catalog_product"("target_organization_id" "uuid", "target_category_id" "uuid", "target_name" "text", "target_description" "text", "target_product_type" "text", "target_sku" "text", "target_barcode" "text", "target_price_minor" bigint, "target_cost_minor" bigint, "target_track_inventory" boolean, "target_unit" "text", "target_store_ids" "uuid"[], "target_variants" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  new_product_id uuid;
  requested_store_count integer;
  valid_store_count integer;
  variant_count integer;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'products.manage')) then
    raise exception 'Product management permission is required.' using errcode = '42501';
  end if;

  if target_category_id is not null and not exists (
    select 1
    from public.categories category
    where category.id = target_category_id
      and category.organization_id = target_organization_id
      and not category.is_archived
  ) then
    raise exception 'Select an active category in this organization.' using errcode = '23503';
  end if;

  if target_store_ids is null or cardinality(target_store_ids) = 0 then
    raise exception 'Select at least one active store.' using errcode = '23514';
  end if;

  select count(distinct requested_store_id)
  into requested_store_count
  from unnest(target_store_ids) as requested_store_id;

  select count(*)
  into valid_store_count
  from public.stores store
  where store.organization_id = target_organization_id
    and store.id = any(target_store_ids)
    and store.is_active;

  if requested_store_count <> valid_store_count then
    raise exception 'Every selected store must be active and belong to this organization.'
      using errcode = '23503';
  end if;

  if jsonb_typeof(coalesce(target_variants, '[]'::jsonb)) <> 'array' then
    raise exception 'Variants must be supplied as a JSON array.' using errcode = '22023';
  end if;

  variant_count := jsonb_array_length(coalesce(target_variants, '[]'::jsonb));

  if target_product_type = 'simple' and variant_count <> 0 then
    raise exception 'Simple products cannot contain variants.' using errcode = '23514';
  end if;

  if target_product_type = 'variable' and variant_count not between 1 and 100 then
    raise exception 'Variable products require between 1 and 100 variants.'
      using errcode = '23514';
  end if;

  if (
    coalesce(target_cost_minor, 0) <> 0
    or exists (
      select 1
      from jsonb_array_elements(coalesce(target_variants, '[]'::jsonb)) variant
      where coalesce((variant ->> 'cost_minor')::bigint, 0) <> 0
    )
  ) and not (select private.has_permission(
    target_organization_id,
    'products.view_cost'
  )) then
    raise exception 'Product cost permission is required.' using errcode = '42501';
  end if;

  insert into public.products (
    organization_id,
    category_id,
    name,
    description,
    product_type,
    sku,
    barcode,
    price_minor,
    cost_minor,
    track_inventory,
    unit
  )
  values (
    target_organization_id,
    target_category_id,
    trim(target_name),
    nullif(trim(target_description), ''),
    target_product_type,
    nullif(upper(trim(target_sku)), ''),
    nullif(trim(target_barcode), ''),
    target_price_minor,
    target_cost_minor,
    target_track_inventory,
    lower(trim(target_unit))
  )
  returning id into new_product_id;

  if target_product_type = 'variable' then
    insert into public.product_variants (
      organization_id,
      product_id,
      name,
      option_values,
      sku,
      barcode,
      price_minor,
      cost_minor,
      sort_order
    )
    select
      target_organization_id,
      new_product_id,
      trim(variant.name),
      coalesce(variant.option_values, '{}'::jsonb),
      nullif(upper(trim(variant.sku)), ''),
      nullif(trim(variant.barcode), ''),
      variant.price_minor,
      variant.cost_minor,
      variant.sort_order
    from jsonb_to_recordset(target_variants) as variant(
      name text,
      option_values jsonb,
      sku text,
      barcode text,
      price_minor bigint,
      cost_minor bigint,
      sort_order integer
    );
  end if;

  insert into public.product_store_settings (
    organization_id,
    store_id,
    product_id,
    is_available
  )
  select
    target_organization_id,
    selected_store_id,
    new_product_id,
    true
  from (
    select distinct unnest(target_store_ids) as selected_store_id
  ) selected_stores;

  return new_product_id;
end;
$$;


ALTER FUNCTION "private"."create_catalog_product"("target_organization_id" "uuid", "target_category_id" "uuid", "target_name" "text", "target_description" "text", "target_product_type" "text", "target_sku" "text", "target_barcode" "text", "target_price_minor" bigint, "target_cost_minor" bigint, "target_track_inventory" boolean, "target_unit" "text", "target_store_ids" "uuid"[], "target_variants" "jsonb") OWNER TO "postgres";

--
-- Name: create_catalog_product_v2("uuid", "uuid", "text", "text", "text", "text", "text", bigint, bigint, boolean, "text", "uuid"[], "jsonb", "text", boolean, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_catalog_product_v2"("target_organization_id" "uuid", "target_category_id" "uuid", "target_name" "text", "target_description" "text", "target_product_type" "text", "target_sku" "text", "target_barcode" "text", "target_price_minor" bigint, "target_cost_minor" bigint, "target_track_inventory" boolean, "target_unit" "text", "target_store_ids" "uuid"[], "target_variants" "jsonb", "target_image_url" "text", "target_is_variable_price" boolean, "target_allow_fractional_quantity" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare new_product_id uuid; normalized_type text;
begin
  normalized_type := case when target_product_type = 'composite' then 'simple' else target_product_type end;
  if target_product_type = 'composite'
    and jsonb_array_length(coalesce(target_variants, '[]'::jsonb)) <> 0 then
    raise exception 'Composite products cannot contain saleable variants.' using errcode = '23514';
  end if;
  if target_product_type = 'composite' and not target_track_inventory then
    raise exception 'Composite products must track inventory to record component movements.' using errcode = '23514';
  end if;
  new_product_id := private.create_catalog_product(
    target_organization_id, target_category_id, target_name, target_description,
    normalized_type, target_sku, target_barcode, target_price_minor,
    target_cost_minor, target_track_inventory, target_unit, target_store_ids, target_variants
  );
  update public.products
  set image_url = nullif(btrim(target_image_url), ''),
      is_variable_price = coalesce(target_is_variable_price, false),
      allow_fractional_quantity = coalesce(target_allow_fractional_quantity, false),
      is_composite = target_product_type = 'composite'
  where id = new_product_id and organization_id = target_organization_id;
  return new_product_id;
end;
$$;


ALTER FUNCTION "private"."create_catalog_product_v2"("target_organization_id" "uuid", "target_category_id" "uuid", "target_name" "text", "target_description" "text", "target_product_type" "text", "target_sku" "text", "target_barcode" "text", "target_price_minor" bigint, "target_cost_minor" bigint, "target_track_inventory" boolean, "target_unit" "text", "target_store_ids" "uuid"[], "target_variants" "jsonb", "target_image_url" "text", "target_is_variable_price" boolean, "target_allow_fractional_quantity" boolean) OWNER TO "postgres";

--
-- Name: create_direct_stock_transfer("uuid", "uuid", "uuid", "jsonb", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_direct_stock_transfer"("target_organization_id" "uuid", "target_source_store_id" "uuid", "target_destination_store_id" "uuid", "target_lines" "jsonb", "target_note" "text", "target_operation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_id uuid;
  destination_actor_id uuid;
  existing_transfer public.stock_transfers%rowtype;
  source_level public.inventory_levels%rowtype;
  product_row record;
  line jsonb;
  transfer_id uuid;
  transfer_number bigint;
  normalized_note text;
  requested_payload jsonb;
  persisted_payload jsonb;
begin
  if (select auth.uid()) is null
     or (
       not (select private.has_permission(target_organization_id, 'inventory.manage'))
       and not (select private.has_all_inventory_capabilities(
         target_organization_id,
         array['inventory.transfer.create', 'inventory.transfer.send']::text[]
       ))
     ) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'A stable transfer operation ID is required.' using errcode = '23514';
  end if;

  if target_source_store_id is null
     or target_destination_store_id is null
     or target_source_store_id = target_destination_store_id
     or target_lines is null
     or jsonb_typeof(target_lines) <> 'array'
     or jsonb_array_length(target_lines) not between 1 and 100
     or (target_note is not null and char_length(btrim(target_note)) > 500) then
    raise exception 'Choose two different stores, one to 100 items, and a valid note.' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(target_lines) transfer_line(value)
    where jsonb_typeof(transfer_line.value) <> 'object'
      or coalesce(transfer_line.value ->> 'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or (nullif(transfer_line.value ->> 'variant_id', '') is not null
        and nullif(transfer_line.value ->> 'variant_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
      or coalesce(transfer_line.value ->> 'quantity', '') !~ '^\d+(\.\d{1,3})?$'
      or (transfer_line.value ->> 'quantity')::numeric <= 0
  )
  or (select count(*) from jsonb_array_elements(target_lines)) <> (
    select count(distinct format('%s|%s', value ->> 'product_id', coalesce(nullif(value ->> 'variant_id', ''), '')))
    from jsonb_array_elements(target_lines)
  ) then
    raise exception 'Transfer lines must contain unique, valid items and positive quantities.' using errcode = '23514';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'product_id', normalized.product_id,
        'variant_id', normalized.variant_id,
        'quantity', normalized.quantity
      )
      order by normalized.product_id, normalized.variant_id
    ),
    '[]'::jsonb
  )
  into requested_payload
  from (
    select
      lower(btrim(value ->> 'product_id')) as product_id,
      nullif(lower(btrim(value ->> 'variant_id')), '') as variant_id,
      ((value ->> 'quantity')::numeric(14,3))::text as quantity
    from jsonb_array_elements(target_lines)
  ) normalized;

  if not exists (
    select 1
    from public.stores store
    where store.organization_id = target_organization_id
      and store.id = target_source_store_id
      and store.is_active
  ) or not exists (
    select 1
    from public.stores store
    where store.organization_id = target_organization_id
      and store.id = target_destination_store_id
      and store.is_active
  ) then
    raise exception 'Choose active source and destination stores in this organization.' using errcode = '23514';
  end if;

  actor_id := private.inventory_actor(target_organization_id, target_source_store_id);
  destination_actor_id := private.inventory_actor(target_organization_id, target_destination_store_id);
  if actor_id is null or destination_actor_id is null then
    raise exception 'An active employee with access to both stores is required for this transfer.' using errcode = '42501';
  end if;

  normalized_note := nullif(btrim(target_note), '');
  select *
  into existing_transfer
  from public.stock_transfers transfer
  where transfer.organization_id = target_organization_id
    and transfer.operation_id = target_operation_id
  for update;

  if found then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'product_id', existing_line.product_id,
          'variant_id', existing_line.variant_id,
          'quantity', existing_line.quantity::text
        )
        order by existing_line.product_id, existing_line.variant_id
      ),
      '[]'::jsonb
    )
    into persisted_payload
    from public.stock_transfer_lines existing_line
    where existing_line.organization_id = target_organization_id
      and existing_line.stock_transfer_id = existing_transfer.id;

    if existing_transfer.stock_request_id is null
       and existing_transfer.source_store_id = target_source_store_id
       and existing_transfer.destination_store_id = target_destination_store_id
       and existing_transfer.transferred_by_employee_id = actor_id
       and existing_transfer.note is not distinct from normalized_note
       and persisted_payload = requested_payload then
      return existing_transfer.id;
    end if;

    raise exception 'This operation ID is already assigned to a different transfer.' using errcode = '23505';
  end if;

  transfer_number := nextval('private.tindio_stock_transfer_number_sequence'::regclass);
  insert into public.stock_transfers (
    organization_id,
    transfer_number,
    operation_id,
    source_store_id,
    destination_store_id,
    stock_request_id,
    status,
    note,
    transferred_by_employee_id
  )
  values (
    target_organization_id,
    transfer_number,
    target_operation_id,
    target_source_store_id,
    target_destination_store_id,
    null,
    'in_transit',
    normalized_note,
    actor_id
  )
  returning id into transfer_id;

  for line in select value from jsonb_array_elements(target_lines)
  loop
    select product.id, product.name, variant.id as variant_id
    into product_row
    from public.products product
    left join public.product_variants variant
      on variant.id = nullif(line ->> 'variant_id', '')::uuid
      and variant.product_id = product.id
      and variant.organization_id = product.organization_id
      and variant.is_active
    where product.id = (line ->> 'product_id')::uuid
      and product.organization_id = target_organization_id
      and product.status = 'active'
      and product.track_inventory
      and (nullif(line ->> 'variant_id', '') is null or variant.id is not null);

    if product_row.id is null then
      raise exception 'Every transfer item must be an active tracked product in this organization.' using errcode = '23514';
    end if;

    if not exists (
      select 1
      from public.product_store_settings setting
      where setting.organization_id = target_organization_id
        and setting.product_id = product_row.id
        and setting.store_id in (target_source_store_id, target_destination_store_id)
        and setting.is_available
      group by setting.product_id
      having count(*) = 2
    ) then
      raise exception 'Each transfer item must be available in both stores.' using errcode = '23514';
    end if;

    select *
    into source_level
    from public.inventory_levels level
    where level.organization_id = target_organization_id
      and level.store_id = target_source_store_id
      and level.product_id = product_row.id
      and level.variant_id is not distinct from nullif(line ->> 'variant_id', '')::uuid
    for update;

    if source_level.id is null
       or source_level.quantity < (line ->> 'quantity')::numeric(14,3) then
      raise exception 'Source stock is insufficient for this transfer.' using errcode = '23514';
    end if;

    if not exists (
      select 1
      from public.inventory_levels level
      where level.organization_id = target_organization_id
        and level.store_id = target_destination_store_id
        and level.product_id = product_row.id
        and level.variant_id is not distinct from nullif(line ->> 'variant_id', '')::uuid
    ) then
      raise exception 'The destination stock projection is not initialized for one transfer item.' using errcode = '23514';
    end if;

    insert into public.stock_transfer_lines (
      organization_id,
      stock_transfer_id,
      stock_request_line_id,
      product_id,
      variant_id,
      quantity,
      unit_cost_minor
    )
    values (
      target_organization_id,
      transfer_id,
      null,
      product_row.id,
      nullif(line ->> 'variant_id', '')::uuid,
      (line ->> 'quantity')::numeric(14,3),
      source_level.average_cost_minor
    );

    -- Transfers always require real source stock. The POS negative-stock
    -- policy is deliberately not consulted for this operational command.
    perform private.apply_inventory_change_v2(
      target_organization_id,
      target_source_store_id,
      product_row.id,
      nullif(line ->> 'variant_id', '')::uuid,
      -(line ->> 'quantity')::numeric(14,3),
      'TRANSFER_OUT',
      actor_id,
      format('Direct transfer TR-%s sent', lpad(transfer_number::text, 6, '0')),
      'stock_transfer',
      transfer_id,
      source_level.average_cost_minor
    );
  end loop;

  perform private.write_audit_log(
    target_organization_id,
    'STOCK_TRANSFER_SENT',
    'inventory.manage',
    actor_id,
    null,
    target_source_store_id,
    null,
    null,
    null,
    normalized_note,
    jsonb_build_object(
      'stock_transfer_id', transfer_id,
      'transfer_number', transfer_number,
      'source_store_id', target_source_store_id,
      'destination_store_id', target_destination_store_id,
      'operation_id', target_operation_id,
      'lines', requested_payload
    )
  );

  return transfer_id;
end;
$_$;


ALTER FUNCTION "private"."create_direct_stock_transfer"("target_organization_id" "uuid", "target_source_store_id" "uuid", "target_destination_store_id" "uuid", "target_lines" "jsonb", "target_note" "text", "target_operation_id" "uuid") OWNER TO "postgres";

--
-- Name: create_inventory_adjustment_reason("uuid", "text", "text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_inventory_adjustment_reason"("target_organization_id" "uuid", "target_code" "text", "target_name" "text", "target_movement_type" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare reason_id uuid;
begin
  if (select auth.uid()) is null or not (select private.has_permission(target_organization_id, 'inventory.manage')) then raise exception 'Inventory permission is required.' using errcode = '42501'; end if;
  insert into public.inventory_adjustment_reasons (organization_id, code, name, movement_type)
  values (target_organization_id, upper(btrim(target_code)), btrim(target_name), target_movement_type)
  returning id into reason_id;
  return reason_id;
end;
$$;


ALTER FUNCTION "private"."create_inventory_adjustment_reason"("target_organization_id" "uuid", "target_code" "text", "target_name" "text", "target_movement_type" "text") OWNER TO "postgres";

--
-- Name: create_inventory_count_batch("uuid", "text", "text", "uuid"[], "text", "text", boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_inventory_count_batch"("target_organization_id" "uuid", "target_name" "text", "target_note" "text", "target_store_ids" "uuid"[], "target_count_mode" "text", "target_sort_mode" "text", "target_include_zero_stock" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  batch_id uuid;
  target_store_id uuid;
  count_id uuid;
  normalized_store_ids uuid[];
begin
  normalized_store_ids := array(
    select distinct store_id
    from unnest(coalesce(target_store_ids, array[]::uuid[])) store_id
    order by store_id
  );
  if coalesce(cardinality(normalized_store_ids), 0) < 2
    or cardinality(normalized_store_ids) > 50 then
    raise exception 'Choose between two and fifty stores for one count batch.' using errcode = '22023';
  end if;
  if target_count_mode not in ('standard', 'blind')
    or target_sort_mode not in ('category_name', 'supplier_name', 'sku', 'barcode', 'product_name') then
    raise exception 'Choose valid count batch options.' using errcode = '22023';
  end if;
  if char_length(btrim(coalesce(target_name, ''))) = 0 then
    raise exception 'Enter a count batch name.' using errcode = '22023';
  end if;

  actor_id := private.inventory_count_actor(target_organization_id, normalized_store_ids[1]);
  foreach target_store_id in array normalized_store_ids loop
    perform private.inventory_count_actor(target_organization_id, target_store_id);
  end loop;

  insert into public.inventory_count_batches (
    organization_id, name, note, created_by_employee_id
  ) values (
    target_organization_id,
    btrim(target_name),
    nullif(btrim(target_note), ''),
    actor_id
  ) returning id into batch_id;

  foreach target_store_id in array normalized_store_ids loop
    count_id := private.create_inventory_count_plan(
      target_organization_id,
      target_store_id,
      target_note,
      target_count_mode,
      'full_store',
      null,
      '[]'::jsonb,
      target_sort_mode,
      target_include_zero_stock
    );
    insert into public.inventory_count_batch_documents (
      organization_id, inventory_count_batch_id, inventory_count_id, store_id
    ) values (
      target_organization_id, batch_id, count_id, target_store_id
    );
  end loop;

  perform private.write_audit_log(
    target_organization_id,
    'INVENTORY_COUNT_BATCH_PREPARED',
    'inventory.count',
    actor_id,
    null,
    null,
    null,
    null,
    null,
    target_note,
    jsonb_build_object(
      'inventory_count_batch_id', batch_id,
      'name', btrim(target_name),
      'store_count', cardinality(normalized_store_ids),
      'count_mode', target_count_mode,
      'sort_mode', target_sort_mode,
      'include_zero_stock', target_include_zero_stock
    )
  );
  return batch_id;
end;
$$;


ALTER FUNCTION "private"."create_inventory_count_batch"("target_organization_id" "uuid", "target_name" "text", "target_note" "text", "target_store_ids" "uuid"[], "target_count_mode" "text", "target_sort_mode" "text", "target_include_zero_stock" boolean) OWNER TO "postgres";

--
-- Name: create_inventory_count_draft("uuid", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_inventory_count_draft"("target_organization_id" "uuid", "target_store_id" "uuid", "target_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  count_id uuid;
  created_count_number bigint;
begin
  actor_id := private.inventory_count_actor(target_organization_id, target_store_id);
  insert into public.inventory_counts (organization_id, store_id, status, note, started_by_employee_id)
  values (target_organization_id, target_store_id, 'draft', nullif(btrim(target_note), ''), actor_id)
  returning id, count_number into count_id, created_count_number;
  perform private.write_audit_log(
    target_organization_id, 'INVENTORY_COUNT_DRAFT_CREATED', 'inventory.count', actor_id,
    null, target_store_id, null, null, null, target_note,
    jsonb_build_object('inventory_count_id', count_id, 'count_number', created_count_number)
  );
  return count_id;
end;
$$;


ALTER FUNCTION "private"."create_inventory_count_draft"("target_organization_id" "uuid", "target_store_id" "uuid", "target_note" "text") OWNER TO "postgres";

--
-- Name: create_inventory_count_plan("uuid", "uuid", "text", "text", "text", "uuid", "jsonb", "text", boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_inventory_count_plan"("target_organization_id" "uuid", "target_store_id" "uuid", "target_note" "text", "target_count_mode" "text", "target_scope_type" "text", "target_scope_reference_id" "uuid", "target_selected_items" "jsonb", "target_sort_mode" "text", "target_include_zero_stock" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  count_id uuid;
  created_count_number bigint;
  prepared_line_count integer;
begin
  actor_id := private.inventory_count_actor(target_organization_id, target_store_id);

  if target_count_mode not in ('standard', 'blind')
    or target_scope_type not in ('full_store', 'category', 'supplier', 'selected')
    or target_sort_mode not in ('category_name', 'supplier_name', 'sku', 'barcode', 'product_name') then
    raise exception 'Choose valid inventory-count preparation options.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(target_selected_items, '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(target_selected_items, '[]'::jsonb)) > 500 then
    raise exception 'Choose no more than 500 products for one count.' using errcode = '22023';
  end if;
  if target_scope_type in ('category', 'supplier') and target_scope_reference_id is null then
    raise exception 'Choose the category or supplier for this count.' using errcode = '22023';
  end if;
  if target_scope_type = 'selected' and jsonb_array_length(coalesce(target_selected_items, '[]'::jsonb)) = 0 then
    raise exception 'Choose at least one product for this count.' using errcode = '22023';
  end if;

  insert into public.inventory_counts (
    organization_id, store_id, status, note, started_by_employee_id,
    count_mode, scope_type, scope_reference_id, scope_selection, sort_mode, include_zero_stock
  ) values (
    target_organization_id, target_store_id, 'draft', nullif(btrim(target_note), ''), actor_id,
    target_count_mode, target_scope_type, target_scope_reference_id,
    coalesce(target_selected_items, '[]'::jsonb), target_sort_mode, target_include_zero_stock
  ) returning id, count_number into count_id, created_count_number;

  with candidates as (
    select
      product.id as product_id,
      case when product.product_type = 'variable' then variant.id else null end as variant_id,
      product.name as product_name,
      case when product.product_type = 'variable' then variant.name else null end as variant_name,
      coalesce(category.name, 'Uncategorized') as category_name,
      coalesce(case when product.product_type = 'variable' then variant.sku end, product.sku) as sku,
      coalesce(case when product.product_type = 'variable' then variant.barcode end, product.barcode) as barcode,
      product.unit,
      coalesce(level.quantity, 0)::numeric(14,3) as expected_quantity,
      coalesce((
        select min(supplier.name)
        from public.purchase_order_lines purchase_line
        join public.purchase_orders purchase_order
          on purchase_order.id = purchase_line.purchase_order_id
         and purchase_order.organization_id = purchase_line.organization_id
        join public.suppliers supplier
          on supplier.id = purchase_order.supplier_id
         and supplier.organization_id = purchase_order.organization_id
        where purchase_line.organization_id = target_organization_id
          and purchase_order.store_id = target_store_id
          and purchase_line.product_id = product.id
      ), '') as supplier_name
    from public.products product
    join public.product_store_settings setting
      on setting.product_id = product.id
     and setting.organization_id = product.organization_id
     and setting.store_id = target_store_id
    left join public.categories category
      on category.id = product.category_id
     and category.organization_id = product.organization_id
    left join public.product_variants variant
      on variant.product_id = product.id
     and variant.organization_id = product.organization_id
     and product.product_type = 'variable'
     and variant.is_active
    left join public.inventory_levels level
      on level.organization_id = product.organization_id
     and level.store_id = target_store_id
     and level.product_id = product.id
     and level.variant_id is not distinct from case when product.product_type = 'variable' then variant.id else null end
    where product.organization_id = target_organization_id
      and product.status = 'active'
      and product.track_inventory
      and (product.product_type <> 'variable' or variant.id is not null)
      and (target_include_zero_stock or coalesce(level.quantity, 0) <> 0)
      and (
        target_scope_type = 'full_store'
        or (target_scope_type = 'category' and product.category_id = target_scope_reference_id)
        or (target_scope_type = 'supplier' and exists (
          select 1
          from public.purchase_order_lines scoped_line
          join public.purchase_orders scoped_order
            on scoped_order.id = scoped_line.purchase_order_id
           and scoped_order.organization_id = scoped_line.organization_id
          where scoped_line.organization_id = target_organization_id
            and scoped_order.store_id = target_store_id
            and scoped_order.supplier_id = target_scope_reference_id
            and scoped_line.product_id = product.id
        ))
        or (target_scope_type = 'selected' and exists (
          select 1
          from jsonb_array_elements(coalesce(target_selected_items, '[]'::jsonb)) selected
          where selected ->> 'product_id' = product.id::text
            and nullif(selected ->> 'variant_id', '') is not distinct from
              (case when product.product_type = 'variable' then variant.id::text else null end)
        ))
      )
  ), ordered as (
    select candidates.*,
      row_number() over (order by
        case when target_sort_mode = 'category_name' then lower(category_name) end nulls last,
        case when target_sort_mode = 'supplier_name' then lower(supplier_name) end nulls last,
        case when target_sort_mode = 'sku' then lower(coalesce(sku, '')) end nulls last,
        case when target_sort_mode = 'barcode' then lower(coalesce(barcode, '')) end nulls last,
        lower(product_name), lower(coalesce(variant_name, '')), product_id, variant_id nulls first
      ) as sort_order
    from candidates
  )
  insert into public.inventory_count_lines (
    organization_id, inventory_count_id, product_id, variant_id,
    expected_quantity, counted_quantity, product_name_snapshot, variant_name_snapshot,
    category_name_snapshot, sku_snapshot, barcode_snapshot, unit_snapshot, line_sort_order
  )
  select
    target_organization_id, count_id, product_id, variant_id,
    expected_quantity, null, product_name, variant_name,
    category_name, sku, barcode, unit, sort_order
  from ordered
  order by sort_order;

  get diagnostics prepared_line_count = row_count;
  if prepared_line_count = 0 then
    raise exception 'No active tracked products match this count scope.' using errcode = '22023';
  end if;

  perform private.write_audit_log(
    target_organization_id, 'INVENTORY_COUNT_PREPARED', 'inventory.count', actor_id,
    null, target_store_id, null, null, null, target_note,
    jsonb_build_object(
      'inventory_count_id', count_id,
      'count_number', created_count_number,
      'count_mode', target_count_mode,
      'scope_type', target_scope_type,
      'sort_mode', target_sort_mode,
      'include_zero_stock', target_include_zero_stock,
      'line_count', prepared_line_count
    )
  );
  return count_id;
end;
$$;


ALTER FUNCTION "private"."create_inventory_count_plan"("target_organization_id" "uuid", "target_store_id" "uuid", "target_note" "text", "target_count_mode" "text", "target_scope_type" "text", "target_scope_reference_id" "uuid", "target_selected_items" "jsonb", "target_sort_mode" "text", "target_include_zero_stock" boolean) OWNER TO "postgres";

--
-- Name: create_purchase_order("uuid", "uuid", "uuid", "text", "date", "jsonb", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_purchase_order"("target_organization_id" "uuid", "target_store_id" "uuid", "target_supplier_id" "uuid", "target_notes" "text", "target_expected_at" "date", "target_lines" "jsonb", "target_operation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_id uuid;
  order_id uuid;
  existing_order public.purchase_orders%rowtype;
  line jsonb;
  product_row record;
  purchase_unit_row record;
  next_number bigint;
  normalized_note text;
  requested_lines jsonb;
  persisted_lines jsonb;
begin
  if (select auth.uid()) is null
     or (not (select private.has_permission(target_organization_id, 'inventory.manage')) and not (select private.has_inventory_capability(target_organization_id, 'purchasing.po.create'))) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'A stable purchase-order operation ID is required.' using errcode = '23514';
  end if;

  if target_lines is null
     or jsonb_typeof(target_lines) <> 'array'
     or jsonb_array_length(target_lines) not between 1 and 100 then
    raise exception 'A purchase order needs one to 100 items.' using errcode = '23514';
  end if;

  for line in select value from jsonb_array_elements(target_lines)
  loop
    if coalesce(line ->> 'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or (nullif(line ->> 'variant_id', '') is not null and coalesce(line ->> 'variant_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
       or coalesce(line ->> 'purchase_unit_code', '') !~ '^[A-Za-z0-9][A-Za-z0-9 _-]{0,23}$'
       or coalesce(line ->> 'quantity', '') !~ '^\d+(\.\d{1,3})?$'
       or (line ->> 'quantity')::numeric <= 0
       or coalesce(line ->> 'unit_cost_minor', '') !~ '^\d+$' then
      raise exception 'Purchase order items, units, quantities, and costs must be valid.' using errcode = '23514';
    end if;
  end loop;

  if exists (
    select 1
    from (
      select lower(btrim(value ->> 'product_id')) as product_id,
             coalesce(nullif(lower(btrim(value ->> 'variant_id')), ''), '') as variant_id,
             count(*) as line_count
      from jsonb_array_elements(target_lines)
      group by 1, 2
    ) duplicate_line
    where duplicate_line.line_count > 1
  ) then
    raise exception 'Each item can appear only once in a purchase order.' using errcode = '23514';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'product_id', normalized.product_id,
        'variant_id', normalized.variant_id,
        'purchase_unit_code', normalized.purchase_unit_code,
        'quantity', normalized.quantity,
        'unit_cost_minor', normalized.unit_cost_minor
      ) order by normalized.product_id, normalized.variant_id
    ),
    '[]'::jsonb
  )
  into requested_lines
  from (
    select lower(btrim(value ->> 'product_id')) as product_id,
           coalesce(nullif(lower(btrim(value ->> 'variant_id')), ''), '') as variant_id,
           lower(btrim(value ->> 'purchase_unit_code')) as purchase_unit_code,
           ((value ->> 'quantity')::numeric(14,3))::text as quantity,
           ((value ->> 'unit_cost_minor')::bigint)::text as unit_cost_minor
    from jsonb_array_elements(target_lines)
  ) normalized;

  normalized_note := nullif(btrim(target_notes), '');
  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for this store.' using errcode = '42501';
  end if;

  select * into existing_order
  from public.purchase_orders purchase_order
  where purchase_order.organization_id = target_organization_id
    and purchase_order.operation_id = target_operation_id
  for update;

  if found then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'product_id', purchase_line.product_id::text,
          'variant_id', coalesce(purchase_line.variant_id::text, ''),
          'purchase_unit_code', purchase_line.purchase_unit_code_snapshot,
          'quantity', purchase_line.ordered_quantity::text,
          'unit_cost_minor', purchase_line.unit_cost_minor::text
        ) order by purchase_line.product_id::text, coalesce(purchase_line.variant_id::text, '')
      ),
      '[]'::jsonb
    ) into persisted_lines
    from public.purchase_order_lines purchase_line
    where purchase_line.organization_id = target_organization_id
      and purchase_line.purchase_order_id = existing_order.id;

    if existing_order.store_id = target_store_id
       and existing_order.supplier_id = target_supplier_id
       and existing_order.created_by_employee_id = actor_id
       and existing_order.requested_expected_at is not distinct from target_expected_at
       and existing_order.notes is not distinct from normalized_note
       and persisted_lines = requested_lines then
      return existing_order.id;
    end if;

    raise exception 'This operation ID is already assigned to a different purchase order request.' using errcode = '23505';
  end if;

  if not exists (
    select 1
    from public.suppliers supplier
    where supplier.id = target_supplier_id
      and supplier.organization_id = target_organization_id
      and supplier.is_active
  ) then
    raise exception 'Choose an active supplier.' using errcode = '23514';
  end if;

  next_number := nextval('private.tindio_purchase_order_number_sequence'::regclass);
  insert into public.purchase_orders (
    organization_id, store_id, supplier_id, order_number, status, notes,
    expected_at, requested_expected_at, ordered_at, created_by_employee_id, operation_id
  ) values (
    target_organization_id, target_store_id, target_supplier_id, next_number,
    'ordered', normalized_note, target_expected_at, target_expected_at, now(), actor_id, target_operation_id
  ) returning id into order_id;

  for line in select value from jsonb_array_elements(target_lines)
  loop
    select product.name as product_name, variant.name as variant_name
    into product_row
    from public.products product
    left join public.product_variants variant
      on variant.id = nullif(line ->> 'variant_id', '')::uuid
      and variant.product_id = product.id
      and variant.organization_id = product.organization_id
    where product.id = (line ->> 'product_id')::uuid
      and product.organization_id = target_organization_id
      and product.status = 'active'
      and product.track_inventory
      and (nullif(line ->> 'variant_id', '') is null or variant.id is not null)
      and exists (
        select 1 from public.product_store_settings store_setting
        where store_setting.organization_id = target_organization_id
          and store_setting.store_id = target_store_id
          and store_setting.product_id = product.id
          and store_setting.is_available
      );

    if not found then
      raise exception 'Every order item must be an active tracked item available in the receiving store.' using errcode = '23514';
    end if;

    select product_unit.unit_code, product_unit.unit_name, product_unit.factor_to_base
    into purchase_unit_row
    from public.product_units product_unit
    where product_unit.organization_id = target_organization_id
      and product_unit.product_id = (line ->> 'product_id')::uuid
      and product_unit.unit_code = lower(btrim(line ->> 'purchase_unit_code'))
      and (product_unit.is_purchase_unit or product_unit.is_base);

    if not found then
      raise exception 'Choose a configured purchase unit for every order item.' using errcode = '23514';
    end if;

    insert into public.purchase_order_lines (
      organization_id, purchase_order_id, product_id, variant_id,
      product_name_snapshot, variant_name_snapshot, unit_snapshot,
      purchase_unit_code_snapshot, purchase_unit_factor_to_base,
      ordered_quantity, unit_cost_minor
    ) values (
      target_organization_id, order_id, (line ->> 'product_id')::uuid,
      nullif(line ->> 'variant_id', '')::uuid, product_row.product_name,
      product_row.variant_name, purchase_unit_row.unit_name,
      purchase_unit_row.unit_code, purchase_unit_row.factor_to_base,
      (line ->> 'quantity')::numeric(14,3), (line ->> 'unit_cost_minor')::bigint
    );
  end loop;

  return order_id;
end;
$_$;


ALTER FUNCTION "private"."create_purchase_order"("target_organization_id" "uuid", "target_store_id" "uuid", "target_supplier_id" "uuid", "target_notes" "text", "target_expected_at" "date", "target_lines" "jsonb", "target_operation_id" "uuid") OWNER TO "postgres";

--
-- Name: create_stock_request("uuid", "uuid", "uuid", "text", "jsonb", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_stock_request"("target_organization_id" "uuid", "target_requesting_store_id" "uuid", "target_source_warehouse_id" "uuid", "target_note" "text", "target_lines" "jsonb", "target_operation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_id uuid;
  request_id uuid;
  request_number bigint;
  warehouse_store_id uuid;
  existing_request public.stock_requests%rowtype;
  product_row record;
  line jsonb;
  normalized_note text;
  requested_lines jsonb;
  persisted_lines jsonb;
begin
  if (select auth.uid()) is null
     or (
       not (select private.has_permission(target_organization_id, 'inventory.manage'))
       and not (select private.has_inventory_capability(target_organization_id, 'inventory.transfer.create'))
     ) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'A stable stock-request operation ID is required.' using errcode = '23514';
  end if;

  if target_lines is null
     or jsonb_typeof(target_lines) <> 'array'
     or jsonb_array_length(target_lines) not between 1 and 100
     or (target_note is not null and char_length(btrim(target_note)) > 500) then
    raise exception 'A stock request needs one to 100 items and valid notes.' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(target_lines) requested(value)
    where jsonb_typeof(requested.value) <> 'object'
      or coalesce(requested.value ->> 'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or (requested.value ? 'variant_id' and requested.value -> 'variant_id' <> 'null'::jsonb and coalesce(requested.value ->> 'variant_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
      or coalesce(requested.value ->> 'quantity', '') !~ '^\d+(\.\d{1,3})?$'
      or (requested.value ->> 'quantity')::numeric <= 0
  ) then
    raise exception 'Request lines need active items and positive quantities.' using errcode = '23514';
  end if;

  if exists (
    select 1
    from (
      select
        lower(btrim(value ->> 'product_id')) as product_id,
        coalesce(nullif(lower(btrim(value ->> 'variant_id')), ''), '') as variant_id,
        count(*) as line_count
      from jsonb_array_elements(target_lines)
      group by 1, 2
    ) duplicate_line
    where duplicate_line.line_count > 1
  ) then
    raise exception 'Each request item can appear only once.' using errcode = '23514';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'product_id', normalized.product_id,
        'variant_id', normalized.variant_id,
        'quantity', normalized.quantity
      )
      order by normalized.product_id, normalized.variant_id
    ),
    '[]'::jsonb
  )
  into requested_lines
  from (
    select
      lower(btrim(value ->> 'product_id')) as product_id,
      coalesce(nullif(lower(btrim(value ->> 'variant_id')), ''), '') as variant_id,
      ((value ->> 'quantity')::numeric(14,3))::text as quantity
    from jsonb_array_elements(target_lines)
  ) normalized;

  normalized_note := nullif(btrim(target_note), '');
  actor_id := private.inventory_actor(target_organization_id, target_requesting_store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for the requesting store.' using errcode = '42501';
  end if;

  select *
  into existing_request
  from public.stock_requests request_row
  where request_row.organization_id = target_organization_id
    and request_row.operation_id = target_operation_id
  for update;

  if found then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'product_id', request_line.product_id::text,
          'variant_id', coalesce(request_line.variant_id::text, ''),
          'quantity', request_line.requested_quantity::text
        )
        order by request_line.product_id::text, coalesce(request_line.variant_id::text, '')
      ),
      '[]'::jsonb
    )
    into persisted_lines
    from public.stock_request_lines request_line
    where request_line.organization_id = target_organization_id
      and request_line.stock_request_id = existing_request.id;

    if existing_request.requesting_store_id = target_requesting_store_id
       and existing_request.source_warehouse_id = target_source_warehouse_id
       and existing_request.requested_by_employee_id = actor_id
       and existing_request.note is not distinct from normalized_note
       and persisted_lines = requested_lines then
      return existing_request.id;
    end if;

    raise exception 'This operation ID is already assigned to a different stock request.' using errcode = '23505';
  end if;

  select warehouse.store_id
  into warehouse_store_id
  from public.supply_chain_warehouses warehouse
  where warehouse.id = target_source_warehouse_id
    and warehouse.organization_id = target_organization_id
    and warehouse.is_active;

  if warehouse_store_id is null or warehouse_store_id = target_requesting_store_id then
    raise exception 'Choose an active warehouse at a different stock location.' using errcode = '23514';
  end if;

  request_number := nextval('private.tindio_stock_request_number_sequence'::regclass);
  insert into public.stock_requests (
    organization_id,
    request_number,
    requesting_store_id,
    source_warehouse_id,
    note,
    requested_by_employee_id,
    operation_id
  )
  values (
    target_organization_id,
    request_number,
    target_requesting_store_id,
    target_source_warehouse_id,
    normalized_note,
    actor_id,
    target_operation_id
  )
  returning id into request_id;

  for line in select value from jsonb_array_elements(target_lines) order by value ->> 'product_id', coalesce(value ->> 'variant_id', '')
  loop
    select product.name as product_name, variant.name as variant_name, product.unit
    into product_row
    from public.products product
    left join public.product_variants variant
      on variant.id = nullif(line ->> 'variant_id', '')::uuid
      and variant.product_id = product.id
      and variant.organization_id = product.organization_id
    where product.id = (line ->> 'product_id')::uuid
      and product.organization_id = target_organization_id
      and product.status = 'active'
      and product.track_inventory
      and (nullif(line ->> 'variant_id', '') is null or variant.id is not null);

    if not found then
      raise exception 'Every request item must be an active tracked product.' using errcode = '23514';
    end if;

    if not exists (
      select 1
      from public.inventory_levels level
      where level.organization_id = target_organization_id
        and level.store_id = target_requesting_store_id
        and level.product_id = (line ->> 'product_id')::uuid
        and level.variant_id is not distinct from nullif(line ->> 'variant_id', '')::uuid
    ) then
      raise exception 'Initialize the destination stock projection for every requested item.' using errcode = '23514';
    end if;

    insert into public.stock_request_lines (
      organization_id,
      stock_request_id,
      product_id,
      variant_id,
      product_name_snapshot,
      variant_name_snapshot,
      unit_snapshot,
      requested_quantity
    )
    values (
      target_organization_id,
      request_id,
      (line ->> 'product_id')::uuid,
      nullif(line ->> 'variant_id', '')::uuid,
      product_row.product_name,
      product_row.variant_name,
      product_row.unit,
      (line ->> 'quantity')::numeric(14,3)
    );
  end loop;

  perform private.write_audit_log(
    target_organization_id,
    'STOCK_REQUEST_SUBMITTED',
    'inventory.manage',
    actor_id,
    null,
    target_requesting_store_id,
    null,
    null,
    null,
    normalized_note,
    jsonb_build_object('stock_request_id', request_id, 'request_number', request_number, 'source_warehouse_id', target_source_warehouse_id)
  );
  return request_id;
end;
$_$;


ALTER FUNCTION "private"."create_stock_request"("target_organization_id" "uuid", "target_requesting_store_id" "uuid", "target_source_warehouse_id" "uuid", "target_note" "text", "target_lines" "jsonb", "target_operation_id" "uuid") OWNER TO "postgres";

--
-- Name: create_supplier("uuid", "text", "text", "text", "text", "text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_supplier"("target_organization_id" "uuid", "target_name" "text", "target_contact_name" "text", "target_email" "text", "target_phone" "text", "target_address" "text", "target_notes" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ declare supplier_id uuid; begin
 if (select auth.uid()) is null or (not (select private.has_permission(target_organization_id, 'inventory.manage')) and not (select private.has_inventory_capability(target_organization_id, 'purchasing.suppliers.manage'))) then raise exception 'Inventory permission is required.' using errcode='42501'; end if;
 insert into public.suppliers (organization_id,name,contact_name,email,phone,address,notes) values (target_organization_id,nullif(btrim(target_name),''),nullif(btrim(target_contact_name),''),nullif(btrim(target_email),''),nullif(btrim(target_phone),''),nullif(btrim(target_address),''),nullif(btrim(target_notes),'')) returning id into supplier_id; return supplier_id; end; $$;


ALTER FUNCTION "private"."create_supplier"("target_organization_id" "uuid", "target_name" "text", "target_contact_name" "text", "target_email" "text", "target_phone" "text", "target_address" "text", "target_notes" "text") OWNER TO "postgres";

--
-- Name: create_supply_chain_warehouse("uuid", "uuid", "text", "text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."create_supply_chain_warehouse"("target_organization_id" "uuid", "target_store_id" "uuid", "target_code" "text", "target_name" "text", "target_notes" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor_id uuid; warehouse_id uuid;
begin
  if (select auth.uid()) is null or not (select private.has_permission(target_organization_id, 'inventory.manage')) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;
  if target_code is null or upper(btrim(target_code)) !~ '^[A-Z][A-Z0-9_-]{1,39}$'
    or target_name is null or char_length(btrim(target_name)) not between 2 and 120
    or (target_notes is not null and char_length(btrim(target_notes)) > 500) then
    raise exception 'Provide a warehouse code, name, and valid notes.' using errcode = '23514';
  end if;
  if not exists (select 1 from public.stores store where store.id = target_store_id and store.organization_id = target_organization_id and store.is_active) then
    raise exception 'Choose an active store stock location for this warehouse.' using errcode = '23514';
  end if;
  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then raise exception 'An assigned employee is required for the warehouse store.' using errcode = '42501'; end if;
  insert into public.supply_chain_warehouses (organization_id, store_id, code, name, notes, created_by_employee_id)
  values (target_organization_id, target_store_id, upper(btrim(target_code)), btrim(target_name), nullif(btrim(target_notes), ''), actor_id)
  returning id into warehouse_id;
  perform private.write_audit_log(target_organization_id, 'SUPPLY_CHAIN_WAREHOUSE_CREATED', 'inventory.manage', actor_id, null, target_store_id, null, null, null, null, jsonb_build_object('warehouse_id', warehouse_id));
  return warehouse_id;
end;
$_$;


ALTER FUNCTION "private"."create_supply_chain_warehouse"("target_organization_id" "uuid", "target_store_id" "uuid", "target_code" "text", "target_name" "text", "target_notes" "text") OWNER TO "postgres";

--
-- Name: current_employee_id("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."current_employee_id"("target_organization_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select employee.id
  from public.employees employee
  join public.organizations organization
    on organization.id = employee.organization_id
   and organization.status = 'active'
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
  order by employee.created_at
  limit 1;
$$;


ALTER FUNCTION "private"."current_employee_id"("target_organization_id" "uuid") OWNER TO "postgres";

