-- Name: current_organization_member_employee_id("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."current_organization_member_employee_id"("target_organization_id" "uuid") RETURNS "uuid"
