--
-- Name: decide_manager_approval("uuid", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."decide_manager_approval"("target_organization_id" "uuid", "target_approval_request_id" "uuid", "target_decision" "text") RETURNS TABLE("approval_request_id" "uuid", "decision" "text", "decided_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  request public.approval_requests%rowtype;
  required_permission text;
begin
  actor_employee_id := private.current_employee_id(target_organization_id);
  if actor_employee_id is null then
    raise exception 'An active employee is required.' using errcode = '42501';
  end if;
  if target_decision not in ('APPROVED', 'REJECTED') then
    raise exception 'Choose Approve or Reject.' using errcode = '23514';
  end if;

  select * into request from public.approval_requests approval_request
  where approval_request.organization_id = target_organization_id
    and approval_request.id = target_approval_request_id
  for update;

  if request.id is null then raise exception 'The approval request was not found.' using errcode = 'P0002'; end if;
  if request.status <> 'PENDING' or request.expires_at <= now() then
    if request.status = 'PENDING' then
      update public.approval_requests set status = 'EXPIRED', updated_at = now()
      where organization_id = target_organization_id and id = request.id;
      return query select request.id, 'EXPIRED'::text, now();
      return;
    end if;
    raise exception 'This approval request is no longer pending.' using errcode = '23514';
  end if;

  required_permission := private.approval_operation_permission(request.operation_code);
  if actor_employee_id = request.requested_by_employee_id
    or not private.employee_has_permission(target_organization_id, actor_employee_id, 'approvals.authorize')
    or not private.employee_has_permission(target_organization_id, actor_employee_id, required_permission)
    or not exists (
      select 1 from public.employee_stores employee_store
      where employee_store.organization_id = target_organization_id
        and employee_store.employee_id = actor_employee_id
        and employee_store.store_id = request.store_id
    ) then
    raise exception 'A qualified approver assigned to this store is required.' using errcode = '42501';
  end if;

  update public.approval_requests
  set status = target_decision,
      approved_by_employee_id = case when target_decision = 'APPROVED' then actor_employee_id else null end,
      decided_at = now(),
      updated_at = now()
  where organization_id = target_organization_id and id = request.id;

  perform private.write_audit_log(
    target_organization_id,
    case when target_decision = 'APPROVED' then 'APPROVAL_APPROVED' else 'APPROVAL_REJECTED' end,
    request.operation_code,
    actor_employee_id,
    request.requested_by_employee_id,
    request.store_id,
    request.register_id,
    request.id,
    request.requested_amount_minor,
    request.reason,
    jsonb_build_object('approval_path', 'REMOTE')
  );

  return query select request.id, target_decision, now();
end;
$$;


ALTER FUNCTION "private"."decide_manager_approval"("target_organization_id" "uuid", "target_approval_request_id" "uuid", "target_decision" "text") OWNER TO "postgres";

--
-- Name: default_cash_offline_policy(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."default_cash_offline_policy"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.payment_type = 'CASH' and new.offline_policy = 'disabled' then
    new.offline_policy := 'cash';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."default_cash_offline_policy"() OWNER TO "postgres";

--
-- Name: default_kitchen_station_for_category("uuid", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."default_kitchen_station_for_category"("target_organization_id" "uuid", "target_category_id" "uuid", "target_category_name" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select coalesce(
    (
      select route.station
      from public.kitchen_station_category_routes route
      where route.organization_id = $1
        and route.category_id = $2
    ),
    case
      when lower(coalesce($3, '')) ~ '(bar|beverage|drink|coffee|cocktail)' then 'BAR'
      when lower(coalesce($3, '')) ~ '(dessert|cake|pastry|ice[ -]?cream)' then 'DESSERT'
      else 'KITCHEN'
    end
  );
$_$;


ALTER FUNCTION "private"."default_kitchen_station_for_category"("target_organization_id" "uuid", "target_category_id" "uuid", "target_category_name" "text") OWNER TO "postgres";

--
-- Name: default_legacy_transfer_line_received_quantity(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."default_legacy_transfer_line_received_quantity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.received_quantity = 0 and exists (
    select 1
    from public.stock_transfers transfer
    where transfer.id = new.stock_transfer_id
      and transfer.status = 'completed'
      and transfer.received_by_employee_id is null
      and transfer.received_at is null
  ) then
    new.received_quantity := new.quantity;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."default_legacy_transfer_line_received_quantity"() OWNER TO "postgres";

--
-- Name: FUNCTION "default_legacy_transfer_line_received_quantity"(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."default_legacy_transfer_line_received_quantity"() IS 'Internal stock-transfer trigger procedure. Direct client execution is forbidden.';


--
-- Name: default_purchase_order_expected_at_from_supplier(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."default_purchase_order_expected_at_from_supplier"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.expected_at is null then
    select current_date + supplier.lead_time_days into new.expected_at
    from public.suppliers supplier
    where supplier.id = new.supplier_id and supplier.organization_id = new.organization_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."default_purchase_order_expected_at_from_supplier"() OWNER TO "postgres";

--
-- Name: delete_catalog_product_if_eligible("uuid", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."delete_catalog_product_if_eligible"("target_organization_id" "uuid", "target_product_id" "uuid", "target_confirmation_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_name text;
  existing_status text;
  actor_employee_id uuid;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'products.manage')) then
    raise exception 'Product management permission is required.' using errcode = '42501';
  end if;

  actor_employee_id := private.current_employee_id(target_organization_id);

  select product.name, product.status
  into existing_name, existing_status
  from public.products product
  where product.id = target_product_id
    and product.organization_id = target_organization_id
  for update;

  if not found then
    raise exception 'The product could not be found.' using errcode = '23503';
  end if;

  if existing_status <> 'archived' then
    raise exception 'Archive this product before deleting it permanently.' using errcode = '55000';
  end if;

  if btrim(coalesce(target_confirmation_name, '')) <> existing_name then
    raise exception 'Enter the exact product name to confirm permanent deletion.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.audit_logs audit
    where audit.organization_id = target_organization_id
      and audit.metadata ->> 'product_id' = target_product_id::text
  ) then
    raise exception 'This product has audit history and cannot be deleted. Keep it archived instead.' using errcode = '55000';
  end if;

  if exists (
    select 1
    from public.product_components component
    where component.organization_id = target_organization_id
      and component.component_product_id = target_product_id
  ) then
    raise exception 'This product is used by a composite product and cannot be deleted. Keep it archived instead.' using errcode = '55000';
  end if;

  if exists (
    select 1
    from public.inventory_levels level
    where level.organization_id = target_organization_id
      and level.product_id = target_product_id
      and level.quantity <> 0
  ) then
    raise exception 'This product has stock on hand and cannot be deleted. Keep it archived instead.' using errcode = '55000';
  end if;

  begin
    -- Empty inventory rows and unsold variants are setup records, not business
    -- history. Removing them allows a never-used archived product to be deleted
    -- while every financial, inventory, purchasing, count, transfer, and receipt
    -- relationship continues to be protected by its restrictive foreign key.
    delete from public.inventory_levels
    where organization_id = target_organization_id
      and product_id = target_product_id;

    delete from public.product_variants
    where organization_id = target_organization_id
      and product_id = target_product_id;

    delete from public.products
    where organization_id = target_organization_id
      and id = target_product_id;
  exception
    when foreign_key_violation then
      raise exception 'This product has business history and cannot be deleted. Keep it archived instead.' using errcode = '55000';
  end;

  perform private.write_audit_log(
    target_organization_id,
    'CATALOG_PRODUCT_DELETED',
    'DELETE_CATALOG_PRODUCT',
    actor_employee_id,
    null,
    null,
    null,
    null,
    null,
    'Archived product permanently deleted after dependency checks.',
    jsonb_build_object('product_id', target_product_id, 'product_name', existing_name)
  );

  return existing_name;
end;
$$;


ALTER FUNCTION "private"."delete_catalog_product_if_eligible"("target_organization_id" "uuid", "target_product_id" "uuid", "target_confirmation_name" "text") OWNER TO "postgres";

--
-- Name: delete_employee_if_eligible("uuid", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."delete_employee_if_eligible"("target_organization_id" "uuid", "target_employee_id" "uuid", "target_confirmation_number" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  employee_record public.employees%rowtype;
  employee_name text;
  blockers text[];
begin
  actor_id := private.require_employee_manager_target(target_organization_id, target_employee_id);
  if actor_id = target_employee_id then
    raise exception 'You cannot permanently delete your own employee record.' using errcode = '42501';
  end if;
  select employee.* into employee_record
  from public.employees employee join public.profiles profile on profile.id = employee.profile_id
  where employee.id = target_employee_id and employee.organization_id = target_organization_id
  for update of employee;
  select coalesce(nullif(profile.full_name, ''), profile.email, employee_record.employee_number)
  into employee_name
  from public.profiles profile
  where profile.id = employee_record.profile_id;
  if upper(btrim(coalesce(target_confirmation_number, ''))) <> employee_record.employee_number then
    raise exception 'Enter the exact employee number to confirm permanent deletion.' using errcode = '23514';
  end if;
  if employee_record.status <> 'archived' then
    raise exception 'Archive this employee before permanently deleting the record.' using errcode = '23514';
  end if;
  if private.employee_has_permission(target_organization_id, target_employee_id, 'organization.manage')
    and not exists (
      select 1
      from public.employees manager
      join public.employee_roles manager_role
        on manager_role.organization_id = manager.organization_id
       and manager_role.employee_id = manager.id
      join public.role_permissions role_permission
        on role_permission.organization_id = manager_role.organization_id
       and role_permission.role_id = manager_role.role_id
      where manager.organization_id = target_organization_id
        and manager.id <> target_employee_id
        and manager.status = 'active'
        and role_permission.permission_code = 'organization.manage'
    ) then
    raise exception 'Assign another active organization manager before deleting the last manager.' using errcode = '23514';
  end if;
  blockers := private.employee_dependency_tables(target_employee_id);
  if cardinality(blockers) > 0 then
    raise exception 'This employee has recorded business activity and cannot be permanently deleted. Archive them instead.' using errcode = '23514';
  end if;

  update private.employee_pin_credentials
  set updated_by_employee_id = actor_id
  where updated_by_employee_id = target_employee_id and employee_id <> target_employee_id;
  update public.audit_logs
  set actor_employee_id = case when actor_employee_id = target_employee_id then null else actor_employee_id end,
      subject_employee_id = case when subject_employee_id = target_employee_id then null else subject_employee_id end,
      metadata = metadata || jsonb_build_object(
        'employee_snapshot', jsonb_build_object(
          'id', target_employee_id,
          'employee_number', employee_record.employee_number,
          'employee_name', employee_name
        )
      )
  where event_type like 'EMPLOYEE\_%' escape '\'
    and (actor_employee_id = target_employee_id or subject_employee_id = target_employee_id);
  delete from public.employees
  where id = target_employee_id and organization_id = target_organization_id;

  perform private.write_audit_log(
    target_organization_id, 'EMPLOYEE_PERMANENTLY_DELETED', 'employees.manage', actor_id,
    null, null, null, null, null, null,
    jsonb_build_object('deleted_employee_id', target_employee_id, 'employee_number', employee_record.employee_number, 'employee_name', employee_name)
  );
  return target_employee_id;
end;
$$;


ALTER FUNCTION "private"."delete_employee_if_eligible"("target_organization_id" "uuid", "target_employee_id" "uuid", "target_confirmation_number" "text") OWNER TO "postgres";

--
-- Name: dispatch_stock_request("uuid", "uuid", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."dispatch_stock_request"("target_organization_id" "uuid", "target_stock_request_id" "uuid", "target_note" "text", "target_operation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request_row public.stock_requests%rowtype;
  existing_transfer public.stock_transfers%rowtype;
  actor_id uuid;
  warehouse_store_id uuid;
  transfer_id uuid;
  transfer_number bigint;
  request_line public.stock_request_lines%rowtype;
  source_level public.inventory_levels%rowtype;
  normalized_note text;
  effective_note text;
begin
  if (select auth.uid()) is null
     or (
       not (select private.has_permission(target_organization_id, 'inventory.manage'))
       and not (select private.has_inventory_capability(target_organization_id, 'inventory.transfer.send'))
     ) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'A stable transfer-dispatch operation ID is required.' using errcode = '23514';
  end if;

  if target_note is not null and char_length(btrim(target_note)) > 500 then
    raise exception 'Dispatch note is too long.' using errcode = '23514';
  end if;

  select *
  into request_row
  from public.stock_requests request_item
  where request_item.id = target_stock_request_id
    and request_item.organization_id = target_organization_id
  for update;

  if request_row.id is null then
    raise exception 'Choose a stock request in this organization.' using errcode = '23514';
  end if;

  select warehouse.store_id
  into warehouse_store_id
  from public.supply_chain_warehouses warehouse
  where warehouse.id = request_row.source_warehouse_id
    and warehouse.organization_id = target_organization_id
    and warehouse.is_active;

  actor_id := private.inventory_actor(target_organization_id, warehouse_store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for the source warehouse.' using errcode = '42501';
  end if;

  normalized_note := nullif(btrim(target_note), '');
  effective_note := coalesce(normalized_note, request_row.note);

  select *
  into existing_transfer
  from public.stock_transfers transfer
  where transfer.organization_id = target_organization_id
    and transfer.operation_id = target_operation_id
  for update;

  if found then
    if existing_transfer.stock_request_id = request_row.id
       and existing_transfer.source_store_id = warehouse_store_id
       and existing_transfer.destination_store_id = request_row.requesting_store_id
       and existing_transfer.transferred_by_employee_id = actor_id
       and existing_transfer.note is not distinct from effective_note then
      return existing_transfer.id;
    end if;

    raise exception 'This operation ID is already assigned to a different transfer dispatch.' using errcode = '23505';
  end if;

  if request_row.status <> 'picking' then
    raise exception 'Only a picked request can be dispatched.' using errcode = '23514';
  end if;

  transfer_number := nextval('private.tindio_stock_transfer_number_sequence'::regclass);
  insert into public.stock_transfers (
    organization_id,
    transfer_number,
    operation_id,
    source_store_id,
    destination_store_id,
    stock_request_id,
    status,
    note,
    transferred_by_employee_id
  )
  values (
    target_organization_id,
    transfer_number,
    target_operation_id,
    warehouse_store_id,
    request_row.requesting_store_id,
    request_row.id,
    'in_transit',
    effective_note,
    actor_id
  )
  returning id into transfer_id;

  for request_line in
    select *
    from public.stock_request_lines item
    where item.stock_request_id = request_row.id
      and item.picked_quantity > 0
    order by item.product_id, item.variant_id
  loop
    select *
    into source_level
    from public.inventory_levels level
    where level.organization_id = target_organization_id
      and level.store_id = warehouse_store_id
      and level.product_id = request_line.product_id
      and level.variant_id is not distinct from request_line.variant_id
    for update;

    if source_level.id is null or source_level.quantity < request_line.picked_quantity then
      raise exception 'Source warehouse stock is insufficient for this request.' using errcode = '23514';
    end if;

    if not exists (
      select 1
      from public.inventory_levels level
      where level.organization_id = target_organization_id
        and level.store_id = request_row.requesting_store_id
        and level.product_id = request_line.product_id
        and level.variant_id is not distinct from request_line.variant_id
    ) then
      raise exception 'The destination stock projection is not initialized for one requested item.' using errcode = '23514';
    end if;

    insert into public.stock_transfer_lines (
      organization_id,
      stock_transfer_id,
      stock_request_line_id,
      product_id,
      variant_id,
      quantity,
      unit_cost_minor
    )
    values (
      target_organization_id,
      transfer_id,
      request_line.id,
      request_line.product_id,
      request_line.variant_id,
      request_line.picked_quantity,
      source_level.average_cost_minor
    );

    perform private.apply_inventory_change_v2(
      target_organization_id,
      warehouse_store_id,
      request_line.product_id,
      request_line.variant_id,
      -request_line.picked_quantity,
      'TRANSFER_OUT',
      actor_id,
      format('Stock transfer TR-%s dispatched', lpad(transfer_number::text, 6, '0')),
      'stock_transfer',
      transfer_id,
      source_level.average_cost_minor
    );

    update public.stock_request_lines
    set dispatched_quantity = request_line.picked_quantity
    where id = request_line.id;
  end loop;

  update public.stock_requests
  set status = 'dispatched', dispatched_by_employee_id = actor_id, dispatched_at = now()
  where id = request_row.id;

  perform private.write_audit_log(
    target_organization_id,
    'STOCK_REQUEST_DISPATCHED',
    'inventory.manage',
    actor_id,
    null,
    warehouse_store_id,
    null,
    null,
    null,
    effective_note,
    jsonb_build_object(
      'stock_request_id', request_row.id,
      'request_number', request_row.request_number,
      'stock_transfer_id', transfer_id,
      'transfer_number', transfer_number,
      'destination_store_id', request_row.requesting_store_id
    )
  );
  return transfer_id;
end;
$$;


ALTER FUNCTION "private"."dispatch_stock_request"("target_organization_id" "uuid", "target_stock_request_id" "uuid", "target_note" "text", "target_operation_id" "uuid") OWNER TO "postgres";

--
-- Name: employee_dependency_tables("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."employee_dependency_tables"("target_employee_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  dependency record;
  dependency_exists boolean;
  dependencies text[] := '{}'::text[];
begin
  for dependency in
    select distinct child_namespace.nspname as schema_name,
           child_table.relname as table_name,
           child_column.attname as column_name
    from pg_catalog.pg_constraint constraint_record
    join pg_catalog.pg_class child_table on child_table.oid = constraint_record.conrelid
    join pg_catalog.pg_namespace child_namespace on child_namespace.oid = child_table.relnamespace
    join lateral unnest(constraint_record.conkey) with ordinality child_key(attnum, position) on true
    join lateral unnest(constraint_record.confkey) with ordinality parent_key(attnum, position)
      on parent_key.position = child_key.position
    join pg_catalog.pg_attribute child_column
      on child_column.attrelid = child_table.oid and child_column.attnum = child_key.attnum
    join pg_catalog.pg_attribute parent_column
      on parent_column.attrelid = constraint_record.confrelid and parent_column.attnum = parent_key.attnum
    where constraint_record.contype = 'f'
      and constraint_record.confrelid = 'public.employees'::regclass
      and parent_column.attname = 'id'
      and not (
        child_namespace.nspname = 'public'
        and child_table.relname in ('employee_roles', 'employee_stores', 'audit_logs')
      )
      and not (
        child_namespace.nspname = 'private'
        and child_table.relname = 'employee_pin_credentials'
      )
    order by child_namespace.nspname, child_table.relname, child_column.attname
  loop
    execute format(
      'select exists (select 1 from %I.%I where %I = $1)',
      dependency.schema_name, dependency.table_name, dependency.column_name
    ) using target_employee_id into dependency_exists;

    if dependency_exists and not dependencies @> ARRAY[dependency.table_name::text] then
      dependencies := array_append(dependencies, dependency.table_name::text);
    end if;
  end loop;

  -- Employee-administration events are retained as immutable snapshots and do
  -- not turn a never-used invitation into an undeletable employee. Operational
  -- audit history still blocks erasure.
  if exists (
    select 1 from public.audit_logs audit
    where (audit.actor_employee_id = target_employee_id or audit.subject_employee_id = target_employee_id)
      and audit.event_type not like 'EMPLOYEE\_%' escape '\'
  ) then
    dependencies := array_append(dependencies, 'audit_logs');
  end if;

  return dependencies;
end;
$_$;


ALTER FUNCTION "private"."employee_dependency_tables"("target_employee_id" "uuid") OWNER TO "postgres";

--
-- Name: employee_has_permission("uuid", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."employee_has_permission"("target_organization_id" "uuid", "target_employee_id" "uuid", "requested_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.employees employee
    join public.organizations organization
      on organization.id = employee.organization_id
     and organization.status = 'active'
    join public.employee_roles employee_role
      on employee_role.employee_id = employee.id
     and employee_role.organization_id = employee.organization_id
    join public.role_permissions role_permission
      on role_permission.role_id = employee_role.role_id
     and role_permission.organization_id = employee_role.organization_id
    where employee.id = target_employee_id
      and employee.organization_id = target_organization_id
      and employee.status = 'active'
      and role_permission.permission_code = requested_permission
  );
$$;


ALTER FUNCTION "private"."employee_has_permission"("target_organization_id" "uuid", "target_employee_id" "uuid", "requested_permission" "text") OWNER TO "postgres";

--
-- Name: enforce_inventory_movement_insert(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."enforce_inventory_movement_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  catalog_unit text;
begin
  -- Stock movements may only be posted for inventory-tracked saleables.  This
  -- protects the ledger even when a caller bypasses a UI-level filter.
  select product.unit
    into catalog_unit
  from public.products product
  where product.id = new.product_id
    and product.organization_id = new.organization_id
    and product.track_inventory;

  if catalog_unit is null then
    raise exception 'Inventory movements require an inventory-tracked product.'
      using errcode = '23514';
  end if;

  if new.actor_employee_id is null then
    raise exception 'Inventory movements require an employee actor.'
      using errcode = '23514';
  end if;

  -- The database captures the product's canonical base unit at posting time.
  -- Callers cannot accidentally omit it, and later product presentation
  -- changes cannot rewrite historical movement meaning.
  new.unit_snapshot := coalesce(nullif(btrim(new.unit_snapshot), ''), catalog_unit);
  new.operation_id := coalesce(new.operation_id, new.source_id, new.id);

  if new.operation_id is null then
    raise exception 'Inventory movements require an immutable operation identity.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_inventory_movement_insert"() OWNER TO "postgres";

--
-- Name: enforce_negative_stock_policy(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."enforce_negative_stock_policy"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.quantity >= 0 then
    return new;
  end if;

  if private.resolve_negative_stock_policy(new.organization_id, new.store_id) = 'block' then
    raise exception 'This store blocks negative stock. Receive or adjust stock before continuing.' using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_negative_stock_policy"() OWNER TO "postgres";

--
-- Name: enforce_open_ticket_capabilities(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."enforce_open_ticket_capabilities"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_organization_id uuid;
begin
  if tg_op = 'DELETE' then
    target_organization_id := old.organization_id;
  else
    target_organization_id := new.organization_id;
  end if;

  -- Internal database maintenance has no Supabase user context. Every client
  -- request has auth.uid() and must satisfy the full POS ticket capability.
  if (select auth.uid()) is not null then
    perform private.require_pos_capabilities(
      target_organization_id,
      array['pos.access', 'sales.create', 'tickets.manage']
    );
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_open_ticket_capabilities"() OWNER TO "postgres";

--
-- Name: ensure_catalog_identifier_unique(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."ensure_catalog_identifier_unique"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  identifier_value text;
  conflicting_product_id uuid;
  conflicting_variant_id uuid;
begin
  new.sku := nullif(upper(trim(new.sku)), '');
  new.barcode := nullif(trim(new.barcode), '');

  for identifier_value in
    select distinct identifier
    from unnest(array[new.sku, new.barcode]) as identifier
    where identifier is not null
    order by identifier
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        new.organization_id::text || ':catalog-identifier:' || identifier_value,
        0
      )
    );
  end loop;

  select product.id
  into conflicting_product_id
  from public.products product
  where product.organization_id = new.organization_id
    and (
      product.sku = any(array[new.sku, new.barcode])
      or product.barcode = any(array[new.sku, new.barcode])
    )
    and (tg_table_name <> 'products' or product.id <> new.id)
  limit 1;

  select variant.id
  into conflicting_variant_id
  from public.product_variants variant
  where variant.organization_id = new.organization_id
    and (
      variant.sku = any(array[new.sku, new.barcode])
      or variant.barcode = any(array[new.sku, new.barcode])
    )
    and (tg_table_name <> 'product_variants' or variant.id <> new.id)
  limit 1;

  if conflicting_product_id is not null or conflicting_variant_id is not null then
    raise exception 'SKU and barcode values must identify one saleable item.'
      using errcode = '23505', constraint = 'catalog_identifiers_unique';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."ensure_catalog_identifier_unique"() OWNER TO "postgres";

--
-- Name: generate_catalog_identifiers("uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."generate_catalog_identifiers"("target_organization_id" "uuid", "target_product_name" "text") RETURNS TABLE("sku" "text", "barcode" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  normalized_name text;
  name_token text;
  identifier_suffix text;
  candidate_sku text;
  candidate_barcode text;
  attempt integer;
begin
  if not coalesce(
    (select private.has_permission(target_organization_id, 'products.manage')),
    false
  ) then
    raise exception 'Product management permission is required.' using errcode = '42501';
  end if;

  normalized_name := btrim(coalesce(target_product_name, ''));
  if normalized_name = '' or char_length(normalized_name) > 160 then
    raise exception 'Enter a product name between 1 and 160 characters.' using errcode = '22023';
  end if;

  name_token := regexp_replace(upper(normalized_name), '[^A-Z0-9]+', '-', 'g');
  name_token := regexp_replace(name_token, '(^-+|-+$)', '', 'g');
  name_token := left(nullif(name_token, ''), 20);
  name_token := coalesce(name_token, 'ITEM');

  for attempt in 1..20 loop
    identifier_suffix := upper(left(replace(gen_random_uuid()::text, '-', ''), 8));
    candidate_sku := format('TND-%s-%s', name_token, identifier_suffix);
    candidate_barcode := format('TND-%s', identifier_suffix);

    if not exists (
      select 1
      from public.products product
      where product.organization_id = target_organization_id
        and (
          product.sku = any(array[candidate_sku, candidate_barcode])
          or product.barcode = any(array[candidate_sku, candidate_barcode])
        )
    ) and not exists (
      select 1
      from public.product_variants variant
      where variant.organization_id = target_organization_id
        and (
          variant.sku = any(array[candidate_sku, candidate_barcode])
          or variant.barcode = any(array[candidate_sku, candidate_barcode])
        )
    ) then
      return query select candidate_sku, candidate_barcode;
      return;
    end if;
  end loop;

  raise exception 'TINDIO could not generate a unique product identifier. Please try again.'
    using errcode = '23505';
end;
$_$;


ALTER FUNCTION "private"."generate_catalog_identifiers"("target_organization_id" "uuid", "target_product_name" "text") OWNER TO "postgres";

--
-- Name: get_attendance_employees("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."get_attendance_employees"("target_organization_id" "uuid", "target_store_id" "uuid") RETURNS TABLE("employee_id" "uuid", "employee_number" "text", "employee_name" "text", "pin_is_set" boolean, "entry_id" "uuid", "entry_store_id" "uuid", "entry_store_name" "text", "clocked_in_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_attendance_terminal(target_organization_id, target_store_id);

  return query
  select employee.id,
         employee.employee_number,
         coalesce(nullif(profile.full_name, ''), profile.email, employee.employee_number),
         credential.employee_id is not null,
         entry.id,
         entry.store_id,
         entry_store.name,
         entry.clocked_in_at
  from public.employees employee
  join public.profiles profile on profile.id = employee.profile_id
  join public.employee_stores assignment
    on assignment.organization_id = employee.organization_id
   and assignment.employee_id = employee.id
   and assignment.store_id = target_store_id
  left join private.employee_pin_credentials credential on credential.employee_id = employee.id
  left join public.time_clock_entries entry
    on entry.organization_id = employee.organization_id
   and entry.employee_id = employee.id
   and entry.clocked_out_at is null
  left join public.stores entry_store
    on entry_store.id = entry.store_id
   and entry_store.organization_id = entry.organization_id
  where employee.organization_id = target_organization_id
    and employee.status = 'active'
    and private.employee_has_permission(target_organization_id, employee.id, 'attendance.use')
  order by lower(coalesce(nullif(profile.full_name, ''), profile.email, employee.employee_number));
end;
$$;


ALTER FUNCTION "private"."get_attendance_employees"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

--
-- Name: get_catalog_costs("uuid", "uuid"[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."get_catalog_costs"("target_organization_id" "uuid", "requested_product_ids" "uuid"[]) RETURNS TABLE("product_id" "uuid", "variant_id" "uuid", "cost_minor" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(
      target_organization_id,
      'products.view_cost'
    )) then
    raise exception 'Product cost permission is required.' using errcode = '42501';
  end if;

  return query
  select product.id, null::uuid, product.cost_minor
  from public.products product
  where product.organization_id = target_organization_id
    and (
      requested_product_ids is null
      or product.id = any(requested_product_ids)
    )
  union all
  select variant.product_id, variant.id, variant.cost_minor
  from public.product_variants variant
  where variant.organization_id = target_organization_id
    and (
      requested_product_ids is null
      or variant.product_id = any(requested_product_ids)
    );
end;
$$;


ALTER FUNCTION "private"."get_catalog_costs"("target_organization_id" "uuid", "requested_product_ids" "uuid"[]) OWNER TO "postgres";

--
-- Name: get_checkout_stock_warning("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."get_checkout_stock_warning"("target_organization_id" "uuid", "target_store_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  negative_item_count integer;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'sales.create')) then
    raise exception 'Sales permission is required.' using errcode = '42501';
  end if;
  if private.inventory_actor(target_organization_id, target_store_id) is null then
    raise exception 'You are not assigned to this store.' using errcode = '42501';
  end if;
  if private.resolve_negative_stock_policy(target_organization_id, target_store_id) <> 'warn' then
    return 0;
  end if;

  select count(*)::integer
  into negative_item_count
  from public.inventory_levels level
  where level.organization_id = target_organization_id
    and level.store_id = target_store_id
    and level.quantity < 0;
  return negative_item_count;
end;
$$;


ALTER FUNCTION "private"."get_checkout_stock_warning"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

--
-- Name: get_checkout_stock_warning("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."get_checkout_stock_warning"("target_organization_id" "uuid", "target_store_id" "uuid", "target_sale_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  negative_item_count integer;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'sales.create')) then
    raise exception 'Sales permission is required.' using errcode = '42501';
  end if;
  if private.inventory_actor(target_organization_id, target_store_id) is null then
    raise exception 'You are not assigned to this store.' using errcode = '42501';
  end if;
  if private.resolve_negative_stock_policy(target_organization_id, target_store_id) <> 'warn' then
    return 0;
  end if;
  if not exists (
    select 1
    from public.sales sale
    where sale.id = target_sale_id
      and sale.organization_id = target_organization_id
      and sale.store_id = target_store_id
  ) then
    raise exception 'The completed sale was not found in this store.' using errcode = 'P0002';
  end if;

  select count(*)::integer
  into negative_item_count
  from (
    select item.product_id, item.variant_id
    from public.sale_items item
    join public.products product
      on product.id = item.product_id
     and product.organization_id = item.organization_id
     and product.track_inventory
    join public.inventory_levels level
      on level.organization_id = item.organization_id
     and level.store_id = target_store_id
     and level.product_id = item.product_id
     and level.variant_id is not distinct from item.variant_id
     and level.quantity < 0
    where item.organization_id = target_organization_id
      and item.sale_id = target_sale_id
    group by item.product_id, item.variant_id
  ) affected;
  return negative_item_count;
end;
$$;


ALTER FUNCTION "private"."get_checkout_stock_warning"("target_organization_id" "uuid", "target_store_id" "uuid", "target_sale_id" "uuid") OWNER TO "postgres";

--
-- Name: get_current_time_clock_entry("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."get_current_time_clock_entry"("target_organization_id" "uuid") RETURNS TABLE("entry_id" "uuid", "store_id" "uuid", "clocked_in_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
begin
  if target_organization_id is null then
    raise exception 'An organization is required for the time clock.' using errcode = '23514';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active';

  if actor_employee_id is null then
    raise exception 'An active employee is required for the time clock.' using errcode = '42501';
  end if;

  return query
  select entry.id, entry.store_id, entry.clocked_in_at
  from public.time_clock_entries entry
  where entry.organization_id = target_organization_id
    and entry.employee_id = actor_employee_id
    and entry.clocked_out_at is null;
end;
$$;


ALTER FUNCTION "private"."get_current_time_clock_entry"("target_organization_id" "uuid") OWNER TO "postgres";

