--
-- Name: get_employee_management_detail("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."get_employee_management_detail"("target_organization_id" "uuid", "target_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  result jsonb;
begin
  actor_id := private.require_employee_manager_target(target_organization_id, target_employee_id);
  select jsonb_build_object(
    'id', employee.id,
    'employeeNumber', employee.employee_number,
    'fullName', coalesce(nullif(profile.full_name, ''), profile.email, employee.employee_number),
    'email', profile.email,
    'phone', profile.phone,
    'jobTitle', employee.job_title,
    'status', employee.status,
    'archivedAt', employee.archived_at,
    'pinIsSet', exists(select 1 from private.employee_pin_credentials credential where credential.employee_id = employee.id),
    'roles', coalesce((
      select jsonb_agg(jsonb_build_object('id', role.id, 'name', role.name) order by role.name)
      from public.employee_roles link join public.roles role on role.id = link.role_id
      where link.organization_id = target_organization_id and link.employee_id = employee.id
    ), '[]'::jsonb),
    'stores', coalesce((
      select jsonb_agg(jsonb_build_object('id', store.id, 'name', store.name) order by store.name)
      from public.employee_stores link join public.stores store on store.id = link.store_id
      where link.organization_id = target_organization_id and link.employee_id = employee.id
    ), '[]'::jsonb),
    'posAccess', private.employee_has_permission(target_organization_id, employee.id, 'pos.access'),
    'backOfficeAccess', exists (
      select 1 from public.employee_roles employee_role
      join public.role_permissions role_permission
        on role_permission.role_id = employee_role.role_id
       and role_permission.organization_id = employee_role.organization_id
      where employee_role.organization_id = target_organization_id
        and employee_role.employee_id = employee.id
        and role_permission.permission_code = any(array[
          'dashboard.view','reports.view','products.manage','inventory.view','inventory.manage',
          'customers.manage','employees.manage','roles.manage','stores.manage','registers.manage',
          'organization.manage','settings.manage','approvals.manage','audit.view','devices.manage'
        ])
    ),
    'attendance', jsonb_build_object(
      'current', (select jsonb_build_object('id', entry.id, 'storeId', entry.store_id, 'storeName', store.name, 'clockedInAt', entry.clocked_in_at)
                  from public.time_clock_entries entry join public.stores store on store.id = entry.store_id
                  where entry.organization_id = target_organization_id and entry.employee_id = employee.id and entry.clocked_out_at is null),
      'lastClockIn', (select entry.clocked_in_at from public.time_clock_entries entry
                      where entry.organization_id = target_organization_id and entry.employee_id = employee.id
                      order by entry.clocked_in_at desc limit 1),
      'historyCount', (select count(*) from public.time_clock_entries entry
                       where entry.organization_id = target_organization_id and entry.employee_id = employee.id),
      'history', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', history.id, 'storeName', history.store_name,
          'clockedInAt', history.clocked_in_at, 'clockedOutAt', history.clocked_out_at
        ) order by history.clocked_in_at desc)
        from (
          select entry.id, store.name as store_name, entry.clocked_in_at, entry.clocked_out_at
          from public.time_clock_entries entry join public.stores store on store.id = entry.store_id
          where entry.organization_id = target_organization_id and entry.employee_id = employee.id
          order by entry.clocked_in_at desc limit 20
        ) history
      ), '[]'::jsonb)
    ),
    'activity', jsonb_build_object(
      'receipts', (select count(*) from public.sales sale where sale.organization_id = target_organization_id and sale.cashier_employee_id = employee.id),
      'registerShifts', (select count(*) from public.shifts shift where shift.organization_id = target_organization_id and (shift.opened_by_employee_id = employee.id or shift.closed_by_employee_id = employee.id)),
      'refunds', (select count(*) from public.refunds refund where refund.organization_id = target_organization_id and refund.refunded_by_employee_id = employee.id),
      'inventoryMovements', (select count(*) from public.inventory_movements movement where movement.organization_id = target_organization_id and movement.actor_employee_id = employee.id)
    ),
    'openShift', (select jsonb_build_object(
      'id', shift.id, 'storeId', shift.store_id, 'storeName', store.name,
      'registerId', shift.register_id, 'registerName', register.name, 'openedAt', shift.opened_at
    ) from public.shifts shift
      join public.stores store on store.id = shift.store_id
      join public.registers register on register.id = shift.register_id
      where shift.organization_id = target_organization_id
        and shift.opened_by_employee_id = employee.id and shift.status = 'open'
      limit 1),
    'deleteBlockers', to_jsonb(private.employee_dependency_tables(employee.id))
  ) into result
  from public.employees employee
  join public.profiles profile on profile.id = employee.profile_id
  where employee.id = target_employee_id and employee.organization_id = target_organization_id;
  return result;
end;
$$;


ALTER FUNCTION "private"."get_employee_management_detail"("target_organization_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";

--
-- Name: get_inventory_count_awareness("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."get_inventory_count_awareness"("target_organization_id" "uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "variant_id" "uuid", "last_counted_at" timestamp with time zone, "expected_quantity" numeric, "counted_quantity" numeric, "inventory_count_id" "uuid", "count_number" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null or not (
    (select private.has_permission(target_organization_id, 'inventory.view'))
    or (select private.has_permission(target_organization_id, 'inventory.count'))
    or (select private.has_permission(target_organization_id, 'inventory.manage'))
  ) then
    raise exception 'Inventory read permission is required.' using errcode = '42501';
  end if;

  return query
  select
    level.store_id,
    level.product_id,
    level.variant_id,
    latest.last_counted_at,
    latest.expected_quantity,
    latest.counted_quantity,
    latest.inventory_count_id,
    latest.count_number
  from public.inventory_levels level
  join public.products product
    on product.id = level.product_id
   and product.organization_id = level.organization_id
   and product.status = 'active'
   and product.track_inventory
  left join lateral (
    select
      coalesce(count_document.completed_at, count_document.updated_at) as last_counted_at,
      count_line.expected_quantity,
      count_line.counted_quantity,
      count_document.id as inventory_count_id,
      count_document.count_number
    from public.inventory_count_lines count_line
    join public.inventory_counts count_document
      on count_document.id = count_line.inventory_count_id
     and count_document.organization_id = count_line.organization_id
    where count_line.organization_id = target_organization_id
      and count_document.store_id = level.store_id
      and count_line.product_id = level.product_id
      and count_line.variant_id is not distinct from level.variant_id
      and count_line.counted_quantity is not null
      and count_document.status in ('posted', 'completed')
    order by coalesce(count_document.completed_at, count_document.updated_at) desc,
      count_document.id desc
    limit 1
  ) latest on true
  where level.organization_id = target_organization_id
    and (select private.has_store_read_scope(target_organization_id, level.store_id))
  order by level.store_id, level.product_id, level.variant_id nulls first;
end;
$$;


ALTER FUNCTION "private"."get_inventory_count_awareness"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: get_kitchen_orders("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."get_kitchen_orders"("target_organization_id" "uuid", "target_store_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("kitchen_order_id" "uuid", "store_id" "uuid", "store_name" "text", "order_number" bigint, "order_label" "text", "order_note" "text", "dining_option_name" "text", "priority" "text", "status" "text", "created_at" timestamp with time zone, "started_at" timestamp with time zone, "ready_at" timestamp with time zone, "completed_at" timestamp with time zone, "items" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null
    or not (
      (select private.has_permission(target_organization_id, 'kitchen.view'))
      or (select private.has_permission(target_organization_id, 'kitchen.manage'))
    ) then
    raise exception 'Kitchen display access is required.' using errcode = '42501';
  end if;

  return query
  select
    kitchen_order.id,
    kitchen_order.store_id,
    store.name,
    kitchen_order.order_number,
    kitchen_order.order_label,
    kitchen_order.order_note,
    kitchen_order.dining_option_name_snapshot,
    kitchen_order.priority,
    kitchen_order.status,
    kitchen_order.created_at,
    kitchen_order.started_at,
    kitchen_order.ready_at,
    kitchen_order.completed_at,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', kitchen_item.id,
          'name', kitchen_item.product_name_snapshot,
          'variant_name', kitchen_item.variant_name_snapshot,
          'modifiers', kitchen_item.modifiers_snapshot,
          'quantity', kitchen_item.quantity,
          'station', kitchen_item.station,
          'status', kitchen_item.status,
          'started_at', kitchen_item.started_at,
          'ready_at', kitchen_item.ready_at,
          'completed_at', kitchen_item.completed_at
        ) order by kitchen_item.line_number
      ) filter (where kitchen_item.id is not null),
      '[]'::jsonb
    )
  from public.kitchen_orders kitchen_order
  join public.stores store
    on store.id = kitchen_order.store_id
   and store.organization_id = kitchen_order.organization_id
  left join public.kitchen_order_items kitchen_item
    on kitchen_item.kitchen_order_id = kitchen_order.id
   and kitchen_item.organization_id = kitchen_order.organization_id
  where kitchen_order.organization_id = target_organization_id
    and (target_store_id is null or kitchen_order.store_id = target_store_id)
    and (
      kitchen_order.status <> 'COMPLETED'
      or kitchen_order.completed_at >= now() - interval '4 hours'
    )
    and exists (
      select 1
      from public.employees employee
      join public.employee_stores employee_store
        on employee_store.employee_id = employee.id
       and employee_store.organization_id = employee.organization_id
      where employee.organization_id = target_organization_id
        and employee.profile_id = (select auth.uid())
        and employee.status = 'active'
        and employee_store.store_id = kitchen_order.store_id
    )
  group by
    kitchen_order.id,
    kitchen_order.store_id,
    store.name,
    kitchen_order.order_number,
    kitchen_order.order_label,
    kitchen_order.order_note,
    kitchen_order.dining_option_name_snapshot,
    kitchen_order.priority,
    kitchen_order.status,
    kitchen_order.created_at,
    kitchen_order.started_at,
    kitchen_order.ready_at,
    kitchen_order.completed_at
  order by
    case kitchen_order.priority when 'RUSH' then 0 else 1 end,
    case kitchen_order.status
      when 'NEW' then 1
      when 'PREPARING' then 2
      when 'READY' then 3
      else 4
    end,
    kitchen_order.created_at;
end;
$$;


ALTER FUNCTION "private"."get_kitchen_orders"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

