--
-- Name: guard_device_management_enabled(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."guard_device_management_enabled"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.device_management_enabled is distinct from old.device_management_enabled
    and coalesce(current_setting('tindio.device_management_change', true), '') <> 'authorized' then
    raise exception 'Device-management enforcement can only be changed through the device management workflow.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."guard_device_management_enabled"() OWNER TO "postgres";

--
-- Name: guard_employee_lifecycle_transition(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."guard_employee_lifecycle_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (new.status is distinct from old.status or new.archived_at is distinct from old.archived_at)
    and (select auth.uid()) is not null
    and coalesce(current_setting('tindio.employee_lifecycle_change', true), '') <> 'authorized' then
    raise exception 'Use the controlled employee lifecycle workflow to change status.' using errcode = '42501';
  end if;
  return new;
end;
$$;


