--
-- Name: guard_offline_checkout_total(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."guard_offline_checkout_total"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  expected_total_minor bigint;
begin
  select (regexp_match(payment.note, '\[tindio-offline-total:([0-9]+)\]'))[1]::bigint
    into expected_total_minor
  from public.payments payment
  where payment.organization_id = new.organization_id
    and payment.sale_id = new.id
    and payment.note ~ '\[tindio-offline-total:[0-9]+\]'
  order by payment.created_at, payment.id
  limit 1;

  if expected_total_minor is not null
    and new.total_minor <> expected_total_minor then
    raise exception 'This queued sale total changed while offline. Review the sale before recording it.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."guard_offline_checkout_total"() OWNER TO "postgres";

--
-- Name: FUNCTION "guard_offline_checkout_total"(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."guard_offline_checkout_total"() IS 'Phase 13: rejects a queued cash checkout when the final server total no longer matches the amount quoted offline.';


--
-- Name: guard_offline_payment_total_marker(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."guard_offline_payment_total_marker"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  expected_total_minor bigint;
  recorded_total_minor bigint;
begin
  if new.note !~ '\[tindio-offline-total:[0-9]+\]' then
    return new;
  end if;

  expected_total_minor := (regexp_match(new.note, '\[tindio-offline-total:([0-9]+)\]'))[1]::bigint;
  select sale.total_minor
  into recorded_total_minor
  from public.sales sale
  where sale.id = new.sale_id
    and sale.organization_id = new.organization_id;

  if recorded_total_minor is null or recorded_total_minor <> expected_total_minor then
    raise exception 'This queued sale total changed while offline. Review the sale before recording it.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."guard_offline_payment_total_marker"() OWNER TO "postgres";

--
-- Name: FUNCTION "guard_offline_payment_total_marker"(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."guard_offline_payment_total_marker"() IS 'Phase 13: rejects an offline-marked payment when the server-calculated checkout total no longer matches its locally captured amount.';


--
-- Name: has_active_pos_shift_access("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."has_active_pos_shift_access"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    (select auth.uid()) is not null
    and (select private.has_permission(target_organization_id, 'sales.create'))
    and exists (
      select 1
      from public.employees employee
      join public.employee_stores employee_store
        on employee_store.employee_id = employee.id
       and employee_store.organization_id = employee.organization_id
       and employee_store.store_id = target_store_id
      join public.stores store
        on store.id = employee_store.store_id
       and store.organization_id = employee_store.organization_id
       and store.is_active
      join public.registers register
        on register.id = target_register_id
       and register.organization_id = employee.organization_id
       and register.store_id = target_store_id
       and register.is_active
      join public.shifts shift
        on shift.organization_id = employee.organization_id
       and shift.store_id = target_store_id
       and shift.register_id = target_register_id
       and shift.opened_by_employee_id = employee.id
       and shift.status = 'open'
      where employee.organization_id = target_organization_id
        and employee.profile_id = (select auth.uid())
        and employee.status = 'active'
    );
$$;


ALTER FUNCTION "private"."has_active_pos_shift_access"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid") OWNER TO "postgres";

