--
-- Name: has_stock_request_read_scope("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."has_stock_request_read_scope"("target_organization_id" "uuid", "target_stock_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.stock_requests stock_request
    left join public.supply_chain_warehouses warehouse
      on warehouse.id = stock_request.source_warehouse_id
     and warehouse.organization_id = stock_request.organization_id
    where stock_request.id = target_stock_request_id
      and stock_request.organization_id = target_organization_id
      and (
        (select private.has_store_read_scope(target_organization_id, stock_request.requesting_store_id))
        or (warehouse.store_id is not null and (select private.has_store_read_scope(target_organization_id, warehouse.store_id)))
      )
  );
$$;


ALTER FUNCTION "private"."has_stock_request_read_scope"("target_organization_id" "uuid", "target_stock_request_id" "uuid") OWNER TO "postgres";

--
-- Name: has_stock_transfer_read_scope("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."has_stock_transfer_read_scope"("target_organization_id" "uuid", "target_stock_transfer_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.stock_transfers stock_transfer
    where stock_transfer.id = target_stock_transfer_id
      and stock_transfer.organization_id = target_organization_id
      and (
        (select private.has_store_read_scope(target_organization_id, stock_transfer.source_store_id))
        or (select private.has_store_read_scope(target_organization_id, stock_transfer.destination_store_id))
      )
  );
$$;


ALTER FUNCTION "private"."has_stock_transfer_read_scope"("target_organization_id" "uuid", "target_stock_transfer_id" "uuid") OWNER TO "postgres";

--
-- Name: has_store_read_scope("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."has_store_read_scope"("target_organization_id" "uuid", "target_store_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (select auth.uid()) is not null
    and target_store_id is not null
    and exists (
      select 1
      from public.organizations organization
      where organization.id = target_organization_id
        and organization.status = 'active'
    )
    and (
      (select private.has_organization_store_scope(target_organization_id))
      or exists (
        select 1
        from public.employees employee
        join public.employee_stores assignment
          on assignment.organization_id = employee.organization_id
         and assignment.employee_id = employee.id
        where employee.organization_id = target_organization_id
          and employee.profile_id = (select auth.uid())
          and employee.status = 'active'
          and assignment.store_id = target_store_id
      )
    ),
    false
  );
$$;


ALTER FUNCTION "private"."has_store_read_scope"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "has_store_read_scope"("target_organization_id" "uuid", "target_store_id" "uuid"); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."has_store_read_scope"("target_organization_id" "uuid", "target_store_id" "uuid") IS 'Requires an active authenticated employee and active organization, then either capability-defined organization-wide stores.manage scope or an assigned store.';


--
-- Name: import_catalog_products_v2("uuid", "uuid"[], "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."import_catalog_products_v2"("target_organization_id" "uuid", "target_store_ids" "uuid"[], "target_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  import_row record;
  row_number integer;
  row_json jsonb;
  row_name text;
  row_sku text;
  row_barcode text;
  row_category_id uuid;
  row_unit text;
  row_price_minor bigint;
  row_cost_minor bigint;
  row_price_override_minor bigint;
  row_low_stock_level numeric(14, 3);
  row_product_id uuid;
  seen_skus text[] := '{}';
  seen_barcodes text[] := '{}';
  imported_count integer := 0;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'products.manage')) then
    raise exception 'Product management permission is required.' using errcode = '42501';
  end if;

  if jsonb_typeof(target_rows) <> 'array'
    or jsonb_array_length(target_rows) not between 1 and 500 then
    raise exception 'Import between 1 and 500 product rows at a time.' using errcode = '22023';
  end if;

  -- Validate every row and its identifiers before inserting anything.
  for import_row in
    select value, ordinality
    from jsonb_array_elements(target_rows) with ordinality
  loop
    row_json := import_row.value;
    row_number := case
      when coalesce(row_json ->> 'row_number', '') ~ '^[1-9][0-9]*$'
        then (row_json ->> 'row_number')::integer
      else import_row.ordinality::integer
    end;
    row_name := btrim(coalesce(row_json ->> 'name', ''));
    row_sku := nullif(upper(btrim(coalesce(row_json ->> 'sku', ''))), '');
    row_barcode := nullif(btrim(coalesce(row_json ->> 'barcode', '')), '');
    row_unit := lower(btrim(coalesce(row_json ->> 'unit', 'each')));

    if jsonb_typeof(row_json) <> 'object' then
      raise exception 'CSV row % must be an object.', row_number using errcode = '22023';
    end if;
    if char_length(row_name) not between 1 and 160 then
      raise exception 'CSV row % needs a product name of at most 160 characters.', row_number using errcode = '22023';
    end if;
    if char_length(coalesce(row_json ->> 'description', '')) > 2000 then
      raise exception 'CSV row % has a description longer than 2,000 characters.', row_number using errcode = '22023';
    end if;
    if row_sku is not null and row_sku !~ '^[A-Z0-9][A-Z0-9._-]{0,63}$' then
      raise exception 'CSV row % has an invalid SKU.', row_number using errcode = '22023';
    end if;
    if row_barcode is not null and row_barcode !~ '^[A-Za-z0-9][A-Za-z0-9._-]{2,63}$' then
      raise exception 'CSV row % has an invalid barcode.', row_number using errcode = '22023';
    end if;
    if char_length(row_unit) not between 1 and 24 or row_unit !~ '^[a-z][a-z0-9 _-]*$' then
      raise exception 'CSV row % has an invalid base unit.', row_number using errcode = '22023';
    end if;
    if jsonb_typeof(row_json -> 'track_inventory') <> 'boolean'
      or jsonb_typeof(row_json -> 'is_variable_price') <> 'boolean'
      or jsonb_typeof(row_json -> 'allow_fractional_quantity') <> 'boolean' then
      raise exception 'CSV row % has invalid yes/no values.', row_number using errcode = '22023';
    end if;
    if coalesce(row_json ->> 'price_minor', '') !~ '^\d{1,10}$'
      or coalesce(row_json ->> 'cost_minor', '') !~ '^\d{1,10}$' then
      raise exception 'CSV row % has an invalid price or cost.', row_number using errcode = '22023';
    end if;
    if nullif(btrim(coalesce(row_json ->> 'image_url', '')), '') is not null
      and btrim(row_json ->> 'image_url') !~* '^https?://' then
      raise exception 'CSV row % has an invalid image URL.', row_number using errcode = '22023';
    end if;
    if jsonb_typeof(row_json -> 'price_override_minor') not in ('number', 'null')
      or jsonb_typeof(row_json -> 'low_stock_level') not in ('number', 'null') then
      raise exception 'CSV row % has invalid store price or low-stock data.', row_number using errcode = '22023';
    end if;
    if jsonb_typeof(row_json -> 'price_override_minor') = 'number'
      and row_json ->> 'price_override_minor' !~ '^\d{1,10}$' then
      raise exception 'CSV row % has an invalid store price.', row_number using errcode = '22023';
    end if;
    if jsonb_typeof(row_json -> 'low_stock_level') = 'number'
      and row_json ->> 'low_stock_level' !~ '^\d{1,8}(\.\d{1,3})?$' then
      raise exception 'CSV row % has an invalid low-stock level.', row_number using errcode = '22023';
    end if;

    if nullif(row_json ->> 'category_id', '') is not null then
      if row_json ->> 'category_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or not exists (
          select 1
          from public.categories category
          where category.id = (row_json ->> 'category_id')::uuid
            and category.organization_id = target_organization_id
            and not category.is_archived
        ) then
        raise exception 'CSV row % references an unavailable category.', row_number using errcode = '23503';
      end if;
    end if;

    if row_sku is not null and row_sku = any(seen_skus) then
      raise exception 'CSV row % repeats a SKU in this file.', row_number using errcode = '23505';
    end if;
    if row_barcode is not null and row_barcode = any(seen_barcodes) then
      raise exception 'CSV row % repeats a barcode in this file.', row_number using errcode = '23505';
    end if;
    if row_sku is not null then seen_skus := array_append(seen_skus, row_sku); end if;
    if row_barcode is not null then seen_barcodes := array_append(seen_barcodes, row_barcode); end if;
  end loop;

  for import_row in
    select value, ordinality
    from jsonb_array_elements(target_rows) with ordinality
  loop
    row_json := import_row.value;
    row_category_id := nullif(row_json ->> 'category_id', '')::uuid;
    row_price_minor := (row_json ->> 'price_minor')::bigint;
    row_cost_minor := (row_json ->> 'cost_minor')::bigint;
    row_price_override_minor := case
      when jsonb_typeof(row_json -> 'price_override_minor') = 'number'
        then (row_json ->> 'price_override_minor')::bigint
      else null
    end;
    row_low_stock_level := case
      when jsonb_typeof(row_json -> 'low_stock_level') = 'number'
        then (row_json ->> 'low_stock_level')::numeric(14, 3)
      else null
    end;

    row_product_id := private.create_catalog_product_v2(
      target_organization_id,
      row_category_id,
      btrim(row_json ->> 'name'),
      coalesce(row_json ->> 'description', ''),
      'simple',
      coalesce(row_json ->> 'sku', ''),
      coalesce(row_json ->> 'barcode', ''),
      row_price_minor,
      row_cost_minor,
      (row_json ->> 'track_inventory')::boolean,
      coalesce(row_json ->> 'unit', 'each'),
      target_store_ids,
      '[]'::jsonb,
      coalesce(row_json ->> 'image_url', ''),
      (row_json ->> 'is_variable_price')::boolean,
      (row_json ->> 'allow_fractional_quantity')::boolean
    );

    if row_price_override_minor is not null or row_low_stock_level is not null then
      update public.product_store_settings setting
      set price_override_minor = row_price_override_minor,
          low_stock_level = row_low_stock_level
      where setting.organization_id = target_organization_id
        and setting.product_id = row_product_id
        and setting.store_id = any(target_store_ids);
    end if;

    imported_count := imported_count + 1;
  end loop;

  return imported_count;
end;
$_$;


ALTER FUNCTION "private"."import_catalog_products_v2"("target_organization_id" "uuid", "target_store_ids" "uuid"[], "target_rows" "jsonb") OWNER TO "postgres";

--
-- Name: import_customers_csv("uuid", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."import_customers_csv"("target_organization_id" "uuid", "target_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  import_row record;
  row_json jsonb;
  row_number integer;
  row_name text;
  row_email text;
  row_phone text;
  row_address text;
  row_birthday date;
  row_notes text;
  row_card_code text;
  actor_employee_id uuid;
  seen_emails text[] := '{}';
  seen_phones text[] := '{}';
  seen_cards text[] := '{}';
  imported_count integer := 0;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'customers.manage')) then
    raise exception 'Customer management permission is required.' using errcode = '42501';
  end if;

  if jsonb_typeof(target_rows) <> 'array'
    or jsonb_array_length(target_rows) not between 1 and 500 then
    raise exception 'Import between 1 and 500 customer rows at a time.' using errcode = '22023';
  end if;

  select employee.id into actor_employee_id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
  limit 1;

  for import_row in
    select value, ordinality from jsonb_array_elements(target_rows) with ordinality
  loop
    row_json := import_row.value;
    row_number := case when coalesce(row_json ->> 'row_number', '') ~ '^[1-9][0-9]*$'
      then (row_json ->> 'row_number')::integer else import_row.ordinality::integer end;
    if jsonb_typeof(row_json) <> 'object' then
      raise exception 'CSV row % must be an object.', row_number using errcode = '22023';
    end if;

    row_name := btrim(coalesce(row_json ->> 'full_name', ''));
    row_email := nullif(lower(btrim(coalesce(row_json ->> 'email', ''))), '');
    row_phone := nullif(btrim(coalesce(row_json ->> 'phone', '')), '');
    row_address := nullif(btrim(coalesce(row_json ->> 'address', '')), '');
    row_notes := nullif(btrim(coalesce(row_json ->> 'notes', '')), '');
    row_card_code := nullif(btrim(coalesce(row_json ->> 'loyalty_card_code', '')), '');

    if char_length(row_name) not between 1 and 160 then
      raise exception 'CSV row % needs a customer name of at most 160 characters.', row_number using errcode = '22023';
    end if;
    if row_email is not null and (char_length(row_email) > 320 or row_email !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') then
      raise exception 'CSV row % has an invalid email address.', row_number using errcode = '22023';
    end if;
    if row_phone is not null and char_length(row_phone) not between 3 and 40 then
      raise exception 'CSV row % has an invalid phone number.', row_number using errcode = '22023';
    end if;
    if row_address is not null and char_length(row_address) not between 2 and 500 then
      raise exception 'CSV row % has an invalid address.', row_number using errcode = '22023';
    end if;
    if row_notes is not null and char_length(row_notes) not between 2 and 1000 then
      raise exception 'CSV row % has invalid notes.', row_number using errcode = '22023';
    end if;
    if row_card_code is not null and char_length(row_card_code) not between 3 and 80 then
      raise exception 'CSV row % has an invalid loyalty card code.', row_number using errcode = '22023';
    end if;

    begin
      row_birthday := nullif(btrim(coalesce(row_json ->> 'birthday', '')), '')::date;
    exception when others then
      raise exception 'CSV row % has an invalid birthday. Use YYYY-MM-DD.', row_number using errcode = '22023';
    end;

    if row_email is not null and row_email = any(seen_emails) then
      raise exception 'CSV row % repeats an email address in this file.', row_number using errcode = '23505';
    end if;
    if row_phone is not null and row_phone = any(seen_phones) then
      raise exception 'CSV row % repeats a phone number in this file.', row_number using errcode = '23505';
    end if;
    if row_card_code is not null and lower(row_card_code) = any(seen_cards) then
      raise exception 'CSV row % repeats a loyalty card code in this file.', row_number using errcode = '23505';
    end if;
    if row_email is not null and exists (select 1 from public.customers customer where customer.organization_id = target_organization_id and lower(customer.email) = row_email) then
      raise exception 'CSV row % matches an existing customer email. Update that customer instead.', row_number using errcode = '23505';
    end if;
    if row_phone is not null and exists (select 1 from public.customers customer where customer.organization_id = target_organization_id and btrim(customer.phone) = row_phone) then
      raise exception 'CSV row % matches an existing customer phone. Update that customer instead.', row_number using errcode = '23505';
    end if;
    if row_card_code is not null and exists (select 1 from public.customers customer where customer.organization_id = target_organization_id and lower(customer.loyalty_card_code) = lower(row_card_code)) then
      raise exception 'CSV row % matches an existing loyalty card code.', row_number using errcode = '23505';
    end if;

    if row_email is not null then seen_emails := array_append(seen_emails, row_email); end if;
    if row_phone is not null then seen_phones := array_append(seen_phones, row_phone); end if;
    if row_card_code is not null then seen_cards := array_append(seen_cards, lower(row_card_code)); end if;
  end loop;

  for import_row in select value from jsonb_array_elements(target_rows) loop
    insert into public.customers (organization_id, full_name, email, phone, address, birthday, notes, loyalty_card_code)
    values (
      target_organization_id,
      btrim(import_row.value ->> 'full_name'),
      nullif(lower(btrim(coalesce(import_row.value ->> 'email', ''))), ''),
      nullif(btrim(coalesce(import_row.value ->> 'phone', '')), ''),
      nullif(btrim(coalesce(import_row.value ->> 'address', '')), ''),
      nullif(btrim(coalesce(import_row.value ->> 'birthday', '')), '')::date,
      nullif(btrim(coalesce(import_row.value ->> 'notes', '')), ''),
      coalesce(nullif(btrim(coalesce(import_row.value ->> 'loyalty_card_code', '')), ''), '')
    );
    imported_count := imported_count + 1;
  end loop;

  perform private.write_audit_log(target_organization_id, 'CUSTOMERS_IMPORTED', 'customers.manage', actor_employee_id, null, null, null, null, null, 'CSV import', jsonb_build_object('row_count', imported_count));
  return imported_count;
end;
$_$;


ALTER FUNCTION "private"."import_customers_csv"("target_organization_id" "uuid", "target_rows" "jsonb") OWNER TO "postgres";

--
-- Name: import_inventory_adjustments_csv("uuid", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."import_inventory_adjustments_csv"("target_organization_id" "uuid", "target_store_id" "uuid", "target_reason_code" "text", "target_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  import_row record;
  row_json jsonb;
  row_number integer;
  actor_employee_id uuid;
  row_product_id uuid;
  row_variant_id uuid;
  row_quantity numeric(14,3);
  row_note text;
  seen_items text[] := '{}';
  imported_count integer := 0;
begin
  if (select auth.uid()) is null or not (select private.has_permission(target_organization_id, 'inventory.manage')) then raise exception 'Inventory management permission is required.' using errcode = '42501'; end if;
  if jsonb_typeof(target_rows) <> 'array' or jsonb_array_length(target_rows) not between 1 and 500 then raise exception 'Import between 1 and 500 adjustment rows at a time.' using errcode = '22023'; end if;
  actor_employee_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_employee_id is null then raise exception 'An assigned employee is required for this store.' using errcode = '42501'; end if;
  if not exists (select 1 from public.inventory_adjustment_reasons reason where reason.organization_id = target_organization_id and reason.code = upper(btrim(target_reason_code)) and reason.is_active) then raise exception 'Choose an active adjustment reason.' using errcode = '23514'; end if;

  for import_row in select value, ordinality from jsonb_array_elements(target_rows) with ordinality loop
    row_json := import_row.value;
    row_number := case when coalesce(row_json ->> 'row_number', '') ~ '^[1-9][0-9]*$' then (row_json ->> 'row_number')::integer else import_row.ordinality::integer end;
    if jsonb_typeof(row_json) <> 'object' or coalesce(row_json ->> 'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'CSV row % needs a valid item.', row_number using errcode = '22023'; end if;
    if coalesce(row_json ->> 'variant_id', '') <> '' and row_json ->> 'variant_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'CSV row % has an invalid variant.', row_number using errcode = '22023'; end if;
    if coalesce(row_json ->> 'quantity_delta', '') !~ '^-?\d{1,8}(\.\d{1,3})?$' or (row_json ->> 'quantity_delta')::numeric = 0 then raise exception 'CSV row % needs a non-zero quantity change.', row_number using errcode = '22023'; end if;
    if char_length(btrim(coalesce(row_json ->> 'note', ''))) > 500 then raise exception 'CSV row % has a note that is too long.', row_number using errcode = '22023'; end if;
    row_product_id := (row_json ->> 'product_id')::uuid;
    row_variant_id := nullif(row_json ->> 'variant_id', '')::uuid;
    if concat(row_product_id::text, '|', coalesce(row_variant_id::text, '')) = any(seen_items) then raise exception 'CSV row % repeats an item in this file.', row_number using errcode = '23505'; end if;
    if not exists (select 1 from public.inventory_levels level where level.organization_id = target_organization_id and level.store_id = target_store_id and level.product_id = row_product_id and level.variant_id is not distinct from row_variant_id) then raise exception 'CSV row % is not initialized in this store.', row_number using errcode = '23514'; end if;
    seen_items := array_append(seen_items, concat(row_product_id::text, '|', coalesce(row_variant_id::text, '')));
  end loop;
  for import_row in select value from jsonb_array_elements(target_rows) loop
    row_quantity := (import_row.value ->> 'quantity_delta')::numeric;
    row_note := nullif(btrim(coalesce(import_row.value ->> 'note', '')), '');
    perform private.record_inventory_adjustment_v2(target_organization_id, target_store_id, (import_row.value ->> 'product_id')::uuid, nullif(import_row.value ->> 'variant_id', '')::uuid, row_quantity, upper(btrim(target_reason_code)), row_note);
    imported_count := imported_count + 1;
  end loop;
  perform private.write_audit_log(target_organization_id, 'INVENTORY_ADJUSTMENTS_IMPORTED', 'inventory.adjust', actor_employee_id, null, target_store_id, null, null, null, 'CSV import', jsonb_build_object('row_count', imported_count, 'reason_code', upper(btrim(target_reason_code))));
  return imported_count;
end;
$_$;


ALTER FUNCTION "private"."import_inventory_adjustments_csv"("target_organization_id" "uuid", "target_store_id" "uuid", "target_reason_code" "text", "target_rows" "jsonb") OWNER TO "postgres";

--
-- Name: import_inventory_adjustments_csv("uuid", "uuid", "text", "jsonb", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."import_inventory_adjustments_csv"("target_organization_id" "uuid", "target_store_id" "uuid", "target_reason_code" "text", "target_rows" "jsonb", "target_operation_id" "uuid", "target_approval_request_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  import_row record;
  row_json jsonb;
  row_number integer;
  actor_id uuid;
  batch_id uuid;
  existing_batch public.inventory_adjustment_import_batches%rowtype;
  expected_payload jsonb;
  payload_fingerprint text;
  normalized_reason_code text;
  seen_items text[] := '{}';
  row_product_id uuid;
  row_variant_id uuid;
  row_quantity numeric(14,3);
  row_note text;
begin
  if (select auth.uid()) is null or target_operation_id is null then
    raise exception 'Inventory adjustment permission and operation identity are required.' using errcode = '42501';
  end if;
  if coalesce(jsonb_typeof(target_rows), '') <> 'array'
    or coalesce(jsonb_array_length(target_rows), 0) not between 1 and 500 then
    raise exception 'Import between 1 and 500 adjustment rows at a time.' using errcode = '23514';
  end if;

  normalized_reason_code := upper(btrim(coalesce(target_reason_code, '')));
  if not exists (
    select 1 from public.inventory_adjustment_reasons reason
    where reason.organization_id = target_organization_id
      and reason.code = normalized_reason_code
      and reason.is_active
  ) then
    raise exception 'Choose an active adjustment reason.' using errcode = '23514';
  end if;

  for import_row in
    select value, ordinality from jsonb_array_elements(target_rows) with ordinality
  loop
    row_json := import_row.value;
    row_number := case
      when coalesce(row_json ->> 'row_number', '') ~ '^[1-9][0-9]*$'
        then (row_json ->> 'row_number')::integer
      else import_row.ordinality::integer
    end;
    if jsonb_typeof(row_json) <> 'object'
      or coalesce(row_json ->> 'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception 'CSV row % needs a valid item.', row_number using errcode = '23514';
    end if;
    if row_json ? 'variant_id'
      and row_json -> 'variant_id' <> 'null'::jsonb
      and coalesce(row_json ->> 'variant_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception 'CSV row % has an invalid variant.', row_number using errcode = '23514';
    end if;
    if coalesce(row_json ->> 'quantity_delta', '') !~ '^-?\d{1,8}(\.\d{1,3})?$'
      or (row_json ->> 'quantity_delta')::numeric = 0 then
      raise exception 'CSV row % needs a non-zero quantity change.', row_number using errcode = '23514';
    end if;
    if char_length(btrim(coalesce(row_json ->> 'note', ''))) not between 2 and 500 then
      raise exception 'CSV row % needs an explanation between 2 and 500 characters.', row_number using errcode = '23514';
    end if;
    row_product_id := (row_json ->> 'product_id')::uuid;
    row_variant_id := nullif(row_json ->> 'variant_id', '')::uuid;
    if concat(row_product_id::text, '|', coalesce(row_variant_id::text, '')) = any(seen_items) then
      raise exception 'CSV row % repeats an item in this file.', row_number using errcode = '23505';
    end if;
    seen_items := array_append(seen_items, concat(row_product_id::text, '|', coalesce(row_variant_id::text, '')));
  end loop;

  expected_payload := jsonb_build_object(
    'store_id', target_store_id,
    'reason_code', normalized_reason_code,
    'operation_id', target_operation_id,
    'rows', target_rows
  );
  payload_fingerprint := md5(expected_payload::text);

  perform private.authorize_sensitive_operation(
    target_organization_id,
    'inventory.adjust',
    target_approval_request_id,
    expected_payload,
    target_operation_id
  );

  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for this store.' using errcode = '42501';
  end if;

  insert into public.inventory_adjustment_import_batches (
    organization_id,
    operation_id,
    store_id,
    reason_code,
    payload_fingerprint,
    item_count,
    created_by_employee_id
  ) values (
    target_organization_id,
    target_operation_id,
    target_store_id,
    normalized_reason_code,
    payload_fingerprint,
    jsonb_array_length(target_rows),
    actor_id
  ) on conflict (organization_id, operation_id) do nothing
  returning id into batch_id;

  if batch_id is null then
    select batch.* into existing_batch
    from public.inventory_adjustment_import_batches batch
    where batch.organization_id = target_organization_id
      and batch.operation_id = target_operation_id
    for key share;

    if existing_batch.id is null then
      raise exception 'The adjustment import operation could not be recovered.' using errcode = 'P0002';
    end if;
    if existing_batch.store_id <> target_store_id
      or existing_batch.reason_code <> normalized_reason_code
      or existing_batch.item_count <> jsonb_array_length(target_rows)
      or existing_batch.payload_fingerprint <> payload_fingerprint then
      raise exception 'This adjustment import operation identity was already used for different details.' using errcode = '23505';
    end if;
    return existing_batch.item_count;
  end if;

  for import_row in
    select value from jsonb_array_elements(target_rows)
  loop
    row_quantity := (import_row.value ->> 'quantity_delta')::numeric;
    row_note := btrim(import_row.value ->> 'note');
    perform private.post_inventory_adjustment(
      target_organization_id,
      target_store_id,
      (import_row.value ->> 'product_id')::uuid,
      nullif(import_row.value ->> 'variant_id', '')::uuid,
      row_quantity,
      normalized_reason_code,
      row_note,
      gen_random_uuid(),
      actor_id,
      batch_id
    );
  end loop;

  perform private.write_audit_log(
    target_organization_id,
    'INVENTORY_ADJUSTMENTS_IMPORTED',
    'inventory.adjust',
    actor_id,
    null,
    target_store_id,
    null,
    null,
    null,
    'CSV inventory adjustment import',
    jsonb_build_object(
      'batch_id', batch_id,
      'operation_id', target_operation_id,
      'row_count', jsonb_array_length(target_rows),
      'reason_code', normalized_reason_code
    )
  );

  return jsonb_array_length(target_rows);
end;
$_$;


ALTER FUNCTION "private"."import_inventory_adjustments_csv"("target_organization_id" "uuid", "target_store_id" "uuid", "target_reason_code" "text", "target_rows" "jsonb", "target_operation_id" "uuid", "target_approval_request_id" "uuid") OWNER TO "postgres";

--
-- Name: import_inventory_count_lines("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."import_inventory_count_lines"("target_organization_id" "uuid", "target_inventory_count_id" "uuid", "target_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  count_document public.inventory_counts%rowtype;
  actor_id uuid;
  row_value jsonb;
  row_line_id uuid;
  row_product_id uuid;
  row_variant_id uuid;
  row_quantity numeric(14,3);
  count_line public.inventory_count_lines%rowtype;
  imported_count integer := 0;
begin
  if jsonb_typeof(coalesce(target_rows, '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(target_rows, '[]'::jsonb)) = 0
    or jsonb_array_length(coalesce(target_rows, '[]'::jsonb)) > 500 then
    raise exception 'Provide between one and five hundred valid count rows.' using errcode = '22023';
  end if;

  select count_row.* into count_document
  from public.inventory_counts count_row
  where count_row.id = target_inventory_count_id
    and count_row.organization_id = target_organization_id
  for update;
  if count_document.id is null then
    raise exception 'Inventory count was not found.' using errcode = '23503';
  end if;
  if count_document.status not in ('draft', 'in_progress') then
    raise exception 'Only an open inventory count can import physical quantities.' using errcode = '23514';
  end if;
  actor_id := private.inventory_count_actor(target_organization_id, count_document.store_id);

  if exists (
    select 1
    from jsonb_array_elements(target_rows) duplicate_row
    group by duplicate_row ->> 'count_line_id'
    having count(*) > 1
  ) then
    raise exception 'The spreadsheet contains a duplicate count line.' using errcode = '22023';
  end if;

  -- Validate every row before recording any quantity.  The enclosing function
  -- is one transaction, so a malformed or cross-document spreadsheet cannot
  -- leave a partial physical count behind.
  for row_value in select value from jsonb_array_elements(target_rows) loop
    if coalesce(row_value ->> 'count_line_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or coalesce(row_value ->> 'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or (coalesce(row_value ->> 'variant_id', '') <> '' and row_value ->> 'variant_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
      or coalesce(row_value ->> 'counted_quantity', '') !~ '^\d{1,8}(\.\d{1,3})?$' then
      raise exception 'The spreadsheet contains an invalid count identifier or quantity.' using errcode = '22023';
    end if;
    row_line_id := (row_value ->> 'count_line_id')::uuid;
    row_product_id := (row_value ->> 'product_id')::uuid;
    row_variant_id := nullif(row_value ->> 'variant_id', '')::uuid;
    row_quantity := (row_value ->> 'counted_quantity')::numeric(14,3);

    select line.* into count_line
    from public.inventory_count_lines line
    where line.id = row_line_id
      and line.organization_id = target_organization_id
      and line.inventory_count_id = target_inventory_count_id
      and line.product_id = row_product_id
      and line.variant_id is not distinct from row_variant_id
    for update;
    if count_line.id is null then
      raise exception 'The spreadsheet contains a line that does not belong to this count.' using errcode = '23503';
    end if;
  end loop;

  for row_value in select value from jsonb_array_elements(target_rows) loop
    perform private.save_inventory_count_line(
      target_organization_id,
      target_inventory_count_id,
      (row_value ->> 'product_id')::uuid,
      nullif(row_value ->> 'variant_id', '')::uuid,
      (row_value ->> 'counted_quantity')::numeric(14,3)
    );
    imported_count := imported_count + 1;
  end loop;

  perform private.write_audit_log(
    target_organization_id,
    'INVENTORY_COUNT_LINES_IMPORTED',
    'inventory.count',
    actor_id,
    null,
    count_document.store_id,
    null,
    null,
    null,
    'Count spreadsheet import',
    jsonb_build_object(
      'inventory_count_id', count_document.id,
      'count_number', count_document.count_number,
      'imported_line_count', imported_count
    )
  );
  return imported_count;
end;
$_$;


ALTER FUNCTION "private"."import_inventory_count_lines"("target_organization_id" "uuid", "target_inventory_count_id" "uuid", "target_rows" "jsonb") OWNER TO "postgres";

--
-- Name: import_suppliers_csv("uuid", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."import_suppliers_csv"("target_organization_id" "uuid", "target_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  import_row record;
  row_json jsonb;
  row_number integer;
  row_name text;
  actor_employee_id uuid;
  seen_names text[] := '{}';
  imported_count integer := 0;
begin
  if (select auth.uid()) is null
    or (not (select private.has_permission(target_organization_id, 'inventory.manage')) and not (select private.has_inventory_capability(target_organization_id, 'purchasing.suppliers.manage'))) then
    raise exception 'Inventory management permission is required.' using errcode = '42501';
  end if;
  if jsonb_typeof(target_rows) <> 'array' or jsonb_array_length(target_rows) not between 1 and 500 then
    raise exception 'Import between 1 and 500 supplier rows at a time.' using errcode = '22023';
  end if;
  select employee.id into actor_employee_id from public.employees employee where employee.organization_id = target_organization_id and employee.profile_id = (select auth.uid()) and employee.status = 'active' limit 1;

  for import_row in select value, ordinality from jsonb_array_elements(target_rows) with ordinality loop
    row_json := import_row.value;
    row_number := case when coalesce(row_json ->> 'row_number', '') ~ '^[1-9][0-9]*$' then (row_json ->> 'row_number')::integer else import_row.ordinality::integer end;
    if jsonb_typeof(row_json) <> 'object' then raise exception 'CSV row % must be an object.', row_number using errcode = '22023'; end if;
    row_name := lower(btrim(coalesce(row_json ->> 'name', '')));
    if char_length(row_name) not between 1 and 160 then raise exception 'CSV row % needs a supplier name of at most 160 characters.', row_number using errcode = '22023'; end if;
    if char_length(btrim(coalesce(row_json ->> 'contact_name', ''))) > 160 or char_length(btrim(coalesce(row_json ->> 'email', ''))) > 320 or char_length(btrim(coalesce(row_json ->> 'phone', ''))) > 40 or char_length(btrim(coalesce(row_json ->> 'address', ''))) > 1000 or char_length(btrim(coalesce(row_json ->> 'notes', ''))) > 2000 then raise exception 'CSV row % has a field that is too long.', row_number using errcode = '22023'; end if;
    if nullif(btrim(coalesce(row_json ->> 'email', '')), '') is not null and btrim(row_json ->> 'email') !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then raise exception 'CSV row % has an invalid email address.', row_number using errcode = '22023'; end if;
    if row_name = any(seen_names) then raise exception 'CSV row % repeats a supplier name in this file.', row_number using errcode = '23505'; end if;
    if exists (select 1 from public.suppliers supplier where supplier.organization_id = target_organization_id and lower(btrim(supplier.name)) = row_name) then raise exception 'CSV row % matches an existing supplier. Update that supplier instead.', row_number using errcode = '23505'; end if;
    seen_names := array_append(seen_names, row_name);
  end loop;

  for import_row in select value from jsonb_array_elements(target_rows) loop
    insert into public.suppliers (organization_id, name, contact_name, email, phone, address, notes)
    values (target_organization_id, btrim(import_row.value ->> 'name'), nullif(btrim(coalesce(import_row.value ->> 'contact_name', '')), ''), nullif(lower(btrim(coalesce(import_row.value ->> 'email', ''))), ''), nullif(btrim(coalesce(import_row.value ->> 'phone', '')), ''), nullif(btrim(coalesce(import_row.value ->> 'address', '')), ''), nullif(btrim(coalesce(import_row.value ->> 'notes', '')), ''));
    imported_count := imported_count + 1;
  end loop;
  perform private.write_audit_log(target_organization_id, 'SUPPLIERS_IMPORTED', 'inventory.manage', actor_employee_id, null, null, null, null, null, 'CSV import', jsonb_build_object('row_count', imported_count));
  return imported_count;
end;
$_$;


ALTER FUNCTION "private"."import_suppliers_csv"("target_organization_id" "uuid", "target_rows" "jsonb") OWNER TO "postgres";

--
-- Name: initialize_inventory_levels_for_setting(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."initialize_inventory_levels_for_setting"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  tracked boolean;
  item_type text;
begin
  if not new.is_available then
    return new;
  end if;

  select product.track_inventory, product.product_type
  into tracked, item_type
  from public.products product
  where product.id = new.product_id
    and product.organization_id = new.organization_id;

  if not coalesce(tracked, false) then
    return new;
  end if;

  if item_type = 'simple' then
    insert into public.inventory_levels (
      organization_id,
      store_id,
      product_id,
      variant_id,
      quantity
    )
    values (
      new.organization_id,
      new.store_id,
      new.product_id,
      null,
      0
    )
    on conflict on constraint inventory_levels_saleable_unique do nothing;
  else
    insert into public.inventory_levels (
      organization_id,
      store_id,
      product_id,
      variant_id,
      quantity
    )
    select
      new.organization_id,
      new.store_id,
      new.product_id,
      variant.id,
      0
    from public.product_variants variant
    where variant.organization_id = new.organization_id
      and variant.product_id = new.product_id
      and variant.is_active
    on conflict on constraint inventory_levels_saleable_unique do nothing;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."initialize_inventory_levels_for_setting"() OWNER TO "postgres";

--
-- Name: initialize_product_base_unit(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."initialize_product_base_unit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.product_units (
    organization_id, product_id, unit_code, unit_name, factor_to_base, is_base, is_sale_unit
  ) values (
    new.organization_id, new.id, lower(new.unit), new.unit, 1, true, true
  ) on conflict (product_id, unit_code) do nothing;
  return new;
end;
$$;


ALTER FUNCTION "private"."initialize_product_base_unit"() OWNER TO "postgres";

--
-- Name: inventory_actor("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."inventory_actor"("target_organization_id" "uuid", "target_store_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select employee.id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
    and (select private.has_store_read_scope(target_organization_id, target_store_id))
  order by employee.created_at
  limit 1;
$$;


ALTER FUNCTION "private"."inventory_actor"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "inventory_actor"("target_organization_id" "uuid", "target_store_id" "uuid"); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."inventory_actor"("target_organization_id" "uuid", "target_store_id" "uuid") IS 'Returns the active authenticated employee when the central capability/store-scope model authorizes the target store. Organization-wide stores.manage roles do not require per-store assignments.';


--
-- Name: inventory_count_actor("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."inventory_count_actor"("target_organization_id" "uuid", "target_store_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select private.inventory_count_actor(
    target_organization_id,
    target_store_id,
    array['inventory.count.create']::text[]
  );
$$;


ALTER FUNCTION "private"."inventory_count_actor"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

--
-- Name: inventory_count_actor("uuid", "uuid", "text"[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."inventory_count_actor"("target_organization_id" "uuid", "target_store_id" "uuid", "requested_capabilities" "text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
begin
  if (select auth.uid()) is null
    or coalesce(cardinality(requested_capabilities), 0) = 0
    or not (select private.has_all_inventory_capabilities(target_organization_id, requested_capabilities)) then
    raise exception 'Inventory count permission is required.' using errcode = '42501';
  end if;
  if not (select private.has_store_read_scope(target_organization_id, target_store_id)) then
    raise exception 'Store access is required for this inventory count.' using errcode = '42501';
  end if;

  actor_id := private.current_employee_id(target_organization_id);
  if actor_id is null or not exists (
    select 1
    from public.employees employee
    where employee.id = actor_id
      and employee.organization_id = target_organization_id
      and employee.status = 'active'
  ) then
    raise exception 'An active employee record is required.' using errcode = '42501';
  end if;
  return actor_id;
end;
$$;


ALTER FUNCTION "private"."inventory_count_actor"("target_organization_id" "uuid", "target_store_id" "uuid", "requested_capabilities" "text"[]) OWNER TO "postgres";

--
-- Name: inventory_organization_actor("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."inventory_organization_actor"("target_organization_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select employee.id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
  limit 1;
$$;


ALTER FUNCTION "private"."inventory_organization_actor"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: is_organization_creator("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."is_organization_creator"("target_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (select auth.uid()) is not null
    and exists (
      select 1
      from public.organizations organization
      where organization.id = target_organization_id
        and organization.created_by = (select auth.uid())
        and organization.status = 'active'
    ), false);
$$;


ALTER FUNCTION "private"."is_organization_creator"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: is_organization_member("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."is_organization_member"("target_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    (select auth.uid()) is not null
    and exists (
      select 1
      from public.employees employee
      join public.organizations organization
        on organization.id = employee.organization_id
       and organization.status = 'active'
      where employee.organization_id = target_organization_id
        and employee.profile_id = (select auth.uid())
        and employee.status = 'active'
    );
$$;


ALTER FUNCTION "private"."is_organization_member"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: issue_kitchen_order_from_completed_sale(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."issue_kitchen_order_from_completed_sale"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  resolved_order_id uuid;
  resolved_order_number bigint;
begin
  if new.dining_option_id is null or old.dining_option_id is not null then
    return new;
  end if;

  select receipt.receipt_number
  into resolved_order_number
  from public.receipts receipt
  where receipt.organization_id = new.organization_id
    and receipt.sale_id = new.id;

  if resolved_order_number is null then
    raise exception 'A completed dining sale must have a receipt before it can be sent to the kitchen.' using errcode = '23514';
  end if;

  insert into public.kitchen_orders (
    organization_id,
    store_id,
    register_id,
    sale_id,
    order_number,
    dining_option_name_snapshot,
    order_label,
    order_note
  )
  values (
    new.organization_id,
    new.store_id,
    new.register_id,
    new.id,
    resolved_order_number,
    new.dining_option_name_snapshot,
    coalesce(
      (
        select ticket.label
        from public.open_tickets ticket
        where ticket.organization_id = new.organization_id
          and ticket.id = new.open_ticket_id
      ),
      'Order #' || resolved_order_number::text
    ),
    (
      select ticket.note
      from public.open_tickets ticket
      where ticket.organization_id = new.organization_id
        and ticket.id = new.open_ticket_id
    )
  )
  returning id into resolved_order_id;

  insert into public.kitchen_order_items (
    organization_id,
    kitchen_order_id,
    sale_item_id,
    line_number,
    product_name_snapshot,
    variant_name_snapshot,
    modifiers_snapshot,
    quantity,
    station
  )
  select
    sale_item.organization_id,
    resolved_order_id,
    sale_item.id,
    row_number() over (order by sale_item.created_at, sale_item.id)::smallint,
    sale_item.product_name_snapshot,
    sale_item.variant_name_snapshot,
    sale_item.modifiers_snapshot,
    sale_item.quantity,
    private.default_kitchen_station_for_category(
      sale_item.organization_id,
      product.category_id,
      category.name
    )
  from public.sale_items sale_item
  join public.products product
    on product.id = sale_item.product_id
   and product.organization_id = sale_item.organization_id
  left join public.categories category
    on category.id = product.category_id
   and category.organization_id = product.organization_id
  where sale_item.organization_id = new.organization_id
    and sale_item.sale_id = new.id;

  if not found then
    raise exception 'A completed dining sale must have at least one line before it can be sent to the kitchen.' using errcode = '23514';
  end if;

  return new;
end;
$$;


