--
-- Name: manage_organization_lifecycle("uuid", "text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."manage_organization_lifecycle"("target_organization_id" "uuid", "target_action" "text", "target_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_action text := upper(btrim(coalesce(target_action, '')));
  normalized_reason text := nullif(btrim(coalesce(target_reason, '')), '');
  organization_record public.organizations%rowtype;
  actor_employee_id uuid;
  rate_limit_result jsonb;
begin
  if not private.has_organization_lifecycle_access(target_organization_id) then
    raise exception 'Only an organization owner can change this lifecycle.' using errcode = '42501';
  end if;

  rate_limit_result := private.consume_organization_rate_limit(
    target_organization_id,
    'organization.lifecycle'
  );

  if not coalesce((rate_limit_result ->> 'allowed')::boolean, false) then
    return rate_limit_result;
  end if;

  select organization.*
  into organization_record
  from public.organizations organization
  where organization.id = target_organization_id
  for update;

  if not found then
    raise exception 'Organization was not found.' using errcode = 'P0002';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
  order by employee.created_at
  limit 1;

  if normalized_action in ('SUSPEND', 'REQUEST_ARCHIVE')
    and (normalized_reason is null or char_length(normalized_reason) not between 3 and 500) then
    raise exception 'Provide a reason between 3 and 500 characters.' using errcode = '22023';
  end if;

  if organization_record.status = 'archived' and normalized_action <> 'ARCHIVE' then
    raise exception 'Archived organizations are retained and cannot be reactivated.' using errcode = '22023';
  end if;

  case normalized_action
    when 'SUSPEND' then
      if organization_record.status = 'suspended' then
        raise exception 'This organization is already suspended.' using errcode = '22023';
      end if;

      perform private.write_audit_log(
        target_organization_id, 'ORGANIZATION_SUSPENDED', 'organization.archive', actor_employee_id,
        null, null, null, null, null, normalized_reason,
        jsonb_build_object('previous_status', organization_record.status)
      );

      update public.organizations organization
      set status = 'suspended',
          suspended_at = now(),
          suspension_reason = normalized_reason
      where organization.id = target_organization_id;

    when 'RESUME' then
      if organization_record.status <> 'suspended' then
        raise exception 'Only a suspended organization can be resumed.' using errcode = '22023';
      end if;

      update public.organizations organization
      set status = 'active',
          suspended_at = null,
          suspension_reason = null
      where organization.id = target_organization_id;

      perform private.write_audit_log(
        target_organization_id, 'ORGANIZATION_RESUMED', 'organization.archive', actor_employee_id,
        null, null, null, null, null, null,
        jsonb_build_object('previous_status', organization_record.status)
      );

    when 'REQUEST_ARCHIVE' then
      if organization_record.archive_requested_at is not null then
        raise exception 'An archive request is already open for this organization.' using errcode = '22023';
      end if;

      update public.organizations organization
      set archive_requested_at = clock_timestamp(),
          archive_requested_by_employee_id = actor_employee_id
      where organization.id = target_organization_id;

      perform private.write_audit_log(
        target_organization_id, 'ORGANIZATION_ARCHIVE_REQUESTED', 'organization.lifecycle', actor_employee_id,
        null, null, null, null, null, normalized_reason,
        jsonb_build_object('status', organization_record.status)
      );

    when 'CANCEL_ARCHIVE' then
      if organization_record.archive_requested_at is null then
        raise exception 'There is no archive request to cancel.' using errcode = '22023';
      end if;

      update public.organizations organization
      set archive_requested_at = null,
          archive_requested_by_employee_id = null
      where organization.id = target_organization_id;

      perform private.write_audit_log(
        target_organization_id, 'ORGANIZATION_ARCHIVE_CANCELLED', 'organization.lifecycle', actor_employee_id,
        null, null, null, null, null, null,
        '{}'::jsonb
      );

    when 'ARCHIVE' then
      if organization_record.archive_requested_at is null then
        raise exception 'Request an archive and download an export before archiving this organization.' using errcode = '22023';
      end if;

      -- organizations_archive_export_delivered verifies that a fresh export
      -- was delivered after this request before this status can be changed.
      perform private.write_audit_log(
        target_organization_id, 'ORGANIZATION_ARCHIVED', 'organization.archive', actor_employee_id,
        null, null, null, null, null, null,
        jsonb_build_object('archive_requested_at', organization_record.archive_requested_at)
      );

      update public.organizations organization
      set status = 'archived',
          archived_at = now(),
          suspended_at = null,
          suspension_reason = null
      where organization.id = target_organization_id;

    else
      raise exception 'Unsupported organization lifecycle action.' using errcode = '22023';
  end case;

  select organization.*
  into organization_record
  from public.organizations organization
  where organization.id = target_organization_id;

  return rate_limit_result || jsonb_build_object(
    'status', organization_record.status,
    'suspended_at', organization_record.suspended_at,
    'archive_requested_at', organization_record.archive_requested_at,
    'archived_at', organization_record.archived_at
  );
end;
$$;


ALTER FUNCTION "private"."manage_organization_lifecycle"("target_organization_id" "uuid", "target_action" "text", "target_reason" "text") OWNER TO "postgres";

--
-- Name: normalize_open_ticket_cart("jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."normalize_open_ticket_cart"("target_cart" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  normalized_cart jsonb;
begin
  if target_cart is null or jsonb_typeof(target_cart) <> 'array'
    or jsonb_array_length(target_cart) not between 1 and 100 then
    raise exception 'An open ticket must contain between 1 and 100 items.' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(target_cart) line(value)
    where jsonb_typeof(line.value) <> 'object'
      or (
        line.value ? 'ticket_line_id'
        and (
          jsonb_typeof(line.value -> 'ticket_line_id') <> 'string'
          or coalesce(line.value ->> 'ticket_line_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        )
      )
      or (
        line.value ? 'item_note'
        and line.value -> 'item_note' <> 'null'::jsonb
        and (
          jsonb_typeof(line.value -> 'item_note') <> 'string'
          or char_length(btrim(line.value ->> 'item_note')) not between 1 and 500
        )
      )
  ) then
    raise exception 'Ticket item notes or line references are invalid.' using errcode = '23514';
  end if;

  if (
    select count(*)
    from jsonb_array_elements(target_cart) line(value)
    where line.value ? 'ticket_line_id'
  ) <> (
    select count(distinct line.value ->> 'ticket_line_id')
    from jsonb_array_elements(target_cart) line(value)
    where line.value ? 'ticket_line_id'
  ) then
    raise exception 'Each ticket line must have a unique reference.' using errcode = '23514';
  end if;

  select coalesce(
    jsonb_agg(
      line.value || jsonb_build_object(
        'ticket_line_id', coalesce(line.value ->> 'ticket_line_id', gen_random_uuid()::text),
        'item_note', nullif(btrim(coalesce(line.value ->> 'item_note', '')), '')
      )
      order by line.ordinality
    ),
    '[]'::jsonb
  )
  into normalized_cart
  from jsonb_array_elements(target_cart) with ordinality line(value, ordinality);

  return normalized_cart;
end;
$_$;


ALTER FUNCTION "private"."normalize_open_ticket_cart"("target_cart" "jsonb") OWNER TO "postgres";

--
-- Name: open_register_shift("uuid", "uuid", "uuid", bigint, "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."open_register_shift"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid", "target_opening_cash_minor" bigint, "target_opening_note" "text") RETURNS TABLE("shift_id" "uuid", "opened_at" timestamp with time zone, "was_replayed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  existing_shift public.shifts%rowtype;
  normalized_opening_note text;
begin
  if target_organization_id is null
    or target_store_id is null
    or target_register_id is null
    or target_opening_cash_minor is null
    or target_opening_cash_minor < 0 then
    raise exception 'A store, register, and non-negative opening cash amount are required.'
      using errcode = '23514';
  end if;

  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'shifts.open')) then
    raise exception 'Shift opening permission is required.' using errcode = '42501';
  end if;

  normalized_opening_note := nullif(trim(coalesce(target_opening_note, '')), '');
  if normalized_opening_note is not null
    and char_length(normalized_opening_note) not between 2 and 500 then
    raise exception 'An opening note must contain between 2 and 500 characters.'
      using errcode = '23514';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  join public.employee_stores employee_store
    on employee_store.employee_id = employee.id
   and employee_store.organization_id = employee.organization_id
   and employee_store.store_id = target_store_id
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
  for update of employee;

  if actor_employee_id is null then
    raise exception 'An active employee assignment for this store is required.'
      using errcode = '42501';
  end if;

  perform 1
  from public.registers register
  join public.stores store
    on store.id = register.store_id
   and store.organization_id = register.organization_id
  where register.id = target_register_id
    and register.organization_id = target_organization_id
    and register.store_id = target_store_id
    and register.is_active
    and store.is_active
  for update of register;

  if not found then
    raise exception 'Select an active register belonging to this store.' using errcode = '23514';
  end if;

  select shift.*
  into existing_shift
  from public.shifts shift
  where shift.organization_id = target_organization_id
    and shift.register_id = target_register_id
    and shift.status = 'open'
  for update;

  if existing_shift.id is not null then
    if existing_shift.opened_by_employee_id = actor_employee_id
      and existing_shift.opening_cash_minor = target_opening_cash_minor
      and existing_shift.opening_note is not distinct from normalized_opening_note then
      return query select existing_shift.id, existing_shift.opened_at, true;
      return;
    end if;

    raise exception 'This register already has an open shift.' using errcode = '23505';
  end if;

  if exists (
    select 1
    from public.shifts shift
    where shift.organization_id = target_organization_id
      and shift.opened_by_employee_id = actor_employee_id
      and shift.status = 'open'
  ) then
    raise exception 'Close your existing register shift before opening another one.'
      using errcode = '23505';
  end if;

  return query
  insert into public.shifts as inserted_shift (
    organization_id,
    store_id,
    register_id,
    opened_by_employee_id,
    opening_cash_minor,
    opening_note
  )
  values (
    target_organization_id,
    target_store_id,
    target_register_id,
    actor_employee_id,
    target_opening_cash_minor,
    normalized_opening_note
  )
  returning inserted_shift.id, inserted_shift.opened_at, false;
end;
$$;


ALTER FUNCTION "private"."open_register_shift"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid", "target_opening_cash_minor" bigint, "target_opening_note" "text") OWNER TO "postgres";

--
-- Name: post_inventory_adjustment("uuid", "uuid", "uuid", "uuid", numeric, "text", "text", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."post_inventory_adjustment"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_reason_code" "text", "target_note" "text", "target_operation_id" "uuid", "target_actor_employee_id" "uuid", "target_import_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  selected_reason public.inventory_adjustment_reasons%rowtype;
  existing_adjustment public.inventory_adjustments%rowtype;
  adjustment_id uuid;
  created_adjustment_number bigint;
  movement_id uuid;
  current_quantity numeric(14,3);
  quantity_before numeric(14,3);
  quantity_after numeric(14,3);
  resolved_note text;
begin
  if target_operation_id is null then
    raise exception 'An adjustment operation identity is required.' using errcode = '23514';
  end if;

  if target_quantity_delta is null
    or target_quantity_delta = 0
    or target_quantity_delta <> round(target_quantity_delta, 3) then
    raise exception 'Adjustment quantity must be non-zero with at most three decimal places.' using errcode = '23514';
  end if;

  resolved_note := nullif(btrim(coalesce(target_note, '')), '');
  if char_length(coalesce(resolved_note, '')) not between 2 and 500 then
    raise exception 'Provide an adjustment explanation between 2 and 500 characters.' using errcode = '23514';
  end if;

  select reason.* into selected_reason
  from public.inventory_adjustment_reasons reason
  where reason.organization_id = target_organization_id
    and reason.code = upper(btrim(coalesce(target_reason_code, '')))
    and reason.is_active;
  if selected_reason.id is null then
    raise exception 'Choose an active adjustment reason.' using errcode = '23514';
  end if;

  if not exists (
    select 1
    from public.products product
    join public.product_store_settings setting
      on setting.organization_id = product.organization_id
     and setting.product_id = product.id
     and setting.store_id = target_store_id
     and setting.is_available
    where product.id = target_product_id
      and product.organization_id = target_organization_id
      and product.status = 'active'
      and product.track_inventory
  ) then
    raise exception 'Choose an active inventory-tracked item available in this store.' using errcode = '23514';
  end if;

  select adjustment.* into existing_adjustment
  from public.inventory_adjustments adjustment
  where adjustment.organization_id = target_organization_id
    and adjustment.operation_id = target_operation_id
  for key share;

  if existing_adjustment.id is not null then
    if existing_adjustment.store_id <> target_store_id
      or existing_adjustment.product_id <> target_product_id
      or existing_adjustment.variant_id is distinct from target_variant_id
      or existing_adjustment.quantity_delta <> target_quantity_delta
      or existing_adjustment.reason_code <> selected_reason.code
      or existing_adjustment.note is distinct from resolved_note
      or existing_adjustment.import_batch_id is distinct from target_import_batch_id then
      raise exception 'This adjustment operation identity was already used for different details.' using errcode = '23505';
    end if;

    select movement.id into movement_id
    from public.inventory_movements movement
    where movement.organization_id = target_organization_id
      and movement.source_type = 'inventory_adjustment'
      and movement.source_id = existing_adjustment.id;
    if movement_id is null then
      raise exception 'The existing adjustment is missing its inventory movement.' using errcode = 'P0002';
    end if;
    return movement_id;
  end if;

  if selected_reason.movement_type = 'OPENING_STOCK' then
    select level.quantity into current_quantity
    from public.inventory_levels level
    where level.organization_id = target_organization_id
      and level.store_id = target_store_id
      and level.product_id = target_product_id
      and level.variant_id is not distinct from target_variant_id
    for update;

    if current_quantity is null
      or current_quantity <> 0
      or exists (
        select 1
        from public.inventory_movements movement
        where movement.organization_id = target_organization_id
          and movement.store_id = target_store_id
          and movement.product_id = target_product_id
          and movement.variant_id is not distinct from target_variant_id
      ) then
      raise exception 'Opening stock can only be recorded once for an item with no prior movement.' using errcode = '23514';
    end if;
  end if;

  insert into public.inventory_adjustments (
    organization_id, store_id, product_id, variant_id, quantity_delta, reason_code,
    note, operation_id, import_batch_id, created_by_employee_id
  ) values (
    target_organization_id, target_store_id, target_product_id, target_variant_id,
    target_quantity_delta, selected_reason.code, resolved_note, target_operation_id,
    target_import_batch_id, target_actor_employee_id
  ) returning id, adjustment_number into adjustment_id, created_adjustment_number;

  perform private.apply_inventory_change_v2(
    target_organization_id, target_store_id, target_product_id, target_variant_id,
    target_quantity_delta, selected_reason.movement_type, target_actor_employee_id,
    resolved_note, 'inventory_adjustment', adjustment_id, null, selected_reason.code
  );

  select movement.id, movement.quantity_before, movement.quantity_after
  into movement_id, quantity_before, quantity_after
  from public.inventory_movements movement
  where movement.organization_id = target_organization_id
    and movement.source_type = 'inventory_adjustment'
    and movement.source_id = adjustment_id;

  if movement_id is null then
    raise exception 'The adjustment movement was not recorded.' using errcode = 'P0002';
  end if;

  perform private.write_audit_log(
    target_organization_id, 'INVENTORY_ADJUSTED', 'inventory.adjust',
    target_actor_employee_id, null, target_store_id, null, null, null, resolved_note,
    jsonb_build_object(
      'adjustment_id', adjustment_id,
      'adjustment_number', created_adjustment_number,
      'operation_id', target_operation_id,
      'import_batch_id', target_import_batch_id,
      'reason_code', selected_reason.code,
      'movement_type', selected_reason.movement_type,
      'quantity_before', quantity_before,
      'quantity_delta', target_quantity_delta,
      'quantity_after', quantity_after
    )
  );

  return movement_id;
end;
$$;


ALTER FUNCTION "private"."post_inventory_adjustment"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_reason_code" "text", "target_note" "text", "target_operation_id" "uuid", "target_actor_employee_id" "uuid", "target_import_batch_id" "uuid") OWNER TO "postgres";

--
-- Name: post_inventory_count("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."post_inventory_count"("target_organization_id" "uuid", "target_inventory_count_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  count_document public.inventory_counts%rowtype;
  actor_id uuid;
  line public.inventory_count_lines%rowtype;
  variance numeric(14,3);
  posted_line_count integer := 0;
  total_variance numeric(14,3) := 0;
begin
  select count_row.* into count_document
  from public.inventory_counts count_row
  where count_row.id = target_inventory_count_id
    and count_row.organization_id = target_organization_id
  for update;

  if count_document.id is null or count_document.status <> 'ready_for_review' then
    raise exception 'Only a reviewed inventory count can be posted.' using errcode = '23514';
  end if;

  actor_id := private.inventory_count_actor(target_organization_id, count_document.store_id, array['inventory.count.finalize']::text[]);

  for line in
    select saved_line.*
    from public.inventory_count_lines saved_line
    where saved_line.organization_id = target_organization_id
      and saved_line.inventory_count_id = target_inventory_count_id
    order by saved_line.line_sort_order, saved_line.id
  loop
    if line.counted_quantity is null
      or line.reconciled_expected_quantity is null
      or line.counted_at is null then
      raise exception 'Every prepared item must be counted and reconciled before posting.' using errcode = '23514';
    end if;

    -- The stored reconciled expected quantity was captured under the same
    -- inventory-level row lock used by sales, receipts, transfers, and other
    -- canonical movements.  Movements after this line was counted remain in
    -- the live projection; only this measured variance is added at posting.
    variance := line.counted_quantity - line.reconciled_expected_quantity;
    total_variance := total_variance + variance;
    posted_line_count := posted_line_count + 1;

    if variance <> 0 then
      perform private.apply_inventory_change_v2(
        target_organization_id,
        count_document.store_id,
        line.product_id,
        line.variant_id,
        variance,
        'COUNT',
        actor_id,
        'Inventory count variance posted',
        'inventory_count',
        count_document.id,
        null,
        'COUNT_VARIANCE'
      );
    end if;
  end loop;

  update public.inventory_counts
  set status = 'posted',
      completed_by_employee_id = actor_id,
      completed_at = clock_timestamp(),
      updated_at = clock_timestamp()
  where id = target_inventory_count_id;

  perform private.write_audit_log(
    target_organization_id,
    'INVENTORY_COUNT_POSTED',
    'inventory.count',
    actor_id,
    null,
    count_document.store_id,
    null,
    null,
    null,
    count_document.note,
    jsonb_build_object(
      'inventory_count_id', count_document.id,
      'count_number', count_document.count_number,
      'line_count', posted_line_count,
      'reconciled_variance', total_variance
    )
  );
end;
$$;


ALTER FUNCTION "private"."post_inventory_count"("target_organization_id" "uuid", "target_inventory_count_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "post_inventory_count"("target_organization_id" "uuid", "target_inventory_count_id" "uuid"); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."post_inventory_count"("target_organization_id" "uuid", "target_inventory_count_id" "uuid") IS 'Posts only count variance against the line reconciliation point so concurrent ledger movements remain intact.';


--
-- Name: post_inventory_count_idempotent("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."post_inventory_count_idempotent"("target_organization_id" "uuid", "target_inventory_count_id" "uuid", "target_operation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  count_document public.inventory_counts%rowtype;
begin
  if target_operation_id is null then
    raise exception 'An inventory count posting operation ID is required.' using errcode = '23514';
  end if;

  select count_row.* into count_document
  from public.inventory_counts count_row
  where count_row.id = target_inventory_count_id
    and count_row.organization_id = target_organization_id
  for update;

  if count_document.id is null then
    raise exception 'Only a reviewed inventory count can be posted.' using errcode = '23514';
  end if;

  -- Preserve the existing capability, store-scope, active-employee, and
  -- authenticated-session checks even when this is a successful replay.
  perform private.inventory_count_actor(
    target_organization_id,
    count_document.store_id,
    array['inventory.count.finalize']::text[]
  );

  if count_document.status = 'posted'
    and count_document.post_operation_id = target_operation_id then
    return;
  end if;

  if count_document.status <> 'ready_for_review' then
    raise exception 'Only a reviewed inventory count can be posted.' using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.inventory_counts existing_count
    where existing_count.organization_id = target_organization_id
      and existing_count.post_operation_id = target_operation_id
      and existing_count.id <> target_inventory_count_id
  ) then
    raise exception 'This inventory count posting operation has already been used for another count.' using errcode = '23514';
  end if;

  update public.inventory_counts
  set post_operation_id = target_operation_id,
      updated_at = clock_timestamp()
  where id = count_document.id;

  -- Delegate all ledger, reconciliation, audit, and historical document work
  -- to the existing canonical posting function.  If it fails, this operation
  -- identifier update rolls back with the same transaction.
  perform private.post_inventory_count(target_organization_id, target_inventory_count_id);
end;
$$;


ALTER FUNCTION "private"."post_inventory_count_idempotent"("target_organization_id" "uuid", "target_inventory_count_id" "uuid", "target_operation_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "post_inventory_count_idempotent"("target_organization_id" "uuid", "target_inventory_count_id" "uuid", "target_operation_id" "uuid"); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."post_inventory_count_idempotent"("target_organization_id" "uuid", "target_inventory_count_id" "uuid", "target_operation_id" "uuid") IS 'Makes an authorized retry of an inventory-count post a no-op only when it uses the same count operation ID.';


--
-- Name: prepare_organization_export("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."prepare_organization_export"("target_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rate_limit_result jsonb;
  export_session_id uuid;
  actor_employee_id uuid;
begin
  rate_limit_result := private.consume_organization_rate_limit(
    target_organization_id,
    'organization.export'
  );

  if not coalesce((rate_limit_result ->> 'allowed')::boolean, false) then
    return rate_limit_result;
  end if;

  delete from public.organization_export_sessions session
  where session.expires_at <= now();

  insert into public.organization_export_sessions (organization_id, profile_id, expires_at)
  values (target_organization_id, (select auth.uid()), now() + interval '1 hour')
  returning id into export_session_id;

  select employee.id
  into actor_employee_id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
  order by employee.created_at
  limit 1;

  perform private.write_audit_log(
    target_organization_id,
    'ORGANIZATION_EXPORT_PREPARED',
    'organization.export',
    actor_employee_id,
    null,
    null,
    null,
    null,
    null,
    null,
    jsonb_build_object('expires_at', now() + interval '1 hour')
  );

  return rate_limit_result || jsonb_build_object(
    'export_session_id', export_session_id,
    'expires_at', now() + interval '1 hour'
  );
end;
$$;


ALTER FUNCTION "private"."prepare_organization_export"("target_organization_id" "uuid") OWNER TO "postgres";

