--
-- Name: produce_composite("uuid", "uuid", "uuid", numeric, "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."produce_composite"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_quantity" numeric, "target_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; run_id uuid; recipe_item record; component_level public.inventory_levels%rowtype; output_level public.inventory_levels%rowtype; component_quantity numeric(14,3); total_cost numeric := 0; output_unit_cost bigint;
begin
  if (select auth.uid()) is null or not (select private.has_permission(target_organization_id, 'inventory.manage')) then raise exception 'Inventory permission is required.' using errcode = '42501'; end if;
  if target_quantity is null or target_quantity <= 0 or target_quantity <> round(target_quantity, 3) then raise exception 'Production quantity must be positive and use at most three decimals.' using errcode = '23514'; end if;
  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then raise exception 'An assigned employee is required for this store.' using errcode = '42501'; end if;
  if not exists (select 1 from public.products product where product.id = target_product_id and product.organization_id = target_organization_id and product.is_composite and product.track_inventory and product.status = 'active') then raise exception 'Choose an active composite inventory product.' using errcode = '23514'; end if;
  if not exists (select 1 from public.product_components recipe where recipe.organization_id = target_organization_id and recipe.product_id = target_product_id) then raise exception 'This composite product needs at least one component recipe item.' using errcode = '23514'; end if;
  perform 1 from public.inventory_levels level where level.organization_id = target_organization_id and level.store_id = target_store_id and (level.product_id = target_product_id or exists (select 1 from public.product_components recipe where recipe.organization_id = target_organization_id and recipe.product_id = target_product_id and recipe.component_product_id = level.product_id and recipe.component_variant_id is not distinct from level.variant_id)) order by level.product_id, level.variant_id for update;
  select * into output_level from public.inventory_levels level where level.organization_id = target_organization_id and level.store_id = target_store_id and level.product_id = target_product_id and level.variant_id is null for update;
  if output_level.id is null then raise exception 'The composite output stock projection is not initialized.' using errcode = '23514'; end if;
  insert into public.production_runs (organization_id, store_id, product_id, quantity_produced, produced_by_employee_id, note)
  values (target_organization_id, target_store_id, target_product_id, target_quantity, actor_id, nullif(btrim(target_note), '')) returning id into run_id;
  for recipe_item in select * from public.product_components recipe where recipe.organization_id = target_organization_id and recipe.product_id = target_product_id order by recipe.component_product_id, recipe.component_variant_id loop
    component_quantity := recipe_item.quantity_per_composite * target_quantity;
    select * into component_level from public.inventory_levels level where level.organization_id = target_organization_id and level.store_id = target_store_id and level.product_id = recipe_item.component_product_id and level.variant_id is not distinct from recipe_item.component_variant_id for update;
    if component_level.id is null or component_level.quantity < component_quantity then raise exception 'One production component has insufficient stock.' using errcode = '23514'; end if;
    total_cost := total_cost + component_quantity * component_level.average_cost_minor;
    perform private.apply_inventory_change_v2(target_organization_id, target_store_id, component_level.product_id, component_level.variant_id, -component_quantity, 'PRODUCTION', actor_id, 'Consumed by production', 'production_run', run_id, component_level.average_cost_minor);
  end loop;
  output_unit_cost := round(total_cost / target_quantity)::bigint;
  perform private.apply_inventory_change_v2(target_organization_id, target_store_id, target_product_id, null, target_quantity, 'PRODUCTION', actor_id, 'Produced composite stock', 'production_run', run_id, output_unit_cost);
  perform private.write_audit_log(target_organization_id, 'PRODUCTION_COMPLETED', 'inventory.manage', actor_id, null, target_store_id, null, null, null, target_note, jsonb_build_object('production_run_id', run_id, 'product_id', target_product_id, 'quantity', target_quantity, 'unit_cost_minor', output_unit_cost));
  return run_id;
end;
$$;


ALTER FUNCTION "private"."produce_composite"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_quantity" numeric, "target_note" "text") OWNER TO "postgres";

--
-- Name: produce_composite("uuid", "uuid", "uuid", numeric, "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."produce_composite"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_quantity" numeric, "target_note" "text", "target_operation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  run_id uuid;
  existing_run public.production_runs%rowtype;
  component record;
  component_level public.inventory_levels%rowtype;
  output_level public.inventory_levels%rowtype;
  component_quantity numeric(14,3);
  total_cost numeric := 0;
  output_unit_cost bigint;
  components_cost_known boolean := true;
  normalized_note text;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'inventory.manage')) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'An operation ID is required for production.' using errcode = '23514';
  end if;

  if target_quantity is null or target_quantity <= 0 or target_quantity <> round(target_quantity, 3) then
    raise exception 'Production quantity must be positive and use at most three decimals.' using errcode = '23514';
  end if;

  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for this store.' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.products product
    where product.id = target_product_id
      and product.organization_id = target_organization_id
      and product.is_composite
      and product.track_inventory
      and product.status = 'active'
  ) then
    raise exception 'Choose an active composite inventory product.' using errcode = '23514';
  end if;

  if not exists (
    select 1
    from public.product_components recipe
    where recipe.organization_id = target_organization_id
      and recipe.product_id = target_product_id
  ) then
    raise exception 'This composite product needs at least one component recipe item.' using errcode = '23514';
  end if;

  normalized_note := nullif(btrim(target_note), '');
  select * into existing_run
  from public.production_runs production_run
  where production_run.organization_id = target_organization_id
    and production_run.operation_id = target_operation_id;

  if found then
    if existing_run.store_id is distinct from target_store_id
      or existing_run.product_id is distinct from target_product_id
      or existing_run.quantity_produced is distinct from target_quantity
      or existing_run.note is distinct from normalized_note then
      raise exception 'This operation ID was already used for a different production run.' using errcode = '23514';
    end if;
    return existing_run.id;
  end if;

  perform 1
  from public.inventory_levels level
  where level.organization_id = target_organization_id
    and level.store_id = target_store_id
    and (
      level.product_id = target_product_id
      or exists (
        select 1
        from public.product_components recipe
        where recipe.organization_id = target_organization_id
          and recipe.product_id = target_product_id
          and recipe.component_product_id = level.product_id
          and recipe.component_variant_id is not distinct from level.variant_id
      )
    )
  order by level.product_id, level.variant_id
  for update;

  select * into output_level
  from public.inventory_levels level
  where level.organization_id = target_organization_id
    and level.store_id = target_store_id
    and level.product_id = target_product_id
    and level.variant_id is null
  for update;

  if output_level.id is null then
    raise exception 'The composite output stock projection is not initialized.' using errcode = '23514';
  end if;

  insert into public.production_runs (
    organization_id, store_id, product_id, quantity_produced, produced_by_employee_id, note, operation_id
  ) values (
    target_organization_id, target_store_id, target_product_id, target_quantity,
    actor_id, normalized_note, target_operation_id
  ) on conflict (organization_id, operation_id) where operation_id is not null do nothing
  returning id into run_id;

  if run_id is null then
    select * into existing_run
    from public.production_runs production_run
    where production_run.organization_id = target_organization_id
      and production_run.operation_id = target_operation_id;
    if existing_run.store_id is distinct from target_store_id
      or existing_run.product_id is distinct from target_product_id
      or existing_run.quantity_produced is distinct from target_quantity
      or existing_run.note is distinct from normalized_note then
      raise exception 'This operation ID was already used for a different production run.' using errcode = '23514';
    end if;
    return existing_run.id;
  end if;

  for component in
    select *
    from public.product_components item
    where item.organization_id = target_organization_id
      and item.product_id = target_product_id
    order by item.component_product_id, item.component_variant_id
  loop
    component_quantity := component.quantity_per_composite * target_quantity;
    select * into component_level
    from public.inventory_levels level
    where level.organization_id = target_organization_id
      and level.store_id = target_store_id
      and level.product_id = component.component_product_id
      and level.variant_id is not distinct from component.component_variant_id
    for update;

    if component_level.id is null or component_level.quantity < component_quantity then
      raise exception 'One production component has insufficient stock.' using errcode = '23514';
    end if;

    total_cost := total_cost + component_quantity * component_level.average_cost_minor;
    components_cost_known := components_cost_known and component_level.cost_is_known;
    perform private.apply_inventory_change_v2(
      target_organization_id, target_store_id, component_level.product_id, component_level.variant_id,
      -component_quantity, 'PRODUCTION', actor_id, 'Consumed by production', 'production_run',
      run_id, component_level.average_cost_minor
    );
  end loop;

  output_unit_cost := round(total_cost / target_quantity)::bigint;
  update public.production_runs
  set cost_is_known = components_cost_known
  where id = run_id
    and organization_id = target_organization_id;

  perform private.apply_inventory_change_v2(
    target_organization_id, target_store_id, target_product_id, null, target_quantity,
    'PRODUCTION', actor_id, 'Produced composite stock', 'production_run', run_id, output_unit_cost
  );

  perform private.write_audit_log(
    target_organization_id, 'PRODUCTION_COMPLETED', 'inventory.manage', actor_id, null,
    target_store_id, null, null, null, target_note,
    jsonb_build_object(
      'production_run_id', run_id,
      'product_id', target_product_id,
      'quantity', target_quantity,
      'unit_cost_minor', output_unit_cost,
      'cost_is_known', components_cost_known,
      'operation_id', target_operation_id
    )
  );
  return run_id;
end;
$$;


ALTER FUNCTION "private"."produce_composite"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_quantity" numeric, "target_note" "text", "target_operation_id" "uuid") OWNER TO "postgres";

--
-- Name: provision_customer_display_session("uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."provision_customer_display_session"("target_organization_id" "uuid", "target_register_id" "uuid", "target_access_token_hash" "text", "target_realtime_topic" "text") RETURNS TABLE("session_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  resolved_store_id uuid;
  actor_employee_id uuid;
  new_session_id uuid;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'registers.manage')) then
    raise exception 'Register management permission is required.' using errcode = '42501';
  end if;

  if target_access_token_hash !~ '^[0-9a-f]{64}$'
    or target_realtime_topic !~ '^[A-Za-z0-9_-]{32,128}$' then
    raise exception 'The customer display pairing values are invalid.' using errcode = '22023';
  end if;

  select register.store_id
  into resolved_store_id
  from public.registers register
  where register.id = target_register_id
    and register.organization_id = target_organization_id
    and register.is_active;

  if resolved_store_id is null then
    raise exception 'Choose an active register in this organization.' using errcode = '23514';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active';

  if actor_employee_id is null then
    raise exception 'An active employee assignment is required.' using errcode = '42501';
  end if;

  update public.customer_display_sessions display
  set
    is_active = false,
    revoked_at = now()
  where display.organization_id = target_organization_id
    and display.register_id = target_register_id
    and display.is_active;

  insert into public.customer_display_sessions (
    organization_id,
    store_id,
    register_id,
    access_token_hash,
    realtime_topic,
    created_by_employee_id
  )
  values (
    target_organization_id,
    resolved_store_id,
    target_register_id,
    target_access_token_hash,
    target_realtime_topic,
    actor_employee_id
  )
  returning id into new_session_id;

  return query select new_session_id;
end;
$_$;


ALTER FUNCTION "private"."provision_customer_display_session"("target_organization_id" "uuid", "target_register_id" "uuid", "target_access_token_hash" "text", "target_realtime_topic" "text") OWNER TO "postgres";

--
-- Name: quote_checkout_subtotal("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."quote_checkout_subtotal"("target_organization_id" "uuid", "target_store_id" "uuid", "target_items" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  checkout_line record;
  product_price_minor bigint;
  requested_price_minor bigint;
  quantity numeric(14, 3);
  product_allows_fractional boolean;
  product_is_variable_price boolean;
  calculated_subtotal_minor bigint := 0;
begin
  if target_items is null or jsonb_typeof(target_items) <> 'array'
    or jsonb_array_length(target_items) not between 1 and 100 then
    raise exception 'Checkout items must contain between 1 and 100 items.' using errcode = '23514';
  end if;

  for checkout_line in
    select value, ordinality
    from jsonb_array_elements(target_items) with ordinality
  loop
    if jsonb_typeof(checkout_line.value) <> 'object'
      or jsonb_typeof(checkout_line.value -> 'product_id') <> 'string'
      or coalesce(checkout_line.value ->> 'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or coalesce(checkout_line.value ->> 'quantity', '') !~ '^(?:0|[1-9][0-9]{0,3})([.][0-9]{1,3})?$' then
      raise exception 'Each checkout item must have valid item references and quantity.' using errcode = '23514';
    end if;

    quantity := (checkout_line.value ->> 'quantity')::numeric(14, 3);
    if quantity <= 0 then raise exception 'Each checkout item must have a quantity greater than zero.' using errcode = '23514'; end if;
    if quantity <= 0 then
      raise exception 'Each checkout item must have a quantity greater than zero.' using errcode = '23514';
    end if;
    if nullif(checkout_line.value ->> 'variant_id', '') is null then
      select
        coalesce(setting.price_override_minor, product.price_minor),
        product.allow_fractional_quantity,
        product.is_variable_price
      into product_price_minor, product_allows_fractional, product_is_variable_price
      from public.products product
      join public.product_store_settings setting
        on setting.organization_id = product.organization_id
       and setting.product_id = product.id
       and setting.store_id = target_store_id
       and setting.is_available
      where product.id = (checkout_line.value ->> 'product_id')::uuid
        and product.organization_id = target_organization_id
        and product.status = 'active'
        and product.product_type = 'simple';
    else
      if jsonb_typeof(checkout_line.value -> 'variant_id') <> 'string'
        or checkout_line.value ->> 'variant_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        raise exception 'Each checkout item must have valid item references and quantity.' using errcode = '23514';
      end if;
      select
        variant.price_minor,
        product.allow_fractional_quantity,
        false
      into product_price_minor, product_allows_fractional, product_is_variable_price
      from public.products product
      join public.product_store_settings setting
        on setting.organization_id = product.organization_id
       and setting.product_id = product.id
       and setting.store_id = target_store_id
       and setting.is_available
      join public.product_variants variant
        on variant.id = (checkout_line.value ->> 'variant_id')::uuid
       and variant.product_id = product.id
       and variant.organization_id = product.organization_id
       and variant.is_active
      where product.id = (checkout_line.value ->> 'product_id')::uuid
        and product.organization_id = target_organization_id
        and product.status = 'active'
        and product.product_type = 'variable';
    end if;

    if product_price_minor is null then
      raise exception 'Every checkout item must be active and available at this store.' using errcode = '23514';
    end if;
    if quantity <> trunc(quantity) and not product_allows_fractional then
      raise exception 'This product must be sold in whole units.' using errcode = '23514';
    end if;
    if product_is_variable_price then
      if jsonb_typeof(checkout_line.value -> 'unit_price_minor') <> 'number'
        or coalesce(checkout_line.value ->> 'unit_price_minor', '') !~ '^[1-9][0-9]{0,9}$' then
        raise exception 'Enter a supported manual price for this product.' using errcode = '23514';
      end if;
      requested_price_minor := (checkout_line.value ->> 'unit_price_minor')::bigint;
      product_price_minor := requested_price_minor;
    elsif checkout_line.value ? 'unit_price_minor'
      and checkout_line.value -> 'unit_price_minor' <> 'null'::jsonb then
      raise exception 'Manual pricing is not enabled for this product.' using errcode = '23514';
    end if;

    calculated_subtotal_minor := calculated_subtotal_minor
      + round(product_price_minor::numeric * quantity)::bigint;
  end loop;

  if calculated_subtotal_minor <= 0 then
    raise exception 'A checkout total must be greater than zero.' using errcode = '23514';
  end if;

  return calculated_subtotal_minor;
end;
$_$;


ALTER FUNCTION "private"."quote_checkout_subtotal"("target_organization_id" "uuid", "target_store_id" "uuid", "target_items" "jsonb") OWNER TO "postgres";

--
-- Name: FUNCTION "quote_checkout_subtotal"("target_organization_id" "uuid", "target_store_id" "uuid", "target_items" "jsonb"); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."quote_checkout_subtotal"("target_organization_id" "uuid", "target_store_id" "uuid", "target_items" "jsonb") IS 'Server-authoritative subtotal quote with exact fractional quantity validation using up to three decimal places.';


--
-- Name: reallocate_open_ticket_lines("uuid", "uuid", "uuid", "jsonb", boolean, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."reallocate_open_ticket_lines"("target_organization_id" "uuid", "target_source_ticket_id" "uuid", "target_destination_ticket_id" "uuid", "target_lines" "jsonb", "target_preserve_empty_source" boolean, "target_replace_destination" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  source_ticket public.open_tickets%rowtype;
  destination_ticket public.open_tickets%rowtype;
  source_line jsonb;
  selected_quantity numeric(14, 3);
  source_quantity numeric(14, 3);
  remaining_quantity numeric(14, 3);
  source_next_cart jsonb := '[]'::jsonb;
  destination_next_cart jsonb;
  moved_line_count integer := 0;
begin
  if target_source_ticket_id is null
    or target_destination_ticket_id is null
    or target_source_ticket_id = target_destination_ticket_id
    or target_lines is null
    or jsonb_typeof(target_lines) <> 'array'
    or jsonb_array_length(target_lines) not between 1 and 100 then
    raise exception 'Choose distinct tickets and between 1 and 100 ticket lines.' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(target_lines) requested(value)
    where jsonb_typeof(requested.value) <> 'object'
      or jsonb_typeof(requested.value -> 'ticket_line_id') <> 'string'
      or coalesce(requested.value ->> 'ticket_line_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or jsonb_typeof(requested.value -> 'quantity') <> 'number'
      or coalesce(requested.value ->> 'quantity', '') !~ '^(?:0|[1-9][0-9]{0,3})([.][0-9]{1,3})?$'
      or (requested.value ->> 'quantity')::numeric(14, 3) <= 0
  ) then
    raise exception 'Choose valid ticket items and quantities.' using errcode = '23514';
  end if;

  if (
    select count(*) from jsonb_array_elements(target_lines) requested(value)
  ) <> (
    select count(distinct requested.value ->> 'ticket_line_id')
    from jsonb_array_elements(target_lines) requested(value)
  ) then
    raise exception 'Choose each ticket line only once.' using errcode = '23514';
  end if;

  perform 1
  from public.open_tickets ticket
  where ticket.organization_id = target_organization_id
    and ticket.id in (target_source_ticket_id, target_destination_ticket_id)
  order by ticket.id
  for update;

  select ticket.* into source_ticket
  from public.open_tickets ticket
  where ticket.id = target_source_ticket_id
    and ticket.organization_id = target_organization_id;
  select ticket.* into destination_ticket
  from public.open_tickets ticket
  where ticket.id = target_destination_ticket_id
    and ticket.organization_id = target_organization_id;

  if source_ticket.id is null
    or destination_ticket.id is null
    or source_ticket.status <> 'open'
    or destination_ticket.status <> 'open'
    or source_ticket.store_id <> destination_ticket.store_id
    or source_ticket.register_id <> destination_ticket.register_id then
    raise exception 'Both tickets must be open on the same register.' using errcode = '23514';
  end if;

  perform private.require_active_pos_shift(
    target_organization_id,
    source_ticket.store_id,
    source_ticket.register_id
  );

  if exists (
    select 1
    from jsonb_array_elements(target_lines) requested(value)
    left join jsonb_array_elements(source_ticket.cart) source_line(value)
      on source_line.value ->> 'ticket_line_id' = requested.value ->> 'ticket_line_id'
    where source_line.value is null
  ) then
    raise exception 'One or more selected ticket items are no longer available.' using errcode = 'P0002';
  end if;

  destination_next_cart := case
    when target_replace_destination then '[]'::jsonb
    else destination_ticket.cart
  end;

  for source_line in
    select line.value
    from jsonb_array_elements(source_ticket.cart) line(value)
  loop
    select (requested.value ->> 'quantity')::numeric(14, 3)
    into selected_quantity
    from jsonb_array_elements(target_lines) requested(value)
    where requested.value ->> 'ticket_line_id' = source_line ->> 'ticket_line_id';

    if selected_quantity is null then
      source_next_cart := source_next_cart || jsonb_build_array(source_line);
      continue;
    end if;

    source_quantity := (source_line ->> 'quantity')::numeric(14, 3);
    if selected_quantity > source_quantity then
      raise exception 'A ticket item cannot move more than its saved quantity.' using errcode = '23514';
    end if;

    remaining_quantity := source_quantity - selected_quantity;
    if remaining_quantity > 0 then
      source_next_cart := source_next_cart || jsonb_build_array(
        source_line || jsonb_build_object('quantity', remaining_quantity)
      );
    end if;

    destination_next_cart := destination_next_cart || jsonb_build_array(
      source_line
      || jsonb_build_object('quantity', selected_quantity)
      || case
        when remaining_quantity > 0 then jsonb_build_object('ticket_line_id', gen_random_uuid()::text)
        else '{}'::jsonb
      end
    );
    moved_line_count := moved_line_count + 1;
  end loop;

  if jsonb_array_length(destination_next_cart) > 100 then
    raise exception 'A ticket can contain at most 100 items.' using errcode = '23514';
  end if;

  if jsonb_array_length(source_next_cart) = 0 and not target_preserve_empty_source then
    raise exception 'Keep at least one item on the source ticket, or merge it instead.' using errcode = '23514';
  end if;

  if jsonb_array_length(source_next_cart) > 0 then
    update public.open_tickets ticket
    set cart = source_next_cart
    where ticket.id = source_ticket.id
      and ticket.organization_id = target_organization_id;
  end if;

  update public.open_tickets ticket
  set cart = destination_next_cart
  where ticket.id = destination_ticket.id
    and ticket.organization_id = target_organization_id;

  return moved_line_count;
end;
$_$;


ALTER FUNCTION "private"."reallocate_open_ticket_lines"("target_organization_id" "uuid", "target_source_ticket_id" "uuid", "target_destination_ticket_id" "uuid", "target_lines" "jsonb", "target_preserve_empty_source" boolean, "target_replace_destination" boolean) OWNER TO "postgres";

--
-- Name: receive_purchase_order("uuid", "uuid", "jsonb", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."receive_purchase_order"("target_organization_id" "uuid", "target_purchase_order_id" "uuid", "target_lines" "jsonb", "target_note" "text", "target_operation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  purchase public.purchase_orders%rowtype;
  existing_receipt public.goods_receipts%rowtype;
  actor_id uuid;
  receipt_id uuid;
  receipt_number bigint;
  line jsonb;
  po_line public.purchase_order_lines%rowtype;
  quantity_received numeric(14,3);
  base_quantity_received numeric(14,6);
  total_remaining numeric(14,3);
  normalized_note text;
  requested_lines jsonb;
  persisted_lines jsonb;
begin
  if (select auth.uid()) is null
     or (not (select private.has_permission(target_organization_id, 'inventory.manage')) and not (select private.has_inventory_capability(target_organization_id, 'purchasing.receive'))) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'A stable goods-receipt operation ID is required.' using errcode = '23514';
  end if;

  if target_lines is null
     or jsonb_typeof(target_lines) <> 'array'
     or jsonb_array_length(target_lines) not between 1 and 100 then
    raise exception 'A receipt needs one to 100 items.' using errcode = '23514';
  end if;

  for line in select value from jsonb_array_elements(target_lines)
  loop
    if coalesce(line ->> 'purchase_order_line_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or coalesce(line ->> 'quantity', '') !~ '^\d+(\.\d{1,3})?$'
       or (line ->> 'quantity')::numeric <= 0 then
      raise exception 'Receipt quantities must be positive.' using errcode = '23514';
    end if;
  end loop;

  if exists (
    select 1
    from (
      select lower(btrim(value ->> 'purchase_order_line_id')) as purchase_order_line_id, count(*) as line_count
      from jsonb_array_elements(target_lines)
      group by 1
    ) duplicate_line
    where duplicate_line.line_count > 1
  ) then
    raise exception 'Each order line can be received once per receipt.' using errcode = '23514';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'purchase_order_line_id', normalized.purchase_order_line_id,
        'quantity', normalized.quantity
      )
      order by normalized.purchase_order_line_id
    ),
    '[]'::jsonb
  )
  into requested_lines
  from (
    select
      lower(btrim(value ->> 'purchase_order_line_id')) as purchase_order_line_id,
      ((value ->> 'quantity')::numeric(14,3))::text as quantity
    from jsonb_array_elements(target_lines)
  ) normalized;

  normalized_note := nullif(btrim(target_note), '');

  select *
  into existing_receipt
  from public.goods_receipts goods_receipt
  where goods_receipt.organization_id = target_organization_id
    and goods_receipt.operation_id = target_operation_id
  for update;

  if found then
    select *
    into purchase
    from public.purchase_orders purchase_order
    where purchase_order.id = target_purchase_order_id
      and purchase_order.organization_id = target_organization_id
    for update;

    actor_id := private.inventory_actor(target_organization_id, purchase.store_id);
    if purchase.id is not null
       and actor_id is not null then
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'purchase_order_line_id', receipt_line.purchase_order_line_id::text,
            'quantity', receipt_line.quantity_received::text
          )
          order by receipt_line.purchase_order_line_id::text
        ),
        '[]'::jsonb
      )
      into persisted_lines
      from public.goods_receipt_lines receipt_line
      where receipt_line.organization_id = target_organization_id
        and receipt_line.goods_receipt_id = existing_receipt.id;

      if existing_receipt.purchase_order_id = target_purchase_order_id
         and existing_receipt.store_id = purchase.store_id
         and existing_receipt.received_by_employee_id = actor_id
         and existing_receipt.note is not distinct from normalized_note
         and persisted_lines = requested_lines then
        return existing_receipt.id;
      end if;
    end if;

    raise exception 'This operation ID is already assigned to a different goods receipt request.' using errcode = '23505';
  end if;

  select *
  into purchase
  from public.purchase_orders purchase_order
  where purchase_order.id = target_purchase_order_id
    and purchase_order.organization_id = target_organization_id
    and purchase_order.status in ('ordered', 'partially_received')
  for update;

  if purchase.id is null then
    raise exception 'This purchase order cannot be received.' using errcode = '23514';
  end if;

  actor_id := private.inventory_actor(target_organization_id, purchase.store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for this store.' using errcode = '42501';
  end if;

  receipt_number := nextval('private.tindio_goods_receipt_number_sequence'::regclass);
  insert into public.goods_receipts (
    organization_id,
    purchase_order_id,
    store_id,
    received_by_employee_id,
    note,
    receipt_number,
    operation_id
  )
  values (
    target_organization_id,
    purchase.id,
    purchase.store_id,
    actor_id,
    normalized_note,
    receipt_number,
    target_operation_id
  )
  returning id into receipt_id;

  for line in select value from jsonb_array_elements(target_lines)
  loop
    select *
    into po_line
    from public.purchase_order_lines purchase_line
    where purchase_line.id = (line ->> 'purchase_order_line_id')::uuid
      and purchase_line.purchase_order_id = purchase.id
      and purchase_line.organization_id = target_organization_id
    for update;

    if po_line.id is null then
      raise exception 'A receipt line does not belong to this purchase order.' using errcode = '23514';
    end if;

    quantity_received := (line ->> 'quantity')::numeric(14,3);
    if po_line.received_quantity + quantity_received > po_line.ordered_quantity then
      raise exception 'Received quantity cannot exceed the ordered quantity.' using errcode = '23514';
    end if;

    base_quantity_received := quantity_received * po_line.purchase_unit_factor_to_base;
    if base_quantity_received <> round(base_quantity_received, 3) then
      raise exception 'This received quantity cannot be expressed in the product base unit to three decimal places.' using errcode = '23514';
    end if;

    insert into public.goods_receipt_lines (
      organization_id,
      goods_receipt_id,
      purchase_order_line_id,
      quantity_received
    )
    values (
      target_organization_id,
      receipt_id,
      po_line.id,
      quantity_received
    );

    update public.purchase_order_lines
    set received_quantity = received_quantity + quantity_received
    where id = po_line.id;

    perform private.apply_inventory_change_v2(
      target_organization_id,
      purchase.store_id,
      po_line.product_id,
      po_line.variant_id,
      round(base_quantity_received, 3),
      'RECEIPT',
      actor_id,
      format('Goods receipt GR-%s', lpad(receipt_number::text, 6, '0')),
      'goods_receipt',
      receipt_id,
      round(po_line.unit_cost_minor::numeric / po_line.purchase_unit_factor_to_base)::bigint
    );
  end loop;

  select coalesce(sum(ordered_quantity - received_quantity), 0)
  into total_remaining
  from public.purchase_order_lines purchase_line
  where purchase_line.purchase_order_id = purchase.id;

  update public.purchase_orders
  set
    status = case when total_remaining = 0 then 'received' else 'partially_received' end,
    received_at = now(),
    received_by_employee_id = actor_id
  where id = purchase.id;

  perform private.write_audit_log(
    target_organization_id,
    'PURCHASE_ORDER_RECEIVED',
    'inventory.manage',
    actor_id,
    null,
    purchase.store_id,
    null,
    null,
    null,
    normalized_note,
    jsonb_build_object(
      'purchase_order_id', purchase.id,
      'goods_receipt_id', receipt_id,
      'goods_receipt_number', receipt_number,
      'operation_id', target_operation_id
    )
  );

  return receipt_id;
end;
$_$;


ALTER FUNCTION "private"."receive_purchase_order"("target_organization_id" "uuid", "target_purchase_order_id" "uuid", "target_lines" "jsonb", "target_note" "text", "target_operation_id" "uuid") OWNER TO "postgres";

--
-- Name: receive_stock_request("uuid", "uuid", "jsonb", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."receive_stock_request"("target_organization_id" "uuid", "target_stock_request_id" "uuid", "target_lines" "jsonb", "target_note" "text", "target_operation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  request_row public.stock_requests%rowtype;
  transfer_row public.stock_transfers%rowtype;
  existing_receipt public.stock_transfer_receipts%rowtype;
  actor_id uuid;
  receipt_id uuid;
  receipt_number bigint;
  line jsonb;
  transfer_line public.stock_transfer_lines%rowtype;
  request_line public.stock_request_lines%rowtype;
  received_now numeric(14,3);
  short_now numeric(14,3);
  remaining numeric(14,3);
  total_remaining numeric(14,3);
  has_shortage boolean;
  normalized_note text;
  requested_payload jsonb;
begin
  if (select auth.uid()) is null
     or (
       not (select private.has_permission(target_organization_id, 'inventory.manage'))
       and not (select private.has_inventory_capability(target_organization_id, 'inventory.transfer.receive'))
     ) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'A stable transfer-receipt operation ID is required.' using errcode = '23514';
  end if;

  if target_lines is null
     or jsonb_typeof(target_lines) <> 'array'
     or jsonb_array_length(target_lines) not between 1 and 100
     or (target_note is not null and char_length(btrim(target_note)) > 500) then
    raise exception 'A receipt needs one to 100 lines and valid notes.' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(target_lines) receipt(value)
    where jsonb_typeof(receipt.value) <> 'object'
      or coalesce(receipt.value ->> 'stock_transfer_line_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or coalesce(receipt.value ->> 'received_quantity', '') !~ '^\d+(\.\d{1,3})?$'
      or coalesce(receipt.value ->> 'short_quantity', '') !~ '^\d+(\.\d{1,3})?$'
      or ((receipt.value ->> 'received_quantity')::numeric + (receipt.value ->> 'short_quantity')::numeric) <= 0
      or ((receipt.value ->> 'short_quantity')::numeric > 0 and char_length(btrim(coalesce(receipt.value ->> 'discrepancy_note', ''))) not between 2 and 500)
  )
  or (select count(*) from jsonb_array_elements(target_lines)) <> (
    select count(distinct value ->> 'stock_transfer_line_id') from jsonb_array_elements(target_lines)
  ) then
    raise exception 'Receipt lines, quantities, and discrepancy notes are invalid.' using errcode = '23514';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'stock_transfer_line_id', normalized.stock_transfer_line_id,
        'received_quantity', normalized.received_quantity,
        'short_quantity', normalized.short_quantity,
        'discrepancy_note', normalized.discrepancy_note
      )
      order by normalized.stock_transfer_line_id
    ),
    '[]'::jsonb
  )
  into requested_payload
  from (
    select
      lower(btrim(value ->> 'stock_transfer_line_id')) as stock_transfer_line_id,
      ((value ->> 'received_quantity')::numeric(14,3))::text as received_quantity,
      ((value ->> 'short_quantity')::numeric(14,3))::text as short_quantity,
      nullif(btrim(coalesce(value ->> 'discrepancy_note', '')), '') as discrepancy_note
    from jsonb_array_elements(target_lines)
  ) normalized;

  normalized_note := nullif(btrim(target_note), '');
  select *
  into request_row
  from public.stock_requests request_item
  where request_item.id = target_stock_request_id
    and request_item.organization_id = target_organization_id
  for update;

  if request_row.id is null then
    raise exception 'Choose a stock request in this organization.' using errcode = '23514';
  end if;

  actor_id := private.inventory_actor(target_organization_id, request_row.requesting_store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for the requesting store.' using errcode = '42501';
  end if;

  select *
  into transfer_row
  from public.stock_transfers transfer
  where transfer.organization_id = target_organization_id
    and transfer.stock_request_id = request_row.id
  for update;

  if transfer_row.id is null then
    raise exception 'The dispatched stock transfer is unavailable.' using errcode = '23514';
  end if;

  select *
  into existing_receipt
  from public.stock_transfer_receipts receipt
  where receipt.organization_id = target_organization_id
    and receipt.operation_id = target_operation_id
  for update;

  if found then
    if existing_receipt.stock_transfer_id = transfer_row.id
       and existing_receipt.destination_store_id = request_row.requesting_store_id
       and existing_receipt.received_by_employee_id = actor_id
       and existing_receipt.note is not distinct from normalized_note
       and existing_receipt.operation_payload = requested_payload then
      return request_row.id;
    end if;

    raise exception 'This operation ID is already assigned to a different transfer receipt.' using errcode = '23505';
  end if;

  if request_row.status not in ('dispatched', 'partially_received')
     or transfer_row.status not in ('in_transit', 'partially_received') then
    raise exception 'This request is not available for receiving.' using errcode = '23514';
  end if;

  receipt_number := nextval('private.tindio_stock_transfer_receipt_number_sequence'::regclass);
  insert into public.stock_transfer_receipts (
    organization_id,
    receipt_number,
    operation_id,
    operation_payload,
    stock_transfer_id,
    destination_store_id,
    received_by_employee_id,
    note
  )
  values (
    target_organization_id,
    receipt_number,
    target_operation_id,
    requested_payload,
    transfer_row.id,
    request_row.requesting_store_id,
    actor_id,
    normalized_note
  )
  returning id into receipt_id;

  for line in select value from jsonb_array_elements(target_lines)
  loop
    select *
    into transfer_line
    from public.stock_transfer_lines item
    where item.id = (line ->> 'stock_transfer_line_id')::uuid
      and item.stock_transfer_id = transfer_row.id
      and item.organization_id = target_organization_id
      and item.stock_request_line_id is not null
    for update;

    if transfer_line.id is null then
      raise exception 'A receipt line does not belong to this stock request.' using errcode = '23514';
    end if;

    select *
    into request_line
    from public.stock_request_lines item
    where item.id = transfer_line.stock_request_line_id
      and item.stock_request_id = request_row.id
      and item.organization_id = target_organization_id
    for update;

    received_now := (line ->> 'received_quantity')::numeric(14,3);
    short_now := (line ->> 'short_quantity')::numeric(14,3);
    remaining := transfer_line.quantity - transfer_line.received_quantity - transfer_line.short_quantity;

    if received_now + short_now > remaining then
      raise exception 'Received and short quantities cannot exceed the remaining dispatched quantity.' using errcode = '23514';
    end if;

    if received_now > 0 then
      insert into public.stock_transfer_receipt_lines (
        organization_id,
        stock_transfer_receipt_id,
        stock_transfer_line_id,
        quantity_received
      )
      values (target_organization_id, receipt_id, transfer_line.id, received_now);

      perform private.apply_inventory_change_v2(
        target_organization_id,
        request_row.requesting_store_id,
        transfer_line.product_id,
        transfer_line.variant_id,
        received_now,
        'TRANSFER_IN',
        actor_id,
        format('Transfer TR-%s receipt %s', lpad(transfer_row.transfer_number::text, 6, '0'), lpad(receipt_number::text, 6, '0')),
        'stock_transfer_receipt',
        receipt_id,
        transfer_line.unit_cost_minor
      );
    end if;

    update public.stock_transfer_lines
    set received_quantity = received_quantity + received_now,
        short_quantity = short_quantity + short_now
    where id = transfer_line.id;

    update public.stock_request_lines
    set received_quantity = received_quantity + received_now,
        short_quantity = short_quantity + short_now
    where id = request_line.id;

    if short_now > 0 then
      insert into public.stock_request_discrepancies (
        organization_id,
        stock_request_id,
        stock_request_line_id,
        stock_transfer_line_id,
        short_quantity,
        note,
        reported_by_employee_id
      )
      values (
        target_organization_id,
        request_row.id,
        request_line.id,
        transfer_line.id,
        short_now,
        btrim(line ->> 'discrepancy_note'),
        actor_id
      );
    end if;
  end loop;

  select coalesce(sum(quantity - received_quantity - short_quantity), 0)
  into total_remaining
  from public.stock_transfer_lines
  where stock_transfer_id = transfer_row.id;

  select exists (
    select 1
    from public.stock_transfer_lines
    where stock_transfer_id = transfer_row.id
      and short_quantity > 0
  )
  into has_shortage;

  update public.stock_transfers
  set status = case when total_remaining = 0 then 'completed' else 'partially_received' end,
      received_by_employee_id = actor_id,
      received_at = now(),
      completed_at = case when total_remaining = 0 then now() else completed_at end
  where id = transfer_row.id;

  update public.stock_requests
  set status = case when total_remaining > 0 then 'partially_received' when has_shortage then 'received_with_discrepancy' else 'received' end,
      received_by_employee_id = actor_id,
      received_at = case when total_remaining = 0 then now() else received_at end
  where id = request_row.id;

  perform private.write_audit_log(
    target_organization_id,
    case when total_remaining = 0 then 'STOCK_REQUEST_RECEIVED' else 'STOCK_REQUEST_PARTIALLY_RECEIVED' end,
    'inventory.manage',
    actor_id,
    null,
    request_row.requesting_store_id,
    null,
    null,
    null,
    normalized_note,
    jsonb_build_object(
      'stock_request_id', request_row.id,
      'request_number', request_row.request_number,
      'stock_transfer_id', transfer_row.id,
      'transfer_number', transfer_row.transfer_number,
      'receipt_id', receipt_id,
      'receipt_number', receipt_number,
      'remaining_quantity', total_remaining,
      'has_discrepancy', has_shortage
    )
  );
  return request_row.id;
end;
$_$;


ALTER FUNCTION "private"."receive_stock_request"("target_organization_id" "uuid", "target_stock_request_id" "uuid", "target_lines" "jsonb", "target_note" "text", "target_operation_id" "uuid") OWNER TO "postgres";

--
-- Name: receive_stock_transfer("uuid", "uuid", "jsonb", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."receive_stock_transfer"("target_organization_id" "uuid", "target_stock_transfer_id" "uuid", "target_lines" "jsonb", "target_note" "text", "target_operation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  transfer public.stock_transfers%rowtype;
  existing_receipt public.stock_transfer_receipts%rowtype;
  actor_id uuid;
  receipt_id uuid;
  receipt_number bigint;
  line jsonb;
  transfer_line public.stock_transfer_lines%rowtype;
  received_now numeric(14,3);
  short_now numeric(14,3);
  remaining numeric(14,3);
  total_remaining numeric(14,3);
  has_shortage boolean;
  normalized_note text;
  requested_payload jsonb;
  uses_legacy_line_shape boolean;
begin
  if (select auth.uid()) is null
     or (
       not (select private.has_permission(target_organization_id, 'inventory.manage'))
       and not (select private.has_inventory_capability(target_organization_id, 'inventory.transfer.receive'))
     ) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;

  if target_operation_id is null then
    raise exception 'A stable transfer-receipt operation ID is required.' using errcode = '23514';
  end if;

  if target_lines is null
     or jsonb_typeof(target_lines) <> 'array'
     or jsonb_array_length(target_lines) not between 1 and 100
     or (target_note is not null and char_length(btrim(target_note)) > 500) then
    raise exception 'A transfer receipt needs one to 100 items and a valid note.' using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(target_lines) receipt(value)
    where jsonb_typeof(receipt.value) <> 'object'
      or coalesce(receipt.value ->> 'stock_transfer_line_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or coalesce(receipt.value ->> 'received_quantity', receipt.value ->> 'quantity', '') !~ '^\d+(\.\d{1,3})?$'
      or coalesce(receipt.value ->> 'short_quantity', '0') !~ '^\d+(\.\d{1,3})?$'
      or ((coalesce(receipt.value ->> 'received_quantity', receipt.value ->> 'quantity'))::numeric
        + (coalesce(receipt.value ->> 'short_quantity', '0'))::numeric) <= 0
      or ((coalesce(receipt.value ->> 'short_quantity', '0'))::numeric > 0
        and char_length(btrim(coalesce(receipt.value ->> 'discrepancy_note', ''))) not between 2 and 500)
  )
  or (select count(*) from jsonb_array_elements(target_lines)) <> (
    select count(distinct value ->> 'stock_transfer_line_id') from jsonb_array_elements(target_lines)
  ) then
    raise exception 'Receipt lines, quantities, and discrepancy notes are invalid.' using errcode = '23514';
  end if;

  select bool_and(not (value ? 'received_quantity') and not (value ? 'short_quantity') and not (value ? 'discrepancy_note'))
  into uses_legacy_line_shape
  from jsonb_array_elements(target_lines);

  if uses_legacy_line_shape then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'stock_transfer_line_id', normalized.stock_transfer_line_id,
          'quantity', normalized.received_quantity
        )
        order by normalized.stock_transfer_line_id
      ),
      '[]'::jsonb
    )
    into requested_payload
    from (
      select
        lower(btrim(value ->> 'stock_transfer_line_id')) as stock_transfer_line_id,
        ((value ->> 'quantity')::numeric(14,3))::text as received_quantity
      from jsonb_array_elements(target_lines)
    ) normalized;
  else
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'stock_transfer_line_id', normalized.stock_transfer_line_id,
          'received_quantity', normalized.received_quantity,
          'short_quantity', normalized.short_quantity,
          'discrepancy_note', normalized.discrepancy_note
        )
        order by normalized.stock_transfer_line_id
      ),
      '[]'::jsonb
    )
    into requested_payload
    from (
      select
        lower(btrim(value ->> 'stock_transfer_line_id')) as stock_transfer_line_id,
        ((coalesce(value ->> 'received_quantity', value ->> 'quantity'))::numeric(14,3))::text as received_quantity,
        ((coalesce(value ->> 'short_quantity', '0'))::numeric(14,3))::text as short_quantity,
        nullif(btrim(coalesce(value ->> 'discrepancy_note', '')), '') as discrepancy_note
      from jsonb_array_elements(target_lines)
    ) normalized;
  end if;

  normalized_note := nullif(btrim(target_note), '');
  select *
  into transfer
  from public.stock_transfers item
  where item.id = target_stock_transfer_id
    and item.organization_id = target_organization_id
  for update;

  if transfer.id is null then
    raise exception 'Choose a transfer in this organization.' using errcode = '23514';
  end if;

  if transfer.stock_request_id is not null then
    raise exception 'Receive replenishment transfers from the stock request workflow so shortages stay traceable.' using errcode = '23514';
  end if;

  actor_id := private.inventory_actor(target_organization_id, transfer.destination_store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for the destination store.' using errcode = '42501';
  end if;

  select *
  into existing_receipt
  from public.stock_transfer_receipts receipt
  where receipt.organization_id = target_organization_id
    and receipt.operation_id = target_operation_id
  for update;

  if found then
    if existing_receipt.stock_transfer_id = transfer.id
       and existing_receipt.destination_store_id = transfer.destination_store_id
       and existing_receipt.received_by_employee_id = actor_id
       and existing_receipt.note is not distinct from normalized_note
       and existing_receipt.operation_payload = requested_payload then
      return existing_receipt.id;
    end if;

    raise exception 'This operation ID is already assigned to a different transfer receipt.' using errcode = '23505';
  end if;

  if transfer.status not in ('in_transit', 'partially_received') then
    raise exception 'This transfer is not available for receiving.' using errcode = '23514';
  end if;

  receipt_number := nextval('private.tindio_stock_transfer_receipt_number_sequence'::regclass);
  insert into public.stock_transfer_receipts (
    organization_id,
    receipt_number,
    operation_id,
    operation_payload,
    stock_transfer_id,
    destination_store_id,
    received_by_employee_id,
    note
  )
  values (
    target_organization_id,
    receipt_number,
    target_operation_id,
    requested_payload,
    transfer.id,
    transfer.destination_store_id,
    actor_id,
    normalized_note
  )
  returning id into receipt_id;

  for line in select value from jsonb_array_elements(target_lines)
  loop
    select *
    into transfer_line
    from public.stock_transfer_lines item
    where item.id = (line ->> 'stock_transfer_line_id')::uuid
      and item.stock_transfer_id = transfer.id
      and item.organization_id = target_organization_id
      and item.stock_request_line_id is null
    for update;

    if transfer_line.id is null then
      raise exception 'A receipt line does not belong to this direct transfer.' using errcode = '23514';
    end if;

    received_now := (coalesce(line ->> 'received_quantity', line ->> 'quantity'))::numeric(14,3);
    short_now := (coalesce(line ->> 'short_quantity', '0'))::numeric(14,3);
    remaining := transfer_line.quantity - transfer_line.received_quantity - transfer_line.short_quantity;
    if received_now + short_now > remaining then
      raise exception 'Received and short quantities cannot exceed the remaining sent quantity.' using errcode = '23514';
    end if;

    if received_now > 0 then
      insert into public.stock_transfer_receipt_lines (
        organization_id,
        stock_transfer_receipt_id,
        stock_transfer_line_id,
        quantity_received
      )
      values (target_organization_id, receipt_id, transfer_line.id, received_now);

      perform private.apply_inventory_change_v2(
        target_organization_id,
        transfer.destination_store_id,
        transfer_line.product_id,
        transfer_line.variant_id,
        received_now,
        'TRANSFER_IN',
        actor_id,
        format('Transfer TR-%s receipt %s', lpad(transfer.transfer_number::text, 6, '0'), lpad(receipt_number::text, 6, '0')),
        'stock_transfer_receipt',
        receipt_id,
        transfer_line.unit_cost_minor
      );
    end if;

    update public.stock_transfer_lines
    set received_quantity = received_quantity + received_now,
        short_quantity = short_quantity + short_now
    where id = transfer_line.id;
  end loop;

  select coalesce(sum(quantity - received_quantity - short_quantity), 0)
  into total_remaining
  from public.stock_transfer_lines
  where stock_transfer_id = transfer.id;

  select exists (
    select 1
    from public.stock_transfer_lines
    where stock_transfer_id = transfer.id
      and short_quantity > 0
  )
  into has_shortage;

  update public.stock_transfers
  set status = case when total_remaining = 0 then 'completed' else 'partially_received' end,
      received_by_employee_id = actor_id,
      received_at = now(),
      completed_at = case when total_remaining = 0 then now() else completed_at end
  where id = transfer.id;

  perform private.write_audit_log(
    target_organization_id,
    case when total_remaining = 0 then 'STOCK_TRANSFER_RECEIVED' else 'STOCK_TRANSFER_PARTIALLY_RECEIVED' end,
    'inventory.manage',
    actor_id,
    null,
    transfer.destination_store_id,
    null,
    null,
    null,
    normalized_note,
    jsonb_build_object(
      'stock_transfer_id', transfer.id,
      'transfer_number', transfer.transfer_number,
      'receipt_id', receipt_id,
      'receipt_number', receipt_number,
      'remaining_quantity', total_remaining,
      'has_discrepancy', has_shortage,
      'receipt_lines', requested_payload
    )
  );
  return receipt_id;
end;
$_$;


ALTER FUNCTION "private"."receive_stock_transfer"("target_organization_id" "uuid", "target_stock_transfer_id" "uuid", "target_lines" "jsonb", "target_note" "text", "target_operation_id" "uuid") OWNER TO "postgres";

--
-- Name: record_archive_request_time(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."record_archive_request_time"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.archive_requested_at is not null and old.archive_requested_at is null then
    new.archive_requested_at := clock_timestamp();
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."record_archive_request_time"() OWNER TO "postgres";

--
-- Name: FUNCTION "record_archive_request_time"(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."record_archive_request_time"() IS 'Uses a real wall-clock archive-request timestamp so a freshly delivered export can be distinguished from an older one inside long transactions.';


--
-- Name: record_cash_movement("uuid", "uuid", "text", bigint, "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."record_cash_movement"("target_organization_id" "uuid", "target_shift_id" "uuid", "target_movement_type" "text", "target_amount_minor" bigint, "target_reason" "text", "target_idempotency_key" "uuid") RETURNS TABLE("cash_movement_id" "uuid", "created_at" timestamp with time zone, "was_replayed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  target_shift public.shifts%rowtype;
  existing_movement public.cash_movements%rowtype;
  normalized_reason text;
  required_permission text;
begin
  if target_organization_id is null
    or target_shift_id is null
    or target_idempotency_key is null
    or target_amount_minor is null
    or target_amount_minor <= 0 then
    raise exception 'An open shift, positive amount, and cash movement key are required.'
      using errcode = '23514';
  end if;

  if target_movement_type is null
    or target_movement_type not in ('PAY_IN', 'PAY_OUT') then
    raise exception 'Select either a cash pay-in or pay-out.' using errcode = '23514';
  end if;

  required_permission := case target_movement_type
    when 'PAY_IN' then 'cash.pay_in'
    else 'cash.pay_out'
  end;

  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, required_permission)) then
    raise exception 'Cash movement permission is required.' using errcode = '42501';
  end if;

  normalized_reason := trim(coalesce(target_reason, ''));
  if char_length(normalized_reason) not between 2 and 500 then
    raise exception 'A cash movement reason must contain between 2 and 500 characters.'
      using errcode = '23514';
  end if;

  select shift.*
  into target_shift
  from public.shifts shift
  where shift.id = target_shift_id
    and shift.organization_id = target_organization_id
    and shift.status = 'open'
  for update;

  if target_shift.id is null then
    raise exception 'The open shift was not found.' using errcode = 'P0002';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  join public.employee_stores employee_store
    on employee_store.employee_id = employee.id
   and employee_store.organization_id = employee.organization_id
   and employee_store.store_id = target_shift.store_id
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active';

  if actor_employee_id is null then
    raise exception 'An active employee assignment for this shift store is required.'
      using errcode = '42501';
  end if;

  if target_shift.opened_by_employee_id is distinct from actor_employee_id then
    raise exception 'Only the employee who opened this shift can record cash movements.'
      using errcode = '42501';
  end if;

  select movement.*
  into existing_movement
  from public.cash_movements movement
  where movement.organization_id = target_organization_id
    and movement.idempotency_key = target_idempotency_key
  for update;

  if existing_movement.id is not null then
    if existing_movement.shift_id is distinct from target_shift_id
      or existing_movement.employee_id is distinct from actor_employee_id
      or existing_movement.movement_type is distinct from target_movement_type
      or existing_movement.amount_minor is distinct from target_amount_minor
      or existing_movement.reason is distinct from normalized_reason then
      raise exception 'This cash movement key was already used for a different request.'
        using errcode = '23505';
    end if;

    return query select existing_movement.id, existing_movement.created_at, true;
    return;
  end if;

  return query
  insert into public.cash_movements as inserted_movement (
    organization_id,
    shift_id,
    store_id,
    register_id,
    employee_id,
    movement_type,
    amount_minor,
    reason,
    idempotency_key
  )
  values (
    target_organization_id,
    target_shift.id,
    target_shift.store_id,
    target_shift.register_id,
    actor_employee_id,
    target_movement_type,
    target_amount_minor,
    normalized_reason,
    target_idempotency_key
  )
  returning inserted_movement.id, inserted_movement.created_at, false;
end;
$$;


ALTER FUNCTION "private"."record_cash_movement"("target_organization_id" "uuid", "target_shift_id" "uuid", "target_movement_type" "text", "target_amount_minor" bigint, "target_reason" "text", "target_idempotency_key" "uuid") OWNER TO "postgres";

--
-- Name: record_composite_component_movements(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."record_composite_component_movements"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  component record;
  current_quantity numeric(14, 3);
  next_quantity numeric(14, 3);
begin
  if tg_op <> 'INSERT' or new.movement_type <> 'SALE' or new.source_type <> 'sale'
    or pg_trigger_depth() > 1
    or not exists (
      select 1 from public.products parent
      where parent.id = new.product_id and parent.organization_id = new.organization_id
        and parent.is_composite
    ) then
    return new;
  end if;

  for component in
    select recipe.component_product_id, recipe.component_variant_id,
      recipe.quantity_per_composite, product.name
    from public.product_components recipe
    join public.products product
      on product.id = recipe.component_product_id
     and product.organization_id = recipe.organization_id
    where recipe.organization_id = new.organization_id
      and recipe.product_id = new.product_id
      and product.track_inventory
  loop
    select level.quantity into current_quantity
    from public.inventory_levels level
    where level.organization_id = new.organization_id and level.store_id = new.store_id
      and level.product_id = component.component_product_id
      and level.variant_id is not distinct from component.component_variant_id
    for update;

    if current_quantity is null then
      raise exception 'The stock projection is not initialized for composite component %.', component.name
        using errcode = '23514';
    end if;

    next_quantity := current_quantity + new.quantity_delta * component.quantity_per_composite;
    update public.inventory_levels level set quantity = next_quantity, updated_at = now()
    where level.organization_id = new.organization_id and level.store_id = new.store_id
      and level.product_id = component.component_product_id
      and level.variant_id is not distinct from component.component_variant_id;

    insert into public.inventory_movements (
      organization_id, store_id, product_id, variant_id, quantity_delta,
      quantity_before, quantity_after, movement_type, actor_employee_id, reason,
      source_type, source_id
    ) values (
      new.organization_id, new.store_id, component.component_product_id,
      component.component_variant_id,
      new.quantity_delta * component.quantity_per_composite,
      current_quantity, next_quantity, 'SALE', new.actor_employee_id,
      'Composite sale: ' || new.reason, 'composite_sale', new.source_id
    );
  end loop;
  return new;
end;
$$;


ALTER FUNCTION "private"."record_composite_component_movements"() OWNER TO "postgres";

--
-- Name: record_inventory_adjustment("uuid", "uuid", "uuid", "uuid", numeric, "text", "text", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."record_inventory_adjustment"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_reason_code" "text", "target_note" "text", "target_operation_id" "uuid", "target_approval_request_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  selected_reason public.inventory_adjustment_reasons%rowtype;
  resolved_note text;
  expected_payload jsonb;
begin
  if (select auth.uid()) is null then
    raise exception 'Inventory adjustment permission is required.' using errcode = '42501';
  end if;

  resolved_note := nullif(btrim(coalesce(target_note, '')), '');
  if char_length(coalesce(resolved_note, '')) not between 2 and 500 then
    raise exception 'Provide an adjustment explanation between 2 and 500 characters.' using errcode = '23514';
  end if;

  select reason.* into selected_reason
  from public.inventory_adjustment_reasons reason
  where reason.organization_id = target_organization_id
    and reason.code = upper(btrim(coalesce(target_reason_code, '')))
    and reason.is_active;
  if selected_reason.id is null then
    raise exception 'Choose an active adjustment reason.' using errcode = '23514';
  end if;

  expected_payload := jsonb_build_object(
    'store_id', target_store_id,
    'product_id', target_product_id,
    'variant_id', target_variant_id,
    'quantity_delta', target_quantity_delta,
    'reason_code', selected_reason.code,
    'movement_type', selected_reason.movement_type,
    'note', resolved_note
  );

  perform private.authorize_sensitive_operation(
    target_organization_id,
    'inventory.adjust',
    target_approval_request_id,
    expected_payload,
    target_operation_id
  );

  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for this store.' using errcode = '42501';
  end if;

  return private.post_inventory_adjustment(
    target_organization_id,
    target_store_id,
    target_product_id,
    target_variant_id,
    target_quantity_delta,
    target_reason_code,
    resolved_note,
    target_operation_id,
    actor_id
  );
end;
$$;


ALTER FUNCTION "private"."record_inventory_adjustment"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_reason_code" "text", "target_note" "text", "target_operation_id" "uuid", "target_approval_request_id" "uuid") OWNER TO "postgres";

--
-- Name: record_inventory_adjustment_v2("uuid", "uuid", "uuid", "uuid", numeric, "text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."record_inventory_adjustment_v2"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_reason_code" "text", "target_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  selected_reason public.inventory_adjustment_reasons%rowtype;
  adjustment_id uuid;
  created_adjustment_number bigint;
  movement_id uuid;
  resolved_note text;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'inventory.manage')) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;
  if target_quantity_delta = 0 then
    raise exception 'Adjustment quantity must not be zero.' using errcode = '23514';
  end if;

  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for this store.' using errcode = '42501';
  end if;

  select reason.* into selected_reason
  from public.inventory_adjustment_reasons reason
  where reason.organization_id = target_organization_id
    and reason.code = upper(btrim(coalesce(target_reason_code, '')))
    and reason.is_active;
  if selected_reason.id is null then
    raise exception 'Choose an active adjustment reason.' using errcode = '23514';
  end if;

  resolved_note := coalesce(nullif(btrim(target_note), ''), selected_reason.name);
  insert into public.inventory_adjustments (
    organization_id, store_id, product_id, variant_id, quantity_delta,
    reason_code, note, created_by_employee_id
  ) values (
    target_organization_id, target_store_id, target_product_id, target_variant_id,
    target_quantity_delta, selected_reason.code, resolved_note, actor_id
  ) returning id, adjustment_number into adjustment_id, created_adjustment_number;

  perform private.apply_inventory_change_v2(
    target_organization_id, target_store_id, target_product_id, target_variant_id,
    target_quantity_delta, selected_reason.movement_type, actor_id, resolved_note,
    'inventory_adjustment', adjustment_id, null, selected_reason.code
  );

  select movement.id into movement_id
  from public.inventory_movements movement
  where movement.organization_id = target_organization_id
    and movement.source_type = 'inventory_adjustment'
    and movement.source_id = adjustment_id;

  perform private.write_audit_log(
    target_organization_id, 'INVENTORY_ADJUSTED', 'inventory.adjust', actor_id,
    null, target_store_id, null, null, null, resolved_note,
    jsonb_build_object(
      'adjustment_id', adjustment_id,
      'adjustment_number', created_adjustment_number,
      'reason_code', selected_reason.code,
      'quantity_delta', target_quantity_delta
    )
  );
  return movement_id;
end;
$$;


ALTER FUNCTION "private"."record_inventory_adjustment_v2"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_quantity_delta" numeric, "target_reason_code" "text", "target_note" "text") OWNER TO "postgres";

--
-- Name: refund_sale("uuid", "uuid", "uuid", "uuid", "text", "text", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."refund_sale"("target_organization_id" "uuid", "target_sale_id" "uuid", "target_payment_method_id" "uuid", "target_idempotency_key" "uuid", "target_reason" "text", "target_reference_number" "text", "target_items" "jsonb") RETURNS TABLE("refund_id" "uuid", "refund_number" bigint, "total_minor" bigint, "was_replayed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  existing_actor_employee_id uuid;
  existing_payload jsonb;
  existing_refund_id uuid;
  original_sale public.sales%rowtype;
  original_item public.sale_items%rowtype;
  refund_item_value jsonb;
  selected_sale_item_id uuid;
  selected_quantity integer;
  selected_return_to_stock boolean;
  already_refunded_quantity integer;
  calculated_total_minor bigint := 0;
  new_refund_id uuid;
  new_refund_number bigint;
  current_quantity numeric(14, 3);
  next_quantity numeric(14, 3);
  payment_method_record public.payment_methods%rowtype;
  canonical_payload jsonb;
  normalized_reason text;
  normalized_reference_number text;
  seen_sale_item_ids uuid[] := array[]::uuid[];
begin
  if target_organization_id is null
    or target_sale_id is null
    or target_idempotency_key is null then
    raise exception 'A sale and refund key are required.' using errcode = '23514';
  end if;

  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'sales.refund')) then
    raise exception 'Sales refund permission is required.' using errcode = '42501';
  end if;

  normalized_reason := trim(coalesce(target_reason, ''));
  normalized_reference_number := nullif(trim(coalesce(target_reference_number, '')), '');

  if char_length(normalized_reason) not between 2 and 500 then
    raise exception 'A refund reason must contain between 2 and 500 characters.'
      using errcode = '23514';
  end if;

  if normalized_reference_number is not null
    and char_length(normalized_reference_number) not between 1 and 120 then
    raise exception 'A refund reference must contain at most 120 characters.'
      using errcode = '23514';
  end if;

  if coalesce(jsonb_typeof(target_items), '') <> 'array'
    or coalesce(jsonb_array_length(target_items), 0) not between 1 and 100 then
    raise exception 'Select between 1 and 100 sale items to refund.' using errcode = '23514';
  end if;

  -- A missing return_to_stock flag retains the established behavior (restore
  -- tracked stock). When supplied, it must be a JSON boolean: strings such as
  -- "true", numeric values, and JSON null are rejected instead of coerced.
  if exists (
    select 1
    from jsonb_array_elements(target_items) as item(value)
    where jsonb_typeof(item.value) <> 'object'
      or (
        item.value ? 'return_to_stock'
        and jsonb_typeof(item.value -> 'return_to_stock') <> 'boolean'
      )
  ) then
    raise exception 'Each refund line must provide return_to_stock as a boolean when supplied.'
      using errcode = '23514';
  end if;

  select sale.*
  into original_sale
  from public.sales sale
  where sale.id = target_sale_id
    and sale.organization_id = target_organization_id
    and sale.status = 'completed'
  for update;

  if original_sale.id is null then
    raise exception 'The completed sale was not found.' using errcode = 'P0002';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  join public.employee_stores employee_store
    on employee_store.employee_id = employee.id
   and employee_store.organization_id = employee.organization_id
   and employee_store.store_id = original_sale.store_id
  join public.stores store
    on store.id = original_sale.store_id
   and store.organization_id = original_sale.organization_id
   and store.is_active
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active';

  if actor_employee_id is null then
    raise exception 'An active employee assignment for the original sale store is required.'
      using errcode = '42501';
  end if;

  canonical_payload := jsonb_build_object(
    'items', target_items,
    'payment_method_id', target_payment_method_id,
    'reason', normalized_reason,
    'reference_number', normalized_reference_number,
    'sale_id', target_sale_id
  );

  select
    request.actor_employee_id,
    request.request_payload,
    request.refund_id
  into
    existing_actor_employee_id,
    existing_payload,
    existing_refund_id
  from public.refund_requests request
  where request.organization_id = target_organization_id
    and request.idempotency_key = target_idempotency_key
  for update;

  if found then
    if existing_actor_employee_id is distinct from actor_employee_id
      or existing_payload is distinct from canonical_payload then
      raise exception 'This refund key was already used for a different request.'
        using errcode = '23505';
    end if;

    if existing_refund_id is null then
      raise exception 'The prior refund request did not complete. Try again with a new key.'
        using errcode = '40001';
    end if;

    return query
    select refund.id, refund.refund_number, refund.total_minor, true
    from public.refunds refund
    where refund.id = existing_refund_id
      and refund.organization_id = target_organization_id;
    return;
  end if;

  -- Lock stock projections in a stable order before the line loop. This keeps
  -- independent refunds from acquiring inventory locks in conflicting orders.
  perform 1
  from public.inventory_levels level
  join public.sale_items sale_item
    on sale_item.organization_id = level.organization_id
   and sale_item.product_id = level.product_id
   and sale_item.variant_id is not distinct from level.variant_id
  where level.organization_id = target_organization_id
    and level.store_id = original_sale.store_id
    and sale_item.sale_id = target_sale_id
    and sale_item.id in (
      select (item.value ->> 'sale_item_id')::uuid
      from jsonb_array_elements(target_items) as item(value)
    )
    and exists (
      select 1
      from public.inventory_movements movement
      where movement.organization_id = target_organization_id
        and movement.store_id = original_sale.store_id
        and movement.product_id = sale_item.product_id
        and movement.variant_id is not distinct from sale_item.variant_id
        and movement.movement_type = 'SALE'
        and movement.source_type = 'sale'
        and movement.source_id = target_sale_id
    )
  order by level.product_id, level.variant_id nulls first
  for update;

  insert into public.refund_requests (
    organization_id,
    actor_employee_id,
    idempotency_key,
    request_payload
  )
  values (
    target_organization_id,
    actor_employee_id,
    target_idempotency_key,
    canonical_payload
  );

  new_refund_number := nextval('private.tindio_refund_number_sequence'::regclass);

  insert into public.refunds (
    organization_id,
    sale_id,
    store_id,
    register_id,
    refunded_by_employee_id,
    refund_number,
    currency_code,
    reason
  )
  values (
    target_organization_id,
    target_sale_id,
    original_sale.store_id,
    original_sale.register_id,
    actor_employee_id,
    new_refund_number,
    original_sale.currency_code,
    normalized_reason
  )
  returning id into new_refund_id;

  for refund_item_value in
    select item.value
    from jsonb_array_elements(target_items) as item(value)
    order by item.value ->> 'sale_item_id'
  loop
    begin
      selected_sale_item_id := (refund_item_value ->> 'sale_item_id')::uuid;
      selected_quantity := (refund_item_value ->> 'quantity')::integer;
      selected_return_to_stock := coalesce(
        (refund_item_value ->> 'return_to_stock')::boolean,
        true
      );
    exception
      when others then
        raise exception 'Each refund line needs a valid sale item and whole quantity.'
          using errcode = '23514';
    end;

    if selected_quantity not between 1 and 10000 then
      raise exception 'Refund quantities must be whole numbers between 1 and 10000.'
        using errcode = '23514';
    end if;

    if selected_sale_item_id = any(seen_sale_item_ids) then
      raise exception 'Each sale item can only appear once in a refund.'
        using errcode = '23514';
    end if;
    seen_sale_item_ids := array_append(seen_sale_item_ids, selected_sale_item_id);

    select sale_item.*
    into original_item
    from public.sale_items sale_item
    where sale_item.id = selected_sale_item_id
      and sale_item.organization_id = target_organization_id
      and sale_item.sale_id = target_sale_id
    for update;

    if original_item.id is null then
      raise exception 'One or more selected items do not belong to this sale.'
        using errcode = '23514';
    end if;

    select coalesce(sum(refund_item.quantity), 0)::integer
    into already_refunded_quantity
    from public.refund_items refund_item
    join public.refunds prior_refund
      on prior_refund.id = refund_item.refund_id
     and prior_refund.organization_id = refund_item.organization_id
    where refund_item.organization_id = target_organization_id
      and refund_item.sale_item_id = original_item.id
      and prior_refund.sale_id = target_sale_id
      and prior_refund.status = 'completed';

    if already_refunded_quantity + selected_quantity > original_item.quantity then
      raise exception 'This refund exceeds the quantity remaining on the original sale.'
        using errcode = '23514';
    end if;

    insert into public.refund_items (
      organization_id,
      refund_id,
      sale_item_id,
      product_id,
      variant_id,
      product_name_snapshot,
      variant_name_snapshot,
      sku_snapshot,
      unit_snapshot,
      quantity,
      unit_price_minor,
      line_total_minor,
      returned_to_stock
    )
    values (
      target_organization_id,
      new_refund_id,
      original_item.id,
      original_item.product_id,
      original_item.variant_id,
      original_item.product_name_snapshot,
      original_item.variant_name_snapshot,
      original_item.sku_snapshot,
      original_item.unit_snapshot,
      selected_quantity,
      original_item.unit_price_minor,
      original_item.unit_price_minor * selected_quantity,
      selected_return_to_stock
    );

    calculated_total_minor := calculated_total_minor
      + original_item.unit_price_minor * selected_quantity;

    if selected_return_to_stock and exists (
      select 1
      from public.inventory_movements movement
      where movement.organization_id = target_organization_id
        and movement.store_id = original_sale.store_id
        and movement.product_id = original_item.product_id
        and movement.variant_id is not distinct from original_item.variant_id
        and movement.movement_type = 'SALE'
        and movement.source_type = 'sale'
        and movement.source_id = target_sale_id
    ) then
      select level.quantity
      into current_quantity
      from public.inventory_levels level
      where level.organization_id = target_organization_id
        and level.store_id = original_sale.store_id
        and level.product_id = original_item.product_id
        and level.variant_id is not distinct from original_item.variant_id;

      if current_quantity is null then
        raise exception 'The stock projection is unavailable for a tracked sale item.'
          using errcode = '23514';
      end if;

      next_quantity := current_quantity + selected_quantity;

      update public.inventory_levels
      set
        quantity = next_quantity,
        updated_at = now()
      where organization_id = target_organization_id
        and store_id = original_sale.store_id
        and product_id = original_item.product_id
        and variant_id is not distinct from original_item.variant_id;

      insert into public.inventory_movements (
        organization_id,
        store_id,
        product_id,
        variant_id,
        quantity_delta,
        quantity_before,
        quantity_after,
        movement_type,
        actor_employee_id,
        reason,
        source_type,
        source_id
      )
      values (
        target_organization_id,
        original_sale.store_id,
        original_item.product_id,
        original_item.variant_id,
        selected_quantity,
        current_quantity,
        next_quantity,
        'REFUND',
        actor_employee_id,
        normalized_reason,
        'refund',
        new_refund_id
      );
    end if;
  end loop;

  if calculated_total_minor > 0 then
    if target_payment_method_id is null then
      raise exception 'Select the method used to return the payment.' using errcode = '23514';
    end if;

    select payment_method.*
    into payment_method_record
    from public.payment_methods payment_method
    join public.store_payment_methods store_payment_method
      on store_payment_method.organization_id = payment_method.organization_id
     and store_payment_method.payment_method_id = payment_method.id
     and store_payment_method.store_id = original_sale.store_id
     and store_payment_method.is_enabled
    where payment_method.organization_id = target_organization_id
      and payment_method.id = target_payment_method_id
      and payment_method.is_enabled;

    if payment_method_record.id is null then
      raise exception 'Select an enabled payment method for the original sale store.'
        using errcode = '23514';
    end if;

    if payment_method_record.requires_reference and normalized_reference_number is null then
      raise exception 'A reference is required for this refund payment method.'
        using errcode = '23514';
    end if;

    insert into public.refund_payments (
      organization_id,
      refund_id,
      payment_method_id,
      payment_method_name_snapshot,
      payment_method_code_snapshot,
      payment_method_type_snapshot,
      amount_minor,
      reference_number
    )
    values (
      target_organization_id,
      new_refund_id,
      payment_method_record.id,
      payment_method_record.name,
      payment_method_record.code,
      payment_method_record.payment_type,
      calculated_total_minor,
      normalized_reference_number
    );
  end if;

  update public.refunds refund
  set total_minor = calculated_total_minor
  where refund.id = new_refund_id
    and refund.organization_id = target_organization_id;

  update public.refund_requests request
  set
    state = 'completed',
    refund_id = new_refund_id,
    completed_at = now()
  where request.organization_id = target_organization_id
    and request.idempotency_key = target_idempotency_key;

  return query
  select new_refund_id, new_refund_number, calculated_total_minor, false;
end;
$$;


ALTER FUNCTION "private"."refund_sale"("target_organization_id" "uuid", "target_sale_id" "uuid", "target_payment_method_id" "uuid", "target_idempotency_key" "uuid", "target_reason" "text", "target_reference_number" "text", "target_items" "jsonb") OWNER TO "postgres";

--
-- Name: remove_inventory_policy_override("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."remove_inventory_policy_override"("target_organization_id" "uuid", "target_store_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  removed_policy text;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'inventory.manage')) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;

  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then
    raise exception 'You do not have access to manage this store.' using errcode = '42501';
  end if;

  delete from public.inventory_policies policy
  where policy.organization_id = target_organization_id
    and policy.store_id = target_store_id
  returning policy.negative_stock_policy into removed_policy;

  if found then
    perform private.write_audit_log(
      target_organization_id,
      'INVENTORY_POLICY_OVERRIDE_REMOVED',
      'inventory.manage',
      actor_id,
      null,
      target_store_id,
      null,
      null,
      null,
      null,
      jsonb_build_object(
        'previous_negative_stock_policy', removed_policy,
        'scope', 'store_override'
      )
    );
  end if;
end;
$$;


ALTER FUNCTION "private"."remove_inventory_policy_override"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

--
-- Name: remove_offline_checkout_total_marker(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."remove_offline_checkout_total_marker"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.payments payment
  set note = nullif(
    btrim(regexp_replace(payment.note, '\s*\[tindio-offline-total:[0-9]+\]', '', 'g')),
    ''
  )
  where payment.organization_id = new.organization_id
    and payment.sale_id = new.id
    and payment.note ~ '\[tindio-offline-total:[0-9]+\]';

  return new;
end;
$$;


ALTER FUNCTION "private"."remove_offline_checkout_total_marker"() OWNER TO "postgres";

--
-- Name: request_manager_approval("uuid", "text", "text", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."request_manager_approval"("target_organization_id" "uuid", "target_operation_code" "text", "target_reason" "text", "target_payload" "jsonb") RETURNS TABLE("decision" "text", "approval_request_id" "uuid", "expires_at" timestamp with time zone, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  required_permission text;
  resolved_store_id uuid;
  resolved_register_id uuid;
  resolved_amount_minor bigint;
  resolved_decision text;
  existing_request public.approval_requests%rowtype;
  normalized_reason text;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in is required.' using errcode = '42501';
  end if;

  required_permission := private.approval_operation_permission(target_operation_code);
  if required_permission is null then
    raise exception 'This approval operation is not supported.' using errcode = '23514';
  end if;

  actor_employee_id := private.current_employee_id(target_organization_id);
  if actor_employee_id is null then
    raise exception 'An active employee is required.' using errcode = '42501';
  end if;

  if not private.has_permission(target_organization_id, 'approvals.request') then
    raise exception 'Approval-request permission is required.' using errcode = '42501';
  end if;

  if target_operation_code = 'inventory.adjust'
    and not private.has_any_inventory_capability(
      target_organization_id,
      array['inventory.adjust.create', 'inventory.adjust.post']
    ) then
    raise exception 'Inventory adjustment permission is required.' using errcode = '42501';
  end if;

  normalized_reason := trim(coalesce(target_reason, ''));
  if char_length(normalized_reason) not between 2 and 500 then
    raise exception 'Provide a reason between 2 and 500 characters.' using errcode = '23514';
  end if;

  select context.store_id, context.register_id, context.amount_minor
  into resolved_store_id, resolved_register_id, resolved_amount_minor
  from private.resolve_approval_context(
    target_organization_id,
    target_operation_code,
    target_payload
  ) context;

  if not private.has_store_read_scope(target_organization_id, resolved_store_id) then
    raise exception 'You do not have access to the store for this request.' using errcode = '42501';
  end if;

  resolved_decision := private.approval_decision(
    target_organization_id,
    target_operation_code,
    resolved_amount_minor
  );

  if resolved_decision = 'DENIED' and not (
    private.employee_has_permission(target_organization_id, actor_employee_id, 'approvals.bypass')
    and private.employee_has_permission(target_organization_id, actor_employee_id, required_permission)
  ) then
    return query select 'DENIED'::text, null::uuid, null::timestamptz, 'This operation is disabled by the organization approval rule.'::text;
    return;
  end if;

  if resolved_decision = 'ALLOWED'
    and private.employee_has_permission(target_organization_id, actor_employee_id, required_permission) then
    return query select 'ALLOWED'::text, null::uuid, null::timestamptz, 'This operation is allowed for your role.'::text;
    return;
  end if;

  select * into existing_request
  from public.approval_requests request
  where request.organization_id = target_organization_id
    and request.requested_by_employee_id = actor_employee_id
    and request.operation_code = target_operation_code
    and request.request_payload = target_payload
    and request.status = 'PENDING'
    and request.expires_at > now()
  order by request.requested_at desc
  limit 1
  for update;

  if existing_request.id is not null then
    return query select 'APPROVAL_REQUIRED'::text, existing_request.id, existing_request.expires_at, 'Manager approval is pending.'::text;
    return;
  end if;

  insert into public.approval_requests (
    organization_id,
    store_id,
    register_id,
    requested_by_employee_id,
    operation_code,
    requested_amount_minor,
    reason,
    request_payload
  )
  values (
    target_organization_id,
    resolved_store_id,
    resolved_register_id,
    actor_employee_id,
    target_operation_code,
    resolved_amount_minor,
    normalized_reason,
    target_payload
  )
  returning id, public.approval_requests.expires_at into approval_request_id, expires_at;

  perform private.write_audit_log(
    target_organization_id,
    'APPROVAL_REQUESTED',
    target_operation_code,
    actor_employee_id,
    null,
    resolved_store_id,
    resolved_register_id,
    approval_request_id,
    resolved_amount_minor,
    normalized_reason,
    jsonb_build_object('status', 'PENDING')
  );

  decision := 'APPROVAL_REQUIRED';
  message := 'Manager approval is required for this operation.';
  return next;
end;
$$;


ALTER FUNCTION "private"."request_manager_approval"("target_organization_id" "uuid", "target_operation_code" "text", "target_reason" "text", "target_payload" "jsonb") OWNER TO "postgres";

--
-- Name: require_active_device_binding("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."require_active_device_binding"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.stores store
    join public.registers register
      on register.id = target_register_id
     and register.organization_id = store.organization_id
     and register.store_id = store.id
     and register.is_active
    where store.id = target_store_id
      and store.organization_id = target_organization_id
      and store.is_active
  ) then
    raise exception 'Choose an active store and register in this organization.' using errcode = '23514';
  end if;
end;
$$;


ALTER FUNCTION "private"."require_active_device_binding"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid") OWNER TO "postgres";

--
-- Name: require_active_pos_device("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."require_active_pos_device"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  device_management_required boolean;
  request_headers jsonb;
  requested_device_id_text text;
  requested_secret text;
  requested_app_version text;
  verified_device_id uuid;
begin
  select organization.device_management_enabled
  into device_management_required
  from public.organizations organization
  where organization.id = target_organization_id;

  if not coalesce(device_management_required, false) then
    return null;
  end if;

  begin
    request_headers := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::jsonb;
  exception when others then
    raise exception 'This POS device credential is invalid.' using errcode = '42501';
  end;

  requested_device_id_text := nullif(request_headers ->> 'x-tindio-device-id', '');
  requested_secret := nullif(request_headers ->> 'x-tindio-device-secret', '');
  requested_app_version := nullif(request_headers ->> 'x-tindio-app-version', '');

  if requested_device_id_text is null
    or requested_device_id_text !~ '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$' then
    raise exception 'This POS device needs to be enrolled before it can use the register.'
      using errcode = '42501';
  end if;

  select verified.device_id
  into verified_device_id
  from private.verify_pos_device_credential(
    target_organization_id,
    requested_device_id_text::uuid,
    requested_secret,
    requested_app_version,
    target_store_id,
    target_register_id
  ) verified;

  return verified_device_id;
end;
$_$;


ALTER FUNCTION "private"."require_active_pos_device"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid") OWNER TO "postgres";

--
-- Name: require_active_pos_shift("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."require_active_pos_shift"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  active_shift_id uuid;
begin
  if target_organization_id is null
    or target_store_id is null
    or target_register_id is null then
    raise exception 'A store and register are required for POS activity.' using errcode = '23514';
  end if;

  perform private.require_active_pos_device(
    target_organization_id,
    target_store_id,
    target_register_id
  );

  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'sales.create')) then
    raise exception 'Sales permission is required.' using errcode = '42501';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  join public.employee_stores employee_store
    on employee_store.employee_id = employee.id
   and employee_store.organization_id = employee.organization_id
   and employee_store.store_id = target_store_id
  join public.stores store
    on store.id = employee_store.store_id
   and store.organization_id = employee_store.organization_id
   and store.is_active
  join public.registers register
    on register.id = target_register_id
   and register.organization_id = employee.organization_id
   and register.store_id = target_store_id
   and register.is_active
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
  for key share of employee, store, register;

  if actor_employee_id is null then
    raise exception 'An active employee assignment, store, and register are required.'
      using errcode = '42501';
  end if;

  select shift.id
  into active_shift_id
  from public.shifts shift
  where shift.organization_id = target_organization_id
    and shift.store_id = target_store_id
    and shift.register_id = target_register_id
    and shift.opened_by_employee_id = actor_employee_id
    and shift.status = 'open'
  for update;

  if active_shift_id is null then
    raise exception 'Open your register shift before using transactional POS features.'
      using errcode = '42501';
  end if;

  return actor_employee_id;
end;
$$;


ALTER FUNCTION "private"."require_active_pos_shift"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid") OWNER TO "postgres";

--
-- Name: require_attendance_terminal("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."require_attendance_terminal"("target_organization_id" "uuid", "target_store_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'attendance.use')) then
    raise exception 'Attendance access is required.' using errcode = '42501';
  end if;

  if target_store_id is null
    or not (select private.has_store_read_scope(target_organization_id, target_store_id))
    or not exists (
      select 1 from public.stores store
      where store.id = target_store_id
        and store.organization_id = target_organization_id
        and store.is_active
    ) then
    raise exception 'Choose an assigned active store for attendance.' using errcode = '42501';
  end if;

  actor_employee_id := private.current_employee_id(target_organization_id);
  if actor_employee_id is null then
    raise exception 'An active terminal employee is required.' using errcode = '42501';
  end if;
  return actor_employee_id;
end;
$$;


ALTER FUNCTION "private"."require_attendance_terminal"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

--
-- Name: require_device_manager("uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."require_device_manager"("target_organization_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'devices.manage')) then
    raise exception 'Device-management permission is required.' using errcode = '42501';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active';

  if actor_employee_id is null then
    raise exception 'An active employee membership is required.' using errcode = '42501';
  end if;

  return actor_employee_id;
end;
$$;


ALTER FUNCTION "private"."require_device_manager"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: require_employee_manager_target("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."require_employee_manager_target"("target_organization_id" "uuid", "target_employee_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'employees.manage')) then
    raise exception 'Employee-management permission is required.' using errcode = '42501';
  end if;
  actor_id := private.current_employee_id(target_organization_id);
  if actor_id is null then
    raise exception 'An active employee manager is required.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.employees employee
    where employee.id = target_employee_id
      and employee.organization_id = target_organization_id
  ) or not private.can_access_employee_store_scope(target_organization_id, target_employee_id) then
    raise exception 'Select an employee within your store access.' using errcode = '42501';
  end if;
  return actor_id;
end;
$$;


ALTER FUNCTION "private"."require_employee_manager_target"("target_organization_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";

--
-- Name: require_pos_capabilities("uuid", "text"[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."require_pos_capabilities"("target_organization_id" "uuid", "required_permission_codes" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  missing_permission_code text;
begin
  if (select auth.uid()) is null then
    raise exception 'An authenticated employee is required.' using errcode = '42501';
  end if;

  select required.permission_code
  into missing_permission_code
  from unnest(coalesce(required_permission_codes, '{}'::text[])) as required(permission_code)
  where not (select private.has_permission(target_organization_id, required.permission_code))
  order by required.permission_code
  limit 1;

  if missing_permission_code is not null then
    raise exception 'The % permission is required.', missing_permission_code using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "private"."require_pos_capabilities"("target_organization_id" "uuid", "required_permission_codes" "text"[]) OWNER TO "postgres";

--
-- Name: FUNCTION "require_pos_capabilities"("target_organization_id" "uuid", "required_permission_codes" "text"[]); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."require_pos_capabilities"("target_organization_id" "uuid", "required_permission_codes" "text"[]) IS 'Shared permission-only POS capability guard. Preset and customer-created roles use the same role_permissions rows.';


--
-- Name: require_pos_workspace_access("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."require_pos_workspace_access"("target_organization_id" "uuid", "target_store_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
begin
  if target_organization_id is null or target_store_id is null then
    raise exception 'Organization and store are required.' using errcode = '22023';
  end if;

  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'sales.create')) then
    raise exception 'POS access is required.' using errcode = '42501';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  join public.employee_stores employee_store
    on employee_store.employee_id = employee.id
   and employee_store.organization_id = employee.organization_id
  join public.stores store
    on store.id = employee_store.store_id
   and store.organization_id = employee_store.organization_id
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active'
    and employee_store.store_id = target_store_id
    and store.is_active;

  if actor_employee_id is null then
    raise exception 'The selected store is not assigned to this employee.' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.shifts shift
    where shift.organization_id = target_organization_id
      and shift.store_id = target_store_id
      and shift.opened_by_employee_id = actor_employee_id
      and shift.status = 'open'
  ) then
    raise exception 'Open a register shift before using the POS workspace.' using errcode = '42501';
  end if;

  return actor_employee_id;
end;
$$;


ALTER FUNCTION "private"."require_pos_workspace_access"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

--
-- Name: resolve_approval_context("uuid", "text", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."resolve_approval_context"("target_organization_id" "uuid", "target_operation_code" "text", "target_payload" "jsonb") RETURNS TABLE("store_id" "uuid", "register_id" "uuid", "amount_minor" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_sale_id uuid;
  target_shift_id uuid;
  target_item jsonb;
  target_sale_item_id uuid;
  target_quantity integer;
  target_unit_price_minor bigint;
  calculated_amount_minor bigint := 0;
begin
  if coalesce(jsonb_typeof(target_payload), '') <> 'object' then
    raise exception 'Approval details are invalid.' using errcode = '23514';
  end if;

  if target_operation_code = 'sales.refund' then
    begin
      target_sale_id := (target_payload ->> 'sale_id')::uuid;
    exception when others then
      raise exception 'A valid sale is required for a refund approval.' using errcode = '23514';
    end;

    select sale.store_id, sale.register_id
    into store_id, register_id
    from public.sales sale
    where sale.organization_id = target_organization_id
      and sale.id = target_sale_id
      and sale.status = 'completed';

    if store_id is null then
      raise exception 'The completed sale was not found.' using errcode = 'P0002';
    end if;

    if coalesce(jsonb_typeof(target_payload -> 'items'), '') <> 'array'
      or coalesce(jsonb_array_length(target_payload -> 'items'), 0) not between 1 and 100 then
      raise exception 'Select refund items before requesting approval.' using errcode = '23514';
    end if;

    for target_item in select value from jsonb_array_elements(target_payload -> 'items') loop
      begin
        target_sale_item_id := (target_item ->> 'sale_item_id')::uuid;
        target_quantity := (target_item ->> 'quantity')::integer;
      exception when others then
        raise exception 'Refund approval items are invalid.' using errcode = '23514';
      end;

      select sale_item.unit_price_minor
      into target_unit_price_minor
      from public.sale_items sale_item
      where sale_item.organization_id = target_organization_id
        and sale_item.sale_id = target_sale_id
        and sale_item.id = target_sale_item_id;

      if target_unit_price_minor is null or target_quantity not between 1 and 10000 then
        raise exception 'Refund approval items do not match the original sale.' using errcode = '23514';
      end if;

      calculated_amount_minor := calculated_amount_minor + target_unit_price_minor * target_quantity;
    end loop;

    amount_minor := calculated_amount_minor;
    return next;
    return;
  end if;

  if target_operation_code = 'cash.pay_out' then
    begin
      target_shift_id := (target_payload ->> 'shift_id')::uuid;
      amount_minor := (target_payload ->> 'amount_minor')::bigint;
    exception when others then
      raise exception 'Cash approval details are invalid.' using errcode = '23514';
    end;

    select shift.store_id, shift.register_id
    into store_id, register_id
    from public.shifts shift
    where shift.organization_id = target_organization_id
      and shift.id = target_shift_id
      and shift.status = 'open';

    if store_id is null or amount_minor <= 0 then
      raise exception 'The open shift or cash amount is invalid.' using errcode = '23514';
    end if;

    return next;
    return;
  end if;

  if target_operation_code = 'inventory.adjust' then
    begin
      store_id := (target_payload ->> 'store_id')::uuid;
    exception when others then
      raise exception 'Inventory approval details are invalid.' using errcode = '23514';
    end;

    if not exists (
      select 1
      from public.stores store
      where store.id = store_id
        and store.organization_id = target_organization_id
        and store.is_active
    ) then
      raise exception 'Select an active store for this inventory adjustment.' using errcode = '23514';
    end if;

    register_id := null;
    amount_minor := null;
    return next;
    return;
  end if;

  raise exception 'This approval operation is not available yet.' using errcode = '23514';
end;
$$;


ALTER FUNCTION "private"."resolve_approval_context"("target_organization_id" "uuid", "target_operation_code" "text", "target_payload" "jsonb") OWNER TO "postgres";

--
-- Name: resolve_negative_stock_policy("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."resolve_negative_stock_policy"("target_organization_id" "uuid", "target_store_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (
      select policy.negative_stock_policy
      from public.inventory_policies policy
      where policy.organization_id = target_organization_id
        and policy.store_id = target_store_id
    ),
    (
      select policy_default.negative_stock_policy
      from public.inventory_policy_defaults policy_default
      where policy_default.organization_id = target_organization_id
    ),
    'block'
  );
$$;


ALTER FUNCTION "private"."resolve_negative_stock_policy"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "resolve_negative_stock_policy"("target_organization_id" "uuid", "target_store_id" "uuid"); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."resolve_negative_stock_policy"("target_organization_id" "uuid", "target_store_id" "uuid") IS 'Returns the effective policy: store override, organization default, then safe block fallback.';


--
-- Name: return_to_supplier("uuid", "uuid", "uuid", "jsonb", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."return_to_supplier"("target_organization_id" "uuid", "target_store_id" "uuid", "target_supplier_id" "uuid", "target_lines" "jsonb", "target_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor_id uuid; return_id uuid; line jsonb; stock_level public.inventory_levels%rowtype; line_quantity numeric(14,3);
begin
  if (select auth.uid()) is null or not (select private.has_permission(target_organization_id, 'inventory.manage')) then raise exception 'Inventory permission is required.' using errcode = '42501'; end if;
  if target_lines is null or jsonb_typeof(target_lines) <> 'array' or jsonb_array_length(target_lines) not between 1 and 100 then raise exception 'A supplier return needs one to 100 items.' using errcode = '23514'; end if;
  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then raise exception 'An assigned employee is required for this store.' using errcode = '42501'; end if;
  if not exists (select 1 from public.suppliers supplier where supplier.id = target_supplier_id and supplier.organization_id = target_organization_id and supplier.is_active) then raise exception 'Choose an active supplier.' using errcode = '23514'; end if;
  insert into public.supplier_returns (organization_id, supplier_id, store_id, returned_by_employee_id, note) values (target_organization_id, target_supplier_id, target_store_id, actor_id, nullif(btrim(target_note), '')) returning id into return_id;
  for line in select value from jsonb_array_elements(target_lines) order by value->>'product_id', coalesce(value->>'variant_id','') loop
    if coalesce(line->>'product_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or coalesce(line->>'quantity','') !~ '^\d+(\.\d{1,3})?$' or (line->>'quantity')::numeric <= 0 then raise exception 'Supplier-return lines must include valid items and quantities.' using errcode = '23514'; end if;
    line_quantity := (line->>'quantity')::numeric(14,3);
    select * into stock_level from public.inventory_levels level where level.organization_id = target_organization_id and level.store_id = target_store_id and level.product_id = (line->>'product_id')::uuid and level.variant_id is not distinct from nullif(line->>'variant_id','')::uuid for update;
    if stock_level.id is null or stock_level.quantity < line_quantity then raise exception 'Stock is insufficient for this supplier return.' using errcode = '23514'; end if;
    insert into public.supplier_return_lines (organization_id, supplier_return_id, product_id, variant_id, quantity, unit_cost_minor) values (target_organization_id, return_id, stock_level.product_id, stock_level.variant_id, line_quantity, stock_level.average_cost_minor);
    perform private.apply_inventory_change_v2(target_organization_id, target_store_id, stock_level.product_id, stock_level.variant_id, -line_quantity, 'SUPPLIER_RETURN', actor_id, 'Returned to supplier', 'supplier_return', return_id, stock_level.average_cost_minor);
  end loop;
  perform private.write_audit_log(target_organization_id, 'SUPPLIER_RETURN_CREATED', 'inventory.manage', actor_id, null, target_store_id, null, null, null, target_note, jsonb_build_object('supplier_return_id', return_id, 'supplier_id', target_supplier_id));
  return return_id;
end;
$_$;


ALTER FUNCTION "private"."return_to_supplier"("target_organization_id" "uuid", "target_store_id" "uuid", "target_supplier_id" "uuid", "target_lines" "jsonb", "target_note" "text") OWNER TO "postgres";

--
-- Name: return_to_supplier("uuid", "uuid", "uuid", "jsonb", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."return_to_supplier"("target_organization_id" "uuid", "target_store_id" "uuid", "target_supplier_id" "uuid", "target_lines" "jsonb", "target_note" "text", "target_operation_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_id uuid;
  return_id uuid;
  existing_return public.supplier_returns%rowtype;
  line jsonb;
  stock_level public.inventory_levels%rowtype;
  line_quantity numeric(14,3);
  normalized_note text;
begin
  if (select auth.uid()) is null or (not (select private.has_permission(target_organization_id, 'inventory.manage')) and not (select private.has_inventory_capability(target_organization_id, 'purchasing.return'))) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;
  if target_operation_id is null then
    raise exception 'An operation ID is required for a supplier return.' using errcode = '23514';
  end if;
  if target_lines is null or jsonb_typeof(target_lines) <> 'array' or jsonb_array_length(target_lines) not between 1 and 100 then
    raise exception 'A supplier return needs one to 100 items.' using errcode = '23514';
  end if;

  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then
    raise exception 'An assigned employee is required for this store.' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.suppliers supplier
    where supplier.id = target_supplier_id
      and supplier.organization_id = target_organization_id
      and supplier.is_active
  ) then
    raise exception 'Choose an active supplier.' using errcode = '23514';
  end if;

  normalized_note := nullif(btrim(target_note), '');
  select * into existing_return
  from public.supplier_returns supplier_return
  where supplier_return.organization_id = target_organization_id
    and supplier_return.operation_id = target_operation_id;

  if found then
    if existing_return.store_id is distinct from target_store_id
      or existing_return.supplier_id is distinct from target_supplier_id
      or existing_return.note is distinct from normalized_note then
      raise exception 'This operation ID was already used for a different supplier return.' using errcode = '23514';
    end if;
    return existing_return.id;
  end if;

  insert into public.supplier_returns (
    organization_id, supplier_id, store_id, returned_by_employee_id, note, operation_id
  ) values (
    target_organization_id, target_supplier_id, target_store_id, actor_id, normalized_note, target_operation_id
  ) on conflict (organization_id, operation_id) where operation_id is not null do nothing
  returning id into return_id;

  if return_id is null then
    select * into existing_return
    from public.supplier_returns supplier_return
    where supplier_return.organization_id = target_organization_id
      and supplier_return.operation_id = target_operation_id;
    if existing_return.store_id is distinct from target_store_id
      or existing_return.supplier_id is distinct from target_supplier_id
      or existing_return.note is distinct from normalized_note then
      raise exception 'This operation ID was already used for a different supplier return.' using errcode = '23514';
    end if;
    return existing_return.id;
  end if;

  for line in
    select value
    from jsonb_array_elements(target_lines)
    order by value->>'product_id', coalesce(value->>'variant_id', '')
  loop
    if coalesce(line->>'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or coalesce(line->>'quantity', '') !~ '^\d+(\.\d{1,3})?$'
      or (line->>'quantity')::numeric <= 0 then
      raise exception 'Supplier-return lines must include valid items and quantities.' using errcode = '23514';
    end if;

    line_quantity := (line->>'quantity')::numeric(14,3);
    select * into stock_level
    from public.inventory_levels level
    where level.organization_id = target_organization_id
      and level.store_id = target_store_id
      and level.product_id = (line->>'product_id')::uuid
      and level.variant_id is not distinct from nullif(line->>'variant_id', '')::uuid
    for update;

    if stock_level.id is null or stock_level.quantity < line_quantity then
      raise exception 'Stock is insufficient for this supplier return.' using errcode = '23514';
    end if;

    insert into public.supplier_return_lines (
      organization_id, supplier_return_id, product_id, variant_id, quantity, unit_cost_minor
    ) values (
      target_organization_id, return_id, stock_level.product_id, stock_level.variant_id,
      line_quantity, stock_level.average_cost_minor
    );
    perform private.apply_inventory_change_v2(
      target_organization_id, target_store_id, stock_level.product_id, stock_level.variant_id,
      -line_quantity, 'SUPPLIER_RETURN', actor_id, 'Returned to supplier', 'supplier_return',
      return_id, stock_level.average_cost_minor
    );
  end loop;

  perform private.write_audit_log(
    target_organization_id, 'SUPPLIER_RETURN_CREATED', 'inventory.manage', actor_id, null,
    target_store_id, null, null, null, target_note,
    jsonb_build_object('supplier_return_id', return_id, 'supplier_id', target_supplier_id, 'operation_id', target_operation_id)
  );
  return return_id;
end;
$_$;


ALTER FUNCTION "private"."return_to_supplier"("target_organization_id" "uuid", "target_store_id" "uuid", "target_supplier_id" "uuid", "target_lines" "jsonb", "target_note" "text", "target_operation_id" "uuid") OWNER TO "postgres";

--
-- Name: reverse_loyalty_earnings_for_refund(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."reverse_loyalty_earnings_for_refund"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  original_sale public.sales%rowtype;
  cumulative_refund_minor bigint;
  already_reversed_points integer;
  target_reversed_points integer;
  incremental_reversal integer;
begin
  if new.status <> 'completed'
    or new.total_minor <= old.total_minor
    or new.total_minor <= 0 then
    return new;
  end if;

  select sale.*
  into original_sale
  from public.sales sale
  where sale.id = new.sale_id and sale.organization_id = new.organization_id
  for share;

  if original_sale.customer_id is null
    or original_sale.loyalty_points_earned = 0
    or original_sale.total_minor <= 0 then
    return new;
  end if;

  select coalesce(sum(refund.total_minor), 0)::bigint
  into cumulative_refund_minor
  from public.refunds refund
  where refund.organization_id = new.organization_id
    and refund.sale_id = new.sale_id
    and refund.status = 'completed';

  select coalesce(-sum(transaction.points_delta), 0)::integer
  into already_reversed_points
  from public.loyalty_transactions transaction
  where transaction.organization_id = new.organization_id
    and transaction.sale_id = new.sale_id
    and transaction.entry_type = 'REFUND_EARN_REVERSAL';

  target_reversed_points := floor(
    original_sale.loyalty_points_earned::numeric
    * least(cumulative_refund_minor, original_sale.total_minor)::numeric
    / original_sale.total_minor::numeric
  )::integer;
  incremental_reversal := target_reversed_points - already_reversed_points;

  if incremental_reversal > 0 then
    insert into public.loyalty_transactions (
      organization_id,
      customer_id,
      sale_id,
      refund_id,
      entry_type,
      points_delta,
      note
    )
    values (
      new.organization_id,
      original_sale.customer_id,
      new.sale_id,
      new.id,
      'REFUND_EARN_REVERSAL',
      -incremental_reversal,
      'Loyalty points reversed for refund'
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."reverse_loyalty_earnings_for_refund"() OWNER TO "postgres";

--
-- Name: save_inventory_count_line("uuid", "uuid", "uuid", "uuid", numeric); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."save_inventory_count_line"("target_organization_id" "uuid", "target_inventory_count_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_counted_quantity" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  count_document public.inventory_counts%rowtype;
  actor_id uuid;
  current_reconciled_expected_quantity numeric(14,3);
  existing_line_id uuid;
  product_snapshot record;
  next_line_sort_order integer;
  recorded_at timestamptz;
begin
  if target_counted_quantity < 0 then
    raise exception 'Counted quantity must be zero or greater.' using errcode = '23514';
  end if;

  select count_row.* into count_document
  from public.inventory_counts count_row
  where count_row.id = target_inventory_count_id
    and count_row.organization_id = target_organization_id
  for update;

  if count_document.id is null then
    raise exception 'Inventory count was not found.' using errcode = '23503';
  end if;
  if count_document.status not in ('draft', 'in_progress') then
    raise exception 'Only draft or in-progress counts can be edited.' using errcode = '23514';
  end if;

  -- This is the shared count permission and store-scope boundary used by
  -- count preparation, review, and posting.  It intentionally supports
  -- inventory.count as well as inventory.manage; it does not use role names.
  actor_id := private.inventory_count_actor(target_organization_id, count_document.store_id);

  select
    product.name as product_name,
    case when target_variant_id is null then null else variant.name end as variant_name,
    coalesce(category.name, 'Uncategorized') as category_name,
    coalesce(case when target_variant_id is null then null else variant.sku end, product.sku) as sku,
    coalesce(case when target_variant_id is null then null else variant.barcode end, product.barcode) as barcode,
    product.unit as unit
  into product_snapshot
  from public.products product
  left join public.product_variants variant
    on variant.id = target_variant_id
    and variant.product_id = product.id
    and variant.organization_id = product.organization_id
  left join public.categories category
    on category.id = product.category_id
    and category.organization_id = product.organization_id
  where product.id = target_product_id
    and product.organization_id = target_organization_id
    and product.status = 'active'
    and product.track_inventory
    and (
      (product.product_type = 'variable' and target_variant_id is not null and variant.id is not null and variant.is_active)
      or
      (product.product_type <> 'variable' and target_variant_id is null)
    );

  if not found then
    raise exception 'Choose an active inventory-tracked item that belongs to this business.' using errcode = '23503';
  end if;

  if not exists (
    select 1
    from public.product_store_settings setting
    where setting.organization_id = target_organization_id
      and setting.store_id = count_document.store_id
      and setting.product_id = target_product_id
  ) then
    raise exception 'Choose an item assigned to this store.' using errcode = '23503';
  end if;

  -- Every canonical inventory movement locks this same projection row.  By
  -- reading it FOR UPDATE at the moment the physical quantity is saved, this
  -- value is the authoritative expected quantity at the count line's exact
  -- reconciliation point, not a stale count-start snapshot.
  select level.quantity into current_reconciled_expected_quantity
  from public.inventory_levels level
  where level.organization_id = target_organization_id
    and level.store_id = count_document.store_id
    and level.product_id = target_product_id
    and level.variant_id is not distinct from target_variant_id
  for update;

  if not found then
    raise exception 'The stock projection is not initialized for this item and store.' using errcode = '23514';
  end if;

  recorded_at := clock_timestamp();

  select line.id into existing_line_id
  from public.inventory_count_lines line
  where line.organization_id = target_organization_id
    and line.inventory_count_id = target_inventory_count_id
    and line.product_id = target_product_id
    and line.variant_id is not distinct from target_variant_id
  for update;

  if existing_line_id is null then
    select coalesce(max(line.line_sort_order) + 1, 0)
    into next_line_sort_order
    from public.inventory_count_lines line
    where line.organization_id = target_organization_id
      and line.inventory_count_id = target_inventory_count_id;

    insert into public.inventory_count_lines (
      organization_id,
      inventory_count_id,
      product_id,
      variant_id,
      expected_quantity,
      reconciled_expected_quantity,
      counted_quantity,
      counted_at,
      product_name_snapshot,
      variant_name_snapshot,
      category_name_snapshot,
      sku_snapshot,
      barcode_snapshot,
      unit_snapshot,
      line_sort_order
    ) values (
      target_organization_id,
      target_inventory_count_id,
      target_product_id,
      target_variant_id,
      current_reconciled_expected_quantity,
      current_reconciled_expected_quantity,
      target_counted_quantity,
      recorded_at,
      product_snapshot.product_name,
      product_snapshot.variant_name,
      product_snapshot.category_name,
      product_snapshot.sku,
      product_snapshot.barcode,
      product_snapshot.unit,
      next_line_sort_order
    );
  else
    -- Prepared lines retain their count-start expected snapshot forever.  A
    -- corrected physical quantity receives a new reconciliation point instead
    -- of rewriting the original snapshot.
    update public.inventory_count_lines
    set counted_quantity = target_counted_quantity,
        reconciled_expected_quantity = current_reconciled_expected_quantity,
        counted_at = recorded_at
    where id = existing_line_id;
  end if;

  update public.inventory_counts
  set status = 'in_progress', updated_at = recorded_at
  where id = target_inventory_count_id;
end;
$$;


ALTER FUNCTION "private"."save_inventory_count_line"("target_organization_id" "uuid", "target_inventory_count_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_counted_quantity" numeric) OWNER TO "postgres";

