    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select *
  from private.save_open_ticket_v2(
    target_organization_id,
    target_store_id,
    target_register_id,
    target_ticket_id,
    target_customer_id,
    target_dining_option_id,
    null,
    target_label,
    target_note,
