--
-- Name: settle_checkout_payment("text", bigint, bigint, bigint); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."settle_checkout_payment"("target_payment_type" "text", "target_requested_amount_minor" bigint, "target_tendered_minor" bigint, "target_remaining_minor" bigint) RETURNS TABLE("applied_minor" bigint, "tendered_minor" bigint, "change_minor" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if target_remaining_minor is null or target_remaining_minor <= 0 then
    raise exception 'No additional payment is needed for this sale.' using errcode = '23514';
  end if;

  if target_payment_type = 'CASH' then
    if target_tendered_minor is null then
      raise exception 'Cash tender is required.' using errcode = '23514';
    end if;

    if target_tendered_minor <= 0 then
      raise exception 'Cash tender must be greater than zero.' using errcode = '23514';
    end if;

    return query
    select
      least(target_tendered_minor, target_remaining_minor),
      target_tendered_minor,
      target_tendered_minor - least(target_tendered_minor, target_remaining_minor);
    return;
  end if;

  if target_requested_amount_minor is null then
    raise exception 'An amount is required for the selected payment method.'
      using errcode = '23514';
  end if;

  if target_requested_amount_minor <= 0
    or target_requested_amount_minor > target_remaining_minor then
    raise exception 'Payment amount must be greater than zero and no more than the remaining balance.'
      using errcode = '23514';
  end if;

  return query
  select target_requested_amount_minor, null::bigint, null::bigint;
end;
$$;


ALTER FUNCTION "private"."settle_checkout_payment"("target_payment_type" "text", "target_requested_amount_minor" bigint, "target_tendered_minor" bigint, "target_remaining_minor" bigint) OWNER TO "postgres";

--
-- Name: FUNCTION "settle_checkout_payment"("target_payment_type" "text", "target_requested_amount_minor" bigint, "target_tendered_minor" bigint, "target_remaining_minor" bigint); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."settle_checkout_payment"("target_payment_type" "text", "target_requested_amount_minor" bigint, "target_tendered_minor" bigint, "target_remaining_minor" bigint) IS 'Canonical checkout payment settlement. Cash applies only the remaining sale balance and records tender/change separately.';


--
-- Name: ship_stock_transfer("uuid", "uuid", "uuid", "jsonb", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."ship_stock_transfer"("target_organization_id" "uuid", "target_source_store_id" "uuid", "target_destination_store_id" "uuid", "target_lines" "jsonb", "target_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare actor_id uuid; transfer_id uuid; line jsonb; source_level public.inventory_levels%rowtype; line_quantity numeric(14,3);
begin
  if (select auth.uid()) is null or not (select private.has_permission(target_organization_id, 'inventory.manage')) then raise exception 'Inventory permission is required.' using errcode = '42501'; end if;
  if target_source_store_id = target_destination_store_id or target_lines is null or jsonb_typeof(target_lines) <> 'array' or jsonb_array_length(target_lines) not between 1 and 100 then raise exception 'Choose two stores and one to 100 transfer items.' using errcode = '23514'; end if;
  if exists (select 1 from jsonb_array_elements(target_lines) requested(value) where jsonb_typeof(requested.value) <> 'object' or coalesce(requested.value->>'product_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or (requested.value ? 'variant_id' and requested.value->'variant_id' <> 'null'::jsonb and coalesce(requested.value->>'variant_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') or coalesce(requested.value->>'quantity','') !~ '^\d+(\.\d{1,3})?$' or (requested.value->>'quantity')::numeric <= 0) then raise exception 'Transfer lines must contain valid items and positive quantities.' using errcode = '23514'; end if;
  if (select count(*) from jsonb_array_elements(target_lines)) <> (select count(distinct (value->>'product_id') || ':' || coalesce(value->>'variant_id','')) from jsonb_array_elements(target_lines)) then raise exception 'Each transfer item can appear only once.' using errcode = '23514'; end if;
  actor_id := private.inventory_actor(target_organization_id, target_source_store_id);
  if actor_id is null then raise exception 'An assigned employee is required for the source store.' using errcode = '42501'; end if;
  if not exists (select 1 from public.stores store where store.id = target_destination_store_id and store.organization_id = target_organization_id and store.is_active) then raise exception 'Choose an active destination store.' using errcode = '23514'; end if;
  insert into public.stock_transfers (organization_id, source_store_id, destination_store_id, status, note, transferred_by_employee_id)
  values (target_organization_id, target_source_store_id, target_destination_store_id, 'in_transit', nullif(btrim(target_note), ''), actor_id)
  returning id into transfer_id;
  for line in select value from jsonb_array_elements(target_lines) order by value->>'product_id', coalesce(value->>'variant_id','') loop
    line_quantity := (line->>'quantity')::numeric(14,3);
    select * into source_level from public.inventory_levels level where level.organization_id = target_organization_id and level.store_id = target_source_store_id and level.product_id = (line->>'product_id')::uuid and level.variant_id is not distinct from nullif(line->>'variant_id','')::uuid for update;
    if source_level.id is null or source_level.quantity < line_quantity then raise exception 'Source stock is insufficient for this transfer.' using errcode = '23514'; end if;
    if not exists (select 1 from public.inventory_levels level where level.organization_id = target_organization_id and level.store_id = target_destination_store_id and level.product_id = source_level.product_id and level.variant_id is not distinct from source_level.variant_id) then raise exception 'The destination stock projection is not initialized for one transfer item.' using errcode = '23514'; end if;
    insert into public.stock_transfer_lines (organization_id, stock_transfer_id, product_id, variant_id, quantity, unit_cost_minor)
    values (target_organization_id, transfer_id, source_level.product_id, source_level.variant_id, line_quantity, source_level.average_cost_minor);
    perform private.apply_inventory_change_v2(target_organization_id, target_source_store_id, source_level.product_id, source_level.variant_id, -line_quantity, 'TRANSFER_OUT', actor_id, 'Stock transferred out', 'stock_transfer', transfer_id, source_level.average_cost_minor);
  end loop;
  perform private.write_audit_log(target_organization_id, 'STOCK_TRANSFER_SHIPPED', 'inventory.manage', actor_id, null, target_source_store_id, null, null, null, target_note, jsonb_build_object('transfer_id', transfer_id, 'destination_store_id', target_destination_store_id));
  return transfer_id;
end;
$_$;


ALTER FUNCTION "private"."ship_stock_transfer"("target_organization_id" "uuid", "target_source_store_id" "uuid", "target_destination_store_id" "uuid", "target_lines" "jsonb", "target_note" "text") OWNER TO "postgres";

--
-- Name: skip_duplicate_employee_store_assignment(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."skip_duplicate_employee_store_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (
    select 1
    from public.employee_stores employee_store
    where employee_store.employee_id = new.employee_id
      and employee_store.store_id = new.store_id
  ) then
    return null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."skip_duplicate_employee_store_assignment"() OWNER TO "postgres";

--
-- Name: FUNCTION "skip_duplicate_employee_store_assignment"(); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."skip_duplicate_employee_store_assignment"() IS 'Makes repeated employee-store assignments idempotent so automatic organization-manager access coexists with legacy assignment flows.';


--
-- Name: snapshot_sale_item_cost(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."snapshot_sale_item_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare cost_minor bigint;
begin
  select level.average_cost_minor into cost_minor
  from public.inventory_levels level
  join public.products product on product.id = level.product_id and product.organization_id = level.organization_id
  where level.organization_id = new.organization_id
    and level.store_id = (select sale.store_id from public.sales sale where sale.id = new.sale_id and sale.organization_id = new.organization_id)
    and level.product_id = new.product_id
    and level.variant_id is not distinct from new.variant_id;
  if cost_minor is null then
    select coalesce(variant.cost_minor, product.cost_minor, 0) into cost_minor
    from public.products product left join public.product_variants variant on variant.id = new.variant_id and variant.product_id = product.id and variant.organization_id = product.organization_id
    where product.id = new.product_id and product.organization_id = new.organization_id;
  end if;
  new.unit_cost_minor := greatest(coalesce(cost_minor, 0), 0);
  new.cogs_minor := round(new.quantity * new.unit_cost_minor)::bigint;
  return new;
end;
$$;


ALTER FUNCTION "private"."snapshot_sale_item_cost"() OWNER TO "postgres";

--
-- Name: start_stock_request_picking("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."start_stock_request_picking"("target_organization_id" "uuid", "target_stock_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare request_row public.stock_requests%rowtype; actor_id uuid; warehouse_store_id uuid;
begin
  if (select auth.uid()) is null
     or (
       not (select private.has_permission(target_organization_id, 'inventory.manage'))
       and not (select private.has_inventory_capability(target_organization_id, 'inventory.transfer.send'))
     ) then raise exception 'Inventory permission is required.' using errcode = '42501'; end if;
  select * into request_row from public.stock_requests request where request.id = target_stock_request_id and request.organization_id = target_organization_id and request.status = 'approved' for update;
  if request_row.id is null then raise exception 'Only an approved request can be picked.' using errcode = '23514'; end if;
  select warehouse.store_id into warehouse_store_id from public.supply_chain_warehouses warehouse where warehouse.id = request_row.source_warehouse_id and warehouse.organization_id = target_organization_id and warehouse.is_active;
  actor_id := private.inventory_actor(target_organization_id, warehouse_store_id);
  if actor_id is null then raise exception 'An assigned employee is required for the source warehouse.' using errcode = '42501'; end if;
  update public.stock_request_lines set picked_quantity = approved_quantity where stock_request_id = request_row.id;
  update public.stock_requests set status = 'picking', picked_by_employee_id = actor_id, picked_at = now() where id = request_row.id;
  perform private.write_audit_log(target_organization_id, 'STOCK_REQUEST_PICKING_STARTED', 'inventory.manage', actor_id, null, warehouse_store_id, null, null, null, null, jsonb_build_object('stock_request_id', request_row.id));
end;
$$;


ALTER FUNCTION "private"."start_stock_request_picking"("target_organization_id" "uuid", "target_stock_request_id" "uuid") OWNER TO "postgres";

--
-- Name: submit_inventory_count_for_review("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."submit_inventory_count_for_review"("target_organization_id" "uuid", "target_inventory_count_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  count_document public.inventory_counts%rowtype;
  actor_id uuid;
begin
  select count_row.* into count_document from public.inventory_counts count_row
  where count_row.id = target_inventory_count_id and count_row.organization_id = target_organization_id
  for update;
  if count_document.id is null or count_document.status not in ('draft', 'in_progress') then
    raise exception 'Only an open count with saved lines can be submitted for review.' using errcode = '23514';
  end if;
  actor_id := private.inventory_count_actor(target_organization_id, count_document.store_id, array['inventory.count.finalize']::text[]);
  if not exists (
    select 1 from public.inventory_count_lines line
    where line.organization_id = target_organization_id and line.inventory_count_id = target_inventory_count_id
  ) or exists (
    select 1 from public.inventory_count_lines line
    where line.organization_id = target_organization_id
      and line.inventory_count_id = target_inventory_count_id
      and line.counted_quantity is null
  ) then
    raise exception 'Count every prepared item before submitting for review.' using errcode = '23514';
  end if;
  update public.inventory_counts set status = 'ready_for_review', updated_at = now() where id = target_inventory_count_id;
  perform private.write_audit_log(
    target_organization_id, 'INVENTORY_COUNT_READY_FOR_REVIEW', 'inventory.count', actor_id,
    null, count_document.store_id, null, null, null, count_document.note,
    jsonb_build_object('inventory_count_id', count_document.id, 'count_number', count_document.count_number)
  );
end;
$$;


ALTER FUNCTION "private"."submit_inventory_count_for_review"("target_organization_id" "uuid", "target_inventory_count_id" "uuid") OWNER TO "postgres";

--
-- Name: sync_auth_user_profile(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."sync_auth_user_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.profiles (id, full_name, email)
  values (
    new.id,
    left(coalesce(new.raw_user_meta_data ->> 'full_name', ''), 160),
    lower(coalesce(new.email, ''))
  )
  on conflict (id) do update
  set
    full_name = case
      when coalesce(excluded.full_name, '') = '' then public.profiles.full_name
      else excluded.full_name
    end,
    email = excluded.email,
    updated_at = now();

  return new;
end;
$$;


ALTER FUNCTION "private"."sync_auth_user_profile"() OWNER TO "postgres";

--
-- Name: sync_organization_manager_store_access("uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."sync_organization_manager_store_access"("target_organization_id" "uuid", "target_employee_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.employee_stores (organization_id, employee_id, store_id)
  select
    employee.organization_id,
    employee.id,
    store.id
  from public.employees employee
  join public.stores store
    on store.organization_id = employee.organization_id
   and store.is_active
  where employee.organization_id = target_organization_id
    and employee.status = 'active'
    and (target_employee_id is null or employee.id = target_employee_id)
    and exists (
      select 1
      from public.employee_roles employee_role
      join public.role_permissions role_permission
        on role_permission.organization_id = employee_role.organization_id
       and role_permission.role_id = employee_role.role_id
      where employee_role.organization_id = employee.organization_id
        and employee_role.employee_id = employee.id
        and role_permission.permission_code = 'organization.manage'
    )
  on conflict (employee_id, store_id) do nothing;
end;
$$;


ALTER FUNCTION "private"."sync_organization_manager_store_access"("target_organization_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "sync_organization_manager_store_access"("target_organization_id" "uuid", "target_employee_id" "uuid"); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."sync_organization_manager_store_access"("target_organization_id" "uuid", "target_employee_id" "uuid") IS 'Internal capability-based assignment of every active store to active employees holding organization.manage.';


--
-- Name: sync_organization_manager_store_access_from_employee(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."sync_organization_manager_store_access_from_employee"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status = 'active' then
    perform private.sync_organization_manager_store_access(new.organization_id, new.id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."sync_organization_manager_store_access_from_employee"() OWNER TO "postgres";

--
-- Name: sync_organization_manager_store_access_from_employee_role(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."sync_organization_manager_store_access_from_employee_role"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- bootstrap_organization explicitly creates the first employee-store row
  -- after assigning the initial Owner role. Waiting until a business has a
  -- second active store avoids racing that bootstrap insert while still giving
  -- newly assigned organization managers full multi-store access.
  if (
    select count(*)
    from public.stores store
    where store.organization_id = new.organization_id
      and store.is_active
  ) > 1 then
    perform private.sync_organization_manager_store_access(new.organization_id, new.employee_id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."sync_organization_manager_store_access_from_employee_role"() OWNER TO "postgres";

--
-- Name: sync_organization_manager_store_access_from_role_permission(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."sync_organization_manager_store_access_from_role_permission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.permission_code = 'organization.manage' then
    perform private.sync_organization_manager_store_access(new.organization_id);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."sync_organization_manager_store_access_from_role_permission"() OWNER TO "postgres";

