--
-- Name: update_approval_rule("uuid", "text", "text", bigint, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_approval_rule"("target_organization_id" "uuid", "target_operation_code" "text", "target_decision" "text", "target_amount_threshold_minor" bigint, "target_is_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
begin
  actor_employee_id := private.current_employee_id(target_organization_id);
  if actor_employee_id is null
    or not private.has_permission(target_organization_id, 'approvals.manage') then
    raise exception 'Approval-rule management permission is required.' using errcode = '42501';
  end if;

  if private.approval_operation_permission(target_operation_code) is null
    or target_decision not in ('ALLOWED', 'DENIED', 'APPROVAL_REQUIRED')
    or (target_amount_threshold_minor is not null and target_amount_threshold_minor < 0) then
    raise exception 'Approval-rule details are invalid.' using errcode = '23514';
  end if;

  insert into public.approval_rules (
    organization_id,
    operation_code,
    decision,
    amount_threshold_minor,
    is_enabled
  )
  values (
    target_organization_id,
    target_operation_code,
    target_decision,
    target_amount_threshold_minor,
    coalesce(target_is_enabled, true)
  )
  on conflict (organization_id, operation_code) do update
  set
    decision = excluded.decision,
    amount_threshold_minor = excluded.amount_threshold_minor,
    is_enabled = excluded.is_enabled,
    updated_at = now();

  perform private.write_audit_log(
    target_organization_id,
    'APPROVAL_RULE_UPDATED',
    target_operation_code,
    actor_employee_id,
    null,
    null,
    null,
    null,
    target_amount_threshold_minor,
    null,
    jsonb_build_object('decision', target_decision, 'is_enabled', coalesce(target_is_enabled, true))
  );
end;
$$;


ALTER FUNCTION "private"."update_approval_rule"("target_organization_id" "uuid", "target_operation_code" "text", "target_decision" "text", "target_amount_threshold_minor" bigint, "target_is_enabled" boolean) OWNER TO "postgres";

--
-- Name: update_business_profile_features("uuid", "text", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_business_profile_features"("target_organization_id" "uuid", "target_business_type" "text", "target_feature_settings" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_business_type text := lower(btrim(coalesce(target_business_type, '')));
  actor_employee_id uuid;
  previous_business_type text;
  previous_feature_settings jsonb;
  current_feature_settings jsonb;
begin
  if (select auth.uid()) is null
     or not (select private.has_permission(target_organization_id, 'settings.manage')) then
    raise exception 'Business profile permission is required.' using errcode = '42501';
  end if;

  if normalized_business_type not in (
    'retail', 'grocery', 'convenience_store', 'restaurant_cafe',
    'bar', 'wholesale', 'service', 'other'
  ) then
    raise exception 'Choose a supported business type.' using errcode = '22023';
  end if;

  if target_feature_settings is null or jsonb_typeof(target_feature_settings) <> 'object' then
    raise exception 'Feature settings must be an object.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_each(target_feature_settings) as setting(feature_key, feature_value)
    where setting.feature_key not in (
      'inventory', 'shifts', 'time_clock', 'open_tickets', 'dining',
      'modifiers', 'loyalty', 'customer_display', 'kitchen_display',
      'purchase_orders', 'transfers', 'production', 'weighted_products',
      'multi_store'
    )
      or jsonb_typeof(setting.feature_value) <> 'boolean'
  ) then
    raise exception 'Feature settings contain an unsupported value.' using errcode = '22023';
  end if;

  select organization.business_type
  into previous_business_type
  from public.organizations organization
  where organization.id = target_organization_id
  for update;

  if previous_business_type is null then
    raise exception 'The organization could not be found.' using errcode = '23514';
  end if;

  select coalesce(jsonb_object_agg(feature.feature_key, feature.is_enabled), '{}'::jsonb)
  into previous_feature_settings
  from public.organization_features feature
  where feature.organization_id = target_organization_id;

  select private.current_employee_id(target_organization_id)
  into actor_employee_id;

  if actor_employee_id is null then
    raise exception 'An active employee is required.' using errcode = '42501';
  end if;

  update public.organizations
  set business_type = normalized_business_type
  where id = target_organization_id;

  insert into public.organization_features (
    organization_id,
    feature_key,
    is_enabled,
    updated_by_employee_id
  )
  select
    target_organization_id,
    recommendation.feature_key,
    case
      when target_feature_settings ? recommendation.feature_key
        then (target_feature_settings ->> recommendation.feature_key)::boolean
      else coalesce(current_feature.is_enabled, recommendation.is_enabled)
    end,
    actor_employee_id
  from private.business_feature_recommendations(normalized_business_type) recommendation
  left join public.organization_features current_feature
    on current_feature.organization_id = target_organization_id
   and current_feature.feature_key = recommendation.feature_key
  on conflict (organization_id, feature_key) do update
  set is_enabled = excluded.is_enabled,
      updated_by_employee_id = excluded.updated_by_employee_id;

  select coalesce(jsonb_object_agg(feature.feature_key, feature.is_enabled), '{}'::jsonb)
  into current_feature_settings
  from public.organization_features feature
  where feature.organization_id = target_organization_id;

  perform private.write_audit_log(
    target_organization_id,
    'BUSINESS_PROFILE_UPDATED',
    'settings.manage',
    actor_employee_id,
    null,
    null,
    null,
    null,
    null,
    null,
    jsonb_build_object(
      'previous_business_type', previous_business_type,
      'business_type', normalized_business_type,
      'previous_feature_settings', previous_feature_settings,
      'feature_settings', current_feature_settings
    )
  );

  return current_feature_settings;
end;
$$;


ALTER FUNCTION "private"."update_business_profile_features"("target_organization_id" "uuid", "target_business_type" "text", "target_feature_settings" "jsonb") OWNER TO "postgres";

--
-- Name: update_catalog_product_v2("uuid", "uuid", "text", "text", "uuid", "text", "text", bigint, bigint, boolean, "text", "text", boolean, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_catalog_product_v2"("target_organization_id" "uuid", "target_product_id" "uuid", "target_name" "text", "target_description" "text", "target_category_id" "uuid", "target_sku" "text", "target_barcode" "text", "target_price_minor" bigint, "target_cost_minor" bigint, "target_track_inventory" boolean, "target_unit" "text", "target_image_url" "text", "target_is_variable_price" boolean, "target_allow_fractional_quantity" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing_product_type text;
  existing_cost_minor bigint;
  existing_unit text;
  effective_cost_minor bigint;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'products.manage')) then
    raise exception 'Product management permission is required.' using errcode = '42501';
  end if;

  select product.product_type, product.cost_minor, product.unit
  into existing_product_type, existing_cost_minor, existing_unit
  from public.products product
  where product.id = target_product_id
    and product.organization_id = target_organization_id;

  if not found then
    raise exception 'The product could not be found.' using errcode = '23503';
  end if;

  if lower(btrim(target_unit)) is distinct from existing_unit then
    raise exception 'The base unit is fixed after product creation to protect inventory and conversion history. Create a new product to use a different unit.' using errcode = '23514';
  end if;

  if target_category_id is not null and not exists (
    select 1
    from public.categories category
    where category.id = target_category_id
      and category.organization_id = target_organization_id
      and not category.is_archived
  ) then
    raise exception 'Select an active category in this organization.' using errcode = '23503';
  end if;

  if existing_product_type <> 'variable'
    and target_cost_minor is not null
    and target_cost_minor is distinct from existing_cost_minor
    and not (select private.has_permission(target_organization_id, 'products.view_cost')) then
    raise exception 'Product cost permission is required.' using errcode = '42501';
  end if;

  effective_cost_minor := coalesce(target_cost_minor, existing_cost_minor);

  if existing_product_type = 'variable' then
    update public.products
    set name = target_name,
        description = nullif(target_description, ''),
        category_id = target_category_id,
        track_inventory = target_track_inventory,
        unit = lower(target_unit),
        image_url = nullif(btrim(target_image_url), ''),
        is_variable_price = false,
        allow_fractional_quantity = target_allow_fractional_quantity
    where id = target_product_id
      and organization_id = target_organization_id;
  else
    update public.products
    set name = target_name,
        description = nullif(target_description, ''),
        category_id = target_category_id,
        sku = nullif(target_sku, ''),
        barcode = nullif(target_barcode, ''),
        price_minor = target_price_minor,
        cost_minor = effective_cost_minor,
        track_inventory = target_track_inventory,
        unit = lower(target_unit),
        image_url = nullif(btrim(target_image_url), ''),
        is_variable_price = target_is_variable_price,
        allow_fractional_quantity = target_allow_fractional_quantity
    where id = target_product_id
      and organization_id = target_organization_id;
  end if;

  return existing_product_type;
end;
$$;


ALTER FUNCTION "private"."update_catalog_product_v2"("target_organization_id" "uuid", "target_product_id" "uuid", "target_name" "text", "target_description" "text", "target_category_id" "uuid", "target_sku" "text", "target_barcode" "text", "target_price_minor" bigint, "target_cost_minor" bigint, "target_track_inventory" boolean, "target_unit" "text", "target_image_url" "text", "target_is_variable_price" boolean, "target_allow_fractional_quantity" boolean) OWNER TO "postgres";

--
-- Name: update_employee_assignments_unscoped("uuid", "uuid", "text", "text", "uuid"[], "uuid"[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_employee_assignments_unscoped"("target_organization_id" "uuid", "target_employee_id" "uuid", "target_job_title" "text", "target_status" "text", "target_role_ids" "uuid"[], "target_store_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_job_title text := nullif(btrim(target_job_title), '');
  normalized_status text := lower(btrim(target_status));
  actor_employee_id uuid;
  target_profile_id uuid;
  current_status text;
  current_role_ids uuid[];
  requested_role_ids uuid[];
  effective_store_ids uuid[];
  valid_role_count integer;
  valid_store_count integer;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'employees.manage')) then
    raise exception 'Employee management permission is required.' using errcode = '42501';
  end if;

  if normalized_status not in ('active', 'inactive', 'suspended') then
    raise exception 'Choose an active, inactive, or suspended employee status.' using errcode = '22023';
  end if;

  if normalized_job_title is not null and char_length(normalized_job_title) > 120 then
    raise exception 'Job title must contain at most 120 characters.' using errcode = '22023';
  end if;

  if coalesce(cardinality(target_role_ids), 0) = 0
    or coalesce(cardinality(target_store_ids), 0) = 0 then
    raise exception 'Assign at least one role and one active store.' using errcode = '22023';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active';

  select employee.profile_id, employee.status
  into target_profile_id, current_status
  from public.employees employee
  where employee.id = target_employee_id
    and employee.organization_id = target_organization_id;

  if target_profile_id is null then
    raise exception 'Select an employee in this organization.' using errcode = '23503';
  end if;

  select coalesce(array_agg(employee_role.role_id order by employee_role.role_id), '{}'::uuid[])
  into current_role_ids
  from public.employee_roles employee_role
  where employee_role.organization_id = target_organization_id
    and employee_role.employee_id = target_employee_id;

  select coalesce(array_agg(distinct requested_role_id order by requested_role_id), '{}'::uuid[])
  into requested_role_ids
  from unnest(target_role_ids) as requested_role_id;

  if target_profile_id = (select auth.uid()) then
    if not (select private.has_permission(target_organization_id, 'organization.manage')) then
      raise exception 'Only organization managers can update their own employee record.' using errcode = '42501';
    end if;

    if normalized_status is distinct from current_status
      or requested_role_ids is distinct from current_role_ids then
      raise exception 'You cannot change your own role assignments or status.' using errcode = '42501';
    end if;
  end if;

  select count(*)
  into valid_role_count
  from public.roles role
  where role.organization_id = target_organization_id
    and role.id = any(target_role_ids);

  if valid_role_count <> cardinality(array(select distinct unnest(target_role_ids))) then
    raise exception 'Every assigned role must belong to this organization.' using errcode = '23503';
  end if;

  if exists (
    select 1
    from unnest(target_role_ids) as requested_role_id
    where not (select private.can_grant_role(target_organization_id, requested_role_id))
  ) then
    raise exception 'You cannot assign a role containing permissions you do not hold.' using errcode = '42501';
  end if;

  select count(*)
  into valid_store_count
  from public.stores store
  where store.organization_id = target_organization_id
    and store.id = any(target_store_ids)
    and store.is_active;

  if valid_store_count <> cardinality(array(select distinct unnest(target_store_ids))) then
    raise exception 'Every assigned store must be active and belong to this organization.' using errcode = '23503';
  end if;

  update public.employees
  set
    job_title = normalized_job_title,
    status = normalized_status
  where id = target_employee_id
    and organization_id = target_organization_id;

  delete from public.employee_roles
  where employee_id = target_employee_id
    and organization_id = target_organization_id;

  insert into public.employee_roles (organization_id, employee_id, role_id)
  select target_organization_id, target_employee_id, distinct_role_id
  from unnest(target_role_ids) as distinct_role_id
  on conflict do nothing;

  delete from public.employee_stores
  where employee_id = target_employee_id
    and organization_id = target_organization_id;

  insert into public.employee_stores (organization_id, employee_id, store_id)
  select target_organization_id, target_employee_id, distinct_store_id
  from unnest(target_store_ids) as distinct_store_id
  on conflict do nothing;

  perform private.sync_organization_manager_store_access(
    target_organization_id,
    target_employee_id
  );

  select coalesce(array_agg(employee_store.store_id order by employee_store.store_id), '{}'::uuid[])
  into effective_store_ids
  from public.employee_stores employee_store
  where employee_store.organization_id = target_organization_id
    and employee_store.employee_id = target_employee_id;

  perform private.write_audit_log(
    target_organization_id,
    'EMPLOYEE_ASSIGNMENTS_UPDATED',
    'employees.manage',
    actor_employee_id,
    target_employee_id,
    null,
    null,
    null,
    null,
    null,
    jsonb_build_object(
      'status', normalized_status,
      'role_ids', requested_role_ids,
      'store_ids', effective_store_ids,
      'requested_store_ids', target_store_ids
    )
  );

  return target_employee_id;
end;
$$;


ALTER FUNCTION "private"."update_employee_assignments_unscoped"("target_organization_id" "uuid", "target_employee_id" "uuid", "target_job_title" "text", "target_status" "text", "target_role_ids" "uuid"[], "target_store_ids" "uuid"[]) OWNER TO "postgres";

--
-- Name: FUNCTION "update_employee_assignments_unscoped"("target_organization_id" "uuid", "target_employee_id" "uuid", "target_job_title" "text", "target_status" "text", "target_role_ids" "uuid"[], "target_store_ids" "uuid"[]); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."update_employee_assignments_unscoped"("target_organization_id" "uuid", "target_employee_id" "uuid", "target_job_title" "text", "target_status" "text", "target_role_ids" "uuid"[], "target_store_ids" "uuid"[]) IS 'Atomically updates employee assignments, permits safe organization-manager self edits, and preserves organization-wide store access.';


--
-- Name: update_employee_profile("uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_employee_profile"("target_organization_id" "uuid", "target_employee_id" "uuid", "target_full_name" "text", "target_phone" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
  target_profile_id uuid;
  normalized_name text := btrim(coalesce(target_full_name, ''));
  normalized_phone text := nullif(btrim(coalesce(target_phone, '')), '');
begin
  actor_id := private.require_employee_manager_target(target_organization_id, target_employee_id);
  if char_length(normalized_name) not between 2 and 160
    or (normalized_phone is not null and char_length(normalized_phone) > 40) then
    raise exception 'Check the employee name and phone number.' using errcode = '23514';
  end if;
  select employee.profile_id into target_profile_id
  from public.employees employee
  where employee.id = target_employee_id and employee.organization_id = target_organization_id;
  update public.profiles set full_name = normalized_name, phone = normalized_phone
  where id = target_profile_id;
  perform private.write_audit_log(
    target_organization_id, 'EMPLOYEE_PROFILE_UPDATED', 'employees.manage', actor_id,
    target_employee_id, null, null, null, null, null, '{}'::jsonb
  );
end;
$$;


ALTER FUNCTION "private"."update_employee_profile"("target_organization_id" "uuid", "target_employee_id" "uuid", "target_full_name" "text", "target_phone" "text") OWNER TO "postgres";

--
-- Name: update_inventory_policy("uuid", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_inventory_policy"("target_organization_id" "uuid", "target_store_id" "uuid", "target_negative_stock_policy" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'inventory.manage')) then
    raise exception 'Inventory permission is required.' using errcode = '42501';
  end if;

  if target_negative_stock_policy not in ('allow', 'warn', 'block')
    or not exists (
      select 1
      from public.stores store
      where store.id = target_store_id
        and store.organization_id = target_organization_id
        and store.is_active
    ) then
    raise exception 'Choose an active store and a valid negative-stock policy.' using errcode = '23514';
  end if;

  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then
    raise exception 'You do not have access to manage this store.' using errcode = '42501';
  end if;

  insert into public.inventory_policies (
    organization_id,
    store_id,
    negative_stock_policy,
    updated_by_employee_id
  )
  values (
    target_organization_id,
    target_store_id,
    target_negative_stock_policy,
    actor_id
  )
  on conflict (organization_id, store_id) do update
    set negative_stock_policy = excluded.negative_stock_policy,
        updated_by_employee_id = excluded.updated_by_employee_id,
        updated_at = now();

  perform private.write_audit_log(
    target_organization_id,
    'INVENTORY_POLICY_UPDATED',
    'inventory.manage',
    actor_id,
    null,
    target_store_id,
    null,
    null,
    null,
    null,
    jsonb_build_object(
      'negative_stock_policy', target_negative_stock_policy,
      'scope', 'store_override'
    )
  );
end;
$$;


ALTER FUNCTION "private"."update_inventory_policy"("target_organization_id" "uuid", "target_store_id" "uuid", "target_negative_stock_policy" "text") OWNER TO "postgres";

--
-- Name: update_kitchen_order_item_status("uuid", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_kitchen_order_item_status"("target_organization_id" "uuid", "target_kitchen_order_item_id" "uuid", "target_status" "text") RETURNS TABLE("order_status" "text", "item_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_status text;
  resolved_order_id uuid;
  resolved_store_id uuid;
  resolved_order_status text;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'kitchen.manage')) then
    raise exception 'Kitchen order management access is required.' using errcode = '42501';
  end if;

  if target_status not in ('PREPARING', 'READY', 'COMPLETED') then
    raise exception 'Choose a valid next kitchen item status.' using errcode = '22023';
  end if;

  select kitchen_item.status, kitchen_item.kitchen_order_id, kitchen_order.store_id
  into current_status, resolved_order_id, resolved_store_id
  from public.kitchen_order_items kitchen_item
  join public.kitchen_orders kitchen_order
    on kitchen_order.id = kitchen_item.kitchen_order_id
   and kitchen_order.organization_id = kitchen_item.organization_id
  where kitchen_item.id = target_kitchen_order_item_id
    and kitchen_item.organization_id = target_organization_id
  for update of kitchen_item, kitchen_order;

  if resolved_order_id is null then
    raise exception 'This kitchen item is no longer available.' using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from public.employees employee
    join public.employee_stores employee_store
      on employee_store.employee_id = employee.id
     and employee_store.organization_id = employee.organization_id
    where employee.organization_id = target_organization_id
      and employee.profile_id = (select auth.uid())
      and employee.status = 'active'
      and employee_store.store_id = resolved_store_id
  ) then
    raise exception 'You are not assigned to this kitchen order store.' using errcode = '42501';
  end if;

  if not (
    (current_status = 'NEW' and target_status = 'PREPARING')
    or (current_status = 'PREPARING' and target_status = 'READY')
    or (current_status = 'READY' and target_status = 'COMPLETED')
  ) then
    raise exception 'Kitchen items must be advanced one status at a time.' using errcode = '23514';
  end if;

  update public.kitchen_order_items kitchen_item
  set
    status = target_status,
    started_at = case when target_status = 'PREPARING' then now() else kitchen_item.started_at end,
    ready_at = case when target_status = 'READY' then now() else kitchen_item.ready_at end,
    completed_at = case when target_status = 'COMPLETED' then now() else kitchen_item.completed_at end
  where kitchen_item.id = target_kitchen_order_item_id
    and kitchen_item.organization_id = target_organization_id;

  select case
    when bool_and(kitchen_item.status = 'COMPLETED') then 'COMPLETED'
    when bool_and(kitchen_item.status in ('READY', 'COMPLETED')) then 'READY'
    when bool_or(kitchen_item.status in ('PREPARING', 'READY', 'COMPLETED')) then 'PREPARING'
    else 'NEW'
  end
  into resolved_order_status
  from public.kitchen_order_items kitchen_item
  where kitchen_item.kitchen_order_id = resolved_order_id
    and kitchen_item.organization_id = target_organization_id;

  update public.kitchen_orders kitchen_order
  set
    status = resolved_order_status,
    started_at = case
      when resolved_order_status = 'NEW' then null
      else coalesce(kitchen_order.started_at, now())
    end,
    ready_at = case
      when resolved_order_status in ('READY', 'COMPLETED') then coalesce(kitchen_order.ready_at, now())
      else null
    end,
    completed_at = case
      when resolved_order_status = 'COMPLETED' then coalesce(kitchen_order.completed_at, now())
      else null
    end
  where kitchen_order.id = resolved_order_id
    and kitchen_order.organization_id = target_organization_id;

  return query select resolved_order_status, target_status;
end;
$$;


ALTER FUNCTION "private"."update_kitchen_order_item_status"("target_organization_id" "uuid", "target_kitchen_order_item_id" "uuid", "target_status" "text") OWNER TO "postgres";

--
-- Name: update_kitchen_order_status("uuid", "uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_kitchen_order_status"("target_organization_id" "uuid", "target_kitchen_order_id" "uuid", "target_status" "text") RETURNS TABLE("status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_status text;
  resolved_store_id uuid;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'kitchen.manage')) then
    raise exception 'Kitchen order management access is required.' using errcode = '42501';
  end if;

  if target_status not in ('PREPARING', 'READY', 'COMPLETED') then
    raise exception 'Choose a valid next kitchen status.' using errcode = '22023';
  end if;

  select kitchen_order.status, kitchen_order.store_id
  into current_status, resolved_store_id
  from public.kitchen_orders kitchen_order
  where kitchen_order.id = target_kitchen_order_id
    and kitchen_order.organization_id = target_organization_id
  for update;

  if current_status is null then
    raise exception 'This kitchen order is no longer available.' using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from public.employees employee
    join public.employee_stores employee_store
      on employee_store.employee_id = employee.id
     and employee_store.organization_id = employee.organization_id
    where employee.organization_id = target_organization_id
      and employee.profile_id = (select auth.uid())
      and employee.status = 'active'
      and employee_store.store_id = resolved_store_id
  ) then
    raise exception 'You are not assigned to this kitchen order store.' using errcode = '42501';
  end if;

  if not (
    (current_status = 'NEW' and target_status = 'PREPARING')
    or (current_status = 'PREPARING' and target_status = 'READY')
    or (current_status = 'READY' and target_status = 'COMPLETED')
  ) then
    raise exception 'Kitchen orders must be advanced one status at a time.' using errcode = '23514';
  end if;

  update public.kitchen_order_items kitchen_item
  set
    status = target_status,
    started_at = case when target_status = 'PREPARING' then now() else kitchen_item.started_at end,
    ready_at = case when target_status = 'READY' then now() else kitchen_item.ready_at end,
    completed_at = case when target_status = 'COMPLETED' then now() else kitchen_item.completed_at end
  where kitchen_item.kitchen_order_id = target_kitchen_order_id
    and kitchen_item.organization_id = target_organization_id;

  return query
  update public.kitchen_orders kitchen_order
  set
    status = target_status,
    started_at = case when target_status = 'PREPARING' then now() else kitchen_order.started_at end,
    ready_at = case when target_status = 'READY' then now() else kitchen_order.ready_at end,
    completed_at = case when target_status = 'COMPLETED' then now() else kitchen_order.completed_at end
  where kitchen_order.id = target_kitchen_order_id
    and kitchen_order.organization_id = target_organization_id
  returning kitchen_order.status;
end;
$$;


ALTER FUNCTION "private"."update_kitchen_order_status"("target_organization_id" "uuid", "target_kitchen_order_id" "uuid", "target_status" "text") OWNER TO "postgres";

--
-- Name: update_organization_inventory_policy("uuid", "text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_organization_inventory_policy"("target_organization_id" "uuid", "target_negative_stock_policy" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid;
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'inventory.manage'))
    or not (select private.has_permission(target_organization_id, 'stores.manage')) then
    raise exception 'Organization-wide inventory policy permission is required.' using errcode = '42501';
  end if;

  if target_negative_stock_policy not in ('allow', 'warn', 'block')
    or not exists (
      select 1
      from public.organizations organization
      where organization.id = target_organization_id
    ) then
    raise exception 'Choose a valid organization and negative-stock policy.' using errcode = '23514';
  end if;

  actor_id := private.inventory_organization_actor(target_organization_id);
  if actor_id is null then
    raise exception 'An active employee is required for this organization.' using errcode = '42501';
  end if;

  insert into public.inventory_policy_defaults (
    organization_id,
    negative_stock_policy,
    updated_by_employee_id
  )
  values (
    target_organization_id,
    target_negative_stock_policy,
    actor_id
  )
  on conflict (organization_id) do update
    set negative_stock_policy = excluded.negative_stock_policy,
        updated_by_employee_id = excluded.updated_by_employee_id,
        updated_at = now();

  perform private.write_audit_log(
    target_organization_id,
    'INVENTORY_POLICY_DEFAULT_UPDATED',
    'inventory.manage',
    actor_id,
    null,
    null,
    null,
    null,
    null,
    null,
    jsonb_build_object(
      'negative_stock_policy', target_negative_stock_policy,
      'scope', 'organization_default'
    )
  );
end;
$$;


ALTER FUNCTION "private"."update_organization_inventory_policy"("target_organization_id" "uuid", "target_negative_stock_policy" "text") OWNER TO "postgres";

--
-- Name: update_shift_cash_close_setting("uuid", boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_shift_cash_close_setting"("target_organization_id" "uuid", "target_show_expected_cash_before_close" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if target_organization_id is null or target_show_expected_cash_before_close is null then
    raise exception 'Choose a cash-close visibility setting.' using errcode = '23514';
  end if;

  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'settings.manage')) then
    raise exception 'Settings permission is required.' using errcode = '42501';
  end if;

  update public.organizations organization
  set show_expected_cash_before_close = target_show_expected_cash_before_close
  where organization.id = target_organization_id;

  if not found then
    raise exception 'The organization was not found.' using errcode = 'P0002';
  end if;

  return target_show_expected_cash_before_close;
end;
$$;


ALTER FUNCTION "private"."update_shift_cash_close_setting"("target_organization_id" "uuid", "target_show_expected_cash_before_close" boolean) OWNER TO "postgres";

--
-- Name: update_supplier_lead_time("uuid", "uuid", integer); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."update_supplier_lead_time"("target_organization_id" "uuid", "target_supplier_id" "uuid", "target_lead_time_days" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid;
begin
  if (select auth.uid()) is null or not (select private.has_permission(target_organization_id, 'inventory.manage')) then raise exception 'Inventory permission is required.' using errcode = '42501'; end if;
  if target_lead_time_days is null or target_lead_time_days not between 0 and 365 then raise exception 'Supplier lead time must be between zero and 365 days.' using errcode = '23514'; end if;
  if not exists (select 1 from public.suppliers supplier where supplier.id = target_supplier_id and supplier.organization_id = target_organization_id) then raise exception 'Choose a supplier in this organization.' using errcode = '23514'; end if;
  select employee.id into actor_id from public.employees employee where employee.organization_id = target_organization_id and employee.profile_id = (select auth.uid()) and employee.status = 'active' order by employee.created_at limit 1;
  if actor_id is null then raise exception 'An active employee record is required.' using errcode = '42501'; end if;
  update public.suppliers set lead_time_days = target_lead_time_days where id = target_supplier_id and organization_id = target_organization_id;
  perform private.write_audit_log(target_organization_id, 'SUPPLIER_LEAD_TIME_UPDATED', 'inventory.manage', actor_id, null, null, null, null, null, null, jsonb_build_object('supplier_id', target_supplier_id, 'lead_time_days', target_lead_time_days));
end;
$$;


ALTER FUNCTION "private"."update_supplier_lead_time"("target_organization_id" "uuid", "target_supplier_id" "uuid", "target_lead_time_days" integer) OWNER TO "postgres";

--
-- Name: upsert_inventory_replenishment_rule("uuid", "uuid", "uuid", "uuid", "uuid", numeric, numeric); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."upsert_inventory_replenishment_rule"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_preferred_warehouse_id" "uuid", "target_reorder_point" numeric, "target_target_stock" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor_id uuid; rule_id uuid; warehouse_store_id uuid;
begin
  if (select auth.uid()) is null or not (select private.has_permission(target_organization_id, 'inventory.manage')) then raise exception 'Inventory permission is required.' using errcode = '42501'; end if;
  if target_reorder_point is null or target_target_stock is null or target_reorder_point < 0 or target_target_stock <= 0 or target_target_stock < target_reorder_point or target_reorder_point <> round(target_reorder_point, 3) or target_target_stock <> round(target_target_stock, 3) then raise exception 'Reorder point and target stock must be valid quantities.' using errcode = '23514'; end if;
  actor_id := private.inventory_actor(target_organization_id, target_store_id);
  if actor_id is null then raise exception 'An assigned employee is required for the requesting store.' using errcode = '42501'; end if;
  if not exists (select 1 from public.inventory_levels level where level.organization_id = target_organization_id and level.store_id = target_store_id and level.product_id = target_product_id and level.variant_id is not distinct from target_variant_id) then raise exception 'Initialize the destination stock projection before setting a replenishment rule.' using errcode = '23514'; end if;
  if not exists (select 1 from public.products product left join public.product_variants variant on variant.id = target_variant_id and variant.product_id = product.id and variant.organization_id = product.organization_id where product.id = target_product_id and product.organization_id = target_organization_id and product.status = 'active' and product.track_inventory and (target_variant_id is null or variant.id is not null)) then raise exception 'Choose an active tracked saleable item.' using errcode = '23514'; end if;
  if target_preferred_warehouse_id is not null then
    select warehouse.store_id into warehouse_store_id from public.supply_chain_warehouses warehouse where warehouse.id = target_preferred_warehouse_id and warehouse.organization_id = target_organization_id and warehouse.is_active;
    if warehouse_store_id is null or warehouse_store_id = target_store_id then raise exception 'Choose an active warehouse at a different stock location.' using errcode = '23514'; end if;
  end if;
  insert into public.inventory_replenishment_rules (organization_id, store_id, product_id, variant_id, preferred_warehouse_id, reorder_point, target_stock, updated_by_employee_id)
  values (target_organization_id, target_store_id, target_product_id, target_variant_id, target_preferred_warehouse_id, target_reorder_point, target_target_stock, actor_id)
  on conflict (organization_id, store_id, product_id, variant_id) do update set preferred_warehouse_id = excluded.preferred_warehouse_id, reorder_point = excluded.reorder_point, target_stock = excluded.target_stock, updated_by_employee_id = excluded.updated_by_employee_id, updated_at = now()
  returning id into rule_id;
  perform private.write_audit_log(target_organization_id, 'INVENTORY_REPLENISHMENT_RULE_SAVED', 'inventory.manage', actor_id, null, target_store_id, null, null, null, null, jsonb_build_object('rule_id', rule_id, 'product_id', target_product_id, 'variant_id', target_variant_id, 'reorder_point', target_reorder_point, 'target_stock', target_target_stock));
  return rule_id;
end;
$$;


ALTER FUNCTION "private"."upsert_inventory_replenishment_rule"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_preferred_warehouse_id" "uuid", "target_reorder_point" numeric, "target_target_stock" numeric) OWNER TO "postgres";

--
-- Name: valid_receipt_email("text"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."valid_receipt_email"("target_email" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select target_email is not null
    and char_length(target_email) between 3 and 320
    and position('@' in target_email) > 1
    and char_length(replace(target_email, '@', '')) = char_length(target_email) - 1
    and position('.' in split_part(target_email, '@', 2)) > 1
    and target_email !~ '[[:space:]]'
$$;


ALTER FUNCTION "private"."valid_receipt_email"("target_email" "text") OWNER TO "postgres";

--
-- Name: validate_advanced_cart("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."validate_advanced_cart"("target_organization_id" "uuid", "target_store_id" "uuid", "target_cart" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_items jsonb;
begin
  if target_cart is null or jsonb_typeof(target_cart) <> 'array'
    or jsonb_array_length(target_cart) not between 1 and 100 then
    raise exception 'An open ticket must contain between 1 and 100 items.' using errcode = '23514';
  end if;

  select jsonb_agg(jsonb_build_object(
    'product_id', line.value -> 'product_id',
    'variant_id', coalesce(line.value -> 'variant_id', 'null'::jsonb),
    'quantity', line.value -> 'quantity',
    'unit_price_minor', coalesce(line.value -> 'unit_price_minor', 'null'::jsonb)
  ) order by line.ordinality)
  into normalized_items
  from jsonb_array_elements(target_cart) with ordinality as line(value, ordinality);

  perform private.quote_checkout_subtotal(
    target_organization_id,
    target_store_id,
    normalized_items
  );
end;
$$;


ALTER FUNCTION "private"."validate_advanced_cart"("target_organization_id" "uuid", "target_store_id" "uuid", "target_cart" "jsonb") OWNER TO "postgres";

--
-- Name: FUNCTION "validate_advanced_cart"("target_organization_id" "uuid", "target_store_id" "uuid", "target_cart" "jsonb"); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION "private"."validate_advanced_cart"("target_organization_id" "uuid", "target_store_id" "uuid", "target_cart" "jsonb") IS 'Validates held POS carts using the same server-authoritative catalogue price and quantity rules as checkout.';


--
-- Name: validate_inventory_count_line(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."validate_inventory_count_line"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.inventory_count_lines line where line.inventory_count_id = new.inventory_count_id and line.product_id = new.product_id and line.variant_id is not distinct from new.variant_id) then raise exception 'Each item can be counted once.' using errcode = '23514'; end if;
  return new;
end; $$;


ALTER FUNCTION "private"."validate_inventory_count_line"() OWNER TO "postgres";

--
-- Name: validate_pos_cart_stock("uuid", "uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."validate_pos_cart_stock"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid", "target_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_employee_id uuid;
  selected_line record;
  resolved_policy text;
  affected_items jsonb;
begin
  perform private.require_pos_capabilities(
    target_organization_id,
    array['pos.access', 'sales.create', 'payments.accept']
  );

  if target_store_id is null or target_register_id is null
    or target_items is null or jsonb_typeof(target_items) <> 'array'
    or jsonb_array_length(target_items) not between 1 and 100 then
    raise exception 'A store, register, and one or more cart items are required.' using errcode = '23514';
  end if;

  select employee.id
  into actor_employee_id
  from public.employees employee
  join public.employee_stores employee_store
    on employee_store.employee_id = employee.id
   and employee_store.organization_id = employee.organization_id
   and employee_store.store_id = target_store_id
  join public.registers register
    on register.id = target_register_id
   and register.organization_id = employee.organization_id
   and register.store_id = target_store_id
   and register.is_active
  where employee.organization_id = target_organization_id
    and employee.profile_id = (select auth.uid())
    and employee.status = 'active';

  if actor_employee_id is null then
    raise exception 'An active assigned employee and register are required.' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.shifts shift
    where shift.organization_id = target_organization_id
      and shift.store_id = target_store_id
      and shift.register_id = target_register_id
      and shift.opened_by_employee_id = actor_employee_id
      and shift.status = 'open'
  ) then
    raise exception 'Open your assigned register shift before charging a sale.' using errcode = '42501';
  end if;

  for selected_line in select value from jsonb_array_elements(target_items)
  loop
    if jsonb_typeof(selected_line.value) <> 'object'
      or jsonb_typeof(selected_line.value -> 'product_id') <> 'string'
      or coalesce(selected_line.value ->> 'product_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or (
        selected_line.value -> 'variant_id' is distinct from 'null'::jsonb
        and jsonb_typeof(selected_line.value -> 'variant_id') <> 'string'
      )
      or (
        nullif(selected_line.value ->> 'variant_id', '') is not null
        and selected_line.value ->> 'variant_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
      or jsonb_typeof(selected_line.value -> 'quantity') <> 'number'
      or coalesce(selected_line.value ->> 'quantity', '') !~ '^(?:0|[1-9][0-9]{0,3})(?:[.][0-9]{1,3})?$'
      or (selected_line.value ->> 'quantity')::numeric(14,3) <= 0 then
      raise exception 'Each stock-check item must have valid references and a positive quantity.' using errcode = '23514';
    end if;
  end loop;

  resolved_policy := private.resolve_negative_stock_policy(
    target_organization_id,
    target_store_id
  );

  with requested_items as (
    select
      (line.value ->> 'product_id')::uuid product_id,
      nullif(line.value ->> 'variant_id', '')::uuid variant_id,
      sum((line.value ->> 'quantity')::numeric(14,3)) cart_quantity
    from jsonb_array_elements(target_items) line(value)
    group by
      (line.value ->> 'product_id')::uuid,
      nullif(line.value ->> 'variant_id', '')::uuid
  ), tracked_items as (
    select
      requested.product_id,
      requested.variant_id,
      requested.cart_quantity,
      product.name product_name,
      variant.name variant_name,
      coalesce(level.quantity, 0::numeric) available_quantity
    from requested_items requested
    join public.products product
      on product.id = requested.product_id
     and product.organization_id = target_organization_id
     and product.status = 'active'
     and product.track_inventory
    join public.product_store_settings setting
      on setting.organization_id = product.organization_id
     and setting.product_id = product.id
     and setting.store_id = target_store_id
     and setting.is_available
    left join public.product_variants variant
      on variant.id = requested.variant_id
     and variant.product_id = product.id
     and variant.organization_id = product.organization_id
     and variant.is_active
    left join public.inventory_levels level
      on level.organization_id = product.organization_id
     and level.store_id = target_store_id
     and level.product_id = product.id
     and level.variant_id is not distinct from requested.variant_id
    where (requested.variant_id is null and product.product_type = 'simple')
       or (requested.variant_id is not null and product.product_type = 'variable' and variant.id is not null)
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'product_id', tracked.product_id,
        'variant_id', tracked.variant_id,
        'product_name', tracked.product_name,
        'variant_name', tracked.variant_name,
        'available_quantity', tracked.available_quantity,
        'cart_quantity', tracked.cart_quantity,
        'projected_quantity', tracked.available_quantity - tracked.cart_quantity
      )
      order by lower(tracked.product_name), lower(coalesce(tracked.variant_name, ''))
    ) filter (where tracked.available_quantity - tracked.cart_quantity < 0),
    '[]'::jsonb
  )
  into affected_items
  from tracked_items tracked;

  return jsonb_build_object(
    'policy', resolved_policy,
    'items', affected_items,
    'checked_at', clock_timestamp()
  );
end;
$_$;


ALTER FUNCTION "private"."validate_pos_cart_stock"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid", "target_items" "jsonb") OWNER TO "postgres";

--
-- Name: validate_product_component(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."validate_product_component"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  parent_is_composite boolean;
  component_type text;
begin
  select is_composite into parent_is_composite
  from public.products
  where id = new.product_id and organization_id = new.organization_id;

  select product_type into component_type
  from public.products
  where id = new.component_product_id and organization_id = new.organization_id;

  if not coalesce(parent_is_composite, false) then
    raise exception 'Only composite products can have component recipes.' using errcode = '23514';
  end if;

  if component_type is null then
    raise exception 'Each component must belong to this organization.' using errcode = '23503';
  end if;

  if component_type = 'variable' and new.component_variant_id is null then
    raise exception 'Choose a specific variant for a variable component.' using errcode = '23514';
  end if;

  if component_type <> 'variable' and new.component_variant_id is not null then
    raise exception 'Only variable components can use a variant.' using errcode = '23514';
  end if;

  if exists (
    with recursive descendants(product_id) as (
      select component.component_product_id
      from public.product_components component
      where component.organization_id = new.organization_id
        and component.product_id = new.component_product_id
      union
      select component.component_product_id
      from public.product_components component
      join descendants descendant on descendant.product_id = component.product_id
      where component.organization_id = new.organization_id
    )
    select 1 from descendants where product_id = new.product_id
  ) then
    raise exception 'A composite product cannot contain itself through a component chain.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."validate_product_component"() OWNER TO "postgres";

--
-- Name: validate_purchase_order_line(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."validate_purchase_order_line"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target_store_id uuid;
begin
  select store_id into target_store_id from public.purchase_orders where id = new.purchase_order_id and organization_id = new.organization_id;
  if target_store_id is null or exists (select 1 from public.purchase_order_lines line where line.purchase_order_id = new.purchase_order_id and line.product_id = new.product_id and line.variant_id is not distinct from new.variant_id) then raise exception 'Purchase order items must be unique and belong to the receiving store.' using errcode = '23514'; end if;
  if not exists (select 1 from public.inventory_levels level where level.organization_id = new.organization_id and level.store_id = target_store_id and level.product_id = new.product_id and level.variant_id is not distinct from new.variant_id) then raise exception 'Every purchase order item needs an inventory projection in the receiving store.' using errcode = '23514'; end if;
  return new;
end; $$;


ALTER FUNCTION "private"."validate_purchase_order_line"() OWNER TO "postgres";

--
-- Name: validate_refund_approval_payload("uuid", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."validate_refund_approval_payload"("target_organization_id" "uuid", "target_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_sale_id uuid;
  target_receipt_id uuid;
  target_receipt_number bigint;
  target_payment_method_id uuid;
  target_item jsonb;
  target_sale_item_id uuid;
  target_quantity integer;
  original_quantity integer;
  refunded_quantity integer;
  target_store_id uuid;
  requires_reference boolean;
  seen_item_ids uuid[] := array[]::uuid[];
begin
  begin
    target_sale_id := (target_payload ->> 'sale_id')::uuid;
    target_receipt_id := (target_payload ->> 'receipt_id')::uuid;
    target_receipt_number := (target_payload ->> 'receipt_number')::bigint;
    target_payment_method_id := (target_payload ->> 'payment_method_id')::uuid;
  exception when others then
    raise exception 'The refund approval no longer matches a valid receipt.' using errcode = '23514';
  end;

  select sale.store_id into target_store_id
  from public.sales sale
  join public.receipts receipt
    on receipt.organization_id = sale.organization_id
   and receipt.sale_id = sale.id
  where sale.organization_id = target_organization_id
    and sale.id = target_sale_id
    and sale.status = 'completed'
    and receipt.id = target_receipt_id
    and receipt.receipt_number = target_receipt_number;

  if target_store_id is null then
    raise exception 'This receipt is no longer refundable.' using errcode = '23514';
  end if;

  if coalesce(jsonb_typeof(target_payload -> 'items'), '') <> 'array'
    or coalesce(jsonb_array_length(target_payload -> 'items'), 0) not between 1 and 100 then
    raise exception 'Select refund items before requesting approval.' using errcode = '23514';
  end if;

  for target_item in select value from jsonb_array_elements(target_payload -> 'items') loop
    begin
      target_sale_item_id := (target_item ->> 'sale_item_id')::uuid;
      target_quantity := (target_item ->> 'quantity')::integer;
    exception when others then
      raise exception 'Refund approval items are invalid.' using errcode = '23514';
    end;

    if target_sale_item_id = any(seen_item_ids) or target_quantity not between 1 and 10000 then
      raise exception 'Refund approval items are invalid.' using errcode = '23514';
    end if;
    seen_item_ids := array_append(seen_item_ids, target_sale_item_id);

    select sale_item.quantity into original_quantity
    from public.sale_items sale_item
    where sale_item.organization_id = target_organization_id
      and sale_item.sale_id = target_sale_id
      and sale_item.id = target_sale_item_id;

    select coalesce(sum(refund_item.quantity), 0)::integer into refunded_quantity
    from public.refund_items refund_item
    join public.refunds refund
      on refund.organization_id = refund_item.organization_id
     and refund.id = refund_item.refund_id
     and refund.sale_id = target_sale_id
     and refund.status = 'completed'
    where refund_item.organization_id = target_organization_id
      and refund_item.sale_item_id = target_sale_item_id;

    if original_quantity is null or target_quantity + refunded_quantity > original_quantity then
      raise exception 'One or more refund quantities are no longer available.' using errcode = '23514';
    end if;
  end loop;

  select payment_method.requires_reference into requires_reference
  from public.payment_methods payment_method
  join public.store_payment_methods store_method
    on store_method.organization_id = payment_method.organization_id
   and store_method.payment_method_id = payment_method.id
   and store_method.store_id = target_store_id
   and store_method.is_enabled
  where payment_method.organization_id = target_organization_id
    and payment_method.id = target_payment_method_id
    and payment_method.is_enabled;

  if requires_reference is null then
    raise exception 'The selected refund method is no longer available.' using errcode = '23514';
  end if;
  if requires_reference and nullif(trim(coalesce(target_payload ->> 'reference_number', '')), '') is null then
    raise exception 'A reference is required for this refund method.' using errcode = '23514';
  end if;
end;
$$;


ALTER FUNCTION "private"."validate_refund_approval_payload"("target_organization_id" "uuid", "target_payload" "jsonb") OWNER TO "postgres";

--
-- Name: validate_refund_approval_request_trigger(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."validate_refund_approval_request_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.operation_code = 'sales.refund'
    and (tg_op = 'INSERT' or new.status = 'APPROVED') then
    perform private.validate_refund_approval_payload(new.organization_id, new.request_payload);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."validate_refund_approval_request_trigger"() OWNER TO "postgres";

--
-- Name: validate_stock_transfer_line(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."validate_stock_transfer_line"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare source_store uuid; destination_store uuid;
begin
  select source_store_id, destination_store_id into source_store, destination_store from public.stock_transfers where id = new.stock_transfer_id and organization_id = new.organization_id;
  if source_store is null or exists (select 1 from public.stock_transfer_lines line where line.stock_transfer_id = new.stock_transfer_id and line.product_id = new.product_id and line.variant_id is not distinct from new.variant_id) then raise exception 'Transfer items must be unique.' using errcode = '23514'; end if;
  if not exists (select 1 from public.inventory_levels level where level.organization_id = new.organization_id and level.store_id in (source_store, destination_store) and level.product_id = new.product_id and level.variant_id is not distinct from new.variant_id group by level.product_id, level.variant_id having count(*) = 2) then raise exception 'The item must have stock projections in both stores before it can be transferred.' using errcode = '23514'; end if;
  return new;
end; $$;


ALTER FUNCTION "private"."validate_stock_transfer_line"() OWNER TO "postgres";

--
-- Name: verify_attendance_employee_pin("uuid", "uuid", "uuid", "text", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."verify_attendance_employee_pin"("target_organization_id" "uuid", "target_store_id" "uuid", "target_employee_id" "uuid", "target_pin" "text", "actor_employee_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  employee_status text;
  credential private.employee_pin_credentials%rowtype;
  next_failed_attempts integer;
begin
  select employee.status
  into employee_status
  from public.employees employee
  where employee.id = target_employee_id
    and employee.organization_id = target_organization_id
  for key share;

  if employee_status is null then return 'EMPLOYEE_NOT_FOUND'; end if;
  if employee_status <> 'active' then return 'EMPLOYEE_INACTIVE'; end if;
  if not private.employee_has_permission(target_organization_id, target_employee_id, 'attendance.use') then
    return 'ATTENDANCE_NOT_ALLOWED';
  end if;
  if not exists (
    select 1 from public.employee_stores assignment
    where assignment.organization_id = target_organization_id
      and assignment.employee_id = target_employee_id
      and assignment.store_id = target_store_id
  ) then
    return 'STORE_NOT_ALLOWED';
  end if;

  select * into credential
  from private.employee_pin_credentials pin_credential
  where pin_credential.employee_id = target_employee_id
  for update;

  if credential.employee_id is null then return 'PIN_NOT_SET'; end if;
  if credential.locked_until is not null and credential.locked_until > now() then
    return 'PIN_LOCKED';
  end if;

  if coalesce(target_pin, '') !~ '^[0-9]{6,12}$'
    or credential.pin_hash <> extensions.crypt(target_pin, credential.pin_hash) then
    next_failed_attempts := case
      when credential.failed_window_started_at is null
        or credential.failed_window_started_at < now() - interval '15 minutes' then 1
      else credential.failed_attempts + 1
    end;

    update private.employee_pin_credentials
    set failed_attempts = least(next_failed_attempts, 5),
        failed_window_started_at = case
          when credential.failed_window_started_at is null
            or credential.failed_window_started_at < now() - interval '15 minutes' then now()
          else credential.failed_window_started_at
        end,
        locked_until = case when next_failed_attempts >= 5 then now() + interval '15 minutes' else null end,
        updated_at = now()
    where employee_id = target_employee_id;

    perform private.write_audit_log(
      target_organization_id,
      case when next_failed_attempts >= 5 then 'EMPLOYEE_PIN_LOCKED' else 'EMPLOYEE_PIN_FAILED' end,
      'attendance.use', actor_employee_id, target_employee_id, target_store_id,
      null, null, null, null,
      jsonb_build_object('attempts_in_window', least(next_failed_attempts, 5))
    );
    return case when next_failed_attempts >= 5 then 'PIN_LOCKED' else 'INVALID_PIN' end;
  end if;

  update private.employee_pin_credentials
  set failed_attempts = 0,
      failed_window_started_at = null,
      locked_until = null,
      updated_at = now()
  where employee_id = target_employee_id;

  return 'VERIFIED';
end;
$_$;


ALTER FUNCTION "private"."verify_attendance_employee_pin"("target_organization_id" "uuid", "target_store_id" "uuid", "target_employee_id" "uuid", "target_pin" "text", "actor_employee_id" "uuid") OWNER TO "postgres";

--
-- Name: verify_pos_device_credential("uuid", "uuid", "text", "text", "uuid", "uuid"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."verify_pos_device_credential"("target_organization_id" "uuid", "target_device_id" "uuid", "target_secret" "text", "target_app_version" "text", "expected_store_id" "uuid" DEFAULT NULL::"uuid", "expected_register_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("device_id" "uuid", "store_id" "uuid", "register_id" "uuid", "device_name" "text", "app_version" "text", "last_seen_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  device_record public.pos_devices%rowtype;
  normalized_app_version text;
begin
  if target_organization_id is null
    or target_device_id is null
    or target_secret is null
    or target_secret !~ '^[0-9A-Fa-f]{64}$' then
    raise exception 'This POS device credential is invalid.' using errcode = '42501';
  end if;

  normalized_app_version := nullif(left(trim(coalesce(target_app_version, '')), 80), '');

  select device.*
  into device_record
  from public.pos_devices device
  join private.pos_device_credentials credential
    on credential.device_id = device.id
  where device.id = target_device_id
    and device.organization_id = target_organization_id
    and device.status = 'active'
    and credential.secret_hash = extensions.digest(target_secret, 'sha256')
    and (expected_store_id is null or device.store_id = expected_store_id)
    and (expected_register_id is null or device.register_id = expected_register_id)
  for update of device;

  if device_record.id is null then
    raise exception 'This POS device is not active for the selected register.' using errcode = '42501';
  end if;

  update public.pos_devices device
  set
    last_seen_at = now(),
    app_version = coalesce(normalized_app_version, device.app_version)
  where device.id = device_record.id
  returning device.last_seen_at, device.app_version
  into last_seen_at, app_version;

  device_id := device_record.id;
  store_id := device_record.store_id;
  register_id := device_record.register_id;
  device_name := device_record.name;
  return next;
end;
$_$;


ALTER FUNCTION "private"."verify_pos_device_credential"("target_organization_id" "uuid", "target_device_id" "uuid", "target_secret" "text", "target_app_version" "text", "expected_store_id" "uuid", "expected_register_id" "uuid") OWNER TO "postgres";

--
-- Name: write_audit_log("uuid", "text", "text", "uuid", "uuid", "uuid", "uuid", "uuid", bigint, "text", "jsonb"); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE OR REPLACE FUNCTION "private"."write_audit_log"("target_organization_id" "uuid", "target_event_type" "text", "target_operation_code" "text" DEFAULT NULL::"text", "target_actor_employee_id" "uuid" DEFAULT NULL::"uuid", "target_subject_employee_id" "uuid" DEFAULT NULL::"uuid", "target_store_id" "uuid" DEFAULT NULL::"uuid", "target_register_id" "uuid" DEFAULT NULL::"uuid", "target_approval_request_id" "uuid" DEFAULT NULL::"uuid", "target_amount_minor" bigint DEFAULT NULL::bigint, "target_reason" "text" DEFAULT NULL::"text", "target_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.audit_logs (
    organization_id,
    event_type,
    operation_code,
    actor_employee_id,
    subject_employee_id,
    store_id,
    register_id,
    approval_request_id,
    amount_minor,
    reason,
    metadata
  )
  values (
    target_organization_id,
    target_event_type,
    target_operation_code,
    target_actor_employee_id,
    target_subject_employee_id,
    target_store_id,
    target_register_id,
    target_approval_request_id,
    target_amount_minor,
    nullif(trim(coalesce(target_reason, '')), ''),
    coalesce(target_metadata, '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "private"."write_audit_log"("target_organization_id" "uuid", "target_event_type" "text", "target_operation_code" "text", "target_actor_employee_id" "uuid", "target_subject_employee_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid", "target_approval_request_id" "uuid", "target_amount_minor" bigint, "target_reason" "text", "target_metadata" "jsonb") OWNER TO "postgres";

