--
-- Name: change_pos_device_register("uuid", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."change_pos_device_register"("target_organization_id" "uuid", "target_device_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid") RETURNS TABLE("device_id" "uuid", "store_id" "uuid", "register_id" "uuid", "status" "text", "last_seen_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  device_record public.pos_devices%rowtype;
begin
  actor_employee_id := private.require_device_manager(target_organization_id);
  perform private.require_active_device_binding(
    target_organization_id,
    target_store_id,
    target_register_id
  );

  select device.*
  into device_record
  from public.pos_devices device
  where device.id = target_device_id
    and device.organization_id = target_organization_id
    and device.status = 'active'
  for update;

  if device_record.id is null then
    raise exception 'The active POS device was not found.' using errcode = 'P0002';
  end if;

  update public.pos_devices device
  set store_id = target_store_id, register_id = target_register_id
  where device.id = device_record.id;

  perform private.write_audit_log(
    target_organization_id,
    'DEVICE_REGISTER_CHANGED',
    'devices.change_register',
    actor_employee_id,
    null,
    target_store_id,
    target_register_id,
    null,
    null,
    null,
    jsonb_build_object(
      'device_id', target_device_id,
      'previous_store_id', device_record.store_id,
      'previous_register_id', device_record.register_id,
      'store_id', target_store_id,
      'register_id', target_register_id
    )
  );

  return query
  select device.id, device.store_id, device.register_id, device.status, device.last_seen_at
  from public.pos_devices device
  where device.id = device_record.id;
end;
$$;


ALTER FUNCTION "public"."change_pos_device_register"("target_organization_id" "uuid", "target_device_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid") OWNER TO "postgres";

--
-- Name: checkout_advanced_sale("uuid", "uuid", "uuid", "uuid", "jsonb", "jsonb", "uuid", integer, "uuid", "uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."checkout_advanced_sale"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid", "target_idempotency_key" "uuid", "target_items" "jsonb", "target_payments" "jsonb", "target_customer_id" "uuid", "target_loyalty_redemption_points" integer, "target_discount_id" "uuid", "target_tax_rate_id" "uuid", "target_dining_option_id" "uuid", "target_open_ticket_id" "uuid") RETURNS TABLE("sale_id" "uuid", "receipt_number" bigint, "total_minor" bigint, "change_minor" bigint, "payment_summary" "jsonb", "was_replayed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_pos_capabilities(
    target_organization_id,
    array['pos.access', 'sales.create', 'payments.accept']
  );

  if target_discount_id is not null then
    perform private.require_pos_capabilities(
      target_organization_id,
      array['discounts.apply']
    );
  end if;

  if target_open_ticket_id is not null then
    perform private.require_pos_capabilities(
      target_organization_id,
      array['tickets.manage']
    );
  end if;

  return query
  select *
  from private.checkout_advanced_sale(
    target_organization_id,
    target_store_id,
    target_register_id,
    target_idempotency_key,
    target_items,
    target_payments,
    target_customer_id,
    target_loyalty_redemption_points,
    target_discount_id,
    target_tax_rate_id,
    target_dining_option_id,
    target_open_ticket_id
  );
end;
$$;


