--
-- Name: get_customer_display_bootstrap("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_customer_display_bootstrap"("target_access_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  display_bootstrap jsonb;
begin
  if target_access_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'This customer display link is unavailable.' using errcode = 'P0002';
  end if;

  select jsonb_build_object(
    'business_name', organization.name,
    'store_name', store.name,
    'register_name', register.name,
    'realtime_topic', display.realtime_topic,
    'current_state', display.current_state,
    'updated_at', display.updated_at
  )
  into display_bootstrap
  from public.customer_display_sessions display
  join public.organizations organization
    on organization.id = display.organization_id
  join public.stores store
    on store.id = display.store_id
  join public.registers register
    on register.id = display.register_id
  where display.access_token_hash = target_access_token_hash
    and display.is_active;

  if display_bootstrap is null then
    raise exception 'This customer display link is unavailable.' using errcode = 'P0002';
  end if;

  return display_bootstrap;
end;
$_$;


ALTER FUNCTION "public"."get_customer_display_bootstrap"("target_access_token_hash" "text") OWNER TO "postgres";

--
-- Name: FUNCTION "get_customer_display_bootstrap"("target_access_token_hash" "text"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_customer_display_bootstrap"("target_access_token_hash" "text") IS 'Returns only the sanitized state and Realtime topic for one opaque 256-bit customer-display pairing capability.';


