-- Name: get_employee_management_detail("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_employee_management_detail"("target_organization_id" "uuid", "target_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$ select private.get_employee_management_detail(target_organization_id, target_employee_id); $$;


ALTER FUNCTION "public"."get_employee_management_detail"("target_organization_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";

--
-- Name: get_inventory_count_awareness("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_inventory_count_awareness"("target_organization_id" "uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "variant_id" "uuid", "last_counted_at" timestamp with time zone, "expected_quantity" numeric, "counted_quantity" numeric, "inventory_count_id" "uuid", "count_number" bigint)
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  select * from private.get_inventory_count_awareness(target_organization_id);
$$;


ALTER FUNCTION "public"."get_inventory_count_awareness"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "get_inventory_count_awareness"("target_organization_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_inventory_count_awareness"("target_organization_id" "uuid") IS 'Returns the latest completed physical-count fact for each authorized active tracked stock position. It is read-only awareness and does not enforce count frequency.';


--
-- Name: get_inventory_count_suppliers("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_inventory_count_suppliers"("target_organization_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null
    or not (select private.has_inventory_capability(target_organization_id, 'inventory.count.create')) then
    raise exception 'Inventory count creation permission is required.' using errcode = '42501';
  end if;

  return query
  select supplier.id, supplier.name
  from public.suppliers supplier
  where supplier.organization_id = target_organization_id
    and supplier.is_active
  order by lower(supplier.name), supplier.id;
end;
$$;


ALTER FUNCTION "public"."get_inventory_count_suppliers"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: get_inventory_health_awareness("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_inventory_health_awareness"("target_organization_id" "uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "variant_id" "uuid", "last_counted_at" timestamp with time zone, "expected_quantity" numeric, "counted_quantity" numeric, "inventory_count_id" "uuid", "count_number" bigint, "days_since_count" integer, "count_recommended" boolean)
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  select
    awareness.store_id,
    awareness.product_id,
    awareness.variant_id,
    awareness.last_counted_at,
    awareness.expected_quantity,
    awareness.counted_quantity,
    awareness.inventory_count_id,
    awareness.count_number,
    case
      when awareness.last_counted_at is null then null
      else greatest(0, floor(extract(epoch from (now() - awareness.last_counted_at)) / 86400))::integer
    end as days_since_count,
    awareness.last_counted_at is null
      or awareness.last_counted_at < now() - interval '30 days' as count_recommended
  from private.get_inventory_count_awareness(target_organization_id) awareness;
$$;


ALTER FUNCTION "public"."get_inventory_health_awareness"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "get_inventory_health_awareness"("target_organization_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_inventory_health_awareness"("target_organization_id" "uuid") IS 'Adds database-clock age awareness to the existing permission-checked latest physical-count facts. The 30-day recommendation is informational and does not enforce a policy.';


--
-- Name: get_inventory_movement_costs("uuid", "uuid"[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_inventory_movement_costs"("target_organization_id" "uuid", "requested_movement_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "unit_cost_minor" bigint, "value_delta_minor" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select movement.id, movement.unit_cost_minor, movement.value_delta_minor
  from public.inventory_movements movement
  where (select auth.uid()) is not null
    and cardinality(requested_movement_ids) between 1 and 100
    and movement.id = any(requested_movement_ids)
    and movement.organization_id = target_organization_id
    and (select private.has_permission(target_organization_id, 'products.view_cost'))
    and (
      (select private.has_permission(target_organization_id, 'inventory.view'))
      or (select private.has_permission(target_organization_id, 'inventory.manage'))
    )
    and (select private.has_store_read_scope(target_organization_id, movement.store_id));
$$;


ALTER FUNCTION "public"."get_inventory_movement_costs"("target_organization_id" "uuid", "requested_movement_ids" "uuid"[]) OWNER TO "postgres";

--
-- Name: FUNCTION "get_inventory_movement_costs"("target_organization_id" "uuid", "requested_movement_ids" "uuid"[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_inventory_movement_costs"("target_organization_id" "uuid", "requested_movement_ids" "uuid"[]) IS 'Returns requested immutable movement values only to store-scoped inventory readers with products.view_cost.';


--
-- Name: get_inventory_schema_contract("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_inventory_schema_contract"("target_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  missing_core text[] := array[]::text[];
  modules jsonb;
begin
  if (select auth.uid()) is null then
    raise exception
      using errcode = '42501',
            message = 'Authentication required.';
  end if;

  if not exists (
    select 1
    from public.organizations organization
    join public.employees employee
      on employee.organization_id = organization.id
    where organization.id = target_organization_id
      and organization.status = 'active'
      and employee.profile_id = (select auth.uid())
      and employee.status = 'active'
  ) then
    raise exception
      using errcode = '42501',
            message = 'Organization access denied.';
  end if;

  if pg_catalog.to_regclass(
    'public.inventory_levels'
  ) is null then
    missing_core := array_append(
      missing_core,
      'inventory_levels'
    );
  end if;

  if pg_catalog.to_regclass(
    'public.inventory_movements'
  ) is null then
    missing_core := array_append(
      missing_core,
      'inventory_movements'
    );
  end if;

  if pg_catalog.to_regclass(
    'public.products'
  ) is null then
    missing_core := array_append(
      missing_core,
      'products'
    );
  end if;

  if pg_catalog.to_regclass(
    'public.product_variants'
  ) is null then
    missing_core := array_append(
      missing_core,
      'product_variants'
    );
  end if;

  if pg_catalog.to_regclass(
    'public.product_store_settings'
  ) is null then
    missing_core := array_append(
      missing_core,
      'product_store_settings'
    );
  end if;

  if pg_catalog.to_regclass(
    'public.stores'
  ) is null then
    missing_core := array_append(
      missing_core,
      'stores'
    );
  end if;

  if not exists (
    select 1
    from pg_catalog.pg_proc procedure
    join pg_catalog.pg_namespace namespace
      on namespace.oid = procedure.pronamespace
    where namespace.nspname = 'private'
      and procedure.proname = 'apply_inventory_change_v2'
  ) then
    missing_core := array_append(
      missing_core,
      'apply_inventory_change_v2'
    );
  end if;

  modules := jsonb_build_object(
    'count_batches',
      pg_catalog.to_regclass(
        'public.inventory_count_batches'
      ) is not null
      and pg_catalog.to_regclass(
        'public.inventory_count_batch_documents'
      ) is not null,

    'direct_transfers',
      pg_catalog.to_regclass(
        'public.stock_transfers'
      ) is not null
      and pg_catalog.to_regclass(
        'public.stock_transfer_lines'
      ) is not null
      and exists (
        select 1
        from pg_catalog.pg_proc procedure
        join pg_catalog.pg_namespace namespace
          on namespace.oid = procedure.pronamespace
        where namespace.nspname = 'public'
          and procedure.proname =
            'create_direct_stock_transfer'
      ),

    'purchasing',
      pg_catalog.to_regclass(
        'public.purchase_orders'
      ) is not null
      and pg_catalog.to_regclass(
        'public.purchase_order_lines'
      ) is not null
      and pg_catalog.to_regclass(
        'public.suppliers'
      ) is not null,

    'valuation',
      exists (
        select 1
        from pg_catalog.pg_proc procedure
        join pg_catalog.pg_namespace namespace
          on namespace.oid = procedure.pronamespace
        where namespace.nspname = 'public'
          and procedure.proname =
            'get_inventory_valuation'
      ),

    'replenishment',
      pg_catalog.to_regclass(
        'public.inventory_replenishment_rules'
      ) is not null
  );

  return jsonb_build_object(
    'contract_version', 1,
    'core_ready', cardinality(missing_core) = 0,
    'core_missing', to_jsonb(missing_core),
    'modules', modules
  );
end;
$$;


ALTER FUNCTION "public"."get_inventory_schema_contract"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: get_inventory_stock_page("uuid", "uuid", "text", "uuid", "text", "text", "text", integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_inventory_stock_page"("target_organization_id" "uuid", "requested_store_id" "uuid" DEFAULT NULL::"uuid", "requested_search" "text" DEFAULT NULL::"text", "requested_category_id" "uuid" DEFAULT NULL::"uuid", "requested_status" "text" DEFAULT 'all'::"text", "requested_restock_policy" "text" DEFAULT 'all'::"text", "requested_sort" "text" DEFAULT 'priority'::"text", "requested_page" integer DEFAULT 1, "requested_page_size" integer DEFAULT 50) RETURNS TABLE("level_id" "uuid", "store_id" "uuid", "store_name" "text", "product_id" "uuid", "product_name" "text", "category_id" "uuid", "category_name" "text", "variant_id" "uuid", "variant_name" "text", "sku" "text", "barcode" "text", "unit" "text", "quantity" numeric, "updated_at" timestamp with time zone, "is_available" boolean, "restock_policy" "text", "reorder_point" numeric, "average_cost_minor" bigint, "total_count" bigint, "negative_count" bigint, "low_count" bigint, "in_stock_count" bigint, "out_of_stock_count" bigint, "active_product_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_search text := nullif(lower(btrim(coalesce(requested_search, ''))), '');
  normalized_status text := coalesce(nullif(btrim(requested_status), ''), 'all');
  normalized_restock_policy text := coalesce(nullif(btrim(requested_restock_policy), ''), 'all');
  normalized_sort text := coalesce(nullif(btrim(requested_sort), ''), 'priority');
  page_number integer := greatest(coalesce(requested_page, 1), 1);
  page_size integer := least(greatest(coalesce(requested_page_size, 50), 1), 100);
  can_read_cost boolean := false;
  can_manage_reorder boolean := false;
begin
  if (select auth.uid()) is null
    or not (select private.has_any_inventory_capability(
      target_organization_id,
      array[
        'inventory.view',
        'inventory.adjust.create',
        'inventory.adjust.post',
        'inventory.count.create',
        'inventory.count.finalize',
        'inventory.transfer.create',
        'inventory.transfer.send',
        'inventory.transfer.receive'
      ]
    )) then
    raise exception 'Inventory access is required.' using errcode = '42501';
  end if;

  if requested_store_id is not null
    and not (select private.has_store_read_scope(target_organization_id, requested_store_id)) then
    raise exception 'Store access is required to review stock.' using errcode = '42501';
  end if;

  if normalized_status not in ('all', 'attention', 'available', 'in_stock', 'low', 'negative', 'out_of_stock') then
    raise exception 'Choose a valid stock status.' using errcode = '22023';
  end if;
  if normalized_restock_policy not in ('all', 'restock', 'do_not_restock') then
    raise exception 'Choose a valid restock policy.' using errcode = '22023';
  end if;
  if normalized_sort not in ('priority', 'name_asc', 'name_desc', 'quantity_asc', 'quantity_desc', 'updated_desc', 'value_desc') then
    raise exception 'Choose a valid stock sort.' using errcode = '22023';
  end if;

  can_read_cost := (select private.has_permission(target_organization_id, 'products.view_cost'));
  can_manage_reorder := (select private.has_inventory_capability(target_organization_id, 'inventory.manage'));
  if not can_manage_reorder and normalized_status in ('attention', 'low') then
    normalized_status := 'all';
  end if;
  if not can_read_cost and normalized_sort = 'value_desc' then
    normalized_sort := 'priority';
  end if;

  return query
  with scoped_stores as materialized (
    select store.id, store.name
    from public.stores store
    where store.organization_id = target_organization_id
      and store.is_active
      and (requested_store_id is null or store.id = requested_store_id)
      and (select private.has_store_read_scope(target_organization_id, store.id))
  ),
  active_products as materialized (
    select product.id, product.category_id, product.name, product.sku, product.barcode, product.product_type, product.unit
    from public.products product
    where product.organization_id = target_organization_id
      and product.status = 'active'
      and product.track_inventory
  ),
  active_variants as materialized (
    select variant.id, variant.product_id, variant.name, variant.sku, variant.barcode
    from public.product_variants variant
    where variant.organization_id = target_organization_id
      and variant.is_active
  ),
  level_positions as (
    select
      level.id as level_id,
      store.id as store_id,
      store.name as store_name,
      product.id as product_id,
      product.name as product_name,
      product.category_id,
      category.name as category_name,
      variant.id as variant_id,
      variant.name as variant_name,
      coalesce(variant.sku, product.sku) as sku,
      coalesce(variant.barcode, product.barcode) as barcode,
      product.unit,
      level.quantity,
      level.updated_at,
      coalesce(setting.is_available, false) as is_available,
      coalesce(setting.restock_policy, 'restock') as restock_policy,
      case when can_manage_reorder then rule.reorder_point else null end as reorder_point,
      case when can_read_cost then level.average_cost_minor else null end as average_cost_minor
    from public.inventory_levels level
    join scoped_stores store on store.id = level.store_id
    join active_products product on product.id = level.product_id
    left join active_variants variant
      on variant.id = level.variant_id
     and variant.product_id = product.id
    left join public.categories category
      on category.id = product.category_id
     and category.organization_id = target_organization_id
    left join public.product_store_settings setting
      on setting.organization_id = target_organization_id
     and setting.store_id = level.store_id
     and setting.product_id = level.product_id
    left join public.inventory_replenishment_rules rule
      on rule.organization_id = target_organization_id
     and rule.store_id = level.store_id
     and rule.product_id = level.product_id
     and rule.variant_id is not distinct from level.variant_id
    where level.organization_id = target_organization_id
  ),
  uninitialized_simple_positions as (
    select
      null::uuid as level_id,
      store.id as store_id,
      store.name as store_name,
      product.id as product_id,
      product.name as product_name,
      product.category_id,
      category.name as category_name,
      null::uuid as variant_id,
      null::text as variant_name,
      product.sku,
      product.barcode,
      product.unit,
      0::numeric as quantity,
      setting.updated_at,
      setting.is_available,
      setting.restock_policy,
      case when can_manage_reorder then rule.reorder_point else null end as reorder_point,
      null::bigint as average_cost_minor
    from public.product_store_settings setting
    join scoped_stores store on store.id = setting.store_id
    join active_products product
      on product.id = setting.product_id
     and product.product_type = 'simple'
    left join public.categories category
      on category.id = product.category_id
     and category.organization_id = target_organization_id
    left join public.inventory_replenishment_rules rule
      on rule.organization_id = target_organization_id
     and rule.store_id = setting.store_id
     and rule.product_id = product.id
     and rule.variant_id is null
    left join public.inventory_levels level
      on level.organization_id = target_organization_id
     and level.store_id = setting.store_id
     and level.product_id = product.id
     and level.variant_id is null
    where setting.organization_id = target_organization_id
      and level.id is null
  ),
  uninitialized_variant_positions as (
    select
      null::uuid as level_id,
      store.id as store_id,
      store.name as store_name,
      product.id as product_id,
      product.name as product_name,
      product.category_id,
      category.name as category_name,
      variant.id as variant_id,
      variant.name as variant_name,
      coalesce(variant.sku, product.sku) as sku,
      coalesce(variant.barcode, product.barcode) as barcode,
      product.unit,
      0::numeric as quantity,
      setting.updated_at,
      setting.is_available,
      setting.restock_policy,
      case when can_manage_reorder then rule.reorder_point else null end as reorder_point,
      null::bigint as average_cost_minor
    from public.product_store_settings setting
    join scoped_stores store on store.id = setting.store_id
    join active_products product
      on product.id = setting.product_id
     and product.product_type = 'variable'
    join active_variants variant on variant.product_id = product.id
    left join public.categories category
      on category.id = product.category_id
     and category.organization_id = target_organization_id
    left join public.inventory_replenishment_rules rule
      on rule.organization_id = target_organization_id
     and rule.store_id = setting.store_id
     and rule.product_id = product.id
     and rule.variant_id = variant.id
    left join public.inventory_levels level
      on level.organization_id = target_organization_id
     and level.store_id = setting.store_id
     and level.product_id = product.id
     and level.variant_id = variant.id
    where setting.organization_id = target_organization_id
      and level.id is null
  ),
  positions as materialized (
    select * from level_positions
    union all
    select * from uninitialized_simple_positions
    union all
    select * from uninitialized_variant_positions
  ),
  classified as materialized (
    select
      position.*,
      case
        when position.quantity < 0 then 'negative'
        when position.reorder_point is not null and position.quantity <= position.reorder_point then
          case when position.quantity = 0 then 'out_of_stock' else 'low' end
        when position.quantity = 0 then 'out_of_stock'
        else 'in_stock'
      end as stock_condition
    from positions position
  ),
  filter_base as materialized (
    select *
    from classified position
    where (requested_category_id is null or position.category_id = requested_category_id)
      and (normalized_restock_policy = 'all' or position.restock_policy = normalized_restock_policy)
      and (
        normalized_search is null
        or lower(position.product_name) like '%' || normalized_search || '%'
        or lower(coalesce(position.variant_name, '')) like '%' || normalized_search || '%'
        or lower(coalesce(position.sku, '')) like '%' || normalized_search || '%'
        or lower(coalesce(position.barcode, '')) like '%' || normalized_search || '%'
      )
  ),
  metrics as materialized (
    select
      count(*) filter (where stock_condition = 'negative') as negative_count,
      count(*) filter (where stock_condition = 'low') as low_count,
      count(*) filter (where stock_condition = 'in_stock') as in_stock_count,
      count(*) filter (where stock_condition = 'out_of_stock') as out_of_stock_count,
      count(distinct product_id) as active_product_count
    from filter_base
  ),
  filtered as materialized (
    select *
    from filter_base
    where normalized_status = 'all'
      or (normalized_status = 'available' and is_available)
      or (normalized_status = 'attention' and stock_condition in ('low', 'negative', 'out_of_stock'))
      or stock_condition = normalized_status
  ),
  paged as (
    select
      position.*,
      count(*) over () as total_count
    from filtered position
    order by
      case when normalized_sort = 'priority' then
        case position.stock_condition when 'negative' then 0 when 'low' then 1 when 'in_stock' then 2 else 3 end
      end asc,
      case when normalized_sort = 'name_asc' then lower(position.product_name) end asc,
      case when normalized_sort = 'name_desc' then lower(position.product_name) end desc,
      case when normalized_sort = 'quantity_asc' then position.quantity end asc,
      case when normalized_sort = 'quantity_desc' then position.quantity end desc,
      case when normalized_sort = 'updated_desc' then position.updated_at end desc,
      case when normalized_sort = 'value_desc' then coalesce(position.average_cost_minor, 0) * position.quantity end desc,
      lower(position.product_name) asc,
      lower(coalesce(position.variant_name, '')) asc,
      lower(position.store_name) asc,
      position.level_id asc nulls last
    limit page_size
    offset (page_number - 1) * page_size
  )
  select
    position.level_id,
    position.store_id,
    position.store_name,
    position.product_id,
    position.product_name,
    position.category_id,
    position.category_name,
    position.variant_id,
    position.variant_name,
    position.sku,
    position.barcode,
    position.unit,
    position.quantity,
    position.updated_at,
    position.is_available,
    position.restock_policy,
    position.reorder_point,
    position.average_cost_minor,
    position.total_count,
    metrics.negative_count,
    metrics.low_count,
    metrics.in_stock_count,
    metrics.out_of_stock_count,
    metrics.active_product_count
  from paged position
  cross join metrics;
end;
$$;


ALTER FUNCTION "public"."get_inventory_stock_page"("target_organization_id" "uuid", "requested_store_id" "uuid", "requested_search" "text", "requested_category_id" "uuid", "requested_status" "text", "requested_restock_policy" "text", "requested_sort" "text", "requested_page" integer, "requested_page_size" integer) OWNER TO "postgres";

--
-- Name: FUNCTION "get_inventory_stock_page"("target_organization_id" "uuid", "requested_store_id" "uuid", "requested_search" "text", "requested_category_id" "uuid", "requested_status" "text", "requested_restock_policy" "text", "requested_sort" "text", "requested_page" integer, "requested_page_size" integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_inventory_stock_page"("target_organization_id" "uuid", "requested_store_id" "uuid", "requested_search" "text", "requested_category_id" "uuid", "requested_status" "text", "requested_restock_policy" "text", "requested_sort" "text", "requested_page" integer, "requested_page_size" integer) IS 'Bounded Stock & Restock read model. It derives display-only zero positions from active product-store settings, preserves inventory_levels as the balance authority, and enforces inventory capability plus store scope in PostgreSQL.';


--
-- Name: get_inventory_valuation("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_inventory_valuation"("target_organization_id" "uuid") RETURNS TABLE("store_id" "uuid", "product_id" "uuid", "variant_id" "uuid", "quantity" numeric, "average_cost_minor" bigint, "value_minor" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    level.store_id,
    level.product_id,
    level.variant_id,
    level.quantity,
    level.average_cost_minor,
    case
      when level.cost_is_known then round(level.quantity * level.average_cost_minor)::bigint
      else null::bigint
    end as value_minor
  from public.inventory_levels level
  where (select auth.uid()) is not null
    and level.organization_id = target_organization_id
    and (select private.has_permission(target_organization_id, 'products.view_cost'))
    and (select private.has_inventory_capability(target_organization_id, 'inventory.valuation.view'))
    and (select private.has_store_read_scope(target_organization_id, level.store_id));
$$;


ALTER FUNCTION "public"."get_inventory_valuation"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "get_inventory_valuation"("target_organization_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_inventory_valuation"("target_organization_id" "uuid") IS 'Returns store-scoped valuation only to cost-authorized employees with inventory.valuation.view. Unknown cost positions return NULL value_minor and must not be treated as zero-value inventory.';


--
-- Name: get_kitchen_orders("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_kitchen_orders"("target_organization_id" "uuid", "target_store_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("kitchen_order_id" "uuid", "store_id" "uuid", "store_name" "text", "order_number" bigint, "order_label" "text", "order_note" "text", "dining_option_name" "text", "priority" "text", "status" "text", "created_at" timestamp with time zone, "started_at" timestamp with time zone, "ready_at" timestamp with time zone, "completed_at" timestamp with time zone, "items" "jsonb")
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $_$
  select * from private.get_kitchen_orders($1, $2);
$_$;


