--
-- Name: get_organization_export_page("uuid", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_organization_export_page"("target_export_session_id" "uuid", "target_section" "text", "target_after_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  export_session public.organization_export_sessions%rowtype;
  normalized_section text := lower(btrim(coalesce(target_section, '')));
  source_table text;
  source_predicate text;
  export_rows jsonb;
  next_after_id uuid;
begin
  select session.*
  into export_session
  from public.organization_export_sessions session
  where session.id = target_export_session_id
    and session.profile_id = (select auth.uid())
    and session.expires_at > now();

  if not found then
    raise exception 'The organization export session is missing or has expired.' using errcode = '42501';
  end if;

  if not private.has_organization_export_access(export_session.organization_id) then
    raise exception 'You do not have permission to export this organization.' using errcode = '42501';
  end if;

  case normalized_section
    when 'organization' then source_table := 'public.organizations'; source_predicate := 'id = $1';
    when 'stores' then source_table := 'public.stores'; source_predicate := 'organization_id = $1';
    when 'registers' then source_table := 'public.registers'; source_predicate := 'organization_id = $1';
    when 'employees' then source_table := 'public.employees'; source_predicate := 'organization_id = $1';
    when 'roles' then source_table := 'public.roles'; source_predicate := 'organization_id = $1';
    when 'categories' then source_table := 'public.categories'; source_predicate := 'organization_id = $1';
    when 'products' then source_table := 'public.products'; source_predicate := 'organization_id = $1';
    when 'product_variants' then source_table := 'public.product_variants'; source_predicate := 'organization_id = $1';
    when 'customers' then source_table := 'public.customers'; source_predicate := 'organization_id = $1';
    when 'payment_methods' then source_table := 'public.payment_methods'; source_predicate := 'organization_id = $1';
    when 'sales' then source_table := 'public.sales'; source_predicate := 'organization_id = $1';
    when 'sale_items' then source_table := 'public.sale_items'; source_predicate := 'organization_id = $1';
    when 'payments' then source_table := 'public.payments'; source_predicate := 'organization_id = $1';
    when 'receipts' then source_table := 'public.receipts'; source_predicate := 'organization_id = $1';
    when 'refunds' then source_table := 'public.refunds'; source_predicate := 'organization_id = $1';
    when 'inventory_movements' then source_table := 'public.inventory_movements'; source_predicate := 'organization_id = $1';
    when 'purchase_orders' then source_table := 'public.purchase_orders'; source_predicate := 'organization_id = $1';
    when 'stock_transfers' then source_table := 'public.stock_transfers'; source_predicate := 'organization_id = $1';
    when 'offline_sync_events' then source_table := 'public.offline_sync_events'; source_predicate := 'organization_id = $1';
    else
      raise exception 'Unsupported organization export section.' using errcode = '22023';
  end case;

  execute format(
    'select coalesce(jsonb_agg(to_jsonb(export_row)), ''[]''::jsonb)
       from (
         select *
         from %s
         where %s
           and ($2::uuid is null or id > $2::uuid)
         order by id
         limit 250
       ) export_row',
    source_table,
    source_predicate
  )
  into export_rows
  using export_session.organization_id, target_after_id;

  if jsonb_array_length(export_rows) = 250 then
    next_after_id := (export_rows -> 249 ->> 'id')::uuid;
  end if;

  return jsonb_build_object(
    'records', export_rows,
    'next_after_id', next_after_id
  );
end;
$_$;


ALTER FUNCTION "public"."get_organization_export_page"("target_export_session_id" "uuid", "target_section" "text", "target_after_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "get_organization_export_page"("target_export_session_id" "uuid", "target_section" "text", "target_after_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_organization_export_page"("target_export_session_id" "uuid", "target_section" "text", "target_after_id" "uuid") IS 'Streams a rate-limited, owner/admin-authorized organization export in fixed keyset pages without cross-tenant table access.';


--
-- Name: get_organization_readiness_access("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_organization_readiness_access"("target_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not private.has_organization_membership(target_organization_id) then
    raise exception 'You do not have access to this organization.' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'can_export', private.has_organization_export_access(target_organization_id),
    'can_manage_lifecycle', private.has_organization_lifecycle_access(target_organization_id),
    'can_view_recovery', private.has_organization_recovery_view_access(target_organization_id),
    'can_manage_recovery', private.has_organization_recovery_manage_access(target_organization_id)
  );
end;
$$;


ALTER FUNCTION "public"."get_organization_readiness_access"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "get_organization_readiness_access"("target_organization_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_organization_readiness_access"("target_organization_id" "uuid") IS 'Returns only tenant lifecycle/export capability flags for the current member; normal operational data remains inaccessible while suspended or archived.';


--
-- Name: get_organization_recovery_snapshot("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_organization_recovery_snapshot"("target_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  governance private.organization_data_governance%rowtype;
  latest_export public.organization_export_sessions%rowtype;
  latest_drill private.organization_recovery_drills%rowtype;
  archive_export_is_current boolean;
  organization_record public.organizations%rowtype;
begin
  if not private.has_organization_recovery_view_access(target_organization_id) then
    raise exception 'You do not have permission to view backup and recovery readiness.' using errcode = '42501';
  end if;

  select organization.*
  into organization_record
  from public.organizations organization
  where organization.id = target_organization_id;

  if not found then
    raise exception 'Organization was not found.' using errcode = 'P0002';
  end if;

  select *
  into governance
  from private.organization_data_governance
  where organization_id = target_organization_id;

  select *
  into latest_export
  from public.organization_export_sessions export_session
  where export_session.organization_id = target_organization_id
    and export_session.delivered_at is not null
  order by export_session.delivered_at desc
  limit 1;

  select *
  into latest_drill
  from private.organization_recovery_drills drill
  where drill.organization_id = target_organization_id
  order by drill.created_at desc
  limit 1;

  archive_export_is_current := organization_record.archive_requested_at is null
    or exists (
      select 1
      from public.organization_export_sessions export_session
      where export_session.organization_id = target_organization_id
        and export_session.delivered_at is not null
        and export_session.delivered_at >= organization_record.archive_requested_at
    );

  return jsonb_build_object(
    'governance', jsonb_build_object(
      'audit_retention_days', governance.audit_retention_days,
      'archived_data_retention_days', governance.archived_data_retention_days,
      'automatic_purge_enabled', governance.automatic_purge_enabled
    ),
    'latest_delivered_export', case
      when latest_export.id is null then null
      else jsonb_build_object(
        'delivered_at', latest_export.delivered_at,
        'record_count', latest_export.delivered_record_count,
        'format', latest_export.delivery_manifest ->> 'format'
      )
    end,
    'latest_recovery_drill', case
      when latest_drill.id is null then null
      else jsonb_build_object(
        'drill_type', latest_drill.drill_type,
        'outcome', latest_drill.outcome,
        'recovery_point_at', latest_drill.recovery_point_at,
        'duration_minutes', latest_drill.duration_minutes,
        'notes', latest_drill.notes,
        'recorded_at', latest_drill.created_at
      )
    end,
    'archive_export_is_current', archive_export_is_current
  );
end;
$$;


ALTER FUNCTION "public"."get_organization_recovery_snapshot"("target_organization_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "get_organization_recovery_snapshot"("target_organization_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_organization_recovery_snapshot"("target_organization_id" "uuid") IS 'Returns only authorized tenant backup, recovery-drill, and retention readiness summary.';


--
-- Name: get_organization_usage_snapshot("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_organization_usage_snapshot"("target_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  organization_timezone text;
  target_usage_date date;
  target_day_start timestamptz;
  target_day_end timestamptz;
  usage_record public.organization_usage_daily%rowtype;
begin
  if not private.has_organization_export_access(target_organization_id) then
    raise exception 'You do not have permission to view organization usage.' using errcode = '42501';
  end if;

  select organization.timezone
  into organization_timezone
  from public.organizations organization
  where organization.id = target_organization_id;

  if organization_timezone is null then
    raise exception 'Organization was not found.' using errcode = 'P0002';
  end if;

  target_usage_date := (now() at time zone organization_timezone)::date;
  target_day_start := target_usage_date::timestamp at time zone organization_timezone;
  target_day_end := target_day_start + interval '1 day';

  insert into public.organization_usage_daily (
    organization_id,
    usage_date,
    active_store_count,
    active_employee_count,
    active_product_count,
    customer_count,
    completed_sale_count,
    completed_sales_total_minor,
    pending_offline_sync_count,
    captured_at
  )
  values (
    target_organization_id,
    target_usage_date,
    (select count(*)::integer from public.stores where organization_id = target_organization_id and is_active),
    (select count(*)::integer from public.employees where organization_id = target_organization_id and status = 'active'),
    (select count(*)::integer from public.products where organization_id = target_organization_id and status = 'active'),
    (select count(*)::integer from public.customers where organization_id = target_organization_id and status = 'active'),
    (select count(*)::integer from public.sales where organization_id = target_organization_id and completed_at >= target_day_start and completed_at < target_day_end),
    (select coalesce(sum(total_minor), 0) from public.sales where organization_id = target_organization_id and completed_at >= target_day_start and completed_at < target_day_end),
    (select count(*)::integer from public.offline_sync_events where organization_id = target_organization_id and state in ('LOCAL_PENDING', 'SYNCING', 'CONFLICT', 'FAILED')),
    now()
  )
  on conflict (organization_id, usage_date)
  do update set
    active_store_count = excluded.active_store_count,
    active_employee_count = excluded.active_employee_count,
    active_product_count = excluded.active_product_count,
    customer_count = excluded.customer_count,
    completed_sale_count = excluded.completed_sale_count,
    completed_sales_total_minor = excluded.completed_sales_total_minor,
    pending_offline_sync_count = excluded.pending_offline_sync_count,
    captured_at = excluded.captured_at
  returning * into usage_record;

  return jsonb_build_object(
    'usage_date', usage_record.usage_date,
    'active_store_count', usage_record.active_store_count,
    'active_employee_count', usage_record.active_employee_count,
    'active_product_count', usage_record.active_product_count,
    'customer_count', usage_record.customer_count,
    'completed_sale_count', usage_record.completed_sale_count,
    'completed_sales_total_minor', usage_record.completed_sales_total_minor,
    'pending_offline_sync_count', usage_record.pending_offline_sync_count,
    'captured_at', usage_record.captured_at
  );
end;
$$;


ALTER FUNCTION "public"."get_organization_usage_snapshot"("target_organization_id" "uuid") OWNER TO "postgres";

