COMMENT ON FUNCTION "public"."get_pos_recent_items"("target_organization_id" "uuid", "target_store_id" "uuid", "target_limit" integer) IS 'Returns current saleable items most recently completed at the caller’s assigned POS store.';


--
-- Name: get_pos_shift_operational_summary("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_pos_shift_operational_summary"("target_organization_id" "uuid", "target_shift_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  shift_record public.shifts%rowtype;
  cash_record record;
  opened_by_name text;
  store_name text;
  register_name text;
  show_expected_before_close boolean := true;
  gross_sales_minor bigint := 0;
  refunds_minor bigint := 0;
  discounts_minor bigint := 0;
  expected_cash_minor bigint := 0;
begin
  if target_organization_id is null or target_shift_id is null then
    raise exception 'The POS shift summary request is invalid.' using errcode = '23514';
  end if;

  if (select auth.uid()) is null then
    raise exception 'Sign in is required to view a shift summary.' using errcode = '42501';
  end if;

  select shift.*
  into shift_record
  from public.shifts shift
  where shift.id = target_shift_id
    and shift.organization_id = target_organization_id;

  if shift_record.id is null then
    raise exception 'The shift was not found.' using errcode = 'P0002';
  end if;

  if not (select private.has_shift_access(target_organization_id, shift_record.store_id)) then
    raise exception 'Shift access is required.' using errcode = '42501';
  end if;

  select coalesce(profile.full_name, profile.email, 'Employee')
  into opened_by_name
  from public.employees employee
  join public.profiles profile on profile.id = employee.profile_id
  where employee.id = shift_record.opened_by_employee_id
    and employee.organization_id = target_organization_id;

  select store.name into store_name
  from public.stores store
  where store.id = shift_record.store_id
    and store.organization_id = target_organization_id;

  select register.name into register_name
  from public.registers register
  where register.id = shift_record.register_id
    and register.organization_id = target_organization_id;

  select * into cash_record from private.calculate_shift_cash(shift_record.id);
  select organization.show_expected_cash_before_close
  into show_expected_before_close
  from public.organizations organization
  where organization.id = target_organization_id;

  select
    coalesce(sum(sale.subtotal_minor), 0)::bigint,
    coalesce(sum(sale.discount_minor), 0)::bigint
  into gross_sales_minor, discounts_minor
  from public.sales sale
  where sale.organization_id = target_organization_id
    and sale.shift_id = shift_record.id;

  select coalesce(sum(refund.total_minor), 0)::bigint
  into refunds_minor
  from public.refunds refund
  where refund.organization_id = target_organization_id
    and refund.shift_id = shift_record.id;

  expected_cash_minor := case
    when shift_record.status = 'open' and not coalesce(show_expected_before_close, true) then null
    else cash_record.expected_cash_minor
  end;

  return jsonb_build_object(
    'shift', jsonb_build_object(
      'id', shift_record.id,
      'number', 'SHIFT-' || upper(left(shift_record.id::text, 8)),
      'status', shift_record.status,
      'openedBy', coalesce(opened_by_name, 'Employee'),
      'openedAt', shift_record.opened_at,
      'closedAt', shift_record.closed_at,
      'store', coalesce(store_name, 'Store'),
      'register', coalesce(register_name, 'Register'),
      'startingCashMinor', shift_record.opening_cash_minor,
      'actualCashMinor', shift_record.counted_cash_minor,
      'differenceMinor', shift_record.difference_minor
    ),
    'cash', jsonb_build_object(
      'cashPaymentsMinor', cash_record.cash_sales_minor,
      'cashRefundsMinor', cash_record.cash_refunds_minor,
      'paidInMinor', cash_record.pay_ins_minor,
      'paidOutMinor', cash_record.pay_outs_minor,
      'expectedCashMinor', expected_cash_minor
    ),
    'sales', jsonb_build_object(
      'grossSalesMinor', gross_sales_minor,
      'refundsMinor', refunds_minor,
      'discountsMinor', discounts_minor,
      'netSalesMinor', gross_sales_minor - refunds_minor - discounts_minor
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_pos_shift_operational_summary"("target_organization_id" "uuid", "target_shift_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "get_pos_shift_operational_summary"("target_organization_id" "uuid", "target_shift_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_pos_shift_operational_summary"("target_organization_id" "uuid", "target_shift_id" "uuid") IS 'Server-derived POS shift, cash-drawer, and sales summary for authorized assigned-store shift users. Blind cash remains hidden while a blind-count shift is open.';


--
-- Name: get_pos_ticket_assignees("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_pos_ticket_assignees"("target_organization_id" "uuid", "target_store_id" "uuid") RETURNS TABLE("employee_id" "uuid", "full_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.require_pos_workspace_access(target_organization_id, target_store_id);

  if not (select private.has_permission(target_organization_id, 'employees.manage')) then
    raise exception 'Employee management permission is required to assign tickets.' using errcode = '42501';
  end if;

  return query
  select
    employee.id,
    coalesce(nullif(btrim(profile.full_name), ''), profile.email)
  from public.employees employee
  join public.employee_stores employee_store
    on employee_store.employee_id = employee.id
   and employee_store.organization_id = employee.organization_id
  join public.profiles profile on profile.id = employee.profile_id
  where employee.organization_id = target_organization_id
    and employee_store.store_id = target_store_id
    and employee.status = 'active'
  order by lower(coalesce(nullif(btrim(profile.full_name), ''), profile.email)), employee.id;
end;
$$;


ALTER FUNCTION "public"."get_pos_ticket_assignees"("target_organization_id" "uuid", "target_store_id" "uuid") OWNER TO "postgres";

--
-- Name: get_public_smart_menu("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."get_public_smart_menu"("target_menu_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'menu_id', menu.id,
    'business_name', organization.name,
    'store_name', store.name,
    'currency_code', organization.currency_code,
    'show_prices', menu.show_prices,
    'show_images', menu.show_images,
    'show_variants', menu.show_variants,
    'show_modifiers', menu.show_modifiers,
    'categories', coalesce(
      (
        select jsonb_agg(category_payload order by category_sort_order, lower(category_name))
        from (
          select
            menu_category.sort_order as category_sort_order,
            category.name as category_name,
            jsonb_build_object(
              'id', category.id,
              'name', category.name,
              'products', coalesce(
                (
                  select jsonb_agg(product_payload order by product_sort_order, lower(product_name))
                  from (
                    select
                      menu_product.sort_order as product_sort_order,
                      product.name as product_name,
                      jsonb_build_object(
                        'id', product.id,
                        'name', product.name,
                        'description', product.description,
                        'image_url', case when menu.show_images then product.image_url else null end,
                        'price_minor', case
                          when menu.show_prices then coalesce(store_setting.price_override_minor, product.price_minor)
                          else null
                        end,
                        'is_variable_price', product.is_variable_price,
                        'available', store_setting.is_available,
                        'variants', case
                          when menu.show_variants then coalesce(
                            (
                              select jsonb_agg(
                                jsonb_build_object(
                                  'id', variant.id,
                                  'name', variant.name,
                                  'price_minor', case when menu.show_prices then variant.price_minor else null end
                                )
                                order by variant.sort_order, lower(variant.name)
                              )
                              from public.product_variants variant
                              where variant.organization_id = menu.organization_id
                                and variant.product_id = product.id
                                and variant.is_active
                            ),
                            '[]'::jsonb
                          )
                          else '[]'::jsonb
                        end,
                        'modifier_groups', case
                          when menu.show_modifiers then coalesce(
                            (
                              select jsonb_agg(
                                jsonb_build_object(
                                  'id', modifier_group.id,
                                  'name', modifier_group.name,
                                  'min_selections', modifier_group.min_selections,
                                  'max_selections', modifier_group.max_selections,
                                  'options', coalesce(
                                    (
                                      select jsonb_agg(
                                        jsonb_build_object(
                                          'id', modifier_option.id,
                                          'name', modifier_option.name,
                                          'price_minor', case when menu.show_prices then modifier_option.price_adjustment_minor else null end
                                        )
                                        order by modifier_option.sort_order, lower(modifier_option.name)
                                      )
                                      from public.modifier_options modifier_option
                                      where modifier_option.organization_id = menu.organization_id
                                        and modifier_option.modifier_group_id = modifier_group.id
                                        and modifier_option.is_active
                                    ),
                                    '[]'::jsonb
                                  )
                                )
                                order by assignment.sort_order, lower(modifier_group.name)
                              )
                              from public.product_modifier_groups assignment
                              join public.modifier_groups modifier_group
                                on modifier_group.id = assignment.modifier_group_id
                               and modifier_group.organization_id = assignment.organization_id
                               and modifier_group.is_active
                              where assignment.organization_id = menu.organization_id
                                and assignment.product_id = product.id
                            ),
                            '[]'::jsonb
                          )
                          else '[]'::jsonb
                        end
                      ) as product_payload
                    from public.smart_menu_products menu_product
                    join public.products product
                      on product.id = menu_product.product_id
                     and product.organization_id = menu_product.organization_id
                     and product.status = 'active'
                     and not product.is_composite
                     and product.category_id = category.id
                    join public.product_store_settings store_setting
                      on store_setting.organization_id = product.organization_id
                     and store_setting.product_id = product.id
                     and store_setting.store_id = menu.store_id
                    where menu_product.smart_menu_id = menu.id
                      and (menu.show_unavailable or store_setting.is_available)
                  ) selected_products
                ),
                '[]'::jsonb
              )
            ) as category_payload
          from public.smart_menu_categories menu_category
          join public.categories category
            on category.id = menu_category.category_id
           and category.organization_id = menu_category.organization_id
           and not category.is_archived
          where menu_category.smart_menu_id = menu.id
            and exists (
              select 1
              from public.smart_menu_products menu_product
              join public.products product
                on product.id = menu_product.product_id
               and product.organization_id = menu_product.organization_id
               and product.status = 'active'
               and not product.is_composite
               and product.category_id = category.id
              join public.product_store_settings store_setting
                on store_setting.organization_id = product.organization_id
               and store_setting.product_id = product.id
               and store_setting.store_id = menu.store_id
              where menu_product.smart_menu_id = menu.id
                and (menu.show_unavailable or store_setting.is_available)
            )
        ) selected_categories
      ),
      '[]'::jsonb
    )
  )
  from public.smart_menus menu
  join public.organizations organization
    on organization.id = menu.organization_id
   and organization.status = 'active'
  join public.stores store
    on store.id = menu.store_id
   and store.organization_id = menu.organization_id
   and store.is_active
  where menu.id = target_menu_id
    and menu.is_enabled;
$$;


