--
-- Name: import_inventory_adjustments_csv("uuid", "uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."import_inventory_adjustments_csv"("target_organization_id" "uuid", "target_store_id" "uuid", "target_reason_code" "text", "target_rows" "jsonb") RETURNS integer
    LANGUAGE "sql"
