--
-- Name: merge_open_tickets("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."merge_open_tickets"("target_organization_id" "uuid", "target_source_ticket_id" "uuid", "target_destination_ticket_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source_ticket public.open_tickets%rowtype;
  actor_employee_id uuid;
  source_lines jsonb;
  moved_line_count integer;
begin
  if target_source_ticket_id is null
    or target_destination_ticket_id is null
    or target_source_ticket_id = target_destination_ticket_id then
    raise exception 'Choose two distinct open tickets to merge.' using errcode = '23514';
  end if;

  select ticket.* into source_ticket
  from public.open_tickets ticket
  where ticket.id = target_source_ticket_id
    and ticket.organization_id = target_organization_id
    and ticket.status = 'open'
  for update;

  if source_ticket.id is null then
    raise exception 'The source ticket is no longer open.' using errcode = 'P0002';
  end if;

  actor_employee_id := private.require_active_pos_shift(
    target_organization_id,
    source_ticket.store_id,
    source_ticket.register_id
  );

  select jsonb_agg(
    jsonb_build_object(
      'ticket_line_id', line.value ->> 'ticket_line_id',
      'quantity', line.value -> 'quantity'
    )
    order by line.ordinality
  )
  into source_lines
  from jsonb_array_elements(source_ticket.cart) with ordinality line(value, ordinality);

  moved_line_count := private.reallocate_open_ticket_lines(
    target_organization_id,
    target_source_ticket_id,
    target_destination_ticket_id,
    source_lines,
    true,
    false
  );

  update public.open_tickets ticket
  set status = 'merged', merged_into_ticket_id = target_destination_ticket_id
  where ticket.id = target_source_ticket_id
    and ticket.organization_id = target_organization_id;

  perform private.write_audit_log(
    target_organization_id,
    'OPEN_TICKETS_MERGED',
    'ticket.merge',
    actor_employee_id,
    null,
    source_ticket.store_id,
    source_ticket.register_id,
    null,
    null,
    null,
    jsonb_build_object(
      'source_ticket_id', target_source_ticket_id,
      'destination_ticket_id', target_destination_ticket_id,
      'moved_line_count', moved_line_count
    )
  );
end;
$$;


ALTER FUNCTION "public"."merge_open_tickets"("target_organization_id" "uuid", "target_source_ticket_id" "uuid", "target_destination_ticket_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "merge_open_tickets"("target_organization_id" "uuid", "target_source_ticket_id" "uuid", "target_destination_ticket_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."merge_open_tickets"("target_organization_id" "uuid", "target_source_ticket_id" "uuid", "target_destination_ticket_id" "uuid") IS 'Moves all source ticket lines into a destination ticket, preserves the source as merged, and records an audit event.';


--
-- Name: move_open_ticket_lines("uuid", "uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."move_open_ticket_lines"("target_organization_id" "uuid", "target_source_ticket_id" "uuid", "target_destination_ticket_id" "uuid", "target_lines" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  source_ticket public.open_tickets%rowtype;
  actor_employee_id uuid;
  moved_line_count integer;
begin
  select ticket.* into source_ticket
  from public.open_tickets ticket
  where ticket.id = target_source_ticket_id
    and ticket.organization_id = target_organization_id;

  if source_ticket.id is null then
    raise exception 'The source ticket was not found.' using errcode = 'P0002';
  end if;

  actor_employee_id := private.require_active_pos_shift(
    target_organization_id,
    source_ticket.store_id,
    source_ticket.register_id
  );
  moved_line_count := private.reallocate_open_ticket_lines(
    target_organization_id,
    target_source_ticket_id,
    target_destination_ticket_id,
    target_lines,
    false,
    false
  );

  perform private.write_audit_log(
    target_organization_id,
    'OPEN_TICKET_LINES_MOVED',
    'ticket.move',
    actor_employee_id,
    null,
    source_ticket.store_id,
    source_ticket.register_id,
    null,
    null,
    null,
    jsonb_build_object(
      'source_ticket_id', target_source_ticket_id,
      'destination_ticket_id', target_destination_ticket_id,
      'moved_line_count', moved_line_count
    )
  );
end;
$$;


ALTER FUNCTION "public"."move_open_ticket_lines"("target_organization_id" "uuid", "target_source_ticket_id" "uuid", "target_destination_ticket_id" "uuid", "target_lines" "jsonb") OWNER TO "postgres";

