-- Name: FUNCTION "move_open_ticket_lines"("target_organization_id" "uuid", "target_source_ticket_id" "uuid", "target_destination_ticket_id" "uuid", "target_lines" "jsonb"); Type: COMMENT; Schema: public; Owner: postgres
