--
-- Name: record_cash_movement("uuid", "uuid", "text", bigint, "text", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."record_cash_movement"("target_organization_id" "uuid", "target_shift_id" "uuid", "target_movement_type" "text", "target_amount_minor" bigint, "target_reason" "text", "target_idempotency_key" "uuid", "target_approval_request_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("cash_movement_id" "uuid", "created_at" timestamp with time zone, "was_replayed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  expected_payload jsonb;
begin
  expected_payload := jsonb_build_object(
    'shift_id', target_shift_id,
    'movement_type', target_movement_type,
    'amount_minor', target_amount_minor,
    'reason', trim(coalesce(target_reason, ''))
  );

  if target_movement_type = 'PAY_OUT' then
    perform private.authorize_sensitive_operation(
      target_organization_id,
      'cash.pay_out',
      target_approval_request_id,
      expected_payload,
      target_idempotency_key
    );
  end if;

  return query
  select * from private.record_cash_movement(
    target_organization_id,
    target_shift_id,
    target_movement_type,
    target_amount_minor,
    target_reason,
    target_idempotency_key
  );
end;
$$;


