--
-- Name: refund_sale("uuid", "uuid", "uuid", "uuid", "text", "text", "jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."refund_sale"("target_organization_id" "uuid", "target_sale_id" "uuid", "target_payment_method_id" "uuid", "target_idempotency_key" "uuid", "target_reason" "text", "target_reference_number" "text", "target_items" "jsonb", "target_approval_request_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("refund_id" "uuid", "refund_number" bigint, "total_minor" bigint, "was_replayed" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  expected_payload jsonb;
  target_receipt_id uuid;
  target_receipt_number bigint;
begin
  select receipt.id, receipt.receipt_number
  into target_receipt_id, target_receipt_number
  from public.receipts receipt
  where receipt.organization_id = target_organization_id
    and receipt.sale_id = target_sale_id;

  expected_payload := jsonb_build_object(
    'items', target_items,
    'payment_method_id', target_payment_method_id,
    'reason', trim(coalesce(target_reason, '')),
    'receipt_id', target_receipt_id,
    'receipt_number', target_receipt_number,
    'reference_number', nullif(trim(coalesce(target_reference_number, '')), ''),
    'sale_id', target_sale_id
  );

  perform private.authorize_sensitive_operation(
    target_organization_id,
    'sales.refund',
    target_approval_request_id,
    expected_payload,
    target_idempotency_key
  );

  return query select * from private.refund_sale(
    target_organization_id,
    target_sale_id,
    target_payment_method_id,
    target_idempotency_key,
    target_reason,
    target_reference_number,
    target_items
  );
end;
$$;


