--
-- Name: FUNCTION "refund_sale"("target_organization_id" "uuid", "target_sale_id" "uuid", "target_payment_method_id" "uuid", "target_idempotency_key" "uuid", "target_reason" "text", "target_reference_number" "text", "target_items" "jsonb", "target_approval_request_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."refund_sale"("target_organization_id" "uuid", "target_sale_id" "uuid", "target_payment_method_id" "uuid", "target_idempotency_key" "uuid", "target_reason" "text", "target_reference_number" "text", "target_items" "jsonb", "target_approval_request_id" "uuid") IS 'Atomically records an authorized partial or full sale refund, restores tracked stock only for refund lines marked returned_to_stock (default true), and replays the same idempotency key safely.';


--
-- Name: register_pos_device("uuid", "uuid", "uuid", "uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."register_pos_device"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid", "target_device_id" "uuid", "target_name" "text", "target_app_version" "text", "target_secret" "text") RETURNS TABLE("device_id" "uuid", "store_id" "uuid", "register_id" "uuid", "status" "text", "last_seen_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_employee_id uuid;
  normalized_name text;
  normalized_app_version text;
begin
  actor_employee_id := private.require_device_manager(target_organization_id);
  perform private.require_active_device_binding(
    target_organization_id,
    target_store_id,
    target_register_id
  );

  normalized_name := left(trim(coalesce(target_name, '')), 80);
  normalized_app_version := left(trim(coalesce(target_app_version, '')), 80);

  if target_device_id is null
    or normalized_name !~ '^.{2,80}$'
    or normalized_app_version !~ '^.{1,80}$'
    or target_secret is null
    or target_secret !~ '^[0-9A-Fa-f]{64}$' then
    raise exception 'The device name, application version, or secure credential is invalid.'
      using errcode = '23514';
  end if;

  insert into public.pos_devices (
    id,
    organization_id,
    store_id,
    register_id,
    name,
    status,
    app_version,
    registered_by_employee_id,
    last_seen_at
  )
  values (
    target_device_id,
    target_organization_id,
    target_store_id,
    target_register_id,
    normalized_name,
    'active',
    normalized_app_version,
    actor_employee_id,
    now()
  );

  insert into private.pos_device_credentials (device_id, secret_hash)
  values (target_device_id, extensions.digest(target_secret, 'sha256'));

  perform set_config('tindio.device_management_change', 'authorized', true);
  update public.organizations organization
  set device_management_enabled = true
  where organization.id = target_organization_id;

  perform private.write_audit_log(
    target_organization_id,
    'DEVICE_REGISTERED',
    'devices.register',
    actor_employee_id,
    null,
    target_store_id,
    target_register_id,
    null,
    null,
    null,
    jsonb_build_object('device_id', target_device_id, 'device_name', normalized_name, 'app_version', normalized_app_version)
  );

  return query
  select device.id, device.store_id, device.register_id, device.status, device.last_seen_at
  from public.pos_devices device
  where device.id = target_device_id;
end;
$_$;


ALTER FUNCTION "public"."register_pos_device"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid", "target_device_id" "uuid", "target_name" "text", "target_app_version" "text", "target_secret" "text") OWNER TO "postgres";

