--
-- Name: save_open_ticket_v2("uuid", "uuid", "uuid", "uuid", "uuid", "uuid", "uuid", "text", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."save_open_ticket_v2"("target_organization_id" "uuid", "target_store_id" "uuid", "target_register_id" "uuid", "target_ticket_id" "uuid", "target_customer_id" "uuid", "target_dining_option_id" "uuid", "target_assigned_employee_id" "uuid", "target_label" "text", "target_note" "text", "target_cart" "jsonb") RETURNS TABLE("ticket_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
