ALTER FUNCTION "public"."set_kitchen_station_category_route"("target_organization_id" "uuid", "target_category_id" "uuid", "target_station" "text") OWNER TO "postgres";

--
-- Name: set_payment_method_offline_policy("uuid", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_payment_method_offline_policy"("target_organization_id" "uuid", "target_payment_method_id" "uuid", "target_offline_policy" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  selected_payment_type text;
  normalized_policy text := lower(nullif(btrim(coalesce(target_offline_policy, '')), ''));
begin
  if target_organization_id is null
    or target_payment_method_id is null
    or normalized_policy not in ('disabled', 'cash', 'manual_external') then
    raise exception 'Choose a valid offline payment policy.' using errcode = '23514';
  end if;

  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'settings.manage')) then
    raise exception 'Settings permission is required to change offline payment policies.'
      using errcode = '42501';
  end if;

  select payment_method.payment_type
  into selected_payment_type
  from public.payment_methods payment_method
  where payment_method.id = target_payment_method_id
    and payment_method.organization_id = target_organization_id
  for update;

  if selected_payment_type is null then
    raise exception 'The payment method was not found in this organization.' using errcode = 'P0002';
  end if;

  if normalized_policy = 'cash' and selected_payment_type <> 'CASH' then
    raise exception 'Only cash methods can be settled automatically while offline.' using errcode = '23514';
  end if;

  if normalized_policy = 'manual_external' and selected_payment_type = 'CASH' then
    raise exception 'Cash methods use either the cash policy or disabled policy.' using errcode = '23514';
  end if;

  update public.payment_methods payment_method
  set offline_policy = normalized_policy
  where payment_method.id = target_payment_method_id
    and payment_method.organization_id = target_organization_id;

  return true;
end;
$$;


ALTER FUNCTION "public"."set_payment_method_offline_policy"("target_organization_id" "uuid", "target_payment_method_id" "uuid", "target_offline_policy" "text") OWNER TO "postgres";

--
-- Name: set_pos_favorite_tile("uuid", "uuid", "uuid", "uuid", boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."set_pos_favorite_tile"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_is_favorite" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_employee_id uuid;
  next_position integer;
begin
  actor_employee_id := private.require_pos_workspace_access(
    target_organization_id,
    target_store_id
  );

  if not (select private.has_permission(target_organization_id, 'products.manage')) then
    raise exception 'Product management permission is required to configure POS tiles.'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.products product
    join public.product_store_settings setting
      on setting.organization_id = product.organization_id
     and setting.store_id = target_store_id
     and setting.product_id = product.id
     and setting.is_available
    left join public.product_variants variant
      on variant.id = target_variant_id
     and variant.product_id = product.id
     and variant.organization_id = product.organization_id
     and variant.is_active
    where product.id = target_product_id
      and product.organization_id = target_organization_id
      and product.status = 'active'
      and (
        (target_variant_id is null and product.product_type = 'simple')
        or (target_variant_id is not null and product.product_type = 'variable' and variant.id is not null)
      )
  ) then
    raise exception 'Only active, saleable products can be pinned to POS favorites.'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtext(target_organization_id::text || ':' || target_store_id::text));

  if target_is_favorite then
    if not exists (
      select 1
      from public.pos_favorite_tiles favorite
      where favorite.organization_id = target_organization_id
        and favorite.store_id = target_store_id
        and favorite.product_id = target_product_id
        and favorite.variant_id is not distinct from target_variant_id
    ) then
      select candidate.position
      into next_position
      from generate_series(1, 24) as candidate(position)
      where not exists (
        select 1
        from public.pos_favorite_tiles favorite
        where favorite.organization_id = target_organization_id
          and favorite.store_id = target_store_id
          and favorite.position = candidate.position
      )
      order by candidate.position
      limit 1;

      if next_position is null then
        raise exception 'A POS workspace can contain up to 24 favorite tiles.' using errcode = '22023';
      end if;

      insert into public.pos_favorite_tiles (
        organization_id,
        store_id,
        product_id,
        variant_id,
        position,
        created_by_employee_id
      ) values (
        target_organization_id,
        target_store_id,
        target_product_id,
        target_variant_id,
        next_position,
        actor_employee_id
      );
    end if;

    return true;
  end if;

  delete from public.pos_favorite_tiles favorite
  where favorite.organization_id = target_organization_id
    and favorite.store_id = target_store_id
    and favorite.product_id = target_product_id
    and favorite.variant_id is not distinct from target_variant_id;

  return false;
end;
$$;


ALTER FUNCTION "public"."set_pos_favorite_tile"("target_organization_id" "uuid", "target_store_id" "uuid", "target_product_id" "uuid", "target_variant_id" "uuid", "target_is_favorite" boolean) OWNER TO "postgres";

