--
-- Name: validate_pos_device("uuid", "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."validate_pos_device"("target_organization_id" "uuid", "target_device_id" "uuid", "target_secret" "text", "target_app_version" "text") RETURNS TABLE("device_id" "uuid", "store_id" "uuid", "register_id" "uuid", "device_name" "text", "app_version" "text", "last_seen_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select auth.uid()) is null
    or not (select private.has_permission(target_organization_id, 'sales.create')) then
    raise exception 'Sales permission is required.' using errcode = '42501';
  end if;

  return query
  select verified.*
  from private.verify_pos_device_credential(
    target_organization_id,
    target_device_id,
    target_secret,
    target_app_version
  ) verified
  where exists (
    select 1
    from public.employees employee
    join public.employee_stores employee_store
      on employee_store.employee_id = employee.id
     and employee_store.organization_id = employee.organization_id
     and employee_store.store_id = verified.store_id
    where employee.organization_id = target_organization_id
      and employee.profile_id = (select auth.uid())
      and employee.status = 'active'
  );

  if not found then
    raise exception 'You are not assigned to this device store.' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "public"."validate_pos_device"("target_organization_id" "uuid", "target_device_id" "uuid", "target_secret" "text", "target_app_version" "text") OWNER TO "postgres";

--
-- Name: verify_loyalty_card_qr("uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION "public"."verify_loyalty_card_qr"("target_loyalty_card_id" "uuid", "target_verification_token" "text") RETURNS TABLE("verification_status" "text", "card_code" "text", "stamp_count" integer, "stamp_target" integer, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  card_record public.loyalty_cards%rowtype;
begin
  if target_verification_token !~ '^[a-f0-9]{64}$' then
    return query select 'invalid'::text, null::text, null::integer, null::integer, null::timestamptz;
    return;
  end if;

  select card.*
  into card_record
  from public.loyalty_cards card
  join public.customers customer
    on customer.id = card.customer_id
   and customer.organization_id = card.organization_id
  where card.id = target_loyalty_card_id
    and card.verification_token_hash = extensions.digest(target_verification_token, 'sha256')
    and customer.status = 'active';

  if card_record.id is null then
    return query select 'invalid'::text, null::text, null::integer, null::integer, null::timestamptz;
    return;
  end if;

  return query
  select
    case
      when card_record.expires_at is not null and card_record.expires_at <= now() then 'expired'
      when card_record.status = 'active' then 'valid'
      else card_record.status
    end,
    card_record.card_code,
    card_record.stamp_count,
    card_record.stamp_target,
    card_record.expires_at;
end;
$_$;


ALTER FUNCTION "public"."verify_loyalty_card_qr"("target_loyalty_card_id" "uuid", "target_verification_token" "text") OWNER TO "postgres";

