-- Name: inventory_counts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."inventory_counts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "store_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "note" "text",
    "started_by_employee_id" "uuid" NOT NULL,
    "completed_by_employee_id" "uuid",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "count_number" bigint DEFAULT "nextval"('"private"."inventory_count_number_sequence"'::"regclass") NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "count_mode" "text" DEFAULT 'standard'::"text" NOT NULL,
    "scope_type" "text" DEFAULT 'selected'::"text" NOT NULL,
    "scope_reference_id" "uuid",
    "scope_selection" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "sort_mode" "text" DEFAULT 'category_name'::"text" NOT NULL,
    "include_zero_stock" boolean DEFAULT true NOT NULL,
    "post_operation_id" "uuid",
    CONSTRAINT "inventory_counts_completion_state" CHECK (((("status" = ANY (ARRAY['posted'::"text", 'completed'::"text"])) AND ("completed_by_employee_id" IS NOT NULL) AND ("completed_at" IS NOT NULL)) OR ("status" <> ALL (ARRAY['posted'::"text", 'completed'::"text"])))),
    CONSTRAINT "inventory_counts_count_mode_values" CHECK (("count_mode" = ANY (ARRAY['standard'::"text", 'blind'::"text"]))),
