--
-- Name: inventory_movements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."inventory_movements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "store_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "variant_id" "uuid",
    "quantity_delta" numeric(14,3) NOT NULL,
    "quantity_before" numeric(14,3) NOT NULL,
    "quantity_after" numeric(14,3) NOT NULL,
    "movement_type" "text" NOT NULL,
    "actor_employee_id" "uuid" NOT NULL,
    "reason" "text" NOT NULL,
    "source_type" "text",
    "source_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "unit_cost_minor" bigint DEFAULT 0 NOT NULL,
    "value_delta_minor" bigint DEFAULT 0 NOT NULL,
    "reason_code" "text",
    "unit_snapshot" "text" NOT NULL,
    "operation_id" "uuid" NOT NULL,
    "cost_is_known" boolean DEFAULT false NOT NULL,
    CONSTRAINT "inventory_movements_balance_math" CHECK (("quantity_after" = ("quantity_before" + "quantity_delta"))),
    CONSTRAINT "inventory_movements_delta_nonzero" CHECK (("quantity_delta" <> (0)::numeric)),
    CONSTRAINT "inventory_movements_reason_length" CHECK ((("char_length"("reason") >= 2) AND ("char_length"("reason") <= 500))),
    CONSTRAINT "inventory_movements_source_pair" CHECK (((("source_type" IS NULL) AND ("source_id" IS NULL)) OR (("source_type" IS NOT NULL) AND ("source_id" IS NOT NULL)))),
    CONSTRAINT "inventory_movements_source_type_length" CHECK ((("source_type" IS NULL) OR (("char_length"("source_type") >= 2) AND ("char_length"("source_type") <= 40)))),
    CONSTRAINT "inventory_movements_type_values" CHECK (("movement_type" = ANY (ARRAY['OPENING_STOCK'::"text", 'ADJUSTMENT'::"text", 'SALE'::"text", 'REFUND'::"text", 'RECEIPT'::"text", 'COUNT'::"text", 'TRANSFER_OUT'::"text", 'TRANSFER_IN'::"text", 'DAMAGE'::"text", 'LOSS'::"text", 'SUPPLIER_RETURN'::"text", 'PRODUCTION'::"text", 'DISASSEMBLY'::"text"]))),
    CONSTRAINT "inventory_movements_unit_cost_nonnegative" CHECK (("unit_cost_minor" >= 0)),
    CONSTRAINT "inventory_movements_unit_snapshot_length" CHECK ((("char_length"("btrim"("unit_snapshot")) >= 1) AND ("char_length"("btrim"("unit_snapshot")) <= 80)))
);


