--
-- Name: offline_sync_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."offline_sync_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "idempotency_key" "uuid" NOT NULL,
    "local_receipt_reference" "text" NOT NULL,
    "state" "text" NOT NULL,
    "conflict_type" "text",
    "failure_message" "text",
    "store_id" "uuid" NOT NULL,
    "register_id" "uuid" NOT NULL,
    "shift_id" "uuid",
    "device_id" "uuid",
    "employee_id" "uuid" NOT NULL,
    "store_name_snapshot" "text" NOT NULL,
    "register_name_snapshot" "text" NOT NULL,
    "device_name_snapshot" "text",
    "employee_name_snapshot" "text" NOT NULL,
    "local_created_at" timestamp with time zone,
    "last_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "attempt_count" integer DEFAULT 1 NOT NULL,
    "official_receipt_number" bigint,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "offline_sync_events_attempt_count_positive" CHECK (("attempt_count" > 0)),
    CONSTRAINT "offline_sync_events_conflict_type_values" CHECK ((("conflict_type" IS NULL) OR ("conflict_type" = ANY (ARRAY['DUPLICATE_TRANSACTION'::"text", 'INVALID_SHIFT'::"text", 'CLOSED_SHIFT'::"text", 'PRODUCT_ARCHIVED'::"text", 'PRICE_CHANGED'::"text", 'TAX_CHANGED'::"text", 'CUSTOMER_INVALID'::"text", 'INVENTORY_CONFLICT'::"text", 'PERMISSION_CHANGED'::"text", 'REGISTER_REVOKED'::"text", 'DEVICE_REVOKED'::"text"])))),
    CONSTRAINT "offline_sync_events_failure_state" CHECK (((("state" = ANY (ARRAY['CONFLICT'::"text", 'FAILED'::"text"])) AND ("conflict_type" IS NOT NULL) AND ("failure_message" IS NOT NULL)) OR ("state" <> ALL (ARRAY['CONFLICT'::"text", 'FAILED'::"text"])))),
    CONSTRAINT "offline_sync_events_local_receipt_reference_format" CHECK (("local_receipt_reference" ~ '^OFF-[A-Z0-9]{6,32}$'::"text")),
    CONSTRAINT "offline_sync_events_state_values" CHECK (("state" = ANY (ARRAY['LOCAL_PENDING'::"text", 'SYNCING'::"text", 'SYNCED'::"text", 'CONFLICT'::"text", 'FAILED'::"text"])))
);


ALTER TABLE "public"."offline_sync_events" OWNER TO "postgres";

--
-- Name: TABLE "offline_sync_events"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."offline_sync_events" IS 'Server-observed offline POS synchronization outcomes. Browser-local pending work is intentionally never uploaded before connectivity returns.';


