    "register_id" "uuid" NOT NULL,
    "opened_by_employee_id" "uuid" NOT NULL,
    "customer_id" "uuid",
    "dining_option_id" "uuid",
    "label" "text" NOT NULL,
    "note" "text",
    "cart" "jsonb" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "sale_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "assigned_employee_id" "uuid" NOT NULL,
    "merged_into_ticket_id" "uuid",
    CONSTRAINT "open_tickets_cart_array" CHECK ((("jsonb_typeof"("cart") = 'array'::"text") AND (("jsonb_array_length"("cart") >= 1) AND ("jsonb_array_length"("cart") <= 100)))),
    CONSTRAINT "open_tickets_completion_state" CHECK (((("status" = 'open'::"text") AND ("sale_id" IS NULL) AND ("merged_into_ticket_id" IS NULL)) OR (("status" = 'cancelled'::"text") AND ("sale_id" IS NULL) AND ("merged_into_ticket_id" IS NULL)) OR (("status" = 'completed'::"text") AND ("sale_id" IS NOT NULL) AND ("merged_into_ticket_id" IS NULL)) OR (("status" = 'merged'::"text") AND ("sale_id" IS NULL) AND ("merged_into_ticket_id" IS NOT NULL)))),
    CONSTRAINT "open_tickets_label_length" CHECK ((("char_length"("btrim"("label")) >= 1) AND ("char_length"("btrim"("label")) <= 100))),
    CONSTRAINT "open_tickets_note_length" CHECK ((("note" IS NULL) OR ("char_length"("note") <= 500))),
    CONSTRAINT "open_tickets_status_values" CHECK (("status" = ANY (ARRAY['open'::"text", 'completed'::"text", 'cancelled'::"text", 'merged'::"text"])))
);


