--

CREATE TABLE IF NOT EXISTS "public"."organizations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "currency_code" "text" DEFAULT 'PHP'::"text" NOT NULL,
    "timezone" "text" DEFAULT 'Asia/Manila'::"text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "show_expected_cash_before_close" boolean DEFAULT true NOT NULL,
    "business_type" "text" DEFAULT 'retail'::"text" NOT NULL,
    "device_management_enabled" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "suspended_at" timestamp with time zone,
    "suspension_reason" "text",
    "archive_requested_at" timestamp with time zone,
    "archive_requested_by_employee_id" "uuid",
    "archived_at" timestamp with time zone,
    CONSTRAINT "organizations_archived_at_requires_archived_status" CHECK (((("status" = 'archived'::"text") AND ("archived_at" IS NOT NULL)) OR (("status" <> 'archived'::"text") AND ("archived_at" IS NULL)))),
    CONSTRAINT "organizations_business_type_values" CHECK (("business_type" = ANY (ARRAY['retail'::"text", 'grocery'::"text", 'convenience_store'::"text", 'restaurant_cafe'::"text", 'bar'::"text", 'wholesale'::"text", 'service'::"text", 'other'::"text"]))),
    CONSTRAINT "organizations_currency_code_format" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "organizations_name_length" CHECK ((("char_length"("name") >= 2) AND ("char_length"("name") <= 160))),
    CONSTRAINT "organizations_status_values" CHECK (("status" = ANY (ARRAY['active'::"text", 'suspended'::"text", 'archived'::"text"]))),
    CONSTRAINT "organizations_suspension_reason_length" CHECK ((("suspension_reason" IS NULL) OR (("char_length"("suspension_reason") >= 3) AND ("char_length"("suspension_reason") <= 500)))),
    CONSTRAINT "organizations_timezone_length" CHECK ((("char_length"("timezone") >= 1) AND ("char_length"("timezone") <= 100)))
);


