    "requires_reference" boolean DEFAULT false NOT NULL,
    "sort_order" integer DEFAULT 100 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_loyalty_redemption" boolean DEFAULT false NOT NULL,
    "offline_policy" "text" DEFAULT 'disabled'::"text" NOT NULL,
    CONSTRAINT "payment_methods_code_format" CHECK (("code" ~ '^[A-Z][A-Z0-9_]{1,39}$'::"text")),
    CONSTRAINT "payment_methods_loyalty_redemption_shape" CHECK (((NOT "is_loyalty_redemption") OR (("code" = 'LOYALTY'::"text") AND ("payment_type" = 'VOUCHER'::"text")))),
    CONSTRAINT "payment_methods_name_length" CHECK ((("char_length"("name") >= 1) AND ("char_length"("name") <= 100))),
    CONSTRAINT "payment_methods_offline_policy_values" CHECK (("offline_policy" = ANY (ARRAY['disabled'::"text", 'cash'::"text", 'manual_external'::"text"]))),
    CONSTRAINT "payment_methods_sort_order_bounds" CHECK ((("sort_order" >= 0) AND ("sort_order" <= 100000))),
    CONSTRAINT "payment_methods_type_values" CHECK (("payment_type" = ANY (ARRAY['CASH'::"text", 'CARD'::"text", 'E_WALLET'::"text", 'BANK_TRANSFER'::"text", 'VOUCHER'::"text", 'OTHER'::"text"])))
);


