--
-- Name: payments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "sale_id" "uuid" NOT NULL,
    "amount_minor" bigint NOT NULL,
    "amount_tendered_minor" bigint,
    "change_given_minor" bigint,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "payment_method_id" "uuid" NOT NULL,
    "payment_method_name_snapshot" "text" NOT NULL,
    "payment_method_code_snapshot" "text" NOT NULL,
    "payment_method_type_snapshot" "text" NOT NULL,
    "reference_number" "text",
    "note" "text",
    CONSTRAINT "payments_amount_applied_positive" CHECK (("amount_minor" > 0)),
    CONSTRAINT "payments_cash_metadata_matches_type" CHECK (((("payment_method_type_snapshot" = 'CASH'::"text") AND ("amount_tendered_minor" IS NOT NULL) AND ("change_given_minor" IS NOT NULL) AND (("amount_tendered_minor" - "change_given_minor") = "amount_minor")) OR (("payment_method_type_snapshot" <> 'CASH'::"text") AND ("amount_tendered_minor" IS NULL) AND ("change_given_minor" IS NULL)))),
    CONSTRAINT "payments_method_code_snapshot_format" CHECK (("payment_method_code_snapshot" ~ '^[A-Z][A-Z0-9_]{1,39}$'::"text")),
    CONSTRAINT "payments_method_name_snapshot_length" CHECK ((("char_length"("payment_method_name_snapshot") >= 1) AND ("char_length"("payment_method_name_snapshot") <= 100))),
    CONSTRAINT "payments_method_type_snapshot_values" CHECK (("payment_method_type_snapshot" = ANY (ARRAY['CASH'::"text", 'CARD'::"text", 'E_WALLET'::"text", 'BANK_TRANSFER'::"text", 'VOUCHER'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "payments_note_length" CHECK ((("note" IS NULL) OR (("char_length"("note") >= 1) AND ("char_length"("note") <= 500)))),
    CONSTRAINT "payments_reference_number_length" CHECK ((("reference_number" IS NULL) OR (("char_length"("reference_number") >= 1) AND ("char_length"("reference_number") <= 120)))),
    CONSTRAINT "payments_tender_change_nonnegative" CHECK (((("amount_tendered_minor" IS NULL) OR ("amount_tendered_minor" >= 0)) AND (("change_given_minor" IS NULL) OR ("change_given_minor" >= 0))))
);


