    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "unit_code" "text" NOT NULL,
    "unit_name" "text" NOT NULL,
    "factor_to_base" numeric(14,3) NOT NULL,
    "is_base" boolean DEFAULT false NOT NULL,
    "is_sale_unit" boolean DEFAULT true NOT NULL,
    "is_purchase_unit" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "product_units_code_format" CHECK ((("unit_code" = "lower"(TRIM(BOTH FROM "unit_code"))) AND ("unit_code" ~ '^[a-z0-9][a-z0-9 _-]{0,23}$'::"text"))),
    CONSTRAINT "product_units_factor_positive" CHECK (("factor_to_base" > (0)::numeric)),
    CONSTRAINT "product_units_factor_precision" CHECK (("factor_to_base" = "round"("factor_to_base", 3))),
    CONSTRAINT "product_units_name_length" CHECK ((("char_length"(TRIM(BOTH FROM "unit_name")) >= 1) AND ("char_length"(TRIM(BOTH FROM "unit_name")) <= 80)))
);


ALTER TABLE "public"."product_units" OWNER TO "postgres";

