    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "product_variants_barcode_format" CHECK ((("barcode" IS NULL) OR (("barcode" = TRIM(BOTH FROM "barcode")) AND ("barcode" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{2,63}$'::"text")))),
    CONSTRAINT "product_variants_cost_nonnegative" CHECK (("cost_minor" >= 0)),
    CONSTRAINT "product_variants_name_length" CHECK ((("char_length"("name") >= 1) AND ("char_length"("name") <= 160))),
    CONSTRAINT "product_variants_option_values_object" CHECK (("jsonb_typeof"("option_values") = 'object'::"text")),
    CONSTRAINT "product_variants_price_nonnegative" CHECK (("price_minor" >= 0)),
    CONSTRAINT "product_variants_sku_format" CHECK ((("sku" IS NULL) OR (("sku" = "upper"(TRIM(BOTH FROM "sku"))) AND ("sku" ~ '^[A-Z0-9][A-Z0-9._-]{0,63}$'::"text")))),
    CONSTRAINT "product_variants_sort_order_nonnegative" CHECK (("sort_order" >= 0))
);


