--
-- Name: products; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."products" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "category_id" "uuid",
    "name" "text" NOT NULL,
    "description" "text",
    "product_type" "text" DEFAULT 'simple'::"text" NOT NULL,
    "sku" "text",
    "barcode" "text",
    "price_minor" bigint DEFAULT 0 NOT NULL,
    "cost_minor" bigint DEFAULT 0 NOT NULL,
    "track_inventory" boolean DEFAULT false NOT NULL,
    "unit" "text" DEFAULT 'each'::"text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "image_url" "text",
    "is_variable_price" boolean DEFAULT false NOT NULL,
    "allow_fractional_quantity" boolean DEFAULT false NOT NULL,
    "is_composite" boolean DEFAULT false NOT NULL,
    CONSTRAINT "products_barcode_format" CHECK ((("barcode" IS NULL) OR (("barcode" = TRIM(BOTH FROM "barcode")) AND ("barcode" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{2,63}$'::"text")))),
    CONSTRAINT "products_composite_type_consistency" CHECK (((NOT "is_composite") OR ("product_type" = 'simple'::"text"))),
    CONSTRAINT "products_cost_nonnegative" CHECK (("cost_minor" >= 0)),
    CONSTRAINT "products_description_length" CHECK ((("description" IS NULL) OR ("char_length"("description") <= 2000))),
    CONSTRAINT "products_image_url_format" CHECK ((("image_url" IS NULL) OR (("char_length"("image_url") <= 2048) AND ("image_url" ~* '^https?://'::"text")))),
    CONSTRAINT "products_name_length" CHECK ((("char_length"("name") >= 1) AND ("char_length"("name") <= 160))),
    CONSTRAINT "products_price_nonnegative" CHECK (("price_minor" >= 0)),
    CONSTRAINT "products_sku_format" CHECK ((("sku" IS NULL) OR (("sku" = "upper"(TRIM(BOTH FROM "sku"))) AND ("sku" ~ '^[A-Z0-9][A-Z0-9._-]{0,63}$'::"text")))),
    CONSTRAINT "products_status_values" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"]))),
    CONSTRAINT "products_type_values" CHECK (("product_type" = ANY (ARRAY['simple'::"text", 'variable'::"text", 'composite'::"text"]))),
    CONSTRAINT "products_unit_format" CHECK (((("char_length"("unit") >= 1) AND ("char_length"("unit") <= 24)) AND ("unit" ~ '^[A-Za-z][A-Za-z0-9 _-]*$'::"text"))),
    CONSTRAINT "products_variable_identifiers" CHECK ((("product_type" = ANY (ARRAY['simple'::"text", 'composite'::"text"])) OR (("sku" IS NULL) AND ("barcode" IS NULL)))),
    CONSTRAINT "products_variable_price_type" CHECK (((NOT "is_variable_price") OR ("product_type" = ANY (ARRAY['simple'::"text", 'composite'::"text"]))))
);


ALTER TABLE "public"."products" OWNER TO "postgres";

