    CONSTRAINT "purchase_order_lines_cost_nonnegative" CHECK (("unit_cost_minor" >= 0)),
    CONSTRAINT "purchase_order_lines_purchase_unit_factor_positive" CHECK ((("purchase_unit_factor_to_base" > (0)::numeric) AND ("purchase_unit_factor_to_base" = "round"("purchase_unit_factor_to_base", 3)))),
    CONSTRAINT "purchase_order_lines_quantity_bounds" CHECK ((("ordered_quantity" > (0)::numeric) AND ("received_quantity" >= (0)::numeric) AND ("received_quantity" <= "ordered_quantity")))
);


