--
-- Name: purchase_orders; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."purchase_orders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "store_id" "uuid" NOT NULL,
    "supplier_id" "uuid" NOT NULL,
    "order_number" bigint NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "notes" "text",
    "ordered_at" timestamp with time zone,
    "expected_at" "date",
    "received_at" timestamp with time zone,
    "created_by_employee_id" "uuid" NOT NULL,
    "received_by_employee_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "operation_id" "uuid" NOT NULL,
    "requested_expected_at" "date",
    CONSTRAINT "purchase_orders_notes_length" CHECK ((("notes" IS NULL) OR ("char_length"("notes") <= 1000))),
    CONSTRAINT "purchase_orders_received_state" CHECK (((("status" = ANY (ARRAY['received'::"text", 'partially_received'::"text"])) AND ("received_at" IS NOT NULL) AND ("received_by_employee_id" IS NOT NULL)) OR ("status" <> ALL (ARRAY['received'::"text", 'partially_received'::"text"])))),
    CONSTRAINT "purchase_orders_status_values" CHECK (("status" = ANY (ARRAY['draft'::"text", 'ordered'::"text", 'partially_received'::"text", 'received'::"text", 'cancelled'::"text"])))
);


