-- Name: COLUMN "purchase_orders"."operation_id"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."purchase_orders"."operation_id" IS 'Stable client-generated operation key. Retrying the same purchase-order command returns this document instead of creating another order.';


