-- Name: COLUMN "purchase_orders"."requested_expected_at"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."purchase_orders"."requested_expected_at" IS 'The explicit expected date supplied with the purchase-order command. Null means the supplier lead-time default was requested.';


--
-- Name: receipt_delivery_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."receipt_delivery_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "receipt_id" "uuid" NOT NULL,
    "requested_by_employee_id" "uuid" NOT NULL,
    "idempotency_key" "uuid" NOT NULL,
    "delivery_channel" "text" NOT NULL,
    "recipient" "text" NOT NULL,
    "status" "text" DEFAULT 'QUEUED'::"text" NOT NULL,
    "provider_message_id" "text",
    "delivered_at" timestamp with time zone,
    "failed_at" timestamp with time zone,
    "failure_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "receipt_delivery_requests_channel_values" CHECK (("delivery_channel" = 'EMAIL'::"text")),
    CONSTRAINT "receipt_delivery_requests_failure_reason_length" CHECK ((("failure_reason" IS NULL) OR (("char_length"("btrim"("failure_reason")) >= 2) AND ("char_length"("btrim"("failure_reason")) <= 500)))),
    CONSTRAINT "receipt_delivery_requests_provider_id_length" CHECK ((("provider_message_id" IS NULL) OR (("char_length"("btrim"("provider_message_id")) >= 1) AND ("char_length"("btrim"("provider_message_id")) <= 320)))),
    CONSTRAINT "receipt_delivery_requests_recipient_length" CHECK ((("char_length"("btrim"("recipient")) >= 3) AND ("char_length"("btrim"("recipient")) <= 320))),
    CONSTRAINT "receipt_delivery_requests_status_timestamps" CHECK (((("status" = 'QUEUED'::"text") AND ("delivered_at" IS NULL) AND ("failed_at" IS NULL)) OR (("status" = 'DELIVERED'::"text") AND ("delivered_at" IS NOT NULL) AND ("failed_at" IS NULL)) OR (("status" = ANY (ARRAY['FAILED'::"text", 'CANCELLED'::"text"])) AND ("failed_at" IS NOT NULL)))),
    CONSTRAINT "receipt_delivery_requests_status_values" CHECK (("status" = ANY (ARRAY['QUEUED'::"text", 'DELIVERED'::"text", 'FAILED'::"text", 'CANCELLED'::"text"])))
);


ALTER TABLE "public"."receipt_delivery_requests" OWNER TO "postgres";

