--

COMMENT ON TABLE "public"."receipt_delivery_requests" IS 'Immutable digital-receipt outbox records. A delivery provider can later process QUEUED records without changing the receipt.';


--
-- Name: receipt_settings; Type: TABLE; Schema: public; Owner: postgres
