    "show_store_address" boolean DEFAULT true NOT NULL,
    "show_store_phone" boolean DEFAULT true NOT NULL,
    "show_cashier" boolean DEFAULT true NOT NULL,
    "show_register" boolean DEFAULT true NOT NULL,
    "show_payment_details" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "receipt_settings_business_address_length" CHECK ((("business_address" IS NULL) OR (("char_length"("btrim"("business_address")) >= 2) AND ("char_length"("btrim"("business_address")) <= 500)))),
    CONSTRAINT "receipt_settings_business_email_length" CHECK ((("business_email" IS NULL) OR (("char_length"("btrim"("business_email")) >= 3) AND ("char_length"("btrim"("business_email")) <= 320)))),
    CONSTRAINT "receipt_settings_business_name_length" CHECK ((("char_length"("btrim"("business_name")) >= 2) AND ("char_length"("btrim"("business_name")) <= 160))),
    CONSTRAINT "receipt_settings_business_phone_length" CHECK ((("business_phone" IS NULL) OR (("char_length"("btrim"("business_phone")) >= 2) AND ("char_length"("btrim"("business_phone")) <= 40)))),
    CONSTRAINT "receipt_settings_business_tax_id_length" CHECK ((("business_tax_id" IS NULL) OR (("char_length"("btrim"("business_tax_id")) >= 2) AND ("char_length"("btrim"("business_tax_id")) <= 80)))),
    CONSTRAINT "receipt_settings_business_website_length" CHECK ((("business_website" IS NULL) OR (("char_length"("btrim"("business_website")) >= 3) AND ("char_length"("btrim"("business_website")) <= 2048)))),
    CONSTRAINT "receipt_settings_footer_message_length" CHECK ((("char_length"("btrim"("footer_message")) >= 2) AND ("char_length"("btrim"("footer_message")) <= 240))),
    CONSTRAINT "receipt_settings_header_message_length" CHECK ((("header_message" IS NULL) OR (("char_length"("btrim"("header_message")) >= 2) AND ("char_length"("btrim"("header_message")) <= 160)))),
    CONSTRAINT "receipt_settings_paper_width_values" CHECK (("paper_width_mm" = ANY (ARRAY[58, 80])))
);


ALTER TABLE "public"."receipt_settings" OWNER TO "postgres";

