--
-- Name: refund_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."refund_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "refund_id" "uuid" NOT NULL,
    "sale_item_id" "uuid" NOT NULL,
    "product_id" "uuid" NOT NULL,
    "variant_id" "uuid",
    "product_name_snapshot" "text" NOT NULL,
    "variant_name_snapshot" "text",
    "sku_snapshot" "text",
    "unit_snapshot" "text" NOT NULL,
    "quantity" integer NOT NULL,
    "unit_price_minor" bigint NOT NULL,
    "line_total_minor" bigint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "returned_to_stock" boolean DEFAULT true NOT NULL,
    CONSTRAINT "refund_items_amounts_nonnegative" CHECK ((("unit_price_minor" >= 0) AND ("line_total_minor" >= 0))),
    CONSTRAINT "refund_items_product_name_snapshot_length" CHECK ((("char_length"("product_name_snapshot") >= 1) AND ("char_length"("product_name_snapshot") <= 160))),
    CONSTRAINT "refund_items_quantity_bounds" CHECK ((("quantity" >= 1) AND ("quantity" <= 10000))),
    CONSTRAINT "refund_items_sku_snapshot_length" CHECK ((("sku_snapshot" IS NULL) OR (("char_length"("sku_snapshot") >= 1) AND ("char_length"("sku_snapshot") <= 64)))),
    CONSTRAINT "refund_items_total_math" CHECK (("line_total_minor" = ("unit_price_minor" * "quantity"))),
    CONSTRAINT "refund_items_unit_snapshot_length" CHECK ((("char_length"("unit_snapshot") >= 1) AND ("char_length"("unit_snapshot") <= 24))),
    CONSTRAINT "refund_items_variant_name_snapshot_length" CHECK ((("variant_name_snapshot" IS NULL) OR (("char_length"("variant_name_snapshot") >= 1) AND ("char_length"("variant_name_snapshot") <= 160))))
);


