    CONSTRAINT "refund_payments_method_type_snapshot_values" CHECK (("payment_method_type_snapshot" = ANY (ARRAY['CASH'::"text", 'CARD'::"text", 'E_WALLET'::"text", 'BANK_TRANSFER'::"text", 'VOUCHER'::"text", 'OTHER'::"text"]))),
    CONSTRAINT "refund_payments_reference_number_length" CHECK ((("reference_number" IS NULL) OR (("char_length"("reference_number") >= 1) AND ("char_length"("reference_number") <= 120))))
);


