--
-- Name: refund_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."refund_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "actor_employee_id" "uuid" NOT NULL,
    "idempotency_key" "uuid" NOT NULL,
    "request_payload" "jsonb" NOT NULL,
    "state" "text" DEFAULT 'processing'::"text" NOT NULL,
    "refund_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    CONSTRAINT "refund_requests_completion_state" CHECK (((("state" = 'processing'::"text") AND ("refund_id" IS NULL) AND ("completed_at" IS NULL)) OR (("state" = 'completed'::"text") AND ("refund_id" IS NOT NULL) AND ("completed_at" IS NOT NULL)))),
    CONSTRAINT "refund_requests_payload_object" CHECK (("jsonb_typeof"("request_payload") = 'object'::"text")),
