    "tax_minor" bigint DEFAULT 0 NOT NULL,
    "line_total_minor" bigint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "modifier_total_minor" bigint DEFAULT 0 NOT NULL,
    "modifiers_snapshot" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "item_note" "text",
    "unit_cost_minor" bigint DEFAULT 0 NOT NULL,
    "cogs_minor" bigint DEFAULT 0 NOT NULL,
    CONSTRAINT "sale_items_amounts_nonnegative" CHECK ((("unit_price_minor" >= 0) AND ("discount_minor" >= 0) AND ("tax_minor" >= 0) AND ("line_total_minor" >= 0))),
    CONSTRAINT "sale_items_cogs_nonnegative" CHECK (("cogs_minor" >= 0)),
    CONSTRAINT "sale_items_item_note_length" CHECK ((("item_note" IS NULL) OR (("char_length"("btrim"("item_note")) >= 1) AND ("char_length"("btrim"("item_note")) <= 500)))),
    CONSTRAINT "sale_items_modifier_total_nonnegative" CHECK (("modifier_total_minor" >= 0)),
    CONSTRAINT "sale_items_modifiers_snapshot_array" CHECK (("jsonb_typeof"("modifiers_snapshot") = 'array'::"text")),
    CONSTRAINT "sale_items_product_name_snapshot_length" CHECK ((("char_length"("product_name_snapshot") >= 1) AND ("char_length"("product_name_snapshot") <= 160))),
    CONSTRAINT "sale_items_quantity_bounds" CHECK ((("quantity" >= 0.001) AND ("quantity" <= (10000)::numeric))),
    CONSTRAINT "sale_items_sku_snapshot_length" CHECK ((("sku_snapshot" IS NULL) OR (("char_length"("sku_snapshot") >= 1) AND ("char_length"("sku_snapshot") <= 64)))),
    CONSTRAINT "sale_items_total_math" CHECK (("line_total_minor" = ("round"((((("unit_price_minor")::numeric * "quantity") - ("discount_minor")::numeric) + ("tax_minor")::numeric)))::bigint)),
    CONSTRAINT "sale_items_unit_cost_nonnegative" CHECK (("unit_cost_minor" >= 0)),
    CONSTRAINT "sale_items_unit_snapshot_length" CHECK ((("char_length"("unit_snapshot") >= 1) AND ("char_length"("unit_snapshot") <= 24))),
