    "store_id" "uuid" NOT NULL,
    "register_id" "uuid" NOT NULL,
    "cashier_employee_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'completed'::"text" NOT NULL,
    "currency_code" "text" NOT NULL,
    "organization_name_snapshot" "text" NOT NULL,
    "store_name_snapshot" "text" NOT NULL,
    "register_name_snapshot" "text" NOT NULL,
    "cashier_name_snapshot" "text" NOT NULL,
    "subtotal_minor" bigint DEFAULT 0 NOT NULL,
    "discount_minor" bigint DEFAULT 0 NOT NULL,
    "tax_minor" bigint DEFAULT 0 NOT NULL,
    "total_minor" bigint DEFAULT 0 NOT NULL,
    "completed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "shift_id" "uuid",
    "customer_id" "uuid",
    "loyalty_redemption_minor" bigint DEFAULT 0 NOT NULL,
    "loyalty_points_redeemed" integer DEFAULT 0 NOT NULL,
    "loyalty_points_earned" integer DEFAULT 0 NOT NULL,
    "tax_is_inclusive" boolean DEFAULT false NOT NULL,
    "discount_id" "uuid",
    "discount_name_snapshot" "text",
    "tax_rate_id" "uuid",
    "tax_name_snapshot" "text",
    "dining_option_id" "uuid",
    "dining_option_name_snapshot" "text",
    "open_ticket_id" "uuid",
    CONSTRAINT "sales_amounts_nonnegative" CHECK ((("subtotal_minor" >= 0) AND ("discount_minor" >= 0) AND ("tax_minor" >= 0) AND ("total_minor" >= 0))),
    CONSTRAINT "sales_cashier_name_snapshot_length" CHECK ((("char_length"("cashier_name_snapshot") >= 1) AND ("char_length"("cashier_name_snapshot") <= 320))),
    CONSTRAINT "sales_currency_code_format" CHECK (("currency_code" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "sales_dining_snapshot_length" CHECK ((("dining_option_name_snapshot" IS NULL) OR (("char_length"("dining_option_name_snapshot") >= 1) AND ("char_length"("dining_option_name_snapshot") <= 60)))),
    CONSTRAINT "sales_discount_snapshot_length" CHECK ((("discount_name_snapshot" IS NULL) OR (("char_length"("discount_name_snapshot") >= 1) AND ("char_length"("discount_name_snapshot") <= 100)))),
    CONSTRAINT "sales_loyalty_values_nonnegative" CHECK ((("loyalty_redemption_minor" >= 0) AND ("loyalty_points_redeemed" >= 0) AND ("loyalty_points_earned" >= 0))),
    CONSTRAINT "sales_organization_name_snapshot_length" CHECK ((("char_length"("organization_name_snapshot") >= 2) AND ("char_length"("organization_name_snapshot") <= 160))),
    CONSTRAINT "sales_register_name_snapshot_length" CHECK ((("char_length"("register_name_snapshot") >= 2) AND ("char_length"("register_name_snapshot") <= 160))),
    CONSTRAINT "sales_status_values" CHECK (("status" = 'completed'::"text")),
    CONSTRAINT "sales_store_name_snapshot_length" CHECK ((("char_length"("store_name_snapshot") >= 2) AND ("char_length"("store_name_snapshot") <= 160))),
    CONSTRAINT "sales_tax_snapshot_length" CHECK ((("tax_name_snapshot" IS NULL) OR (("char_length"("tax_name_snapshot") >= 1) AND ("char_length"("tax_name_snapshot") <= 100)))),
    CONSTRAINT "sales_total_math" CHECK (("total_minor" = (("subtotal_minor" - "discount_minor") +
CASE
    WHEN "tax_is_inclusive" THEN (0)::bigint
    ELSE "tax_minor"
END)))
);


