    CONSTRAINT "shifts_closing_note_length" CHECK ((("closing_note" IS NULL) OR (("char_length"("closing_note") >= 2) AND ("char_length"("closing_note") <= 500)))),
    CONSTRAINT "shifts_counted_cash_nonnegative" CHECK ((("counted_cash_minor" IS NULL) OR ("counted_cash_minor" >= 0))),
