    "received_quantity" numeric(14,3) DEFAULT 0 NOT NULL,
    "short_quantity" numeric(14,3) DEFAULT 0 NOT NULL,
    CONSTRAINT "stock_request_lines_quantities" CHECK ((("requested_quantity" > (0)::numeric) AND ("approved_quantity" >= (0)::numeric) AND ("picked_quantity" >= (0)::numeric) AND ("dispatched_quantity" >= (0)::numeric) AND ("received_quantity" >= (0)::numeric) AND ("short_quantity" >= (0)::numeric) AND ("approved_quantity" <= "requested_quantity") AND ("picked_quantity" <= "approved_quantity") AND ("dispatched_quantity" <= "picked_quantity") AND (("received_quantity" + "short_quantity") <= "dispatched_quantity"))),
    CONSTRAINT "stock_request_lines_snapshots" CHECK (((("char_length"("btrim"("product_name_snapshot")) >= 1) AND ("char_length"("btrim"("product_name_snapshot")) <= 200)) AND (("char_length"("btrim"("unit_snapshot")) >= 1) AND ("char_length"("btrim"("unit_snapshot")) <= 40))))
);


