--
-- Name: stock_transfers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."stock_transfers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "source_store_id" "uuid" NOT NULL,
    "destination_store_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'completed'::"text" NOT NULL,
    "note" "text",
    "transferred_by_employee_id" "uuid" NOT NULL,
    "completed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "received_by_employee_id" "uuid",
    "received_at" timestamp with time zone,
    "stock_request_id" "uuid",
    "transfer_number" bigint NOT NULL,
    "operation_id" "uuid" NOT NULL,
    CONSTRAINT "stock_transfers_different_stores" CHECK (("source_store_id" <> "destination_store_id")),
    CONSTRAINT "stock_transfers_note_length" CHECK ((("note" IS NULL) OR ("char_length"("note") <= 500))),
    CONSTRAINT "stock_transfers_received_state" CHECK (((("status" = ANY (ARRAY['partially_received'::"text", 'completed'::"text"])) AND ("received_by_employee_id" IS NOT NULL) AND ("received_at" IS NOT NULL)) OR ("status" = 'in_transit'::"text") OR (("status" = 'completed'::"text") AND ("received_by_employee_id" IS NULL) AND ("received_at" IS NULL)))),
    CONSTRAINT "stock_transfers_status_values" CHECK (("status" = ANY (ARRAY['in_transit'::"text", 'partially_received'::"text", 'completed'::"text"])))
);


ALTER TABLE "public"."stock_transfers" OWNER TO "postgres";

--
-- Name: COLUMN "stock_transfers"."transfer_number"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."stock_transfers"."transfer_number" IS 'Organization-scoped sequential human transfer reference, displayed as TR-000001.';


--
-- Name: COLUMN "stock_transfers"."operation_id"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."stock_transfers"."operation_id" IS 'Stable client-generated key. Retrying a transfer dispatch returns the original transfer without subtracting source stock twice.';


