    "clock_in_note" "text",
    "clock_out_note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "clock_in_verification_method" "text" DEFAULT 'authenticated_session'::"text" NOT NULL,
    "clock_out_verification_method" "text",
    "clock_in_request_id" "uuid",
    "clock_out_request_id" "uuid",
    "clocked_in_by_employee_id" "uuid" NOT NULL,
    "clocked_out_by_employee_id" "uuid",
    CONSTRAINT "time_clock_entries_clock_in_note_length" CHECK ((("clock_in_note" IS NULL) OR (("char_length"("clock_in_note") >= 2) AND ("char_length"("clock_in_note") <= 500)))),
    CONSTRAINT "time_clock_entries_clock_in_verification_check" CHECK (("clock_in_verification_method" = ANY (ARRAY['authenticated_session'::"text", 'employee_pin'::"text"]))),
    CONSTRAINT "time_clock_entries_clock_out_note_length" CHECK ((("clock_out_note" IS NULL) OR (("char_length"("clock_out_note") >= 2) AND ("char_length"("clock_out_note") <= 500)))),
    CONSTRAINT "time_clock_entries_clock_out_verification_check" CHECK ((("clock_out_verification_method" IS NULL) OR ("clock_out_verification_method" = 'employee_pin'::"text"))),
    CONSTRAINT "time_clock_entries_ordering" CHECK ((("clocked_out_at" IS NULL) OR ("clocked_out_at" >= "clocked_in_at")))
);


ALTER TABLE "public"."time_clock_entries" OWNER TO "postgres";

